<script setup lang="ts">
// ⭐ ปุ่มกลางของทั้งเว็บ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/141) ⇒ ทุกปุ่มบนหน้านี้เรียกชิ้นนี้ ⇒ เหตุผลอยู่ที่ `app/components/ui/button/index.ts`
import { Button } from '~/components/ui/button'
// หน้าอ่านพระคัมภีร์ — **ม้วนเดียว** (ใบงาน v3/phrakham#65 · พี่เอมสั่ง 6 ก.ย. 2569)
//
// ⭐⭐ **1 เล่ม = 1 หน้า** (ใบงาน v3/phrakham#73 · พี่เอมสั่ง 6 ก.ย. 2569)
//   ⇒ *"ตัวบทและข้อคือการเลือกภายใน ไม่ใช่หน้า"* ⇒ บทที่กางอยู่เป็น **หน้าต่างที่เลื่อนตามผู้อ่าน**
//   ⇒ เลื่อนลงต่อบทถัดไป · เลื่อนขึ้นต่อบทก่อนหน้า · บทที่พ้นไปไกลถูกทิ้ง (ดูหัวข้อ *เลื่อนอ่านทะลุบท*)
//
// ⭐⭐ **ชิ้นนี้เป็นตัวหน้าอ่านทั้งหมด ⇒ ใช้ทั้งที่ราก `/` และที่ `/read/<เล่ม>`**
//   ⇒ พี่เอมสั่งว่า *"เปิดเว็บมาต้องเห็นพระคัมภีร์ทันที"* ⇒ **ราก `/` จึงเป็นหน้าอ่าน ⛔ ไม่ใช่ประตู**
//   ⇒ **แบบหน้าจอเต็ม ๆ อยู่ในคอมเมนต์ของใบงาน #65** ⛔ ไม่คัดมาไว้ที่นี่
//
// ⭐ **ของที่ยกมาจากหน้าอ่านเดิมทั้งดุ้น** ⇒ ตัวเลือกฉบับ · มุมมองการจัดวาง · ขนาดตัวอักษร
//   · จุดที่พาไปในคำถามท้ายที่อยู่ · หน้าต่างเลือกพระธรรม
//   ⇒ **ลายนิ้วมือของที่คัดมาจากรุ่น 2 อยู่ที่ `docs/ของที่คัดจากรุ่น-2.tsv`** ⛔ ไม่จดซ้ำที่นี่
//
// ⛔ **ต้องสั่ง import เอง** — ตัวเติม import อัตโนมัติ ⛔ ไม่รู้จักชื่อภาษาไทย
import {
  ที่อยู่หน้าอ่าน,
  ที่อยู่หลังบ้าน,
  อ่านคอลัมน์เทียบ,
  อ่านช่วงฟัง,
  เขียนช่วงฟัง,
  แสดงช่วงฟัง,
  เพดานคอลัมน์ในที่อยู่,
  อ่านฉบับในที่อยู่,
  เขียนฉบับในที่อยู่,
  type คอลัมน์เทียบ,
  type ช่วงฟัง,
} from '~/utils/ที่อยู่'
import { type ดัชนีเสียง } from '~/utils/คิวเสียง'
import { ใช้เสียงบนหน้าอ่าน } from '~/composables/เสียงบนหน้าอ่าน'
import { สร้างตัวเล่นเสียง, type สภาพตัวเล่น } from '~/utils/ตัวเล่นเสียง'
import { ตัดเนื้อตามคำพระเยซู, type ช่วงคำพระเยซู, type ชิ้นเนื้อ } from '~/utils/คำพระเยซู'
import { แทรกเชิงอรรถ, type เชิงอรรถ, type เครื่องหมายเชิงอรรถ } from '~/utils/เชิงอรรถ'
import แผ่นเชิงอรรถ from '~/components/แผ่นเชิงอรรถ.vue'
import คู่ขนานใต้หัวข้อ from '~/components/คู่ขนานใต้หัวข้อ.vue'
import {
  จัดย่อหน้า,
  จับคู่ย่อหน้า,
  เลือกฉบับต้นแบบ,
  ยืมรอยย่อหน้า,
  เยื้องบรรทัดแรก,
  type รอยย่อหน้า,
  type ย่อหน้า,
} from '~/utils/ย่อหน้า'
import {
  หัวข้อตามข้อ,
  รอยของหัวข้อ,
  หัวข้อของย่อหน้า,
  แทรกแถวหัวข้อ,
  type หัวข้อย่อย,
  type แถวย่อหน้า,
} from '~/utils/หัวข้อย่อย'
import { จัดข้อเดิมลงแถว, ข้อแปลของกลุ่ม, type ข้อแปลในแถว } from '~/utils/แถวคำเดิม'
import { ป้ายเลขข้อ } from '~/utils/ป้ายเลขข้อ'
import { ชิ้นโหลดแยก } from '~/utils/ชิ้นโหลดแยก'
// ⛔⛔ **ต้องสั่ง import เอง — ตัวเติม import อัตโนมัติ ⛔ ไม่รู้จักชื่อภาษาไทย**
import แถบนำทาง from '~/components/แถบนำทาง.vue'
import พวงลิงก์ from '~/components/พวงลิงก์.vue'
import หัวคอลัมน์ from '~/components/หัวคอลัมน์.vue'
import คำเดิมใต้แถว from '~/components/คำเดิมใต้แถว.vue'
import { ถ้อยคำคำเดิมท้ายบท, type ชั้นของแถว, type ตัวช่วยคำเดิม } from '~/utils/คำเดิมจอแคบ'
import { ฉบับตั้งต้น, อ่านฉบับที่เลือก, จำฉบับที่เลือก, อ่านที่คำเดิม, จำที่คำเดิม } from '~/utils/ฉบับที่เลือก'
import { ถ้อยคำคอลัมน์เดียว, ถ้อยคำหลายคอลัมน์ } from '~/utils/ถ้อยคำแถบล่าง'
import { ถ้อยคำคำเดิม, ชื่อตัวบท, ป้ายชั้นคำ, ชื่อตัวบทเดิมทั้งหมด, ภาษาของตัวบท } from '~/utils/ถ้อยคำคำเดิม'
import { ถ้อยคำเมนูเทียบ, ป้ายอ่านฉบับ } from '~/utils/ถ้อยคำเมนูเทียบ'
import { ถ้อยคำแผงAa } from '~/utils/ถ้อยคำแผงAa'
import { ถ้อยคำการวางจอแคบ, ป้ายบนล่าง } from '~/utils/ถ้อยคำการวางจอแคบ'
import เนื้อตอนเทียบ from '~/components/เนื้อตอนเทียบ.vue'
import { ใช้ขนาดตัวอักษร } from '~/composables/ขนาดตัวอักษร'
import { แสดงเป็นข้อความ, type จุดอ่าน } from '~/utils/อ้างอิง'
import {
  อ่านมุมมอง,
  จำมุมมอง,
  มุมมองตั้งต้น,
  การวางจอแคบที่มี,
  type มุมมอง,
  type แบบวางจอแคบ,
  type ตระกูลเครื่องหมาย,
} from '~/utils/มุมมอง'
import { กางเครื่องหมาย, หน้าตาของคำ, type จุดบนคำ, type หน้าตาคำ } from '~/utils/เครื่องหมายบนคำ'
// ⭐ แตะข้อเพื่อเลือก แล้วแชร์ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/139) ⇒ กติกาอยู่ในไฟล์ของมันเอง
import ปุ่มแชร์ from '~/components/ปุ่มแชร์.vue'
// ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/173 ⇒ ปุ่ม Aa กับแผงเป็นชิ้นเดียวกับแถบบนของทุกหน้า ⇒ เหตุผลอยู่หัวไฟล์นั้น
import ปุ่มAa from '~/components/ปุ่มAa.vue'
import กล่องเด้ง from '~/components/กล่องเด้ง.vue'
import { ใช้กล่องเด้ง } from '~/composables/กล่องเด้ง'
import { ใช้การเลือกข้อ, กุญแจชิ้น, แยกชิ้น, ฉบับในกุญแจ, แยกฉบับซ้ำ } from '~/composables/เลือกข้อ'
import { ประกอบข้อความข้อ, ประกอบข้อความหน้า, type ข้อที่จะแชร์, type ฉบับที่จะแชร์ } from '~/utils/แชร์ข้อ'
import { ถ้อยคำแชร์ } from '~/utils/ถ้อยคำแชร์'
import { ถ้อยคำเชิงอรรถ } from '~/utils/ถ้อยคำเชิงอรรถ'
import { แสดงเลขStrong as ตัวสลับเลขStrong, เลขบนคำ } from '~/utils/เลขStrong'
import { ที่อยู่ข้อที่แชร์, อ่านข้อที่แชร์, ที่อยู่หน้าแหล่งข้อมูล, อ่านคำที่แชร์, type คำในเล่ม } from '~/utils/ที่อยู่'
import { ที่อยู่ใช้เลขเดิม, เดิมไปแปล, จุดเป็นเลขเดิม, จุดจากเลขเดิม, type ไฟล์เลขเดิม } from '~/utils/เลขเดิมในที่อยู่'

interface เล่ม {
  รหัส: string
  ชื่อไทย: string
  พันธสัญญา: string
  /** จำนวนบทของฉบับแปล ⇒ เท่ากับจำนวนของ `บทที่มี` เสมอ (ใบ #94) */
  บท: number
  /** จำนวนบทของฝั่งภาษาเดิม ⇒ โยเอลฮีบรู 4 · มาลาคีฮีบรู 3 (ใบ #94) ⇒ เจ้าของคือ `server/utils/เนื้อบท.ts` */
  บทเดิม?: number
  บทที่มี: number[]
  ข้อสุดท้าย: number[]
}
/** เนื้อของบทเดียว ⇒ ⛔ **มีแค่เนื้อ** ⇒ ของประจำเล่มอยู่ที่ `ผลเล่ม` (ใบงาน v3/phrakham#73) */
interface ผลบท {
  บท: number
  ชั้น: Record<string, Record<string, string>>
  /** ช่วงคำที่พระเยซูพูด ของ *บทนี้* ⇒ `{<ฉบับ>: [ช่วง...]}` ⇒ ฉบับที่เจ้าของไม่ได้ทำเครื่องหมาย **ไม่มีกุญแจ** */
  คำพระเยซู?: Record<string, ช่วงคำพระเยซู[]>
  /** เชิงอรรถของผู้แปล ของ *บทนี้* ⇒ `{<ฉบับ>: [...]}` ⇒ ฉบับที่ไม่มี **ไม่มีกุญแจ** */
  เชิงอรรถ?: Record<string, เชิงอรรถ[]>
  /** รอยขึ้นย่อหน้าที่ *คนแปล* แบ่งไว้ ของ *บทนี้* ⇒ ฉบับที่ยังไม่มี **ไม่มีกุญแจ** (ใบงาน #98) */
  ย่อหน้า?: Record<string, รอยย่อหน้า[]>
  /** หัวข้อย่อย `s1` ของ *บทนี้* ⇒ ฉบับที่ไม่มีหัวข้อ **ไม่มีกุญแจ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134) */
  หัวข้อ?: Record<string, หัวข้อย่อย[]>
}
/** ของประจำเล่ม ⇒ โหลดครั้งเดียวต่อเล่ม ⛔ ไม่ติดไปกับเนื้อบททุกบท */
interface ผลเล่ม {
  เล่ม: เล่ม
  ชั้น: string[]
  แหล่งของชั้น: Record<string, string>
  /** ภาษาของแต่ละฉบับ เป็นรหัส BCP 47 ⇒ เจ้าของตารางคือ `server/utils/เนื้อบท.ts` ⛔ ไม่จดซ้ำที่นี่ */
  ภาษาของชั้น: Record<string, string>
  /** ⭐ ชื่อย่อเล่มนี้ของแต่ละฉบับ ⇒ ช่อง `toc3` ของต้นฉบับ (ใบ #131 note_30489) ⇒ เจ้าของคือ `server/utils/เนื้อบท.ts` */
  ชื่อย่อของชั้น?: Record<string, string>
  /** ⭐ ฉบับที่ยังไม่มีย่อหน้าให้ใช้ ⇒ `{<ฉบับ>: เหตุผลที่เครื่องนับเอง}` (ใบงาน #98)
   *  ⇒ ⛔ **หยิบประโยคนี้ไปแสดงตรง ๆ** ⛔ ห้ามพิมพ์ประโยคใหม่ทับ ⇒ เหตุผลอยู่ที่ `server/utils/เนื้อบท.ts` */
  ฉบับที่ยังไม่มีย่อหน้า?: Record<string, string>
  /** ⭐ ดัชนีเสียงของเล่มนี้ ⇒ ⛔ ไม่มี = เล่มนี้ยังไม่มีเสียงสักบท (ใบงาน #101)
   *  ⇒ เจ้าของรูปและเหตุผลคือ `server/utils/เสียงของเล่ม.ts` ⛔ ไม่จดซ้ำที่นี่ */
  เสียง?: Record<string, ดัชนีเสียง>
  /** ⭐ ดัชนีเรื่องเล่าของเล่มนี้ ⇒ แค่รหัสกับช่วงข้อ ⛔ ไม่มีตัวเรื่อง ⇒ ⛔ ไม่มี = เล่มนี้ไม่มีเรื่องเล่า (ใบงาน #105)
   *  ⇒ เจ้าของรูปและเหตุผลคือ `server/utils/เรื่องเล่า.ts` ⛔ ไม่จดซ้ำที่นี่ */
  เรื่องเล่า?: ดัชนีเรื่องเล่า[]
}
interface ดัชนีเรื่องเล่า {
  รหัส: string
  จาก: { บท: number; ข้อ: number }
  ถึง: { บท: number; ข้อ: number }
}

const props = defineProps<{
  /** เล่มกับบทที่หน้านี้ถูกสร้างไว้ล่วงหน้าด้วย */
  รหัสเล่ม: string
  เลขบท: number
}>()

const รหัสเล่ม = props.รหัสเล่ม
const เลขบท = String(props.เลขบท)
const route = useRoute()
const router = useRouter()

const { data: บท } = await useAsyncData(`บท:${รหัสเล่ม}/${เลขบท}`, () =>
  $fetch<ผลบท>(ที่อยู่หลังบ้าน(`api/chapter/${รหัสเล่ม}/${เลขบท}.json`)),
)
// ⭐ กุญแจตรงกับที่หน้า `/read/<เล่ม>` ใช้ ⇒ ทั้งสองที่แชร์ผลก้อนเดียวกัน ⛔ ไม่โหลดซ้ำ
const { data: ของเล่ม } = await useAsyncData(`เล่ม:${รหัสเล่ม}`, () =>
  $fetch<ผลเล่ม>(ที่อยู่หลังบ้าน(`api/book/${รหัสเล่ม}.json`)),
)

// ⛔ ไม่มีบทนี้ = 404 จริง ⛔ ไม่ใช่หน้าเปล่าที่ดูเหมือนใช้ได้
if (!บท.value || !ของเล่ม.value) {
  throw createError({ statusCode: 404, statusMessage: 'ไม่มีบทนี้', fatal: true })
}

const เล่มนี้ = computed(() => ของเล่ม.value!.เล่ม)
const ฉบับที่มี = computed(() => ของเล่ม.value!.ชั้น)
const แหล่งของชั้น = computed(() => ของเล่ม.value!.แหล่งของชั้น)
// ⭐⭐ **ภาษาของฉบับ ⇒ ไปเป็น `lang` ของกล่องตัวบทฉบับนั้น**
//   **WCAG 2.2 SC 3.1.2 Language of Parts (ระดับ AA)** ⇒ ตัวบทสั่งว่า *The human language of each
//     passage or phrase in the content can be programmatically determined*
//   ⇒ **นี่คือรูที่เราเปิดไว้จริง** ⇒ หน้าเป็น `lang="th"` ทั้งหน้า ⇒ คอลัมน์ `WEB` กับ `LSV`
//     ถูกโปรแกรมอ่านหน้าจอออกเสียงด้วยเสียงไทย ⇒ ฟังไม่รู้เรื่อง (N กับ G ทักตรงกัน 11 ต.ค. 2569)
//   ⛔ **ป้ายชื่อแหล่งที่ซ่อนไว้ให้เสียงอ่าน (`Thai Common Version 2025`) ⛔ ไม่ติด `lang`**
//     ⇒ ตัวบทของข้อนี้ยกเว้นไว้เอง ⇒ *except for proper names, technical terms, …*
const ภาษาของชั้น = computed(() => ของเล่ม.value!.ภาษาของชั้น)

// ⭐⭐ **บัญชี 66 เล่มกับแผงเลือกพระธรรม ย้ายไปอยู่ที่ `app/components/แถบนำทาง.vue` แล้ว**
//   (12 ต.ค. 2569) ⇒ **ทั้งเว็บมีแผงเดียว** ⇒ หน้านี้แค่กดเปิดมันกับรับผลการเลือก
//   ⇒ เหตุผลกับมาตรฐานที่อ้าง อยู่ที่ชิ้นส่วนนั้น ⛔ ไม่จดซ้ำที่นี่

// ---------------------------------------------------------------- ฉบับที่เลือก
const ฉบับที่เลือก = ref<string[]>([ฉบับตั้งต้น])
// ⭐⭐ **เรียงตามที่ผู้อ่านวาง ⛔ ไม่ใช่ตามลำดับฉบับของเล่ม** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 8)
//   ⇒ ของเดิมเรียงตาม `ฉบับที่มี` ⇒ เปลี่ยนฉบับของคอลัมน์แรกเป็นฉบับที่อยู่ท้ายรายชื่อ ⇒ คอลัมน์อื่นกระโดดมาเป็นคอลัมน์แรกแทน
//     ⇒ คำภาษาเดิมก็ย้ายไปคู่กับคอลัมน์ที่ผู้อ่านไม่ได้แตะ ⇒ ขัดข้อ 8 *คอลัมน์อื่นไม่ขยับเลย*
//   ⇒ ⭐ ค่าที่ซ้ำกันถูกทิ้ง ⇒ ที่เก็บหรือที่อยู่ที่ใครแก้มือมาซ้ำ ⛔ ไม่ทำให้ได้ 2 คอลัมน์ฉบับเดียวกันในตาราง
const ฉบับที่แสดง = computed(() =>
  ฉบับที่เลือก.value.filter((x, i, ทั้งหมด) => ฉบับที่มี.value.includes(x) && ทั้งหมด.indexOf(x) === i),
)
// ⭐⭐ **ทุกคอลัมน์เท่ากัน ⇒ คำภาษาเดิมคือฉบับหนึ่ง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ⇒ พี่เอมเคาะ 6 พ.ย. 2569)
//   ⇒ ปิดฉบับแปลฉบับสุดท้ายได้ ⇒ ตารางเหลือคอลัมน์คำภาษาเดิมคอลัมน์เดียว ⇒ มันถือบทของหน้าเอง (ชื่อหน้า · แถบล่าง · `c` `v`)
//   ⇒ ⚠️ ของเดิม (ใบ #102 ข้อ 1.2) ⇒ นับเฉพาะฉบับแปล ⇒ เหลือฉบับแปลฉบับเดียวปิดไม่ได้ ทั้งที่ยังมีคำเดิม
/** ⭐ ตารางเหลือแต่คอลัมน์คำภาษาเดิม ⇒ ไม่มีฉบับแปลในตารางเลย */
const เหลือแต่คำเดิม = computed(() => มุม.value.ภาษาเดิม && !ฉบับที่แสดง.value.length)
/**
 * ⭐⭐ **โครงแถวของตาราง** (ใบ #145) ⇒ คำเดิมลงแถวตามข้อของฉบับแปล (ตาราง `ข้อแปล` ของใบ #104 · #112)
 *   ⇒ เหลือแต่คำเดิม ⇒ ตารางยังต้องมีแถว ⇒ ใช้ข้อของฉบับตั้งต้นเป็นโครงที่ตา ⛔ ไม่เห็น
 *   ⇒ ท่าเดียวกับปุ่ม *อ่าน SBLGNT* ของทีละฉบับ (ใบ #131 note_30490) ⇒ แถวของฉบับแปลอยู่ในหน้าแต่ ⛔ ถูกวาด (`แถวคำเดิม.css`)
 *   ⇒ ⭐ เป็นฉบับตั้งต้นเสมอ ⛔ ไม่ใช่ฉบับที่เพิ่งปิด ⇒ เปิดลิงก์ `t=SBLGNT` ที่ไหนก็ได้แถวชุดเดียวกัน
 *   ⇒ ⛔ ไม่ใช่คอลัมน์ ⇒ ⛔ ไม่นับ ⛔ ไม่มีหัว ⛔ ไม่อยู่ในที่อยู่ ⇒ ทุกที่ที่นับคอลัมน์ยังใช้ `ฉบับที่แสดง`
 */
const ฉบับโครง = computed(() => {
  if (ฉบับที่แสดง.value.length || !มุม.value.ภาษาเดิม) return ฉบับที่แสดง.value
  const ตั้งต้น = ฉบับที่มี.value.includes(ฉบับตั้งต้น) ? ฉบับตั้งต้น : ฉบับที่มี.value[0]
  return ตั้งต้น ? [ตั้งต้น] : []
})
// ⭐⭐ **1 ฉบับในตาราง = 1 คอลัมน์ของที่เดียวกับหน้า** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/102)
//   ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161 ⇒ เพิ่ม = ปุ่ม *เพิ่มคอลัมน์* ในเมนู *เทียบ* · เปลี่ยนฉบับ = ตัวเลือกในหัวคอลัมน์ · เอาออก = ปุ่ม × ในหัวคอลัมน์
//     ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9) ⇒ ช่องติ๊กของทุกฉบับในเมนู *เทียบ* ⇒ ถอดแล้ว ⇒ เหตุผลอยู่หัวหัวข้อ *ปุ่มเพิ่มคอลัมน์* ข้างล่าง
//     ⇒ ⭐ ฉบับเดียวกันเปิดได้หลายคอลัมน์แล้ว ⇒ ตารางยังมีช่องเดียวต่อฉบับ ⇒ ตัวที่ซ้ำเป็นคอลัมน์ตอนเดียวกันต่อท้ายตาราง (`คอลัมน์เทียบที่เปิด`)
//   ⇒ ⭐⭐ **คอลัมน์แรกจะเปลี่ยนฉบับ ⇒ ตรึงฉบับของคอลัมน์ตอนอื่นที่ยังไม่มีฉบับของตัวเองก่อน** (ใบ #131 ข้อ 9.7 ทาง ก.)
//     ⇒ คอลัมน์ตอนอื่นที่ที่อยู่ไม่บอกฉบับ (`p=MAT.17`) ใช้ฉบับของคอลัมน์แรก ⇒ คอลัมน์แรกเปลี่ยนฉบับเมื่อไร มันเปลี่ยนตามเงียบ ๆ
//       ⇒ ขัดใบ #125 ข้อ 8 *คอลัมน์อื่นไม่ขยับ* ⇒ และทำให้ฉบับเดียวกันกลับมาเปิด 2 คอลัมน์ได้ ทั้งที่ 1 ฉบับได้ 1 คอลัมน์ (ข้อ 6.3)
//     ⇒ ⛔ `ตอนถอยหลัง` ⛔ ตรึง ⇒ มันคืนสภาพจากที่อยู่ตรงตัว ⇒ ที่อยู่ว่าว่างก็ต้องว่าง
function ตั้งฉบับ(ใหม่: string[], ตรึงเทียบ = true, ที่ใหม่?: number) {
  if (ตรึงเทียบ && ใหม่[0] !== ฉบับที่แสดง.value[0]) ตรึงฉบับของเทียบ()
  ที่คำเดิม.value = ที่ใหม่ ?? ที่คำเดิมหลังเปลี่ยน(ใหม่)
  ฉบับที่เลือก.value = ใหม่
  จำฉบับที่เลือก(ใหม่)
  จำที่คำเดิม(ที่คำเดิม.value)
}

// ---------------------------------------------------------------- ลำดับของคำภาษาเดิมในตาราง (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 2)
// ⭐⭐ **คำภาษาเดิมวางตามลำดับที่เปิด เหมือนฉบับแปล** ⇒ พี่เอมเคาะ 6 พ.ย. 2569 *ทุกคอลัมน์ทุกเวอร์ชั่นเทียบเท่ากันหมด*
//   ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 11) ⇒ ขวาติดคอลัมน์แรกเสมอ ⇒ เปิด TCV · LSV แล้วติ๊กคำเดิม ⇒ คำเดิมแทรกกลาง ⇒ LSV ถูกดันไปขวา
//   ⇒ ⭐ เก็บเป็น *จำนวนฉบับแปลที่อยู่ซ้ายของคำเดิม* (`ที่คำเดิม`) ⇒ ⛔ ใส่คำเดิมลงรายชื่อฉบับ ⇒ ทุกที่ที่นับฉบับแปล (เสียง · ย่อหน้า · หัวข้อ) ⛔ ต้องรู้จักมัน
//   ⇒ ติ๊กคำเดิม ⇒ ต่อท้ายตาราง · ติ๊กฉบับหลังจากนั้น ⇒ ต่อท้ายหลังคำเดิม · ปิดหรือย้ายฉบับที่อยู่ซ้าย ⇒ คำเดิมขยับตามช่องที่ว่าง
//   ⇒ เปลี่ยนฉบับในช่องเดิม ⇒ คำเดิมอยู่ที่เดิม ⇒ ที่อยู่ `t=TCV,SBLGNT,LSV` บอกลำดับเต็ม (ข้อ 5)
/** จำนวนฉบับแปลในตารางที่อยู่ซ้ายของคอลัมน์คำภาษาเดิม ⇒ ค่าดิบ ⇒ ใช้ผ่าน `ตำแหน่งคำเดิม` */
const ที่คำเดิม = ref(1)
/** ⭐ ตำแหน่งจริง ⇒ ⛔ เกินจำนวนฉบับแปลในตาราง */
const ตำแหน่งคำเดิม = computed(() => Math.max(0, Math.min(ที่คำเดิม.value, ฉบับที่แสดง.value.length)))
/** ⭐ ชื่อแทนคอลัมน์คำภาษาเดิมในลำดับของตาราง ⇒ ตัวเดียวกับค่าของ `ฉบับที่ดู` ตอนเลือกอ่านคำเดิม ⇒ ⛔ ชนรหัสฉบับ */
const คำเดิมในลำดับ = 'คำเดิม'
/** ⭐ ลำดับทุกคอลัมน์ของตารางจากซ้ายไปขวา ⇒ ฉบับแปล + คำภาษาเดิม (`คำเดิม`) ที่ตำแหน่งของมัน */
const ลำดับตาราง = computed(() => {
  const ล = [...ฉบับที่แสดง.value]
  if (มุม.value.ภาษาเดิม) ล.splice(ตำแหน่งคำเดิม.value, 0, คำเดิมในลำดับ)
  return ล
})
/**
 * ⭐ รายชื่อฉบับแปลชุดใหม่ ⇒ คำเดิมไปอยู่ตรงไหน ⇒ ฉบับที่อยู่ซ้ายคำเดิมยังอยู่ซ้าย ⇒ ฉบับใหม่นับตามช่องที่มันไปนั่ง
 *   ⇒ ปิดฉบับซ้าย ⇒ ขยับซ้าย 1 · ติ๊กฉบับใหม่ (ต่อท้าย) ⇒ ไปขวาของคำเดิม · เปลี่ยนฉบับในช่องเดิม ⇒ ข้างเดิม
 */
function ที่คำเดิมหลังเปลี่ยน(ใหม่: string[]): number {
  const เดิม = ฉบับที่แสดง.value
  const P = ตำแหน่งคำเดิม.value
  return ใหม่.filter((x, i) => {
    const k = เดิม.indexOf(x)
    return k >= 0 ? k < P : i < P
  }).length
}
/** ⭐ คอลัมน์ตอนอื่นที่ยังไม่มีฉบับของตัวเอง ⇒ เขียนฉบับที่มันแสดงอยู่ตอนนี้ลงไป ⇒ หน้าตา ⛔ ไม่เปลี่ยน */
function ตรึงฉบับของเทียบ() {
  if (!คอลัมน์เทียบที่เปิด.value.some((ค) => !ค.ฉบับ)) return
  คอลัมน์เทียบที่เปิด.value = คอลัมน์เทียบที่เปิด.value.map((ค) => (ค.ฉบับ ? ค : { ...ค, ฉบับ: ฉบับของเทียบ(ค) }))
}
/**
 * ⭐ อ่าน `t` ⇒ ฉบับแปลของตาราง + เปิดคำภาษาเดิมไหม (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 5)
 *   ⇒ ชื่อตัวบทภาษาเดิม (`SBLGNT` `WLC`) ⇒ เปิดคำเดิม ⇒ ⛔ ไม่ใช่ฉบับแปล ⇒ ไม่เข้ารายชื่อฉบับ
 *   ⇒ `มี` = ที่อยู่บอกชุดของตารางจริง ⇒ ⛔ มี ⇒ ใช้ความชอบในเครื่องเหมือนเดิม ⇒ ลิงก์เก่ายังเปิดได้
 *   ⇒ ⛔ ไม่มีชื่อตัวบท ⇒ คำเดิมเป็นไปตามความชอบในเครื่องเหมือนก่อนใบนี้ ⇒ ลิงก์เก่า ⛔ ปิดคำเดิมของคนเปิด
 */
function ฉบับของตารางจากที่อยู่(ค่า: unknown): { ฉบับ: string[]; คำเดิม: boolean; ที่: number; มี: boolean } {
  const ทั้งหมด = อ่านฉบับในที่อยู่(ค่า)
  // ⭐ ก้อน ข. ⇒ ลำดับของคำเดิม = จำนวนฉบับแปลที่เขียนไว้ซ้ายของชื่อตัวบท ⇒ `t=TCV,SBLGNT,LSV` ⇒ 1
  const ใช้ได้ = ทั้งหมด.filter((x) => ฉบับที่มี.value.includes(x) || ชื่อตัวบทเดิมทั้งหมด.includes(x))
  const ฉบับ = ใช้ได้.filter((x) => ฉบับที่มี.value.includes(x))
  const ที่ = ใช้ได้.findIndex((x) => ชื่อตัวบทเดิมทั้งหมด.includes(x))
  return { ฉบับ, คำเดิม: ที่ >= 0, ที่: Math.max(0, ที่), มี: ฉบับ.length > 0 || ที่ >= 0 }
}
/**
 * ⭐⭐ **เปลี่ยนฉบับของคอลัมน์ในตาราง ⇒ เลือกฉบับที่คอลัมน์อื่นเปิดอยู่แล้วได้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161 เกณฑ์ข้อ 7.3)
 *   ⇒ `ช่อง` ⇒ ค่าใน `ลำดับตาราง` ของหัวที่ถูกกด (รหัสฉบับ หรือ `คำเดิม`) ⇒ `ใหม่` ⇒ ค่าในช่องเลือกฉบับ (รหัสฉบับ หรือชื่อตัวบท SBLGNT · WLC)
 *   ⇒ ⭐ **แทนที่ในช่องเดิม** ⇒ คอลัมน์ที่ผู้อ่านแตะอยู่ตำแหน่งเดิม (ใบ #125 ข้อ 8) ⇒ ใบ #145 ก้อน ค. ⇒ ตัวบทภาษาเดิมก็เลือกที่นี่
 *   ⇒ ⭐ ตารางมีช่องเดียวต่อฉบับ (ข้อตรงแถว ⇒ ใบ #125 ข้อ 20) ⇒ ฉบับที่เลือกอยู่ในตารางแล้วที่ช่องอื่น
 *     ⇒ **ช่องอื่นนั้นออกไปเป็นคอลัมน์ตอนเดียวกันต่อท้ายตาราง** ⇒ ได้ฉบับเดียวกัน 2 คอลัมน์ ⇒ ⛔ ไม่มีคอลัมน์หาย ⛔ ไม่ปิดอะไรเอง
 *   ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9.7 ทาง ก.) ⇒ ฉบับที่คอลัมน์อื่นใช้อยู่ล็อกในตัวเลือก ⇒ 1 ฉบับได้ 1 คอลัมน์
 */
function เปลี่ยนช่องตาราง(ช่อง: string, ใหม่: string) {
  const ลำดับ = ลำดับตาราง.value
  const p = ลำดับ.indexOf(ช่อง)
  if (p < 0) return
  const เป็นตัวบท = ชื่อตัวบทเดิมทั้งหมด.includes(ใหม่)
  if (!เป็นตัวบท && !ฉบับที่มี.value.includes(ใหม่)) return
  const ค่า = เป็นตัวบท ? คำเดิมในลำดับ : ใหม่
  if (ค่า === ช่อง) return
  const q = ลำดับ.indexOf(ค่า)
  เริ่มก้าว()
  const ใหม่ลำดับ = ลำดับ.map((x, i) => (i === p ? ค่า : x)).filter((_, i) => i !== q)
  // ⭐ ช่องที่ถือฉบับนี้อยู่ก่อน ⇒ ออกไปเป็นคอลัมน์ตอนเดียวกัน ⇒ ไปหน้าคอลัมน์ตอนอื่นที่มีอยู่ ⇒ ใกล้ที่เดิมที่สุดเท่าที่ตารางยอม
  if (q >= 0) {
    const ออก = ค่า === คำเดิมในลำดับ ? หัวคำเดิม.value.ตัวบท : ค่า
    ตรึงฉบับของเทียบ()
    คอลัมน์เทียบที่เปิด.value = [{ เล่ม: รหัสเล่ม, บท: บทของคอลัมน์แรก(), ฉบับ: ออก }, ...คอลัมน์เทียบที่เปิด.value]
  }
  const ฉบับ = ใหม่ลำดับ.filter((x) => x !== คำเดิมในลำดับ)
  const ที่ = ใหม่ลำดับ.indexOf(คำเดิมในลำดับ)
  const ดู = มุม.value.ฉบับที่ดู
  const ดูช่องนี้ = ดู === ช่อง || (ช่อง === คำเดิมในลำดับ && ดู === ดูคำเดิม)
  const ดูช่องที่ออก = q >= 0 && (ดู === ค่า || (ค่า === คำเดิมในลำดับ && ดู === ดูคำเดิม))
  ตั้งฉบับ(ฉบับ, true, ที่ >= 0 ? ที่ : undefined)
  มุม.value = {
    ...มุม.value,
    ภาษาเดิม: ที่ >= 0,
    ...(ดูช่องนี้ ? { ฉบับที่ดู: ค่า === คำเดิมในลำดับ ? ดูคำเดิม : ค่า } : ดูช่องที่ออก ? { ฉบับที่ดู: 'เทียบ:0' } : {}),
  }
  if (q >= 0) for (const ค of คอลัมน์เทียบที่เปิด.value) void หยิบของเทียบ(ค)
  ปรับที่อยู่()
  void nextTick(() => โฟกัสฉบับในตาราง(ค่า))
}
/**
 * ⭐ ใบ #161 ⇒ หัวถูกวาดใหม่เมื่อฉบับเปลี่ยน (`key` ผูกกับฉบับ) ⇒ โฟกัสหลุดไป `body` ⇒ คืนให้ช่องเลือกฉบับของหัวในช่องเดิม
 *   ⇒ ผู้อ่านอยู่ที่เดิมในลำดับ Tab ⇒ WCAG 2.2 SC 2.4.3 ⇒ ⛔ แตะเมื่อโฟกัสยังอยู่ที่อื่น (ผู้อ่านไปต่อแล้ว)
 */
function โฟกัสฉบับในตาราง(ค่า: string) {
  if (import.meta.server || (document.activeElement && document.activeElement !== document.body)) return
  const ที่ = ค่า === คำเดิมในลำดับ ? '[data-ชื่อคำเดิม]' : `.pk-หัวคอลัมน์ .pk-ช่องหัว[data-ฉบับ="${ค่า}"]`
  const ช่อง = [...document.querySelectorAll<HTMLSelectElement>(`${ที่} .pk-ช่องเลือกฉบับ`)].find((x) => x.getClientRects().length)
  ช่อง?.focus({ preventScroll: true })
}

// ---------------------------------------------------------------- มุมมอง
const มุม = ref<มุมมอง>({ ...มุมมองตั้งต้น })

// ---------------------------------------------------------------- จอแคบอ่านทีละฉบับ
// ⭐⭐ **จอแคบวางหลายฉบับเรียงข้างกัน ⛔ ไม่ได้ ⇒ จึงอ่านทีละฉบับ** (ใบงาน v3/phrakham#76)
//   **วัดเอง 7 ก.ย. 2569** ⇒ จอ 412 · ตัวอักษร 200% · 4 ฉบับซ้อนกัน ⇒ **ข้อเดียวสูง 1243 จุด**
//     ⇒ สูงกว่าจอ (915 จุด) ⇒ ⛔ **มองข้อเดียวเทียบ 4 ฉบับพร้อมกันไม่ได้อยู่แล้ว**
//   ⇒ และ Bible Gateway ที่ดันคอลัมน์ทั้ง 4 ลงจอ 412 ⇒ ได้คอลัมน์ละ ~100 จุด ⇒ บรรทัดละ 2 คำ
//
// ⭐ **ผู้อ่านรู้ว่ากำลังอ่านฉบับไหนจากปุ่ม `ฉบับ` บนแถบบนที่หนึบอยู่** ⇒ ⛔ ไม่ใช่ป้ายต่อบรรทัด
//   ⇒ ปุ่มนั้นมีอยู่แล้ว ⇒ **แถบหนึบจึง ⛔ ไม่สูงขึ้นเลยบนจอแคบ**
// ⛔ **ต้องรู้ความกว้างจอในโค้ด ⛔ ไม่ใช่แค่ใน CSS** — ตัวเลือก *ดูฉบับไหน* มีความหมาย
//   เฉพาะจอแคบ ⇒ โผล่บนจอกว้างเมื่อไร มันก็กลายเป็นปุ่มที่กดแล้วไม่เกิดอะไร ซึ่งใบนี้ห้ามไว้เอง
// ⭐ **768 คือเส้นแบ่งเดียวกับที่ `main.css` ใช้** ⇒ ⛔ ไม่ตั้งเส้นใหม่ของตัวเอง
//   ⛔ ตอนสร้างหน้ายังไม่มีจอ ⇒ ตั้งต้นว่า *กว้าง* ⇒ หน้าที่สร้างไว้จึงมีเนื้อครบทุกฉบับเสมอ
const จอแคบ = ref(false)
let ตัววัดจอ: MediaQueryList | undefined
let ตัวเฝ้าแถบ: ResizeObserver | undefined

/** ⭐ ค่าของ `ฉบับที่ดู` ตอนเลือกอ่านคอลัมน์คำภาษาเดิมบนจอแคบแบบทีละฉบับ ⇒ ⛔ ชนกับรหัสฉบับ (ตัวอักษรละติน) */
const ดูคำเดิม = 'คำเดิม'

// ---------------------------------------------------------------- จอแคบวางคอลัมน์ยังไง (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30367)
// ⭐⭐ **พี่เอมเคาะ 3 พ.ย. 2569** ⇒ *"การที่ดูบนล่างมันดูยากกว่าซ้ายขวา ... ต้องมีให้เลือกว่าแล้วแต่คนแต่ละคนชอบแบบไหน"*
//   ⇒ 3 แบบ ⇒ **ซ้ายขวา** (ค่าตั้งต้น) · **บนล่าง** · **ทีละฉบับ** ⇒ ปุ่มกลมกลุ่มเดิมในเมนู *เทียบ* ⇒ จำไว้ในเครื่องแบบขนาดตัวอักษร
//   ⇒ ⭐ **กติกาเดียวทุกคอลัมน์** (ข้อ 5) ⇒ ฉบับในตาราง · คอลัมน์ที่เปิดคนละเล่มคนละบท · คำภาษาเดิม
//     ⇒ ⭐ ชิ้นที่ 3 (note_30490) ⇒ คำภาษาเดิมนับใน `กี่คอลัมน์ข้างกัน` ⇒ เส้นตัดสิน ป้ายบนล่าง และเหตุผลใช้ของชุดนี้ทั้งหมด
//   ⇒ ⭐⭐ **ซ้ายขวาแคบจนคำขาดกลางคำ ⇒ ย่อตัวหนังสือของคอลัมน์ให้พอก่อน** (@krisada เคาะ 20 พ.ย. 2569 ⇒ แทนข้อ 4 เดิม)
//     ⇒ ย่อเท่าที่จำเป็นพอดี ⇒ ⛔ ให้ตัวบทเล็กกว่า 12 จุด (เกณฑ์ *legible font sizes* ของ Google Lighthouse) ⇒ ตัวคิดคือ `ย่อที่ต้องการ`
//     ⇒ ⛔ เขียนลงขนาดที่ผู้อ่านตั้งใน Aa ⇒ จอกว้างขึ้น · ปิดคอลัมน์ · เลือกบนล่างหรือทีละฉบับ ⇒ ได้ขนาดของเขาคืนเอง
//     ⇒ ย่อถึง 12 จุดแล้วยังไม่พอ ⇒ เว็บวางบนล่างเองแบบเดิม ⇒ มีตัวหนังสือบอกเหตุผลข้างตัวเลือก
//     ⇒ ⛔ ไม่เขียนทับค่าที่ผู้อ่านเลือก ⇒ ค่าที่จำไว้ยังเป็นซ้ายขวา ⇒ ที่ว่างพอเมื่อไรได้ซ้ายขวาคืนเอง ⇒ Nielsen ข้อ 3
//   ⇒ เหตุผลเต็มกับตารางที่วัดอยู่ที่ `docs/เคาะ/หน้าจอกับการอ่าน.md` หัวข้อ *การวางคอลัมน์บนจอแคบ* ⛔ ไม่จดซ้ำที่นี่

/** ⭐ คอลัมน์ทั้งหมดที่ต้องวางข้างกันถ้าเป็นซ้ายขวา ⇒ ฉบับในตาราง + คำภาษาเดิม + คอลัมน์ที่เปิดคนละเล่มคนละบท
 *  ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30490 ⇒ คำภาษาเดิมเป็นคอลัมน์ธรรมดาแล้ว ⇒ นับ 1 คอลัมน์
 *    ⇒ ⚠️ ของเดิม (ใบ #124) ⇒ จอแคบวางคำเดิมใต้แต่ละข้อเสมอ ⇒ ⛔ ไม่นับ ⇒ ตอนนี้ใต้แต่ละข้อเหลือเฉพาะบนล่าง (ดู `ทางคำเดิมจอแคบ`) */
const กี่คอลัมน์ข้างกัน = computed(
  () => ฉบับที่แสดง.value.length + (มุม.value.ภาษาเดิม ? 1 : 0) + คอลัมน์เทียบที่เปิด.value.length,
)

/** ไม้บรรทัดของเส้นตัดสินซ้ายขวา ⇒ ความยาวเป็น `em` ของตัวบท ⇒ เลขอยู่ที่ `main.css` ที่เดียว (`.pk-ไม้บรรทัดซ้ายขวา`) */
const ไม้บรรทัดซ้ายขวา = ref<HTMLElement | null>(null)
const ไม้บรรทัดเลขข้อ = ref<HTMLElement | null>(null)
// ⭐⭐ **ทุกค่าที่วัดได้ เก็บเป็นขนาด *ก่อนย่อ* (ย่อ = 1)** (@krisada 20 พ.ย. 2569) ⇒ ดู `วัดที่ว่าง`
//   ⇒ ตัวหนังสือที่ย่ออยู่ทำให้ไม้บรรทัดสั้นลงเอง (มันเป็น `em`) ⇒ วัดแล้วหารด้วยสัดส่วนที่ย่ออยู่ตอนวัด ⇒ ได้ค่าเดิมทุกครั้ง
//   ⇒ ⛔ วัด ⇒ ย่อ ⇒ วัดใหม่ได้ที่ว่างเพิ่ม ⇒ ขยาย ⇒ วัดใหม่ไม่พอ ⇒ ย่อ ⇒ **⛔ วนไม่จบ**
/** ตัวบท 6em ที่ย่อ = 1 ⇒ ส่วนที่โตตามตัวหนังสือของไม้บรรทัดซ้ายขวา */
const ตัวบทขั้นต่ำก่อนย่อ = ref(0)
/** ช่องไฟระหว่างคอลัมน์ ⇒ `--pk-ช่องคอลัมน์` เป็น `rem` ⇒ ⛔ ย่อตามตัวหนังสือของคอลัมน์ */
const ช่องไฟคอลัมน์ = ref(0)
/** ช่องเลขข้อ 2.4em ที่ย่อ = 1 */
const ช่องเลขข้อก่อนย่อ = ref(0)
/** ตัวบทของคอลัมน์ที่ย่อ = 1 (จุด) ⇒ ใช้คิดพื้น 12 จุด */
const ขนาดตัวบทก่อนย่อ = ref(0)
let ตัวเฝ้าไม้บรรทัดซ้ายขวา: ResizeObserver | undefined

/**
 * ⭐⭐ **หัวแถวเดียวที่ย่อเท่านี้กว้างเท่าไร** ⇒ ⛔ ย่อตามตัวหนังสือตรง ๆ ⇒ ⛔ คิดเป็นสูตร
 *   ⇒ ⚠️ วัดเองแล้ว 20 พ.ย. 2569 ⇒ ในหัวมีของหลายแบบ ⇒ ตัวหนังสือกับช่องไฟใน `em` ย่อตาม · ปุ่มต่ำสุด 44 จุด (SC 2.5.8) ทั้งที่ตัวปุ่มและที่ป้ายข้างใน
 *     · ช่องไฟ `rem` · เส้นขอบ ⛔ ย่อ · ตัวหนังสือในหัวหยุดที่ 12 จุด (`max(12px, …)`) ⇒ สูตรที่ลองมา 3 แบบเดาผิดทุกแบบ
 *     ⇒ จอ 320 ตัวอักษร 200% ⇒ วัดที่ขนาดหนึ่งบอกว่าย่อเท่านี้พอ ⇒ ย่อแล้ววัดใหม่บอกไม่พอ ⇒ สลับไปมาทุก 0.1 วินาทีไม่จบ
 *   ⇒ ⭐ จึงวัดหัวจริงที่ขั้นย่อตายตัว (`วัดหัวทุกขั้น`) ⇒ ระหว่างขั้นลากเส้นตรง ⇒ หัวกว้างขึ้นแบบโค้งหงาย ⇒ เส้นตรงเดาเกินนิดเดียว ⇒ ปลอดภัย
 *   ⇒ ⭐ ตารางเดียวกันไม่ว่าวัดตอนย่ออยู่เท่าไร ⇒ คำตอบเดิมทุกครั้ง ⇒ ⛔ วน
 */
const หัวตามย่อ = ref<[number, number][]>([])
function กว้างหัวที่ย่อ(ย่อ: number): number {
  const ต = หัวตามย่อ.value
  if (!ต.length) return 0
  if (ย่อ <= ต[0]![0]) return ต[0]![1]
  for (let i = 1; i < ต.length; i++) {
    const [ก, หก] = ต[i - 1]!
    const [ข, หข] = ต[i]!
    if (ย่อ <= ข) return หก + ((หข - หก) * (ย่อ - ก)) / (ข - ก)
  }
  return ต[ต.length - 1]![1]
}

/**
 * ⭐⭐ **ที่ว่างพอวางซ้ายขวาโดยคำไม่ขาดไหม ⇒ ที่ย่อเท่านี้** (note_30367 ข้อ 4)
 *   ⇒ ช่องตัวบทของแต่ละคอลัมน์ = (หน้าอ่าน − ช่องเลขข้อ) ÷ จำนวนคอลัมน์ − ช่องไฟ ⇒ ต้องไม่แคบกว่า `6em` ของตัวบท
 *   ⇒ `6em` คือผลวัดของ !161 ⇒ ฉบับอังกฤษไม่มีคำขาดตั้งแต่ 6em · 5.5em ขาด 2 คำ (Jehoshaphat)
 *     ⇒ วัดซ้ำบนหน้าจริงในชิ้นนี้ ⇒ ตารางอยู่ที่ `docs/ข้อมูล/การวางคอลัมน์จอแคบ.md`
 *   ⇒ ⭐ คิดจากไม้บรรทัด 2 อัน ⇒ ตัวอักษรใหญ่ขึ้นไม้บรรทัดยาวขึ้นเอง ⇒ ⛔ ไม่ต้องฟังปุ่ม ก+ ก− แยก
 *   ⇒ ⭐ หน้าอ่านกว้างเท่าเดิมไม่ว่าย่อเท่าไร ⇒ ช่องข้างของหน้าเป็นจุด (`px`) และย่อแค่ในคอลัมน์ ⇒ ⛔ ขึ้นกับตัวหนังสือ
 *   ⇒ ⭐ หัวมี 2 ท่า ⇒ ดูหัวข้อ `หัวตรงคอลัมน์พอ` ข้างล่าง
 */
function พอที่ย่อ(ย่อ: number, เข้ม = false) {
  const n = กี่คอลัมน์ข้างกัน.value
  const ว = กว้างหน้าอ่าน.value + 1e-6
  const เลขข้อ = ช่องเลขข้อก่อนย่อ.value * ย่อ
  const ต่อคอลัมน์ = ตัวบทขั้นต่ำก่อนย่อ.value * ย่อ + ช่องไฟคอลัมน์.value
  const หัว = กว้างหัวที่ย่อ(ย่อ)
  const ตัวบทพอ = ว >= เลขข้อ + n * ต่อคอลัมน์
  const ตรงคอลัมน์ = ว >= เลขข้อ + n * Math.max(ต่อคอลัมน์, หัว + ช่องไฟคอลัมน์.value)
  // ⭐ ใบ #164 ⇒ คอลัมน์ฉบับซ้ำที่อยู่ที่เดียวกับหน้าเป็นช่องในตารางแล้ว ⇒ ยังใช้เงื่อนไขของกล่องที่เข้มกว่า (หักช่องเลขข้อเต็ม ≥ ช่องไฟ)
  //   ⇒ จอที่เคยได้ซ้ายขวาก็ยังได้ · จอที่เคยเป็นบนล่างก็ยังบนล่าง ⇒ การตัดสินการวาง ⛔ เปลี่ยนในใบนี้
  // ⭐ `เข้ม` (ตอนหาค่าย่อ) ⇒ หัวของกล่องคนละบท ⛔ กินช่องไฟระหว่างกล่อง ⇒ ช่องไฟเต็มทุกช่อง
  //   ⇒ ⚠️ วัดเองแล้ว 20 พ.ย. 2569 ⇒ ย่อเท่าที่พอดีเป๊ะ ⇒ หัวกินช่องไฟเกือบครึ่ง ⇒ ปุ่มของสองหัวห่าง 7.4 จุด
  //     ⇒ ต่ำกว่า 1.5 เท่าของช่องไฟปุ่มที่ `tools/ด่านเส้นแบ่งคอลัมน์.mjs` ข้อ ② ตั้งไว้ ⇒ ย่อเพิ่มอีกนิดแทนการกินช่อง
  //   ⇒ ⛔ เข้ม (ย่อ = 1) ⇒ เงื่อนไขเดิมทุกตัว ⇒ จอที่เคยได้ซ้ายขวาโดยไม่ย่อยังได้เหมือนเดิม
  const เต็มแถว = คอลัมน์เทียบที่เปิด.value.length
    ? ว - เลขข้อ >= n * หัว + (เข้ม ? (n - 1) * ช่องไฟคอลัมน์.value : 0)
    : ว >= n * หัว + (n - 1) * ช่องไฟคอลัมน์.value
  return { ตรงคอลัมน์, พอ: ตัวบทพอ && (ตรงคอลัมน์ || เต็มแถว) }
}

/** ⛔ ยังไม่ได้วัด (ยังไม่ได้ขึ้นหน้า) ⇒ ถือว่าพอ ⇒ หน้าที่สร้างไว้ล่วงหน้าเป็นจอกว้างอยู่แล้ว */
const ซ้ายขวาพอ = computed(() => !ตัวบทขั้นต่ำก่อนย่อ.value || พอที่ย่อ(1).พอ)

/** ⭐ **พื้น 12 จุด** ⇒ เกณฑ์ *Uses legible font sizes* ของ Google Lighthouse ⇒ ตัวหนังสือต่ำกว่า 12 จุด (CSS px) นับว่าอ่านยาก
 *    ⇒ WCAG ⛔ กำหนดขนาดต่ำสุด ⇒ @krisada เคาะใช้เส้นนี้ 20 พ.ย. 2569 ⇒ ตัวเฝ้า `tools/ด่านวางคอลัมน์จอแคบ.mjs` ข้อ ③ ⑫ */
const ตัวบทเล็กสุด = 12
/** ย่อได้ต่ำสุดเท่าไร ⇒ ตัวบทเหลือ 12 จุดพอดี */
const พื้นย่อ = computed(() => (ขนาดตัวบทก่อนย่อ.value ? Math.min(1, ตัวบทเล็กสุด / ขนาดตัวบทก่อนย่อ.value) : 1))

/**
 * ⭐⭐ **ย่อตัวหนังสือของคอลัมน์เท่าไร ⇒ ตามสูตร** ⇒ 1 = ⛔ ย่อ · `null` = ย่อถึงพื้นแล้วยังไม่พอ ⇒ วางบนล่างเอง
 *   ⇒ ⭐ คิดจากสูตร ⛔ ลองย่อบนหน้าแล้ววัด ⇒ ทุกค่าเป็นขนาดก่อนย่อ
 *   ⇒ ความกว้างทุกชิ้นโตตามย่อ (หรือคงที่) ⇒ *พอ* เป็นจริงตั้งแต่ย่อค่าหนึ่งลงไป ⇒ หาค่าใหญ่สุดที่พอด้วยการแบ่งครึ่ง
 *   ⇒ ปัดลงทีละ 1% ⇒ ตัวเลขนิ่ง ⇒ ⛔ ขยับเศษจุดไปมา
 *   ⇒ ⭐ พื้นนับที่ตัวบท (ตัวหนังสือหลักของคอลัมน์) ⇒ ของที่เล็กกว่าตัวบท (เลขข้อ · ป้าย) ⇒ `main.css` ตรึงไว้ไม่ต่ำกว่า 12 จุดเอง
 *   ⇒ ⭐ ไม้บรรทัดกับหัวคอลัมน์แยกส่วนที่ย่อกับส่วนคงที่ไว้แล้ว ⇒ วัดที่ย่อไหนก็ได้สูตรเดียวกัน ⇒ ⛔ วัด ⇒ ย่อ ⇒ วัดใหม่ ⇒ ขยาย ⇒ วน
 */
const ย่อตามสูตร = computed<number | null>(() => {
  if (!จอแคบ.value || กี่คอลัมน์ข้างกัน.value <= 1 || มุม.value.วางคอลัมน์ !== 'ซ้ายขวา') return 1
  if (ซ้ายขวาพอ.value) return 1
  const ต่ำสุด = พื้นย่อ.value
  if (!พอที่ย่อ(ต่ำสุด, true).พอ) return null
  let พอ = ต่ำสุด
  let ไม่พอ = 1
  for (let i = 0; i < 20; i++) {
    const กลาง = (พอ + ไม่พอ) / 2
    if (พอที่ย่อ(กลาง, true).พอ) พอ = กลาง
    else ไม่พอ = กลาง
  }
  // ⭐ ปัดลง ⇒ ยังพอ · ⛔ ต่ำกว่าพื้น ⇒ ใช้พื้นพอดี
  return Math.max(ต่ำสุด, Math.floor(พอ * 100) / 100)
})

/** ⭐ ค่าที่หน้าใช้ ⇒ ตามสูตรตรง ๆ ⇒ ชื่อแยกไว้ให้ส่วนอื่นอ่าน (`วางที่ใช้` · `ย่อที่ใช้`) */
const ย่อที่ต้องการ = ย่อตามสูตร
/** ⭐ ย่อที่หน้าใช้จริง ⇒ `--pk-ย่อจอแคบ` บน `.pk-คอลัมน์` ⇒ ⛔ ย่อ ⇒ 1 */
const ย่อที่ใช้ = computed(() => ย่อที่ต้องการ.value ?? 1)
/** ⭐ ผู้อ่านเลือกซ้ายขวา ⇒ หน้าย่อตัวหนังสือให้ ⇒ ตัวหนังสือบอกขึ้นใต้ตัวเลือก */
const ย่อให้ซ้ายขวา = computed(() => ย่อที่ใช้.value < 1)

/**
 * ⭐⭐ **หัวแถวเดียว 3 ปุ่มต้องพอด้วย** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30489) ⇒ วางหัวได้ 2 ท่า
 *   ⇒ ท่าแรก ⇒ หัวอยู่ตรงคอลัมน์ของมันพอดี ⇒ ช่องละ max(ตัวบท 6em, หัวขั้นต่ำ + ช่องไฟ) ⇒ ช่องไฟ = ไม้บรรทัดลบ 6em ⇒ ⛔ ไม่ตั้งเลขใหม่
 *   ⇒ ท่าที่สอง ⇒ ตรงคอลัมน์ไม่พอ ⇒ หัวแบ่งทั้งแถวเท่ากัน **รวมที่เหนือช่องเลขข้อ** (`pk-หัวเต็มแถว` ใน `main.css`)
 *     ⇒ เหนือช่องเลขข้อไม่มีอะไรให้หัวบอก ⇒ ⛔ เสียอะไร ⇒ หัวขยับซ้ายไม่เกินครึ่งช่องเลขข้อ ⇒ ยังอยู่เหนือคอลัมน์ของมันเกือบทั้งหัว
 *     ⇒ ⭐ ที่มา ⇒ ด่าน `ด่านขนานกันจอแคบ` ข้อ ⑨ (พี่เอม *"อยู่ใน mobile mode ก็เห็นเป็น 2 คอลัมน์"*) ⇒ หัวตรงคอลัมน์ทำให้จอ 360 ทุกคู่ฉบับเป็นบนล่าง
 *       ⇒ วัดแล้ว 4 พ.ย. 2569 ⇒ จอ 360 ตัวอักษร 100% ⇒ คอลัมน์ละ 133 จุด · หัวขั้นต่ำ TCV 135 · WEB 141 · THKJV 154 ⇒ แบ่งทั้งแถวได้หัวละ 160
 *     ⇒ มีคอลัมน์คนละเล่มคนละบท ⇒ หัวของมันอยู่ในกล่องของมันเอง ⇒ แบ่งแถวร่วมกันไม่ได้ ⇒ หัวในกล่องนั้นยื่นซ้ายกินช่องไฟระหว่างกล่อง (`main.css`)
 *       ⇒ ฝั่งหลักได้ช่องเลขข้อไปเต็ม ⇒ เงื่อนไขเหลือ ⇒ หน้าอ่านลบช่องเลขข้อ ≥ จำนวนคอลัมน์ × หัวขั้นต่ำ
 *       ⇒ ⭐ ที่มา ⇒ ท่อของ !168 ⇒ จอ 375 TCV กับคอลัมน์ WEB คนละบท ⇒ หัวตรงคอลัมน์เหลือที่ 1 จุด ⇒ ตัวหนังสือบนลินุกซ์กว้างกว่าวินโดวส์นิดเดียวก็เป็นบนล่าง
 *         ⇒ กินช่องไฟได้เพิ่ม 8 จุด ⇒ ⛔ แขวนอยู่บนเศษจุดของฟอนต์แต่ละเครื่องแล้ว
 *   ⇒ ⚠️ การตัดสินของคนทำ ⇒ รอพี่เอมเคาะ ⇒ เหตุผลเต็มอยู่ใน `docs/เคาะ/หน้าจอกับการอ่าน.md` หัวข้อ *หัวคอลัมน์แถวเดียวทุกจอ* ข้อ 5
 */
//   ⇒ ⭐ 20 พ.ย. 2569 ⇒ เงื่อนไขทั้ง 2 ท่าย้ายเข้า `พอที่ย่อ` ⇒ คิดที่ย่อเท่าไรก็ได้ ⇒ ที่นี่อ่านผลที่ย่อที่หน้าใช้จริง
const หัวตรงคอลัมน์พอ = computed(() => !ตัวบทขั้นต่ำก่อนย่อ.value || พอที่ย่อ(ย่อที่ใช้.value).ตรงคอลัมน์)

/** ⭐ แบบที่หน้าใช้จริงตอนนี้ ⇒ `null` = ไม่มีอะไรให้วาง (จอกว้าง หรือมีคอลัมน์เดียว) */
const วางที่ใช้ = computed<แบบวางจอแคบ | null>(() => {
  if (!จอแคบ.value || กี่คอลัมน์ข้างกัน.value <= 1) return null
  const เลือก = มุม.value.วางคอลัมน์
  // ⭐ 20 พ.ย. 2569 ⇒ ย่อแล้วพอ ⇒ ยังซ้ายขวา ⇒ บนล่างเองเฉพาะตอนย่อถึงพื้น 12 จุดแล้วยังไม่พอ (`ย่อที่ต้องการ` = null)
  return เลือก === 'ซ้ายขวา' && ย่อที่ต้องการ.value === null ? 'บนล่าง' : เลือก
})
/** ⭐ ผู้อ่านเลือกซ้ายขวา แต่ย่อถึงพื้นแล้วก็ยังไม่พอ ⇒ เว็บวางบนล่างให้ ⇒ ตัวหนังสือบอกเหตุผลขึ้นข้างตัวเลือก */
const วางบนล่างเอง = computed(() => มุม.value.วางคอลัมน์ === 'ซ้ายขวา' && วางที่ใช้.value === 'บนล่าง')
const ซ้ายขวาอยู่ = computed(() => วางที่ใช้.value === 'ซ้ายขวา')
/** ⭐ ซ้ายขวาที่หัวตรงคอลัมน์ไม่พอ ⇒ หัวแบ่งทั้งแถว (ดู `หัวตรงคอลัมน์พอ`) */
const หัวเต็มแถว = computed(() => ซ้ายขวาอยู่.value && !หัวตรงคอลัมน์พอ.value)
const บนล่างอยู่ = computed(() => วางที่ใช้.value === 'บนล่าง')

/**
 * ⭐⭐ **คอลัมน์ที่อ่านอยู่ตอนทีละฉบับ** ⇒ ฉบับในตาราง หรือ `เทียบ:<ลำดับ>` ของคอลัมน์ที่เปิดคนละเล่มคนละบท
 *   ⇒ ⚠️ ของเดิม (ใบ #97) เลือกได้แค่ฉบับในตาราง ⇒ คอลัมน์คนละบทไปต่อท้ายใต้คอลัมน์แรกเสมอ ⇒ กติกาเดียวทุกคอลัมน์แล้ว (note_30367 ข้อ 5)
 *   ⇒ ค่าที่จำไว้ไม่มีบนหน้าแล้ว ⇒ ฉบับแรกของตาราง
 */
const ที่ดูอยู่ = computed(() => {
  const ข = ฉบับที่แสดง.value
  const ดู = มุม.value.ฉบับที่ดู
  // ⭐ ใบ #131 note_30490 ⇒ คำภาษาเดิมเลือกอ่านทีละคอลัมน์ได้เหมือนฉบับ ⇒ ปิดคำภาษาเดิมแล้ว ⇒ กลับไปฉบับแรก
  if (ดู === ดูคำเดิม && มุม.value.ภาษาเดิม) return ดู
  const i = ดู.startsWith('เทียบ:') ? Number(ดู.slice(6)) : -1
  if (i >= 0 && i < คอลัมน์เทียบที่เปิด.value.length) return ดู
  // ⭐ ใบ #145 ⇒ ตารางเหลือแต่คำเดิม ⇒ คอลัมน์แรกของตารางคือคำเดิม ⇒ ⛔ ไม่ปล่อยค่าว่างที่ทำให้ตารางถูกซ่อนทั้งฝั่ง
  if (!ข.length && มุม.value.ภาษาเดิม) return ดูคำเดิม
  return ข.includes(ดู) ? ดู : (ข[0] ?? '')
})
const ฉบับที่กำลังดู = computed(() =>
  ที่ดูอยู่.value.startsWith('เทียบ:') || ที่ดูอยู่.value === ดูคำเดิม ? '' : ที่ดูอยู่.value,
)
function ดูฉบับ(ชื่อ: string) {
  มุม.value = { ...มุม.value, ฉบับที่ดู: ชื่อ }
}
/**
 * ⭐⭐ **ฉบับในตารางวางเห็นครบทุกฉบับไหม** ⇒ ซ้ายขวา หรือบนล่าง (ใบงาน v3/phrakham#97 ⇒ ใบ #131 note_30367)
 * ⛔ **ติ๊กไว้ฉบับเดียว ⇒ ⛔ ไม่มีอะไรให้ขนาน** ⇒ ตารางวาดฉบับเดียวเหมือนเดิม
 */
const ขนานกันอยู่ = computed(
  () => ฉบับที่แสดง.value.length > 1 && (ซ้ายขวาอยู่.value || บนล่างอยู่.value),
)

/** หน้ากำลังวาดฉบับเดียวอยู่ไหม ⇒ **จอแคบวาดทีละฉบับ ยกเว้นตอนวางซ้ายขวาหรือบนล่าง** */
const กำลังแสดงฉบับเดียว = computed(
  () => (จอแคบ.value && !ขนานกันอยู่.value) || ฉบับที่แสดง.value.length <= 1,
)

/** ⭐ **จอแคบที่อ่านทีละฉบับ ⇒ เห็นหัวของคอลัมน์ที่กำลังอ่านอันเดียว** (ใบงาน #102)
 *  ⇒ ⭐ ใบ #131 ⇒ นับคอลัมน์คนละเล่มคนละบทด้วย ⇒ อ่านคอลัมน์นั้นอยู่ ⇒ ฝั่งตารางซ่อนทั้งฝั่ง */
const ทีละฉบับอยู่ = computed(() => วางที่ใช้.value === 'ทีละฉบับ')
/** ⭐ ทีละฉบับแล้วอ่านคอลัมน์คำภาษาเดิมอยู่ (ใบ #131 note_30490) ⇒ ฝั่งตารางเหลือแค่คอลัมน์คำภาษาเดิม */
const ดูคำเดิมอยู่ = computed(() => ทีละฉบับอยู่.value && ที่ดูอยู่.value === ดูคำเดิม)
/** ⭐ ทีละฉบับแล้วอ่านคอลัมน์คนละเล่มคนละบทอยู่ ⇒ ลำดับของคอลัมน์นั้น ⇒ −1 = อ่านฉบับในตาราง */
const ดูเทียบที่ = computed(() =>
  ทีละฉบับอยู่.value && ที่ดูอยู่.value.startsWith('เทียบ:') ? Number(ที่ดูอยู่.value.slice(6)) : -1,
)

/**
 * ⭐⭐ **บนล่าง + มีคอลัมน์คนละเล่มคนละบท ⇒ คู่ทีละข้อ** (note_30310 ข้อ 3 · note_30367 ข้อ 5)
 *   ⇒ มัทธิว 17:1 ⇒ มาระโก 9:1 ⇒ 17:2 ⇒ 9:2 ⇒ บทไหนหมดก่อน อีกบทเดินต่อคนเดียวจนจบ
 *   ⇒ คู่กับ **บทที่คอลัมน์แรกถูกพาไป** ⇒ ⛔ ไม่ใช่บทที่เลื่อนผ่าน ⇒ เลื่อนอ่านทะลุไปบทถัดไป ⇒ คอลัมน์แรกเดินต่อคนเดียว
 *     ⇒ ⛔ ไม่ย้ายคู่ไปบทใหม่เองระหว่างที่ผู้อ่านเลื่อนอยู่ ⇒ หลักเดียวกับ `รวมคอลัมน์ที่ตรงแถว` (Nielsen ข้อ 1)
 */
// ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ ตารางไม่มีแถวของฉบับแปลให้คู่ ⇒ คอลัมน์คนละที่อยู่กล่องของตัวเองแบบซ้ายขวา
// ⭐ ใบ #164 ⇒ ทุกคอลัมน์ตอนอื่นเป็นฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ เป็นช่องในตาราง (`เงาในตาราง`) ⇒ ซ้อนกันทีละข้อตามกฎตาราง ⇒ ⛔ มีอะไรให้คู่
const จับคู่บนล่าง = computed(
  () =>
    บนล่างอยู่.value && คอลัมน์เทียบที่เปิด.value.length > 0 && !เหลือแต่คำเดิม.value && !ซ้ำที่เดียวกันทุกคอลัมน์.value,
)

/**
 * ⭐⭐ **คำภาษาเดิมเป็นคอลัมน์ของตัวเองไหม** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30490)
 *   ⇒ พี่เอมเคาะ 3 พ.ย. 2569 ⇒ *ปฏิบัติเหมือนเป็นอีกฉบับหนึ่ง* ⇒ ได้คอลัมน์ของตัวเอง · ใช้การวางคอลัมน์ของ !165 · ⛔ ไม่เป็นกล่องใต้ข้อแบบเดิม
 *   ⇒ จอกว้าง ⇒ เป็นคอลัมน์อยู่แล้ว (ใบ #112 · #125) ⇒ ⛔ ไม่เปลี่ยน
 *   ⇒ จอแคบ ⇒ **ซ้ายขวา** ⇒ คอลัมน์ข้างคอลัมน์แรก ช่องเท่าฉบับอื่น · **ทีละฉบับ** ⇒ เป็นคอลัมน์เดียวที่เห็นเมื่อเลือกอ่านมัน
 *     ⇒ **บนล่าง** ⇒ ข้อ n ของทุกคอลัมน์อยู่ติดกัน ⇒ คำเดิมของข้อ n ต่อท้ายข้อ n พร้อมป้ายบอกภาษากับตัวบท (ใบ #124 ⇒ `ทางคำเดิมจอแคบ`)
 *       ⇒ ⚠️ การตัดสินของคนทำ ⇒ เหตุผลอยู่ใน `docs/เคาะ/หน้าจอกับการอ่าน.md` หัวข้อ *คำภาษาเดิมเป็นคอลัมน์ธรรมดา*
 *   ⇒ กฎหน้าตาอยู่ที่ `app/assets/css/แถวคำเดิม.css` ⇒ ⚠️ ของเดิมผูกกับเส้น `@media (min-width: 768px)` ⇒ ตอนนี้ผูกกับคลาสที่หน้าใส่
 */
const คำเดิมเป็นคอลัมน์ = computed(
  () =>
    มุม.value.ภาษาเดิม &&
    !คำเดิมในช่อง.value &&
    (!จอแคบ.value || ซ้ายขวาอยู่.value || ดูคำเดิมอยู่.value || เหลือแต่คำเดิม.value),
)
/**
 * ⭐⭐ **จอกว้างที่วางทุกคอลัมน์ข้างกันช่องละ 23em ไม่พอ ⇒ คำภาษาเดิมเป็นช่องหนึ่งในตารางฉบับ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 4)
 *   ⇒ พี่เอมเคาะ 7 พ.ย. 2569 ⇒ *นับภาษาเดิมเป็นคอลัมน์เหมือนฉบับอื่น แล้วใช้กฎวางข้างกันหรือซ้อนกันเดียวกันทั้งหมด*
 *   ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 1.2) ⇒ ฉบับแปลซ้อนกันในช่องแรก · คำเดิมได้ช่องเต็มของตัวเองทางขวา ⇒ คำเดิมไม่อยู่ในการนับ
 *   ⇒ ⭐ ตอนนี้คำเดิมของแต่ละแถวเป็นช่องหนึ่งใน `.pk-ช่องทั้งหมด` ของแถวนั้น ที่ตำแหน่งของมันตามลำดับที่เปิด (`ลำดับช่อง`)
 *     ⇒ ตารางฉบับใช้ `auto-fit` 23em ตัวเดิม ⇒ วางข้างกันได้กี่ช่อง ห่อลงแถวใหม่ตรงไหน ⇒ กฎเดียวกับฉบับแปลทุกช่อง
 *     ⇒ ข้อ n ของคำเดิมอยู่ในกล่องของข้อ n ⇒ ยังตรงแถว · ⛔ ไม่ต้องจับแถวเอง
 *   ⇒ ที่พอวางทุกคอลัมน์ข้างกัน (`แทรกคำเดิมได้`) ⇒ ตารางแถวของใบ #125 เหมือนเดิมทุกจุด
 *   ⇒ ยังไม่ได้วัด (`null`) ⇒ ⛔ ใช่ ⇒ หน้าตาเหมือนก่อนวัด
 */
const แทรกคำเดิมได้ = ref<boolean | null>(null)
const คำเดิมในช่อง = computed(
  () =>
    มุม.value.ภาษาเดิม &&
    !จอแคบ.value &&
    !เหลือแต่คำเดิม.value &&
    ฉบับที่แสดง.value.length > 0 &&
    แทรกคำเดิมได้.value === false,
)
/**
 * ⭐⭐ **ตารางเห็นแต่คอลัมน์คำภาษาเดิม** ⇒ ทีละฉบับที่เลือกอ่านคำเดิม (ใบ #131) · หรือเหลือแต่คำเดิมจริง ๆ (ใบ #145)
 *   ⇒ ทั้งสองแบบใช้กฎหน้าตาชุดเดียวกัน (`pk-อ่านคำเดิม` ใน `แถวคำเดิม.css`) ⇒ คำเดิมกินเต็มกว้าง ⇒ แถวของฉบับแปลไม่ถูกวาด
 *   ⇒ ทุกจอ ทุกแบบวาง (ใบ #145 ข้อ 1.1) ⇒ ⛔ ไม่ขึ้นกับเส้น 768
 */
const ตารางเห็นแต่คำเดิม = computed(() => ดูคำเดิมอยู่.value || เหลือแต่คำเดิม.value)
/** ⭐ จอแคบ ⇒ หัวของคอลัมน์คำภาษาเดิมอยู่แถวหัวที่หนึบ ข้างหัวของคอลัมน์แรก ⇒ ทุกแบบวาง ⇒ ทุกคอลัมน์เห็นชื่อของตัวเองตลอด */
// ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ ไม่มีแถวหัวของฉบับแปลให้หัวนี้ไปอยู่ ⇒ ใช้กล่องหัวของตัวเอง (`pk-ชื่อคำเดิม`) ทุกจอ
// ⭐ ใบ #145 ข้อ 4 ⇒ จอกว้างที่คำเดิมเป็นช่องในตาราง (`คำเดิมในช่อง`) ⇒ หัวของมันก็เป็นช่องในแถวหัวตามลำดับเดียวกัน
const หัวคำเดิมในแถว = computed(
  () => มุม.value.ภาษาเดิม && (จอแคบ.value || คำเดิมในช่อง.value) && !เหลือแต่คำเดิม.value,
)
/** ⭐ ทีละฉบับแล้วอ่านฉบับแปลอยู่ ⇒ คำภาษาเดิมเป็นอีกคอลัมน์ที่ไม่ได้เลือก ⇒ ⛔ วาด (ท่าเดียวกับช่องฉบับที่ไม่ได้อ่าน) */
const ซ่อนคำเดิม = computed(() => ทีละฉบับอยู่.value && !ดูคำเดิมอยู่.value)
const บทจับคู่ = ref(Number(เลขบท))
/** ป้ายเล็กหน้าข้อของตารางตอนวางบนล่าง ⇒ มีคอลัมน์คนละบท ⇒ บอกเล่มกับบทด้วย */
function ป้ายบนล่างของตาราง(ฉ: string, บท: number): string {
  return ป้ายบนล่าง(ฉ, คอลัมน์เทียบที่เปิด.value.length ? `${เล่มนี้.value.ชื่อไทย} ${บท}` : '')
}
/** ป้ายเล็กหน้าข้อของคอลัมน์คนละเล่มคนละบท ⇒ บอกเล่ม บท และฉบับเสมอ (note_30310 ข้อ 3.3) */
function ป้ายบนล่างของเทียบ(ต: { ชื่อเล่ม: string; เล่ม: string; บท: number; ฉบับ: string }): string {
  return ป้ายบนล่าง(ต.ฉบับ, `${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท}`)
}
/**
 * ⭐⭐ **บนล่าง ⇒ ข้อที่ผู้อ่านเลือกให้คอลัมน์คนละที่ คู่กับข้อที่คอลัมน์แรกอยู่** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/143)
 *   ⇒ ของเดิมคู่แถวที่ n กับแถวที่ n เสมอ ⇒ คอลัมน์แรกอยู่ 12:35 แล้วเลือกมาระโก 11:1 ให้ LSV
 *     ⇒ 11:1 ไปคู่กับ 12:1 ที่อยู่สูงพ้นจอ ⇒ บทที่ 11 สั้นกว่า ⇒ ข้างข้อ 12:35 ไม่มีข้อของ LSV เลย ⇒ คอลัมน์ที่ติ๊กไว้ไม่แสดง
 *   ⇒ ⭐ เลื่อนการคู่ ⇒ แถวของข้อที่เลือกคู่กับแถวของข้อที่คอลัมน์แรกถูกพามา (`ข้อที่พาไป` ในบทคู่)
 *     ⇒ บนล่างเลื่อนแยกกันไม่ได้ (ทุกคอลัมน์อยู่ในม้วนเดียว) ⇒ ท่านี้คือ *เลื่อนแยก* ของบนล่าง ⇒ แต่ละคอลัมน์เริ่มที่ข้อของตัวเอง
 *   ⇒ ⛔ ไม่ได้เลือกข้อ (ทั้งบท · ลิงก์เก่า) ⇒ 0 ⇒ คู่แถวต่อแถวเหมือนเดิม
 *   ⇒ ค่าบวก = ข้อของคอลัมน์นี้ที่ไม่มีแถวของบทคู่ให้คู่ ⇒ ต่อท้ายแถวแรก · ค่าลบ = แถวต้นบทคู่ยังไม่มีคู่
 */
const เลื่อนคู่ = computed<number[]>(() => {
  const แถวหลัก = บทที่แสดง.value.find((ก) => ก.บท === บทจับคู่.value)?.แถว || []
  const ข้อหลัก = บทของข้อที่พาไป.value === บทจับคู่.value ? ข้อที่พาไป.value : null
  const iหลัก = ข้อหลัก ? Math.max(0, แถวหลัก.findIndex((x) => Number(x.เลข) === ข้อหลัก)) : 0
  return คอลัมน์เทียบที่เปิด.value.map((ค, i) => {
    if (!ค.ข้อ) return 0
    const iเทียบ = คอลัมน์เทียบที่แสดง.value[i]?.แถว.findIndex((x) => Number(x.เลข) === ค.ข้อ) ?? -1
    return iเทียบ < 0 ? 0 : iเทียบ - iหลัก
  })
})
/** แถวของคอลัมน์คนละบทที่ไม่มีแถวของบทคู่ให้คู่ทางต้นบท ⇒ ต่อท้ายแถวแรก (ใบ #143) */
function แถวก่อนของเทียบ(): { ต: ก้อนเทียบ; r: number }[] {
  const out: { ต: ก้อนเทียบ; r: number }[] = []
  คอลัมน์เทียบที่แสดง.value.forEach((ต, i) => {
    for (let r = 0; r < (เลื่อนคู่.value[i] ?? 0); r++) if (ต.แถว[r]) out.push({ ต, r })
  })
  return out
}
/** แถวของคอลัมน์คนละบทที่เกินแถวของบทคู่ ⇒ ต่อท้ายหลังแถวสุดท้ายของบทคู่ (บทไหนหมดก่อน อีกบทเดินต่อ) */
function แถวเกินของเทียบ(จำนวนแถวของบทคู่: number): { ต: ก้อนเทียบ; r: number }[] {
  const out: { ต: ก้อนเทียบ; r: number }[] = []
  const มากสุด = Math.max(0, ...คอลัมน์เทียบที่แสดง.value.map((ต, i) => ต.แถว.length - (เลื่อนคู่.value[i] ?? 0)))
  for (let r = จำนวนแถวของบทคู่; r < มากสุด; r++)
    คอลัมน์เทียบที่แสดง.value.forEach((ต, i) => {
      const k = r + (เลื่อนคู่.value[i] ?? 0)
      if (k >= 0 && ต.แถว[k]) out.push({ ต, r: k })
    })
  return out
}

// ---------------------------------------------------------------- ขนาดตัวอักษร
const ขนาด = ใช้ขนาดตัวอักษร()

// ---------------------------------------------------------------- จุดที่พาไป กับม้วนที่กางอยู่
// ⭐⭐ **หน้านี้เป็นม้วนเดียว ⇒ ไม่มีขอบเขตบน ไม่มีขอบเขตล่าง** (พี่เอมเคาะ 5-6 ก.ย. 2569)
//   > *"เลือกจุดเดียว แต่คนอ่านสามารถเดินหน้าหรือถอยหลังได้อิสระ เหมือน web ebook
//   >   บท ข้อ เป็นแค่ไฟส่อง และ reference แค่นั้น"*
//   ⇒ **เลขข้อที่ผู้อ่านเลือกคือ *จุดที่พาไป* ⛔ ไม่ใช่กำแพง** ⇒ ไปถึงแล้วเลื่อนอ่านต่อได้จนจบเล่ม
//
// ⭐ **หน้าต่างของบทที่กางอยู่บอกแค่ว่า *วาดถึงไหนแล้ว*** ⛔ ไม่ใช่ช่วงที่ผู้อ่านขอ
//   ⇒ มันเลื่อนตามผู้อ่านไปเรื่อย ๆ ⇒ ⛔ ไม่มีอะไรมาหยุดมันนอกจากหัวเล่มกับท้ายเล่ม
//
// ⛔ **เก็บเป็น *ลำดับที่* ในรายการบทที่มี ⛔ ไม่ใช่เลขบท** — เล่มที่ข้อมูลยังแปลไม่ครบทุกบท
//   เลขบทจะกระโดด (เช่น 1, 2, 5) ⇒ บวกลบเลขบทตรง ๆ แล้วจะได้บทที่ ⛔ ไม่มีอยู่จริง
const ลำดับบท = computed<number[]>(() => เล่มนี้.value.บทที่มี)
const iแรก = ref(Math.max(0, ลำดับบท.value.indexOf(Number(เลขบท))))
const iท้าย = ref(iแรก.value)

// ⭐ ข้อที่พาไป ⇒ เก็บไว้ 2 อย่าง ① ติดไปกับที่อยู่เพื่อให้แชร์แล้วลงจุดเดิม ② เน้นให้ตาเห็นสักครู่
const ข้อที่พาไป = ref<number | null>(null)
const บทของข้อที่พาไป = ref(Number(เลขบท))
const ไฟส่องติด = ref(false)
let ตัวนับไฟส่อง: ReturnType<typeof setTimeout> | undefined

// ⭐⭐ **ช่วงที่ผู้อ่านเลือก** (ใบงาน #101 ข้อ 15 · 29 ⇒ ขยับโดยใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/102 ข้อ 19)
//   ⇒ ได้มาจากแผงเลือกพระธรรมแบบ *เลือกเป็นช่วง* หรือจากคำถาม `r=` ท้ายที่อยู่
//   ⇒ 🔴 **ช่วงเป็นขอบเขตของ *การแสดง* ด้วยแล้ว** ⇒ หน้าแสดงเฉพาะข้อในช่วง · ปุ่มเล่นเล่นเฉพาะช่วง
//     ⇒ พี่เอมเปลี่ยนเอง 24 ต.ค. 2569 ⇒ ของเดิม (#101) เป็นขอบเขตของการฟังอย่างเดียว
//     ⇒ ⭐ **ใต้ช่วงมีลิงก์ *อ่านทั้งบท* เสมอ** ⇒ ทางออก และตัวบอกว่ากำลังดูแค่บางช่วง (ข้อ 19.2)
//   ⇒ ⛔ **ไม่มีช่วง = แบบ *เลือกแค่ข้อเริ่ม*** ⇒ ม้วนเดียวทั้งเล่มเหมือนเดิมทุกอย่าง (ข้อ 18)
//   ⇒ เหตุผลที่เปลี่ยนการเคาะเดิม อยู่ที่ `docs/เคาะ/หน้าจอกับการอ่าน.md` ⛔ ไม่จดซ้ำที่นี่
const ช่วงที่ฟัง = ref<ช่วงฟัง | null>(null)

/**
 * ⭐ **กางบทที่ช่วงคร่อมอยู่ให้ครบ** ⇒ หน้าต่างของม้วน = บทต้นช่วงถึงบทท้ายช่วงพอดี
 *   ⇒ ⛔ ไม่ต่อบทนอกช่วงเข้ามา ⇒ `ต่อบทถัดไป` กับ `ต่อบทก่อนหน้า` หยุดเองตอนมีช่วง
 */
async function กางช่วง(ช: ช่วงฟัง): Promise<boolean> {
  const iต้น = ลำดับบท.value.indexOf(ช.จาก.บท)
  const iท้ายช่วง = ลำดับบท.value.indexOf(ช.ถึง.บท)
  if (iต้น < 0 || iท้ายช่วง < iต้น) return false
  กำลังโหลด.value = true
  const ได้ = await Promise.all(
    ลำดับบท.value.slice(iต้น, iท้ายช่วง + 1).map((c) => หยิบบท(รหัสเล่ม, c)),
  )
  กำลังโหลด.value = false
  if (ได้.some((x) => !x)) {
    คำเตือน.value = `โหลดเนื้อบทในช่วง ${แสดงช่วงฟัง(ช)} ไม่ครบ · ลองใหม่อีกครั้ง`
    return false
  }
  iแรก.value = iต้น
  iท้าย.value = iท้ายช่วง
  return true
}

/** ข้ออยู่ในช่วงไหม ⇒ ⛔ ไม่มีช่วง = อยู่เสมอ */
function อยู่ในช่วง(บท: number, ข้อ: number): boolean {
  const ช = ช่วงที่ฟัง.value
  if (!ช) return true
  if (บท < ช.จาก.บท || บท > ช.ถึง.บท) return false
  if (บท === ช.จาก.บท && ข้อ < ช.จาก.ข้อ) return false
  if (บท === ช.ถึง.บท && ข้อ > ช.ถึง.ข้อ) return false
  return true
}

/**
 * ⭐⭐ **ลิงก์ *อ่านทั้งบท*** (ข้อ 19.2) ⇒ ท่าเดียวกับ *Read full chapter* ของ Bible Gateway
 *   ⇒ ออกจากช่วงแล้ว **ยืนอยู่ที่ข้อต้นช่วงเดิม** ⇒ ผู้อ่าน ⛔ ไม่เสียที่ที่กำลังอ่าน ⇒ เลื่อนขึ้นลงอ่านต่อได้ทั้งเล่ม
 *   ⇒ ⛔ หยุดเสียงที่เล่นช่วงเดิม ⇒ คิวเดิม ⛔ ตรงกับสิ่งที่หน้าแสดงแล้ว (ท่าเดียวกับตอนเปลี่ยนช่วงในแผง)
 */
function อ่านทั้งบท() {
  const ช = ช่วงที่ฟัง.value
  if (!ช) return
  เสียง.หยุด()
  ช่วงที่ฟัง.value = null
  void ไปที่จุด({ รหัส: รหัสเล่ม, บท: ช.จาก.บท, ข้อ: ช.จาก.ข้อ })
}

/**
 * ⭐⭐ **พาตารางของคอลัมน์แรกไปบทอื่น** ⇒ ใช้กับลูกศรแถบล่าง (ปุ่ม ‹ › บนหัวคอลัมน์ถูกถอดแล้ว ⇒ ใบ #131)
 *   ⇒ ⛔ ตัวนี้ ⛔ ตัดสินว่าคอลัมน์อื่นไปด้วยไหม ⇒ คนเรียกจัดเอง (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 8 · 9)
 *   ⇒ **กำลังดูช่วงอยู่ ⇒ ออกจากช่วง แล้วไปบทเต็มที่อยู่ติดกับช่วง** ⇒ เหตุผลอยู่ใน `docs/เคาะ/หน้าจอกับการอ่าน.md`
 */
function ไปบท(c: number) {
  if (ช่วงที่ฟัง.value) {
    เสียง.หยุด()
    ช่วงที่ฟัง.value = null
  }
  return ไปที่จุด({ รหัส: รหัสเล่ม, บท: c, ข้อ: null })
}

// เนื้อของบทอื่นที่ไปหยิบมาเพิ่ม — ทั้งตอนผู้อ่านกดเลือกบทอื่น และตอนเลื่อนอ่านต่อ
const บทที่หยิบมา = ref<Record<string, ผลบท>>({ [`${รหัสเล่ม}/${เลขบท}`]: บท.value! })

async function หยิบบท(รหัส: string, c: number): Promise<ผลบท | null> {
  const กุญแจ = `${รหัส}/${c}`
  if (บทที่หยิบมา.value[กุญแจ]) return บทที่หยิบมา.value[กุญแจ]!
  try {
    const ผล = await $fetch<ผลบท>(ที่อยู่หลังบ้าน(`api/chapter/${รหัส}/${c}.json`))
    บทที่หยิบมา.value = { ...บทที่หยิบมา.value, [กุญแจ]: ผล }
    return ผล
  } catch {
    return null
  }
}

// ---------------------------------------------------------------- คอลัมน์ที่อยู่คนละที่ (ใบงาน #99 · us07)
//
// ⭐⭐ **พี่เอมขอเอง 20 ต.ค. 2569** ⇒ *"อยากดูคู่ขนานกับแมทธิวบทอื่นข้ออื่น"*
//   ⇒ วาง **มาระโก 9** กับ **มัทธิว 17** ไว้ข้างกันแล้วอ่านเทียบด้วยตาตัวเอง
//
// ⭐⭐ **ที่ทำได้เพราะข้อมูลทุกบทเป็นไฟล์นิ่งอยู่แล้ว** ⇒ `/api/chapter/<เล่ม>/<บท>.json`
//   ⇒ **คอลัมน์ที่สองหยิบไฟล์นั้นได้เลย** ⇒ ⛔ **ไม่ต้องพ่นหน้าใหม่สักหน้า** ⇒ เว็บ ⛔ ไม่โตขึ้น
//   ⇒ ท่าหยิบคือ `หยิบบท()` ตัวเดิมของใบ #73 ⇒ ⛔ ไม่ได้เริ่มจากศูนย์
//
// ⛔⛔ **คอลัมน์ที่อยู่คนละที่ ⛔ ไม่เข้าผังเทียบบรรทัด** ⇒ มันเป็นกล่องไหลของตัวเอง
//   ⇒ **เพราะเกณฑ์ผ่านของ us07 ห้ามจับคู่เลขข้ามคอลัมน์** ⇒ ยัดเข้าผังเทียบบรรทัดเมื่อไร
//     **ผังนั้นเองคือการอ้างว่าข้อไหนคู่กับข้อไหน** ⇒ ท่าเดียวกับกล่องชั้นคำภาษาเดิมของใบ #95
//
// ⛔ **ที่อยู่เป็นเจ้าของค่านี้ ⛔ ไม่ใช่ที่เก็บของเบราว์เซอร์** ⇒ *ที่ที่กำลังอ่าน* ⛔ ไม่ใช่ *ความชอบ*
//   ⇒ ส่งลิงก์ให้คนอื่นแล้วเขาเห็นเหมือนที่เราเห็น ⇒ WCAG 2.2 SC 2.4.5 Multiple Ways
//   ⇒ และคนที่เคยตั้งค่าอะไรไว้เมื่อวาน ⛔ ไม่มีทางถูกยัดคอลัมน์เทียบมาให้โดยไม่ได้ขอ
const คอลัมน์เทียบที่เปิด = ref<คอลัมน์เทียบ[]>([])
/** ของประจำเล่มของคอลัมน์เทียบ ⇒ ใช้ชื่อไทยกับรายชื่อบท ⇒ โหลดครั้งเดียวต่อเล่ม */
const เล่มของเทียบ = ref<Record<string, ผลเล่ม>>({})
/** เนื้อบทของคอลัมน์เทียบ ⇒ ⛔ **เก็บแยกจาก `บทที่หยิบมา`** เพราะตัวนั้นถูกเก็บกวาดตามหน้าต่างของเล่มนี้ */
const เนื้อของเทียบ = ref<Record<string, ผลบท>>({})
const คอลัมน์เทียบพัง = ref('')
/**
 * ⭐⭐ **คำภาษาเดิมเป็นคอลัมน์คนละที่ได้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 4 ⇒ ก้อน ง.)
 *   ⇒ คอลัมน์เทียบที่ฉบับเป็นชื่อตัวบท (`SBLGNT` · `WLC`) ⇒ วาดคำเดิมของบทนั้นในกล่องของตัวเอง ⇒ ท่าเดียวกับฉบับแปลคนละที่ (ใบ #143)
 *   ⇒ ชั้นคำของบทคนละที่เก็บแยกจาก `ชั้นคำที่หยิบมา` ⇒ ตัวนั้นถูกจัดตามบทที่กางของหน้า ⇒ `null` = บทนั้นไม่มีคำเดิม
 */
const ชั้นคำของเทียบ = ref<Record<string, ผลชั้นคำ | null>>({})
/** ⭐ คอลัมน์นี้เป็นคำภาษาเดิมไหม ⇒ ดูจากชื่อตัวบทอย่างเดียว ⇒ ⛔ ชนรหัสฉบับแปล */
const เป็นคำเดิม = (ฉ: string) => ชื่อตัวบทเดิมทั้งหมด.includes(ฉ)

async function หยิบของเทียบ(ค: คอลัมน์เทียบ) {
  const กุญแจ = `${ค.เล่ม}/${ค.บท}`
  if (เป็นคำเดิม(ค.ฉบับ) && !(กุญแจ in ชั้นคำของเทียบ.value)) {
    try {
      const ผล = await $fetch<ผลชั้นคำ>(ที่อยู่หลังบ้าน(`api/words/${ค.เล่ม}/${ค.บท}.json`))
      ชั้นคำของเทียบ.value = { ...ชั้นคำของเทียบ.value, [กุญแจ]: ผล }
    } catch (e: unknown) {
      if ((e as { statusCode?: number })?.statusCode === 404)
        ชั้นคำของเทียบ.value = { ...ชั้นคำของเทียบ.value, [กุญแจ]: null }
      else คอลัมน์เทียบพัง.value = `เปิด ${ค.เล่ม} ${ค.บท} มาเทียบไม่ได้ ⇒ ตัวบทที่อ่านอยู่ยังอ่านต่อได้ตามปกติ`
    }
  }
  // ⭐ คอลัมน์ที่เพิ่งออกจากตารางของเล่มนี้ ⇒ ของมีอยู่ในหน้าแล้ว ⇒ ⛔ ไม่ต้องโหลดซ้ำ ⇒ ⛔ ไม่กระพริบเป็น *กำลังเปิด* (ใบ #125)
  if (ค.เล่ม === รหัสเล่ม) {
    if (!เล่มของเทียบ.value[ค.เล่ม] && ของเล่ม.value)
      เล่มของเทียบ.value = { ...เล่มของเทียบ.value, [ค.เล่ม]: ของเล่ม.value }
    const มี = บทที่หยิบมา.value[กุญแจ]
    if (!เนื้อของเทียบ.value[กุญแจ] && มี) เนื้อของเทียบ.value = { ...เนื้อของเทียบ.value, [กุญแจ]: มี }
  }
  try {
    if (!เล่มของเทียบ.value[ค.เล่ม]) {
      const ผล = await $fetch<ผลเล่ม>(ที่อยู่หลังบ้าน(`api/book/${ค.เล่ม}.json`))
      เล่มของเทียบ.value = { ...เล่มของเทียบ.value, [ค.เล่ม]: ผล }
    }
    if (!เนื้อของเทียบ.value[กุญแจ]) {
      const ผล = await $fetch<ผลบท>(ที่อยู่หลังบ้าน(`api/chapter/${ค.เล่ม}/${ค.บท}.json`))
      เนื้อของเทียบ.value = { ...เนื้อของเทียบ.value, [กุญแจ]: ผล }
      // ⭐ ใบ #143 ⇒ บนล่างแทรกข้อของคอลัมน์นี้ลงในตาราง ⇒ ของมาถึงทีหลังแล้วดันแถวข้างบน ⇒ คอลัมน์แรกต้องยังอยู่ข้อเดิม
      if (ยึดข้อที่พาไป) void nextTick(เลื่อนไปที่จุด)
    }
  } catch {
    // ⛔ หยิบไม่ได้ ⇒ **บอกตรง ๆ** และตัวบทของคอลัมน์แรกต้องอ่านต่อได้ ⛔ ห้ามหน้าพัง
    คอลัมน์เทียบพัง.value = `เปิด ${ค.เล่ม} ${ค.บท} มาเทียบไม่ได้ ⇒ ตัวบทที่อ่านอยู่ยังอ่านต่อได้ตามปกติ`
  }
}

/** ⭐ **ของที่คอลัมน์เทียบวาดออกมา** ⇒ ⛔ ไม่จับคู่กับข้อของคอลัมน์แรกแม้แต่นิดเดียว */
interface ก้อนเทียบ {
  กุญแจ: string
  เล่ม: string
  บท: number
  /** ชื่อไทยของเล่ม ⇒ ว่าง = ยังโหลดของประจำเล่มไม่เสร็จ */
  ชื่อเล่ม: string
  /** ชื่อย่อเล่มของฉบับนี้ (toc3) ⇒ ตาเห็นบนหัวคอลัมน์ (ใบ #131 note_30489) ⇒ ว่าง = ยังโหลดไม่เสร็จ */
  ชื่อย่อ: string
  ฉบับ: string
  /** ชื่อเต็มของฉบับ ⇒ ใช้กับโปรแกรมอ่านหน้าจอ ⛔ ไม่ให้มันสะกดตัวย่อทีละตัวอักษร */
  ชื่อฉบับ: string
  ภาษา: string
  บทก่อน: number | null
  บทถัด: number | null
  /** ⭐ `คำ` มีเฉพาะคอลัมน์คำภาษาเดิมคนละที่ (ใบ #145 ก้อน ง.) ⇒ แต่ละข้อเป็นปุ่มคำ ⛔ ใช่ตัวบทแปล */
  แถว: { บท: number; เลข: string; ป้าย: string; ชิ้น: ชิ้นเนื้อ[]; คำ?: คำเดิม[] }[]
  /** ⭐ คอลัมน์คำภาษาเดิมคนละที่ ⇒ ชื่อชั้นกับทิศของตัวหนังสือ ⇒ `undefined` = ฉบับแปล */
  คำเดิม?: { ชั้น: string; ทิศ: 'ltr' | 'rtl' }
  /** ⭐ ย่อหน้าที่ *คนแปล* แบ่งไว้ ⇒ ใช้เฉพาะตอนผู้อ่านเลือกโหมด *แยกตามย่อหน้า* (ใบ #98) */
  ย่อหน้า: ย่อหน้า[]
  /** ว่าง = ฉบับนี้มีย่อหน้าให้ใช้ ⇒ ไม่ว่าง = **ประโยคเหตุผลที่เครื่องนับเอง** ⛔ ไม่ได้พิมพ์เอง */
  ยังไม่มีย่อหน้า: string
  /** ⭐ ฉบับที่คอลัมน์นี้ยืมย่อหน้ามา ⇒ ว่าง = ใช้ของตัวเอง (ใบ #106) */
  ย่อหน้าตาม: string
  /** ⭐ หัวข้อย่อยของคอลัมน์นี้ (ใบ #134) ⇒ ว่าง = ผู้อ่านปิดสวิตช์ หรือฉบับนี้ไม่มีหัวข้อ
   *  ⇒ คอลัมน์คนละเล่มคนละบท ⛔ ไม่อยู่ในผังเทียบบรรทัด ⇒ หัวข้อไหลไปกับคอลัมน์ของตัวเอง (กติกา ③ ใน `app/utils/หัวข้อย่อย.ts`) */
  หัวข้อ: หัวข้อย่อย[]
  /** ⭐ หัวข้อที่เปิดย่อหน้าแต่ละย่อหน้า ⇒ ยาวเท่า `ย่อหน้า` ⇒ ใช้ตอน *แยกตามย่อหน้า* */
  หัวของย่อหน้า: (หัวข้อย่อย | null)[]
  /** ⭐ *ไหลต่อเนื่อง* ⇒ ตัวบทผ่าเป็นตอนตามหัวข้อ ⇒ `null` = ไม่มีหัวข้อ ⇒ วาดกล่องเดียวแบบเดิม */
  ตอนไหล: { ย่อหน้า: ย่อหน้า[]; หัว: (หัวข้อย่อย | null)[] } | null
  /** ว่าง = ปกติ ⇒ ไม่ว่าง = บอกผู้อ่านตรง ๆ ว่าทำไมยังไม่มีอะไรให้อ่าน */
  ยังไม่มี: string
}

/** ฉบับที่คอลัมน์เทียบใช้ ⇒ ⛔ ไม่ได้เลือกเอง = **ฉบับแรกที่ผู้อ่านติ๊กไว้** */
function ฉบับของเทียบ(ค: คอลัมน์เทียบ): string {
  // ⭐ ใบ #145 ก้อน ง. ⇒ ชื่อตัวบทภาษาเดิมเป็นฉบับของคอลัมน์คนละที่ได้ ⇒ ทุกคอลัมน์เท่ากัน
  if (ค.ฉบับ && (ฉบับที่มี.value.includes(ค.ฉบับ) || เป็นคำเดิม(ค.ฉบับ))) return ค.ฉบับ
  return ฉบับที่แสดง.value[0] || ฉบับที่มี.value[0] || ''
}

/**
 * ⭐⭐ **ก้อนของคอลัมน์คำภาษาเดิมคนละที่** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 4)
 *   ⇒ แถวคือข้อของฝั่งภาษาเดิมเอง เลขของฝั่งตัวเอง (ใบ #117) ⇒ ⛔ ไม่จับคู่กับข้อแปล ⇒ อยู่คนละที่อยู่แล้ว
 *   ⇒ ชื่อตัวบทมาจากชั้นในไฟล์ (`ชื่อตัวบท`) ⇒ ข้ามพันธสัญญา (SBLGNT ไปเล่มพันธสัญญาเดิม) ⇒ ได้ WLC ตามเล่มเอง
 *   ⇒ ชื่อย่อเล่ม ⇒ ยืม `toc3` ของฉบับไทยแบบหัวคำเดิมในตาราง (หัวข้อ *คำภาษาเดิมเป็นคอลัมน์ธรรมดา* ข้อ 5.4)
 *   ⇒ ⛔ มีย่อหน้า ⛔ มีหัวข้อ ⇒ ทุกแบบจัดวางวาด 1 ข้อ 1 ย่อหน้า ⇒ ท่าเดียวกับก้อนคำในตาราง
 */
function ก้อนคำเดิมเทียบ(ค: คอลัมน์เทียบ, i: number, ของเล่ม: ผลเล่ม | undefined): ก้อนเทียบ {
  const ไฟล์ = ชั้นคำของเทียบ.value[`${ค.เล่ม}/${ค.บท}`]
  const ชั้น = ไฟล์ ? Object.keys(ไฟล์.ชั้น)[0] : undefined
  const ข้อ = ไฟล์ && ชั้น ? ไฟล์.ชั้น[ชั้น] || {} : {}
  const เลข = Object.keys(ข้อ).sort((a, b) => Number(a) - Number(b))
  const บทที่มี = ของเล่ม?.เล่ม.บทที่มี || []
  const ที่ยืน = บทที่มี.indexOf(ค.บท)
  const ไทย = ของเล่ม?.ชั้น.find((ฉ) => ของเล่ม.ภาษาของชั้น[ฉ] === 'th')
  const ตัวบท = (ชั้น && ชื่อตัวบท(ชั้น)) || ค.ฉบับ
  return {
    กุญแจ: `เทียบ-${i}-${ค.เล่ม}-${ค.บท}-${ตัวบท}`,
    เล่ม: ค.เล่ม,
    บท: ค.บท,
    ชื่อเล่ม: ของเล่ม?.เล่ม.ชื่อไทย || '',
    ชื่อย่อ: (ไทย && ของเล่ม?.ชื่อย่อของชั้น?.[ไทย]) || '',
    ฉบับ: ตัวบท,
    ชื่อฉบับ: ชั้น ? ป้ายชั้นคำ(ชั้น) : ตัวบท,
    ภาษา: (ไฟล์ && ชั้น && ไฟล์.ภาษาของชั้น[ชั้น]) || '',
    บทก่อน: ที่ยืน > 0 ? บทที่มี[ที่ยืน - 1]! : null,
    บทถัด: บทที่มี.find((c) => c > ค.บท) ?? null,
    แถว: เลข.map((n, k) => ({ บท: ค.บท, เลข: n, ป้าย: ป้ายเลขข้อ(ค.บท, n, ค.บท, k === 0), ชิ้น: [], คำ: ข้อ[n] })),
    คำเดิม: { ชั้น: ชั้น || '', ทิศ: (ไฟล์ && ชั้น && ไฟล์.ทิศของชั้น[ชั้น]) || 'ltr' },
    ย่อหน้า: [],
    ยังไม่มีย่อหน้า: '',
    ย่อหน้าตาม: '',
    หัวข้อ: [],
    หัวของย่อหน้า: [],
    ตอนไหล: null,
    // ⭐ ถ้อยคำเดิมทั้งคู่ ⇒ *กำลังเปิด…* ของคอลัมน์เทียบ · *บทนี้ไม่มีคำภาษาเดิม…* ของก้อนคำในตาราง ⇒ ⛔ คำใหม่
    ยังไม่มี:
      ไฟล์ === undefined
        ? 'กำลังเปิดตอนนี้ขึ้นมา…'
        : เลข.length
          ? ''
          : 'บทนี้ ⛔ ไม่มีคำภาษาเดิมในข้อมูลที่เรามี ⇒ ฝั่งภาษาเดิมแบ่งบทไม่ตรงกับฉบับแปล',
  }
}

/**
 * ⭐⭐ **ฉบับที่ทั้งหน้ายืมย่อหน้ามาใช้** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/106)
 *   ⇒ **คอลัมน์ซ้ายสุดที่มีย่อหน้าของตัวเอง** ⇒ ไม่มีเลย ⇒ `TCV` (ข้อ 6.1)
 *   ⇒ ไล่ **ทุกคอลัมน์บนหน้าจากซ้ายไปขวา** ⇒ ฉบับของที่เดียวกับหน้าก่อน แล้วตามด้วยตอนที่เอามาเทียบ
 *   ⇒ ⭐ **ทั้งหน้าใช้ต้นแบบตัวเดียว** ⇒ คอลัมน์เทียบที่เป็น LSV ก็ยืมรอย *ของบทนั้น* จากฉบับเดียวกัน
 *     ⇒ ซองบทมีรอยของทุกฉบับติดมาอยู่แล้ว ⇒ ⛔ ไม่ต้องโหลดอะไรเพิ่ม
 * ⭐ **ผู้อ่านเปลี่ยนคอลัมน์ซ้ายสุดเมื่อไร ⇒ ตัวนี้คำนวณใหม่เอง** ⇒ ป้ายกับย่อหน้าเปลี่ยนตาม (ข้อ 8.1)
 */
const ฉบับต้นแบบย่อหน้า = computed(() =>
  เลือกฉบับต้นแบบ(
    // ⭐ ใบ #145 ⇒ คอลัมน์คำภาษาเดิมคนละที่ ⛔ มีย่อหน้าให้ยืม ⇒ ⛔ นับ
    [...ฉบับที่แสดง.value, ...คอลัมน์เทียบที่เปิด.value.map(ฉบับของเทียบ).filter((ฉ) => !เป็นคำเดิม(ฉ))],
    ของเล่ม.value?.ฉบับที่ยังไม่มีย่อหน้า || {},
    ฉบับที่มี.value,
  ),
)

/**
 * จัดย่อหน้าของฉบับหนึ่ง **ทั้งแบบใช้ของตัวเองและแบบยืม** ⇒ ที่เดียวที่ตัดสินว่าใช้แบบไหน
 *   ⇒ ฝั่งที่เดียวกับหน้ากับคอลัมน์เทียบเรียกตัวเดียวกัน ⛔ ไม่มีสองสำเนาให้แยกกันเดิน
 *
 * ⭐ ฉบับที่ซองบอกว่า ⛔ ไม่มีย่อหน้าของตัวเอง + มีต้นแบบให้ยืม ⇒ **ยืม** ⇒ ป้ายเดิม *ยังไม่มีย่อหน้า* ⛔ ไม่ขึ้น
 *   ⇒ **ทำไม** ⇒ ขึ้นสองป้ายพร้อมกัน = บอกว่า *ไม่มี* แล้วโชว์ย่อหน้า ⇒ พูดขัดกันเอง
 * ⭐ ต้นแบบ ⛔ ไม่มีรอยในบทนี้ (บทกวีของ TCV 239 บท) ⇒ ได้ก้อนเดียวทั้งบท **เหมือนต้นแบบเป๊ะ**
 */
function จัดย่อหน้าของฉบับ(
  ฉ: string,
  ข้อ: { บท: number; เลข: string; ป้าย: string; ชิ้น: ชิ้นเนื้อ[] }[],
  รอยของบท: Record<string, รอยย่อหน้า[]> | undefined,
  ไม่มีของตัวเอง: Record<string, string> | undefined,
  หัว: หัวข้อย่อย[] = [],
): { ย่อหน้า: ย่อหน้า[]; ยังไม่มี: string; ย่อหน้าตาม: string } {
  const เหตุ = ไม่มีของตัวเอง?.[ฉ] || ''
  const ต้นแบบ = เหตุ ? ฉบับต้นแบบย่อหน้า.value : ''
  // ⭐ หัวข้อย่อยของฉบับนี้ ⇒ ขึ้นย่อหน้าใหม่ตรงที่หัวข้อเริ่มเสมอ (ใบ #134)
  //   ⇒ TCV มีหัวข้อ 142 อันที่ตามด้วยบรรทัดกวี ⛔ ไม่ใช่ป้ายย่อหน้า ⇒ ⛔ ผ่าไม่ได้ = หัวข้อไปค้างกลางย่อหน้า
  //   ⇒ ⭐ เป็นจุดที่เจ้าของฉบับเองวางหัวข้อ ⇒ ⛔ ไม่ใช่การเพิ่มรอยให้ฉบับอื่น (ใบ #109 ข้อ 6.2 ยังจริง)
  //   ⇒ ปิดสวิตช์ ⇒ `หัว` ว่าง ⇒ ได้ย่อหน้าแบบก่อนมีใบนี้ทุกก้อน
  const รอยหัว = รอยของหัวข้อ(หัว)
  if (!ต้นแบบ) return { ย่อหน้า: จัดย่อหน้า(ข้อ, [...(รอยของบท?.[ฉ] || []), ...รอยหัว]), ยังไม่มี: เหตุ, ย่อหน้าตาม: '' }
  return {
    ย่อหน้า: จัดย่อหน้า(
      ข้อ,
      [
        ...ยืมรอยย่อหน้า(
          รอยของบท?.[ต้นแบบ],
          ข้อ.map((x) => x.เลข),
        ),
        ...รอยหัว,
      ],
    ),
    ยังไม่มี: '',
    ย่อหน้าตาม: ต้นแบบ,
  }
}

const คอลัมน์เทียบที่แสดง = computed<ก้อนเทียบ[]>(() =>
  คอลัมน์เทียบที่เปิด.value.map((ค, i) => {
    const ของเล่ม = เล่มของเทียบ.value[ค.เล่ม]
    const ของบท = เนื้อของเทียบ.value[`${ค.เล่ม}/${ค.บท}`]
    const ฉ = ฉบับของเทียบ(ค)
    const บทที่มี = ของเล่ม?.เล่ม.บทที่มี || []
    const ที่ยืน = บทที่มี.indexOf(ค.บท)
    if (เป็นคำเดิม(ฉ)) return ก้อนคำเดิมเทียบ(ค, i, ของเล่ม)
    const เนื้อฉบับ = ของบท?.ชั้น[ฉ] || {}
    const เลข = Object.keys(เนื้อฉบับ).sort((a, b) => Number(a) - Number(b))
    const แถว = เลข.map((n, k) => ({
      บท: ค.บท,
      เลข: n,
      ป้าย: ป้ายเลขข้อ(ค.บท, n, ค.บท, k === 0),
      ชิ้น: แทรกเชิงอรรถ(
        ตัดเนื้อตามคำพระเยซู(เนื้อฉบับ[n] || '', Number(n), ของบท?.คำพระเยซู?.[ฉ]),
        Number(n),
        ของบท?.เชิงอรรถ?.[ฉ],
        ฉ,
        ของเล่ม?.ภาษาของชั้น?.[ฉ],
      ),
    }))
    const หัว = มุม.value.หัวข้อย่อย ? ของบท?.หัวข้อ?.[ฉ] || [] : []
    // ⛔ คำนวณเมื่อถูกใช้เท่านั้น ⇒ ⛔ ไม่ ⇒ `จัดย่อหน้า` วิ่งทุกครั้งที่หน้าขยับโดยไม่มีใครใช้ผล
    const ย่อ =
      มุม.value.จัดวาง === 'แยกตามย่อหน้า'
        ? จัดย่อหน้าของฉบับ(
            ฉ,
            แถว.filter((x) => x.ชิ้น.length),
            ของบท?.ย่อหน้า,
            ของเล่ม?.ฉบับที่ยังไม่มีย่อหน้า,
            หัว,
          )
        : { ย่อหน้า: [], ยังไม่มี: '', ย่อหน้าตาม: '' }
    const ไหล = มุม.value.จัดวาง === 'ไหลต่อเนื่อง' && หัว.length ? ผ่าตอนไหล(แถว.filter((x) => x.ชิ้น.length), หัว) : null
    return {
      กุญแจ: `เทียบ-${i}-${ค.เล่ม}-${ค.บท}-${ฉ}`,
      เล่ม: ค.เล่ม,
      บท: ค.บท,
      ชื่อเล่ม: ของเล่ม?.เล่ม.ชื่อไทย || '',
      ชื่อย่อ: ของเล่ม?.ชื่อย่อของชั้น?.[ฉ] || '',
      ฉบับ: ฉ,
      ชื่อฉบับ: ของเล่ม?.แหล่งของชั้น[ฉ] || ฉ,
      ภาษา: ของเล่ม?.ภาษาของชั้น[ฉ] || '',
      บทก่อน: ที่ยืน > 0 ? บทที่มี[ที่ยืน - 1]! : null,
      บทถัด: บทที่มี.find((c) => c > ค.บท) ?? null,
      แถว,
      ย่อหน้า: ย่อ.ย่อหน้า,
      ยังไม่มีย่อหน้า: ย่อ.ยังไม่มี,
      ย่อหน้าตาม: ย่อ.ย่อหน้าตาม,
      หัวข้อ: หัว,
      หัวของย่อหน้า: หัวข้อของย่อหน้า(ย่อ.ย่อหน้า, หัว),
      ตอนไหล: ไหล,
      ยังไม่มี: !ของบท
        ? 'กำลังเปิดตอนนี้ขึ้นมา…'
        : เลข.length
          ? ''
          : `ตอนนี้ ⛔ ไม่มีในฉบับ ${ของเล่ม?.แหล่งของชั้น[ฉ] || ฉ} ⇒ ลองเลือกฉบับอื่นของคอลัมน์นี้`,
    }
  }),
)

/**
 * ⭐⭐ **กล่องของคอลัมน์คนละที่เลื่อนไปข้อที่ผู้อ่านเลือก** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/143)
 *   ⇒ พี่เอมเคาะ 5 พ.ย. 2569 ⇒ คนละที่ = เลื่อนแยก ⇒ กล่องของมันเลื่อนเอง ⇒ เปิดมาต้องอยู่ที่ข้อที่เลือก ⛔ ไม่ใช่ต้นบทเสมอ
 *   ⇒ เลื่อน **ครั้งเดียวต่อ 1 ที่ที่เลือก** ⇒ จดไว้กับกล่อง ⇒ ผู้อ่านเลื่อนกล่องต่อเองแล้ว ⛔ ไม่ถูกดึงกลับ
 *   ⇒ ⛔ ไม่ได้เลือกข้อ (ทั้งบท) ⇒ ต้นบท ⇒ กล่องที่เพิ่งเปลี่ยนบท ⛔ ค้างที่กลางบทของบทเก่า
 *   ⇒ กล่องที่ ⛔ เลื่อนเองได้ (บนล่างคู่ทีละข้อ) ⇒ ⛔ ไม่มีกล่องให้เลื่อน ⇒ การคู่ดูแลเอง (`เลื่อนคู่`)
 */
const ที่เลื่อนกล่องแล้ว = new WeakMap<Element, string>()
function เลื่อนกล่องเทียบไปข้อ() {
  if (import.meta.server) return
  คอลัมน์เทียบที่เปิด.value.forEach((ค, i) => {
    const ต = คอลัมน์เทียบที่แสดง.value[i]
    // ⭐ ใบ #164 ⇒ หากล่องด้วยลำดับของมัน (`data-เทียบ`) ⛔ ลำดับในหน้า ⇒ คอลัมน์ที่เป็นช่องในตาราง ⛔ มีกล่อง ⇒ ลำดับในหน้าเลื่อน
    const ม้วน = document.querySelector<HTMLElement>(`section.pk-ตอนเทียบ[data-เทียบ="${i}"] .pk-เนื้อตอนเทียบ`)
    // ⛔ กล่องที่ซ่อนอยู่ (ทีละฉบับที่อ่านคอลัมน์อื่น) ⇒ ยังวัดไม่ได้ ⇒ รอตอนผู้อ่านเลือกมาอ่าน (`ที่ดูอยู่` ในตัวเฝ้า)
    if (!ต || ต.ยังไม่มี || !ม้วน || !ม้วน.getClientRects().length) return
    const เป้า = `${ค.เล่ม}.${ค.บท}.${ต.ฉบับ}.${ค.ข้อ ?? ''}`
    if (ที่เลื่อนกล่องแล้ว.get(ม้วน) === เป้า) return
    const ข้อ = ค.ข้อ ? ม้วน.querySelector<HTMLElement>(`[data-ข้อเทียบ="${ค.บท}:${ค.ข้อ}"]`) : null
    if (ค.ข้อ && !ข้อ) return
    ที่เลื่อนกล่องแล้ว.set(ม้วน, เป้า)
    ม้วน.scrollTop = ข้อ ? ม้วน.scrollTop + ข้อ.getBoundingClientRect().top - ม้วน.getBoundingClientRect().top - 4 : 0
  })
}
watch(
  () => [
    คอลัมน์เทียบที่เปิด.value.map((ค) => `${ค.เล่ม}.${ค.บท}.${ค.ข้อ ?? ''}`).join(),
    คอลัมน์เทียบที่แสดง.value.map((ต) => `${ต.กุญแจ}${ต.ยังไม่มี}`).join(),
    วางที่ใช้.value,
    มุม.value.จัดวาง,
    ที่ดูอยู่.value,
  ],
  () => void nextTick(เลื่อนกล่องเทียบไปข้อ),
  { flush: 'post' },
)

/** จำนวนคอลัมน์ของฝั่งที่อยู่ที่เดียวกับหน้า ⇒ ใช้เป็น *น้ำหนัก* ตอนแบ่งความกว้างกับตอนที่เอามาเทียบ
 *  ⇒ ⭐ ใบ #164 ⇒ คอลัมน์ฉบับซ้ำที่เป็นช่องในตาราง (`เงาในตาราง`) อยู่ฝั่งนี้ ⇒ นับที่ฝั่งนี้ ⛔ นับซ้ำที่ฝั่งเทียบ */
const กี่ช่องฝั่งหลัก = computed(
  () =>
    เหลือแต่คำเดิม.value
      ? 1
      : (กำลังแสดงฉบับเดียว.value ? 1 : ฉบับที่แสดง.value.length) + (มุม.value.ภาษาเดิม ? 1 : 0) + เงาในตาราง.value.length,
)
/** จำนวนคอลัมน์ที่วางอยู่จริงทั้งหน้า ⇒ ใช้บอก CSS ว่าคอลัมน์อ่านต้องกว้างเท่าไร */
const กี่คอลัมน์ทั้งหน้า = computed(
  () => กี่ช่องฝั่งหลัก.value + คอลัมน์เทียบที่เปิด.value.length - เงาในตาราง.value.length,
)
/** ⭐ คอลัมน์ที่มีหัว (ฉบับ + ตอนที่เทียบ) ⇒ เหลืออันเดียว ⇒ ⛔ ไม่มีปุ่มปิด (เกณฑ์ข้อ 6.1) */
const ปิดคอลัมน์ได้ = computed(() => ฉบับที่แสดง.value.length + คอลัมน์เทียบที่เปิด.value.length > 1)
/**
 * ⭐⭐ **ปิดได้เหมือนกันหมด** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 1)
 *   ⇒ นับทุกคอลัมน์ รวมคำภาษาเดิม ⇒ เหลือคอลัมน์เดียวจริง ๆ เมื่อไร ⇒ คอลัมน์นั้น ⛔ ไม่มี × ⇒ ไม่ว่าเป็นฉบับแปลหรือคำเดิม
 *   ⇒ ⚠️ ของเดิม (ใบ #102 ข้อ 1.2) ⇒ นับเฉพาะฉบับแปล ⇒ TCV + คำเดิม ⇒ TCV ไม่มี × ⇒ แต่คำเดิมมี
 *   ⇒ ⭐ `ปิดคอลัมน์ได้` ตัวเดิมยังเป็นตัวเลือกถ้อยคำของแถบล่าง ⇒ ⛔ แตะในก้อนนี้
 */
const ปิดได้ทุกคอลัมน์ = computed(() => ปิดคอลัมน์ได้.value || (มุม.value.ภาษาเดิม && ฉบับที่แสดง.value.length + คอลัมน์เทียบที่เปิด.value.length > 0))

/**
 * ปิดคอลัมน์ฉบับของที่เดียวกับหน้า
 * ⭐ **เป็นฉบับสุดท้ายของที่นี้ แต่ยังมีตอนที่เอามาเทียบ** ⇒ ตอนเทียบอันแรกขึ้นมาเป็นเจ้าของหน้าแทน
 *   ⇒ ⛔ ไม่ใช่ปิดไม่ได้ ⇒ ปุ่มหน้าตาเดียวกันต้องทำงานเหมือนกันทุกคอลัมน์ (SC 3.2.4)
 *   ⇒ ⛔ และ ⛔ ไม่ใช่ปล่อยหน้าที่ไม่มีตัวบทของตัวเองเหลือ
 */
function ปิดช่องฉบับ(ฉ: string) {
  const เหลือ = ฉบับที่แสดง.value.filter((x) => x !== ฉ)
  // ⭐ ใบ #145 ⇒ ยังมีคำภาษาเดิมอยู่ที่เดียวกับหน้า ⇒ คำเดิมถือบทของหน้าต่อ ⇒ ⛔ ไม่ยกตอนเทียบขึ้นมาแทน
  if (เหลือ.length || มุม.value.ภาษาเดิม) {
    เริ่มก้าว()
    // ⭐ ตอนเทียบที่ยังไม่มีฉบับของตัวเองยืมฉบับของคอลัมน์แรก ⇒ คอลัมน์แรกหายไป ⇒ ตรึงก่อน ⛔ ให้มันเปลี่ยนตามเงียบ ๆ
    if (!เหลือ.length) ตรึงฉบับของเทียบ()
    ตั้งฉบับ(เหลือ)
    รวมคอลัมน์ที่ตรงแถว()
    ปรับที่อยู่()
    return
  }
  ยกตอนเทียบเป็นเจ้าของหน้า()
}
/** ⭐ ตารางไม่เหลือคอลัมน์ไหนแล้ว แต่ยังมีตอนที่เอามาเทียบ ⇒ ตอนเทียบอันแรกขึ้นมาเป็นเจ้าของหน้า (ใบ #102 ข้อ 1.3)
 *  ⇒ ⭐ ใบ #145 ⇒ ปิดคอลัมน์คำภาษาเดิมตอนมันเป็นคอลัมน์สุดท้ายของตาราง ⇒ ทางเดียวกัน ⇒ ปุ่มหน้าตาเดียวกันทำงานเหมือนกัน */
function ยกตอนเทียบเป็นเจ้าของหน้า() {
  // ⭐ ตรึงก่อนแยกตอนเทียบอันแรกออกมา ⇒ ตอนเทียบที่เหลือยังเป็นฉบับเดิมของมัน (ใบ #131 ข้อ 9.7)
  ตรึงฉบับของเทียบ()
  const [แรก, ...ที่เหลือ] = คอลัมน์เทียบที่เปิด.value
  if (!แรก) return
  if (แรก.เล่ม === รหัสเล่ม) เริ่มก้าว()
  ตั้งฉบับ([ฉบับของเทียบ(แรก)])
  คอลัมน์เทียบที่เปิด.value = ที่เหลือ
  เสียง.หยุด()
  ช่วงที่ฟัง.value = null
  if (แรก.เล่ม === รหัสเล่ม) รวมคอลัมน์ที่ตรงแถว(แรก.บท)
  void ไปที่จุด({ รหัส: แรก.เล่ม, บท: แรก.บท, ข้อ: null })
}

// ---------------------------------------------------------------- ปุ่มเพิ่มคอลัมน์ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161)
// ⭐⭐ **@krisada เลือกแบบ Bible Gateway 8 พ.ย. 2569** ⇒ *"เพิ่มอีก 1 ช่อง แล้วก็ให้มีดรอปดาวน์ให้เราเลือกว่าจะเอาเวอร์ชันไหน"*
//   ⇒ เมนู *เทียบ* มีปุ่ม *เพิ่มคอลัมน์* ปุ่มเดียว ⇒ กดแล้วได้คอลัมน์ใหม่ทันที ⇒ ฉบับและตอนเดียวกับคอลัมน์แรก (เกณฑ์ข้อ 7.1 · 7.2)
//   ⇒ เลือกฉบับที่ช่องเลือกฉบับบนหัวคอลัมน์ทางเดียว ⇒ ซ้ำกับคอลัมน์อื่นได้ (7.3) ⇒ เปลี่ยนตอนที่ปุ่มชื่อเล่ม · ปิดด้วย × (7.4)
//   ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9) ⇒ ช่องติ๊กของทุกฉบับ ⇒ 2 ทางทำเรื่องเดียวกัน · 1 ฉบับได้ 1 คอลัมน์ ⇒ ถอดแล้ว
//   ⇒ เหตุผลเต็มอยู่ที่ `docs/เคาะ/หน้าจอกับการอ่าน.md` หัวข้อ *ปุ่มเพิ่มคอลัมน์แบบ Bible Gateway* ⛔ ไม่จดซ้ำที่นี่
// ⭐ **คอลัมน์ใหม่เป็นคอลัมน์ตอนเดียวกันต่อท้าย** (`คอลัมน์เทียบที่เปิด`) ⇒ ฉบับซ้ำกับคอลัมน์แรก ⇒ ตารางมีช่องเดียวต่อฉบับ ⇒ ⛔ เข้าตาราง (ใบ #125 ข้อ 20)
//   ⇒ ผู้อ่านเปลี่ยนเป็นฉบับที่ตารางยังไม่มี ⇒ เข้าตารางเอง ข้อตรงแถว (`รวมคอลัมน์ที่ตรงแถว`) ⇒ ได้หน้าเดียวกับติ๊กฉบับแบบเดิม
// ⭐ **กดแล้วเมนูปิด ⇒ โฟกัสไปช่องเลือกฉบับของคอลัมน์ใหม่** ⇒ ขั้นถัดไปของผู้อ่านคือเลือกฉบับ ⇒ ท่าเดียวกับ Bible Gateway
//   ⇒ โปรแกรมอ่านหน้าจอได้ยินว่ามีคอลัมน์ใหม่ด้วยชื่อเดิมของช่องนั้น (*ฉบับของคอลัมน์ที่ 2*) ⇒ ⛔ คำใหม่ ⇒ WCAG 2.2 SC 2.4.3
//   ⇒ ทีละฉบับ ⇒ อ่านคอลัมน์ใหม่เลย ⇒ ⛔ ไม่งั้นมันซ่อนอยู่หลังคอลัมน์ที่อ่านอยู่
// ⭐⭐ **เปิดครบเพดานแล้ว ⇒ ปุ่มยังกดได้ (`aria-disabled`) ⇒ กดแล้วข้อความเดิมขึ้นใต้ปุ่มทันที** (เกณฑ์ข้อ 8 ⇒ ใบ #160 รวมเข้ามา)
//   ⇒ ⛔ `disabled` ⇒ หลุดจากลำดับ Tab และกดแล้วเงียบ ⇒ ข้อความอยู่ในกล่อง `role="status"` ⇒ โปรแกรมอ่านหน้าจออ่านทันที ⇒ SC 4.1.3
//   ⇒ ⛔ กล่องเด้งกลางจอ ⛔ ปิดคอลัมน์เก่าให้เอง ⇒ ทางออกคือ × บนหัวคอลัมน์
//   ⇒ จอ 768 ขึ้นไป ⛔ ไม่มีเพดานจอ (ใบ #131 ข้อ 10.7) ⇒ ชนแค่เพดานของที่อยู่ (`เพดานคอลัมน์ในที่อยู่`) ⇒ บอกด้วยข้อความเดียวกัน เลขคือจำนวนที่เปิดอยู่

/** ⭐ ฉบับที่อยู่บนจอ ⇒ กี่คอลัมน์ ⇒ นับทั้งคอลัมน์ในตารางและคอลัมน์ตอนอื่น */
const คอลัมน์ของฉบับ = computed(() => {
  const นับ = new Map<string, number>()
  for (const ฉ of [...ฉบับที่แสดง.value, ...คอลัมน์เทียบที่เปิด.value.map(ฉบับของเทียบ)])
    if (ฉ) นับ.set(ฉ, (นับ.get(ฉ) ?? 0) + 1)
  return นับ
})
/** ⭐ เปิดครบแล้ว ⇒ จอแคบชนเพดานจอ · ทุกจอชนเพดานของที่อยู่ */
const ครบเพดาน = computed(() => ครบเพดานจอแคบ.value || คอลัมน์เทียบที่เปิด.value.length >= เพดานคอลัมน์ในที่อยู่)
/** ⭐ ข้อความใต้ปุ่มตอนเต็ม ⇒ ว่าง = ยังไม่ได้กดตอนเต็ม ⇒ กล่อง `role="status"` อยู่ในหน้าตลอด ⇒ ใส่ข้อความแล้วอ่านทันที */
const ข้อความเต็ม = ref('')
/** ⭐ คอลัมน์ตอนอื่นลำดับที่ `i` ⇒ ช่องเลือกฉบับบนหัวของมัน ⇒ มีกล่องของตัวเอง หรือหัวคู่ในแถวหัว (บนล่าง) */
function โฟกัสฉบับของเทียบ(i: number) {
  // ⭐ ใบ #164 ⇒ คอลัมน์ฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ หัวของมันอยู่ในแถวหัวของตาราง (`pk-หัวเงา`)
  const ช่อง =
    document.querySelector<HTMLSelectElement>(`section.pk-ตอนเทียบ[data-เทียบ="${i}"] .pk-ช่องเลือกฉบับ`) ||
    document.querySelector<HTMLSelectElement>(`.pk-หัวคู่[data-เทียบ="${i}"] .pk-ช่องเลือกฉบับ`) ||
    document.querySelector<HTMLSelectElement>(`.pk-หัวเงา[data-เทียบ="${i}"] .pk-ช่องเลือกฉบับ`)
  ช่อง?.focus({ preventScroll: true })
}
function กดเพิ่มคอลัมน์() {
  if (ครบเพดาน.value) {
    // ⭐ กดซ้ำตอนเต็ม ⇒ ล้างก่อนแล้วใส่ใหม่ ⇒ โปรแกรมอ่านหน้าจออ่านซ้ำทุกครั้งที่กด ⛔ เงียบเพราะข้อความเดิม
    ข้อความเต็ม.value = ''
    const เลข = จอแคบ.value ? เพดานจอแคบ.value : คอลัมน์ที่เปิดทั้งหมด.value
    void nextTick(() => (ข้อความเต็ม.value = ถ้อยคำเมนูเทียบ.เพดานจอแคบ(เลข)))
    return
  }
  const แรก = ลำดับตาราง.value[0]
  const เทียบแรก = คอลัมน์เทียบที่เปิด.value[0]
  // ⭐ คอลัมน์แรก ⇒ ช่องซ้ายสุดของตาราง ⇒ คำภาษาเดิมได้ชื่อตัวบท ⇒ ตารางว่าง (ระหว่างยกตอนเทียบขึ้น) ⇒ คอลัมน์ตอนอื่นอันแรก
  const ใหม่: คอลัมน์เทียบ | undefined = แรก
    ? { เล่ม: รหัสเล่ม, บท: บทของคอลัมน์แรก(), ฉบับ: แรก === คำเดิมในลำดับ ? หัวคำเดิม.value.ตัวบท : แรก }
    : เทียบแรก && { เล่ม: เทียบแรก.เล่ม, บท: เทียบแรก.บท, ฉบับ: ฉบับของเทียบ(เทียบแรก) }
  if (!ใหม่?.ฉบับ) return
  เริ่มก้าว()
  ตั้งคอลัมน์เทียบ([...คอลัมน์เทียบที่เปิด.value, ใหม่])
  const i = คอลัมน์เทียบที่เปิด.value.length - 1
  ปิดเมนู(false)
  if (ทีละฉบับอยู่.value) ดูฉบับ(`เทียบ:${i}`)
  void nextTick(() => โฟกัสฉบับของเทียบ(i))
}

/**
 * ⭐⭐ **ฉบับเดียวกันหลายคอลัมน์ ⇒ แต่ละคอลัมน์มีที่อยู่ของตัวเอง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161 ข้อ 8 ของคนจ่ายงาน)
 *   ⇒ ชิ้นที่เลือก = ฉบับ + เล่ม + บท + ข้อ (ใบ #159) ⇒ 2 คอลัมน์ฉบับเดียวกันเล่มเดียวกัน ⇒ ได้กุญแจเดียวกัน ⇒ แตะคอลัมน์หนึ่งแล้วอีกคอลัมน์ขีดเส้นใต้ไปด้วย
 *   ⇒ ⭐ นับ *ลำดับซ้ำ* ⇒ คอลัมน์ที่ n ของฉบับนั้นในเล่มนั้น นับจากซ้าย (ตารางก่อน แล้วคอลัมน์ตอนอื่นตามลำดับ) ⇒ ตัวแรก = 1
 *     ⇒ ตัวแรกได้กุญแจเดิมทุกตัวอักษร ⇒ ลิงก์และการเลือกที่ไม่มีฉบับซ้ำ ⛔ เปลี่ยนเลย ⇒ ตัวที่ 2 ขึ้นไปได้ `~n` ต่อท้ายฉบับ (`ฉบับในกุญแจ`)
 *   ⇒ `ตาราง` ⇒ ฉบับในตาราง (อยู่เล่มของหน้าเสมอ) ⇒ `เทียบ` ⇒ ฉบับกับเล่มของคอลัมน์ตอนอื่นตามลำดับ
 */
const ซ้ำของเทียบ = computed(() => นับซ้ำ(ฉบับที่แสดง.value, คอลัมน์เทียบที่แสดง.value))
function นับซ้ำ(ตาราง: string[], เทียบ: { ฉบับ: string; เล่ม: string }[]): number[] {
  return เทียบ.map(
    (ต, i) =>
      1 +
      (ต.เล่ม === รหัสเล่ม && ตาราง.includes(ต.ฉบับ) ? 1 : 0) +
      เทียบ.slice(0, i).filter((x) => x.ฉบับ === ต.ฉบับ && x.เล่ม === ต.เล่ม).length,
  )
}

// ---------------------------------------------------------------- คอลัมน์ฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ ช่องในตาราง (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/164)
// ⭐⭐ **@krisada ลองบนมือถือจริง 10 พ.ย. 2569** ⇒ เปิด มัทธิว 9 แล้วกด *เพิ่มคอลัมน์* ⇒ ได้ TCV อีกคอลัมน์ ⇒ เจอ 4 จุด
//   ⇒ คอลัมน์ใหม่แคบกว่า · เลขข้อไม่ตรงแนว · เลื่อนขึ้นบทก่อนไม่ได้ · เส้นคั่นไม่ขึ้นตอนเปิด
// 🔴 **ต้นเหตุร่วมของข้อ 2 กับ 3** ⇒ ตารางมีช่องเดียวต่อฉบับ (ใบ #125 ข้อ 20) ⇒ TCV ตัวที่ 2 ⛔ เข้าตาราง
//   ⇒ เลยเป็นกล่องคอลัมน์คนละที่ (ใบ #143) ⇒ หนึบใต้แถบบนแล้วเลื่อนในกล่องของตัวเอง ⇒ ทั้งที่อยู่ที่เดียวกับคอลัมน์แรก
//   ⇒ ข้อ 2 ⇒ กล่องเริ่มที่หัวของมันเอง ⛔ มีหมุดบท · ⛔ อยู่ในแถวของตาราง ⇒ ข้อเดียวกันอยู่คนละระดับ แล้วห่างขึ้นตอนเลื่อน
//   ⇒ ข้อ 3 ⇒ นิ้วที่ปัดบนคอลัมน์ขวา เลื่อนแค่กล่อง (`overscroll-behavior: contain`) ⇒ หน้า ⛔ ขยับ ⇒ ⛔ ต่อบทก่อนหน้า
//   ⇒ ขัดกติกาของ @krisada เอง (ใบ #143) *"ถ้าเลือก เล่ม บท ข้อ เดียวกันควร link scroll"*
// ⭐ **ทางแก้ ⇒ คอลัมน์แบบนี้วาดเป็นช่องหนึ่งในตาราง ต่อท้ายฉบับในตาราง** ⇒ ตัวบทเป็นของฉบับเดียวกันที่ตารางมีอยู่แล้ว
//   ⇒ ช่องเท่ากันตามกฎตาราง · ข้อตรงแถวเอง · เลื่อนกับหน้า ⇒ ต่อบทก่อนและบทถัดไปเหมือนคอลัมน์เดียว · เส้นคั่นเป็นของตาราง
//   ⇒ ⭐ **ของในหน้ายังเป็นคอลัมน์ตอนอื่นเหมือนเดิม** (`คอลัมน์เทียบที่เปิด` · `p=` ในที่อยู่) ⇒ ลิงก์ · กุญแจของข้อที่เลือก (`TCV~2`)
//     · ปุ่มบนหัว (ฉบับ · เปลี่ยนตอน · ×) ทำงานผ่านลำดับของมันเหมือนเดิม ⇒ เปลี่ยนแค่ที่วาด
//   ⇒ ⛔ ทีละฉบับ ⇒ ท่าเดิม ⇒ เห็นทีละคอลัมน์ ⛔ มีอะไรให้ตรงแนว
//   ⇒ บนล่าง ⇒ ทุกคอลัมน์ตอนอื่นเป็นแบบนี้ ⇒ ช่องในตาราง ⇒ ซ้อนกันทีละข้อตามกฎตาราง ⇒ กว้างเต็มเท่ากันทุกช่อง
//     ⇒ ⚠️ ของเดิม ⇒ ทั้งบทของมันต่อท้ายบทของคอลัมน์แรก (`pk-บทคู่`) ⇒ แคบกว่าช่องของตาราง 2–8 จุด
//     ⇒ ยังมีคอลัมน์คนละที่ปนอยู่ ⇒ ท่าเดิมทั้งชุด (คู่ทีละข้อ ⇒ `จับคู่บนล่าง`)
//   ⇒ ⛔ คำภาษาเดิมเปิดอยู่ ⇒ ท่าเดิม ⇒ ตารางของคำเดิมนับช่องเอง (`แถวคำเดิม.css`) ⇒ ⛔ แตะในใบนี้
//   ⇒ เลือกข้อให้คอลัมน์นี้ไว้ (`ข้อ`) ⇒ ท่าเดิม ⇒ เลื่อนแยกไปข้อที่เลือก (ใบ #143)
/** ⭐ ลำดับของคอลัมน์ตอนอื่นที่อยู่ที่เดียวกับคอลัมน์แรก แต่ฉบับซ้ำกับตาราง ⇒ ⛔ ขึ้นกับการวาง ⇒ ตัวตัดสินการวางใช้ได้ ⛔ วน */
const ซ้ำที่เดียวกัน = computed<number[]>(() => {
  // 🔴 ไม่มีคอลัมน์ตอนอื่น ⇒ คืนก่อนถามบท ⇒ ตัวเฝ้า `วัดเส้นแบ่ง` อ่านค่านี้ตั้งแต่ตอนสร้างหน้า ⇒ ตอนนั้น `บทที่อ่านอยู่` ยังไม่ถูกประกาศ
  //   ⇒ ⛔ คืนก่อน ⇒ `Cannot access before initialization` ⇒ ทั้งหน้าพัง (ท่อของ !215 ⇒ ด่านหน้าเว็บ ⓪ · ด่านเลือกฉบับ)
  //   ⇒ คอลัมน์ตอนอื่นมาจากที่อยู่ตอน `onMounted` เท่านั้น ⇒ ถึงตอนนั้นทุกตัวประกาศครบแล้ว
  if (!คอลัมน์เทียบที่เปิด.value.length || มุม.value.ภาษาเดิม || !ฉบับที่แสดง.value.length) return []
  const บท = บทของคอลัมน์แรก()
  return คอลัมน์เทียบที่เปิด.value.flatMap((ค, i) =>
    ค.เล่ม === รหัสเล่ม && ค.บท === บท && !ค.ข้อ && ฉบับที่แสดง.value.includes(ฉบับของเทียบ(ค)) ? [i] : [],
  )
})
/** ⭐ ทุกคอลัมน์ตอนอื่นเป็นฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ บนล่างก็เป็นช่องในตารางได้ ⇒ ⛔ มีอะไรต้องคู่ทีละข้อ (`จับคู่บนล่าง`) */
const ซ้ำที่เดียวกันทุกคอลัมน์ = computed(
  () => คอลัมน์เทียบที่เปิด.value.length > 0 && ซ้ำที่เดียวกัน.value.length === คอลัมน์เทียบที่เปิด.value.length,
)
/** ⭐ ที่วาดเป็นช่องในตารางจริง ⇒ ทีละฉบับ ⇒ ท่าเดิม · บนล่างที่ยังมีคอลัมน์คนละที่ให้คู่ทีละข้อ ⇒ ท่าเดิมทั้งชุด */
const เงาในตาราง = computed(() =>
  ทีละฉบับอยู่.value || (บนล่างอยู่.value && !ซ้ำที่เดียวกันทุกคอลัมน์.value) ? [] : ซ้ำที่เดียวกัน.value,
)
/** ⭐ ช่องของเงาแต่ละช่อง ⇒ `ฐาน` = ช่องของฉบับเดียวกันในตาราง ⇒ ตัวบทมาจากช่องนั้น ⇒ `ซ้ำ` = ลำดับซ้ำของกุญแจ (ใบ #161) */
const ช่องเงา = computed(() =>
  เงาในตาราง.value.map((i) => {
    const ฉ = ฉบับของเทียบ(คอลัมน์เทียบที่เปิด.value[i]!)
    return { เทียบ: i, ฉ, ฐาน: ฉบับที่แสดง.value.indexOf(ฉ), ซ้ำ: ซ้ำของเทียบ.value[i] ?? 2 }
  }),
)
/** ⭐ จำนวนช่องของตารางที่ตาเห็น ⇒ ฉบับในตาราง + เงา ⇒ คลาส `pk-คอลัมน์-N` ใช้ตัวนี้ ⇒ ช่องเท่ากันตามกฎเดิม */
const กี่ช่องตาราง = computed(() => ฉบับที่แสดง.value.length + ช่องเงา.value.length)
/** ⭐ ลำดับช่องของแถว ⇒ ช่องของตาราง (มีคำเดิมแทรกตามเดิม) แล้วต่อท้ายด้วยเงา ⇒ เงาลำดับที่ m ได้เลข n + m */
function ลำดับช่องทั้งหมด(n: number): number[] {
  return [...ลำดับช่อง(n), ...ช่องเงา.value.map((_, m) => n + m)]
}
/** ⭐ ช่องที่ i ⇒ เงาของคอลัมน์ไหน ⇒ `undefined` = ช่องของฉบับในตาราง */
function เงาของช่อง(i: number) {
  return i < ฉบับที่แสดง.value.length ? undefined : ช่องเงา.value[i - ฉบับที่แสดง.value.length]
}
/** ⭐ ช่องที่ i เอาตัวบทจากช่องไหนของตาราง ⇒ ช่องของตารางเอง = ตัวเอง */
function ฐานของช่อง(i: number): number {
  return เงาของช่อง(i)?.ฐาน ?? i
}
/** ⭐ ของบนกล่องข้อในช่องที่ i ⇒ เงาใช้กุญแจของคอลัมน์มันเอง (`TCV~2`) ⇒ แตะคอลัมน์หนึ่ง ⛔ ขีดเส้นใต้อีกคอลัมน์ (ใบ #161) */
function ของข้อในช่อง(i: number, กุญแจ: string, ฉ: string, ถือ: boolean) {
  const ง = เงาของช่อง(i)
  return ง ? เลือก.ของข้อ(กุญแจ, ง.ฉ, false, { เล่ม: รหัสเล่ม, ข้อแรก: '', ซ้ำ: ง.ซ้ำ }) : เลือก.ของข้อ(กุญแจ, ฉ, ถือ)
}
/**
 * ⭐ **เลื่อนอ่านทะลุบท ⇒ เงาไปบทเดียวกับตาราง** ⇒ มันเป็นช่องของตาราง ⇒ บทของมันคือบทของหน้า
 *   ⇒ ⛔ ไม่ตาม ⇒ `p=` ในที่อยู่ค้างบทเดิม ⇒ เปิดลิงก์นั้นใหม่ได้กล่องคนละที่ ⇒ และกดปุ่มบนหัวทีหลังแล้วหลุดออกจากตาราง
 *   ⇒ เรียกจากตัววัดการเลื่อน (`ทานบทที่อ่านอยู่`) ทางเดียว ⇒ ปุ่มที่พาไปบทอื่นจัดคอลัมน์ของมันเอง (`แยกคอลัมน์อื่นออกจากแถว` · `กดลูกศรล่าง`)
 *   ⇒ ⛔ ตอนดูช่วง ⇒ บทของคอลัมน์แรกคือบทต้นช่วง ⇒ ⛔ ตาม
 */
function ตามบทของเงา(ใหม่: number) {
  if (ช่วงที่ฟัง.value || !เงาในตาราง.value.length) return
  const เงา = new Set(เงาในตาราง.value)
  คอลัมน์เทียบที่เปิด.value = คอลัมน์เทียบที่เปิด.value.map((ค, i) => (เงา.has(i) ? { ...ค, บท: ใหม่ } : ค))
}

// ---------------------------------------------------------------- เพดานคอลัมน์บนจอแคบ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 คำขอรวมที่ 2 · note_30332)
// ⭐⭐ **พี่เอมเคาะ 2 พ.ย. 2569** ⇒ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30302 ข้อ 1 · 2
//   ⇒ แผนที่รับแล้ว https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30303 ข้อ 1 · 2 ⇒ หน้าต่างที่ย่อ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30310 ข้อ 1
//   ⇒ จอแคบกว่า 768 จุดมีเพดาน ⇒ **นับทุกคอลัมน์** ⇒ ฉบับในตาราง · คำภาษาเดิม · คอลัมน์ที่เปิดคนละเล่มหรือคนละบท
//   ⇒ ครบเพดานแล้ว ⇒ ปุ่ม *เพิ่มคอลัมน์* เป็น `aria-disabled` ⇒ กดแล้วบอกเหตุผลใต้ปุ่ม (ใบ #161 ⇒ ⚠️ ของเดิม ช่องที่ยังไม่ติ๊กในเมนูล็อก)
//   ⇒ ลิงก์เก่า · หน้าต่างที่ย่อจนแคบ · มือถือที่หมุนกลับแนวตั้ง ⇒ เหลือคอลัมน์แรก ๆ จากซ้ายเท่าเพดาน ⇒ ที่เหลือปิดจริง ⛔ ไม่ซ่อน
//     ⇒ ขยายกลับแล้ว ⛔ ไม่คืนเอง ⇒ *"เวลาคนอ่านคงไม่สลับไปมา เริ่มแล้ว นิ่งแล้วก็คงไว้แบบนั้น"* (พี่เอม 2 พ.ย. 2569)
//   ⇒ จอ 768 ขึ้นไป ⛔ ไม่มีเพดาน ⇒ หน้าตาเหมือนเดิมทุกอย่าง (ใบ #131 ข้อ 10.7)
//   ⚠️ เปลี่ยนการเคาะ 18 ต.ค. 2569 ข้อ 4 *ไม่ใช่ห้ามผู้อ่านติ๊กฉบับเพิ่ม* ⇒ เหตุผลอยู่ที่ `docs/เคาะ/หน้าจอกับการอ่าน.md` ⛔ ไม่จดซ้ำที่นี่
// ⭐⭐ **เพดานนับจากที่ว่าง ⛔ ไม่ใช่เลข 2 ตายตัว** (พี่เอมเคาะเพิ่ม https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30332 ข้อ 1 · note_30333)
//   ⇒ ที่มา ⇒ Samsung Galaxy Z Fold 6 ของพี่เอมตอนกางจอกว้าง 707 จุด ⇒ ได้แค่ 2 คอลัมน์ ⇒ ควรได้ 3
//   ⇒ เพดาน = ความกว้างของหน้าอ่าน ÷ ความกว้างขั้นต่ำของ 1 คอลัมน์ ⇒ ปัดลง ⇒ ⛔ ไม่ต่ำกว่า 2
//   ⇒ ความกว้างขั้นต่ำเป็น `em` ของตัวบท ⇒ วัดจากไม้บรรทัดที่ซ่อนในคอลัมน์ (`.pk-ไม้บรรทัดคอลัมน์`) ⇒ เลขอยู่ที่ `main.css` ที่เดียว
//     ⇒ ตัวอักษรใหญ่ขึ้น ⇒ ไม้บรรทัดยาวขึ้นเอง ⇒ เพดานลดเอง ⇒ ⛔ ไม่ต้องฟังปุ่ม ก+ ก− แยก
//   ⇒ ⭐ **หารด้วยความกว้างของหน้าอ่าน ⛔ ไม่ใช่กล่องคอลัมน์** ⇒ กล่องคอลัมน์กว้างตามจำนวนฉบับที่เปิด (เพดาน 34em ต่อฉบับ)
//     ⇒ หารด้วยกล่องนั้นแล้วเพดานจะเปลี่ยนตามจำนวนที่เปิดอยู่เอง ⇒ วัดเอง 3 พ.ย. 2569 ⇒ จอ 707 ตัวอักษร 85% เปิด 1 ฉบับ
//       ⇒ กล่องคอลัมน์ 549 จุด · หน้าอ่าน 675 จุด ⇒ หารด้วยกล่องได้ 3 · หารด้วยหน้าได้ 4
/** ⛔ ต่ำกว่านี้ไม่ได้ ⇒ จอแคบสุดก็ยังเปิดเทียบได้ 2 คอลัมน์ (note_30332 ข้อ 1.2) */
const เพดานต่ำสุด = 2
/** ไม้บรรทัดที่ซ่อนอยู่ในคอลัมน์ ⇒ ยาวเท่าความกว้างขั้นต่ำของ 1 คอลัมน์ */
const ไม้บรรทัด = ref<HTMLElement | null>(null)
const กว้างหน้าอ่าน = ref(0)
const กว้างขั้นต่ำต่อคอลัมน์ = ref(0)
let ตัวเฝ้าที่ว่าง: ResizeObserver | undefined
const เพดานจอแคบ = computed(() => {
  const ขั้นต่ำ = กว้างขั้นต่ำต่อคอลัมน์.value
  if (!ขั้นต่ำ) return เพดานต่ำสุด
  // ⭐ เผื่อเศษทศนิยม ⇒ หารลงตัวพอดี (จอ 412 ÷ 10em) ⛔ ไม่ให้ตกไปเลขล่างเพราะ 1.9999
  return Math.max(เพดานต่ำสุด, Math.floor(กว้างหน้าอ่าน.value / ขั้นต่ำ + 1e-6))
})
/** วัดที่ว่างจากของจริงบนหน้า ⇒ ความกว้างเนื้อของหน้าอ่าน กับความยาวไม้บรรทัด */
function วัดที่ว่าง() {
  const หน้า = document.querySelector<HTMLElement>('.pk-หน้าอ่าน')
  if (หน้า) {
    const ส = getComputedStyle(หน้า)
    กว้างหน้าอ่าน.value = หน้า.clientWidth - parseFloat(ส.paddingLeft) - parseFloat(ส.paddingRight)
  }
  // ⭐⭐ 20 พ.ย. 2569 ⇒ สัดส่วนที่ย่ออยู่ตอนวัด ⇒ อ่านจากหน้าจริง (`--pk-ย่อจอแคบ` ที่ไม้บรรทัดได้รับ) ⇒ ⛔ เชื่อค่าในสคริปต์ที่อาจยังไม่ได้วาด
  //   ⇒ ทุกค่าที่เป็น `em` ของคอลัมน์ หารด้วยสัดส่วนนี้ ⇒ ได้ขนาดก่อนย่อ ⇒ ดูหัวข้อ `ตัวบทขั้นต่ำก่อนย่อ`
  const อ้าง = ไม้บรรทัดซ้ายขวา.value ?? ไม้บรรทัด.value
  const ย่อตอนวัด = (อ้าง && parseFloat(getComputedStyle(อ้าง).getPropertyValue('--pk-ย่อจอแคบ'))) || 1
  // ⭐ เพดานจอแคบนับจากขนาดก่อนย่อ ⇒ ⛔ ย่ออยู่แล้วเปิดคอลัมน์เพิ่มได้ ⇒ ขยายคืนแล้วคอลัมน์ถูกตัดทิ้งเอง
  if (ไม้บรรทัด.value) กว้างขั้นต่ำต่อคอลัมน์.value = ไม้บรรทัด.value.getBoundingClientRect().width / ย่อตอนวัด
  // ⭐ ใบ #131 note_30367 ข้อ 4 ⇒ เส้นตัดสินซ้ายขวา ⇒ วัดพร้อมกันที่เดียว ⇒ ตัวเฝ้าชุดเดียวกัน
  if (ไม้บรรทัดซ้ายขวา.value && ไม้บรรทัดเลขข้อ.value) {
    const ไม้ = ไม้บรรทัดซ้ายขวา.value.getBoundingClientRect().width
    const เลขข้อ = ไม้บรรทัดเลขข้อ.value.getBoundingClientRect().width
    // ⭐ ไม้บรรทัดซ้ายขวา = 6em + ช่องไฟ (`rem`) · เลขข้อ = 2.4em ⇒ แยกส่วนที่ย่อกับส่วนคงที่ออกจากกัน ⇒ ⛔ ตั้งเลขใหม่
    const ตัวบท = (6 * เลขข้อ) / 2.4
    ช่องไฟคอลัมน์.value = Math.max(0, ไม้ - ตัวบท)
    ตัวบทขั้นต่ำก่อนย่อ.value = ตัวบท / ย่อตอนวัด
    ช่องเลขข้อก่อนย่อ.value = เลขข้อ / ย่อตอนวัด
    ขนาดตัวบทก่อนย่อ.value = เลขข้อ / 2.4 / ย่อตอนวัด
  }
  กว้างหัวขั้นต่ำ.value = วัดหัวขั้นต่ำ()
  หัวตามย่อ.value = วัดหัวทุกขั้น(ย่อตอนวัด, พื้นย่อ.value)
}

/**
 * ⭐⭐ **หัวแถวเดียวที่แคบที่สุดที่ยังไม่ตัดอะไรนอกจากชื่อย่อ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30489)
 *   ⇒ ช่องฉบับ + × + ปุ่มตอนที่เหลือแค่เลขบท (⛔ ต่ำกว่า 44 จุด) + ช่องไฟ ⇒ ของหัวที่กว้างสุดบนหน้า
 *   ⇒ ซ้ายขวาต้องให้ทุกคอลัมน์กว้างพอทั้งตัวบท (6em) และหัวนี้ ⇒ ⛔ ไม่งั้นปุ่มในหัวล้นไปทับคอลัมน์ข้าง ๆ หรือเลขบทถูกตัด
 *   ⇒ วัดจากของจริง ⇒ ตัวอักษรใหญ่ขึ้นหรือเปลี่ยนฉบับ ⇒ ช่องฉบับกว้างขึ้นเอง ⇒ ⛔ ไม่มีเลขในสคริปต์
 *   ⇒ ⛔ หัวที่ซ่อนอยู่ (ทีละฉบับ) ⇒ ⛔ นับ ⇒ แบบนั้นไม่ได้ใช้เส้นนี้
 */
const กว้างหัวขั้นต่ำ = ref(0)
function วัดหัวขั้นต่ำ(): number {
  let มาก = 0
  for (const กลุ่ม of document.querySelectorAll<HTMLElement>('.pk-หัวช่อง > .pk-ปุ่มตอนเทียบ')) {
    if (!กลุ่ม.getClientRects().length) continue
    // ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154 ⇒ ⛔ นับกล่องปุ่มเฟืองกับ i ⇒ ที่ไม่พอ มันขึ้นแถวใหม่ในหัวเอง (`หัวคอลัมน์.vue`)
    //   ⇒ การตัดสินซ้ายขวาหรือบนล่างเหมือนก่อนใบนี้ทุกจุด ⇒ เหตุผลอยู่หัวไฟล์ `หัวคอลัมน์.vue`
    const ลูก = [...กลุ่ม.children].filter(
      (x) => x.getClientRects().length && !x.matches('[data-ปุ่มคำเดิมบนหัว]'),
    ) as HTMLElement[]
    // ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/140 รอบที่ 3 ⇒ ช่องไฟระหว่างปุ่มเป็นตัวคั่นที่หดได้ (`::before` `::after` ใน `main.css`)
    //   ⇒ หัวขั้นต่ำนับตัวคั่นที่หดสุดแล้ว (`min-width`) ⇒ บวก `gap` เผื่อวันที่กลับไปใช้ ⇒ ตัวคั่น 1 ตัวต่อช่องระหว่างของ 2 ชิ้นเหมือนเดิม
    const ช่องไฟ =
      (parseFloat(getComputedStyle(กลุ่ม).columnGap) || 0) + (parseFloat(getComputedStyle(กลุ่ม, '::before').minWidth) || 0)
    let กว้าง = ช่องไฟ * Math.max(0, ลูก.length - 1)
    for (const x of ลูก) {
      const เลข = x.querySelector<HTMLElement>('.pk-เลขตอน')
      if (!เลข) {
        กว้าง += x.getBoundingClientRect().width
        continue
      }
      const ส = getComputedStyle(x)
      const ขอบ = ['paddingLeft', 'paddingRight', 'borderLeftWidth', 'borderRightWidth'].reduce(
        (a, k) => a + (parseFloat(ส[k as 'paddingLeft']) || 0),
        0,
      )
      กว้าง += Math.max(parseFloat(ส.minWidth) || 0, เลข.getBoundingClientRect().width + ขอบ)
    }
    มาก = Math.max(มาก, กว้าง)
  }
  return มาก
}
/**
 * ⭐⭐ **หัวแถวเดียวที่ย่อเท่านั้นเท่านี้ ⇒ ลองย่อหัวจริงทีละขั้นแล้ววัด** (@krisada เคาะ 20 พ.ย. 2569 ⇒ ดู `กว้างหัวที่ย่อ`)
 *   ⇒ ตั้งขนาดตัวหนังสือของกลุ่มปุ่มในหัว (`.pk-ปุ่มตอนเทียบ`) เท่ากับที่จะได้ตอนย่อขั้นนั้น ⇒ วัดด้วย `วัดหัวขั้นต่ำ` ตัวเดิม ⇒ คืนค่าเดิมทันที
 *     ⇒ ทั้งหมดอยู่ในงานเดียว ⇒ หน้า ⛔ ได้วาดขั้นที่ลอง ⇒ ⛔ กระพริบ ⇒ ตัวเฝ้าขนาดเห็นขนาดเดิม ⇒ ⛔ ปลุกตัวเองซ้ำ
 *   ⇒ ⭐ ขั้นละ 0.05 จาก 1 ลงถึงพื้น ⇒ ขั้นเดียวกันทุกครั้ง (⛔ ขึ้นกับย่อที่ใช้อยู่) ⇒ วัดตอนย่ออยู่หรือไม่ย่อก็ได้ตารางเดียวกัน
 *   ⇒ ⛔ เฉพาะจอแคบที่มีมากกว่า 1 คอลัมน์ ⇒ ที่อื่นไม่มีอะไรให้ย่อ ⇒ ⛔ เสียเวลาวัด
 */
function วัดหัวทุกขั้น(ย่อตอนวัด: number, ต่ำสุด: number): [number, number][] {
  const ตอนนี้ = วัดหัวขั้นต่ำ()
  if (!จอแคบ.value || กี่คอลัมน์ข้างกัน.value <= 1 || ต่ำสุด >= 1) return [[ย่อตอนวัด, ตอนนี้]]
  const กลุ่ม = [...document.querySelectorAll<HTMLElement>('.pk-หัวช่อง > .pk-ปุ่มตอนเทียบ')].filter((x) => x.getClientRects().length)
  const เดิม = กลุ่ม.map((x) => x.style.fontSize)
  const ขนาด = กลุ่ม.map((x) => parseFloat(getComputedStyle(x).fontSize) || 16)
  const ขั้น: number[] = []
  for (let ย่อ = 1; ย่อ > ต่ำสุด + 1e-9; ย่อ = Math.round((ย่อ - 0.05) * 100) / 100) ขั้น.push(ย่อ)
  ขั้น.push(ต่ำสุด)
  const ผล: [number, number][] = []
  try {
    for (const ย่อ of ขั้น) {
      กลุ่ม.forEach((x, i) => (x.style.fontSize = `${(ขนาด[i]! * ย่อ) / ย่อตอนวัด}px`))
      ผล.push([ย่อ, วัดหัวขั้นต่ำ()])
    }
  } finally {
    กลุ่ม.forEach((x, i) => (x.style.fontSize = เดิม[i] ?? ''))
  }
  return ผล.sort((ก, ข) => ก[0] - ข[0])
}
/** ตัวเลิกฟังการเปลี่ยนเส้นทาง ⇒ ใช้ตอนลิงก์เก่าถูกตัด ⇒ ดู `onMounted` */
let เลิกฟังเส้นทาง: (() => void) | undefined
/** ทุกคอลัมน์ที่เปิดอยู่ ⇒ ⛔ ไม่ขึ้นกับว่าวางทีละฉบับหรือขนานกัน ⇒ ของที่เปิดคือของที่เปิด */
const คอลัมน์ที่เปิดทั้งหมด = computed(
  () => ฉบับที่แสดง.value.length + คอลัมน์เทียบที่เปิด.value.length + (มุม.value.ภาษาเดิม ? 1 : 0),
)
const ครบเพดานจอแคบ = computed(() => จอแคบ.value && คอลัมน์ที่เปิดทั้งหมด.value >= เพดานจอแคบ.value)
// ⭐ ใบ #161 ⇒ ปิดคอลัมน์จนไม่เต็มแล้ว ⇒ ข้อความใต้ปุ่ม *เพิ่มคอลัมน์* หมดความจริง ⇒ ล้าง ⇒ ⛔ ค้างบอกว่าเต็มทั้งที่กดได้
watch(ครบเพดาน, (เต็ม) => {
  if (!เต็ม) ข้อความเต็ม.value = ''
})

/**
 * ⭐⭐ **เกินเพดานบนจอแคบ ⇒ เหลือคอลัมน์แรก ๆ จากซ้ายเท่าเพดาน** ⇒ ที่เหลือปิดจริง ⇒ ⛔ ไม่ซ่อน ⛔ ไม่มีตัวหนังสือบอก (note_30302 ข้อ 2.1)
 *   ⇒ ลำดับจากซ้าย = ลำดับที่จอกว้างวาง ⇒ คอลัมน์แรก · คำภาษาเดิม (ขวาติดคอลัมน์แรก ใบ #125 ข้อ 11) · ฉบับอื่นในตาราง · คอลัมน์ตอนอื่น
 *   ⇒ คอลัมน์แรกอยู่เสมอ ⇒ ⛔ ไม่ต้องตรึงฉบับของคอลัมน์ตอนอื่น
 *   ⇒ คืน `true` เมื่อตัด ⇒ คนเรียกเขียนที่อยู่ด้วย `ปรับที่อยู่` ซึ่งเขียนทับช่องเดิม ⇒ ⛔ ไม่เปิดช่องถอยหลัง ⇒ ถอยหลังแล้วไม่วนกลับมาตัดซ้ำ
 *   ⇒ `จำ` = เก็บฉบับที่เหลือไว้ในเครื่องแบบปุ่ม × ⇒ ⛔ ฉบับที่มาจาก `t=` ของลิงก์ ⛔ เขียนทับความชอบในเครื่อง (ดู `onMounted`)
 */
function ตัดให้พอจอแคบ(จำ = true): boolean {
  if (!จอแคบ.value || คอลัมน์ที่เปิดทั้งหมด.value <= เพดานจอแคบ.value) return false
  const ฉบับเดิม = ฉบับที่แสดง.value
  // ⭐ ใบ #145 ก้อน ข. ⇒ เหลือคอลัมน์ซ้ายสุดตามลำดับจริงของตาราง ⇒ คำเดิมนับตามตำแหน่งของมัน ⛔ ไม่ใช่ที่ 2 เสมอ
  //   ⇒ คอลัมน์ซ้ายสุดอยู่เสมอ ⇒ เพดานต่ำสุด 2 ⇒ ⛔ มีทางตัดจนตารางว่าง
  const ลำดับ = ลำดับตาราง.value.slice(0, Math.max(1, เพดานจอแคบ.value))
  const ฉบับ = ลำดับ.filter((x) => x !== คำเดิมในลำดับ)
  const คำเดิมอยู่ = ลำดับ.includes(คำเดิมในลำดับ)
  const เหลือที่ = Math.max(0, เพดานจอแคบ.value - ลำดับ.length)
  const เทียบ = คอลัมน์เทียบที่เปิด.value.slice(0, เหลือที่)
  if (มุม.value.ภาษาเดิม && !คำเดิมอยู่) มุม.value = { ...มุม.value, ภาษาเดิม: false }
  if (ฉบับ.length !== ฉบับเดิม.length) {
    if (จำ) ตั้งฉบับ(ฉบับ, false)
    else ฉบับที่เลือก.value = ฉบับ
  }
  คอลัมน์เทียบที่เปิด.value = เทียบ
  คอลัมน์เทียบพัง.value = ''
  return true
}

// ---------------------------------------------------------------- ทุกคอลัมน์ทำงานแบบเดียวกัน (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125)
// ⭐⭐ **พี่เอมเคาะ 31 ต.ค. 2569** ⇒ *"ด้านบน เลือกของใครของมัน ด้านล่าง เลือกทั้งหมดที่แสดงอยู่ จำง่าย"*
//   ⇒ ปุ่มบนหัวคอลัมน์ไหน ⇒ ขยับคอลัมน์นั้นคอลัมน์เดียว (ข้อ 8) ⇒ ปุ่มแถบล่าง ⇒ ขยับทุกคอลัมน์ (ข้อ 9)
//   ⇒ เหตุผลเต็มอยู่ที่ `docs/เคาะ/หน้าจอกับการอ่าน.md` หัวข้อ *ปุ่มบนหัวขยับคอลัมน์เดียว ปุ่มแถบล่างขยับทุกคอลัมน์* ⛔ ไม่จดซ้ำที่นี่
//
// ⭐⭐ **ของในหน้ายังเป็น 2 กอง เหมือนเดิม** ⇒ ⛔ ไม่ได้รื้อ
//   ① `ฉบับที่แสดง` ⇒ คอลัมน์ที่อยู่บทเดียวกับคอลัมน์แรก ⇒ อยู่ในตารางเดียวกัน ⇒ **ข้อตรงแถวกัน** (ข้อ 10)
//   ② `คอลัมน์เทียบที่เปิด` ⇒ คอลัมน์ที่อยู่คนละที่ ⇒ กล่องไหลของตัวเอง
//   ⇒ **คอลัมน์ย้ายกองได้** ⇒ ขยับออกจากบทของคอลัมน์แรก ⇒ ออกไปไหลเอง · ขยับกลับมาบทเดียวกัน ⇒ กลับเข้าตาราง
//   ⇒ ⛔ **การเลื่อนอ่านทะลุบท ⛔ ไม่นับเป็นการขยับ** ⇒ จัดกองใหม่เฉพาะตอนมีคนกดปุ่ม
//     ⇒ ไม่งั้นคอลัมน์จะกระโดดเข้าออกตารางระหว่างที่ผู้อ่านเลื่อนอยู่ ⇒ Nielsen ข้อ 1 ⇒ ของที่เปลี่ยนต้องมาจากที่เขากด
//   ⇒ ⭐ คอลัมน์ที่ซ้ำกับกองตารางทั้งตอนและฉบับ ⇒ ⛔ ไม่เข้าตาราง ⇒ ตารางมีช่องเดียวต่อฉบับ ⇒ ปล่อยไหลเอง (ใบ #125 ข้อ 20)

/** ⭐ บทของคอลัมน์แรกตอนนี้ ⇒ ดูช่วงอยู่ = บทต้นช่วง */
function บทของคอลัมน์แรก(): number {
  return ช่วงที่ฟัง.value ? ช่วงที่ฟัง.value.จาก.บท : บทที่อ่านอยู่.value
}

/**
 * ⭐⭐ **คอลัมน์เทียบที่มาอยู่บทเดียวกับคอลัมน์แรก ⇒ เข้าตาราง** (ข้อ 10)
 *   ⇒ ต่อท้ายกองตาราง ตามลำดับที่มันอยู่ ⇒ คอลัมน์ที่ยังไหลเองเรียงตามเดิม
 *   ⇒ ⛔ ฉบับที่ตารางมีอยู่แล้ว ⇒ ⛔ ไม่เข้า ⇒ เหตุผลอยู่หัวหัวข้อนี้
 */
function รวมคอลัมน์ที่ตรงแถว(บท = บทของคอลัมน์แรก(), ข้อ?: number) {
  const { หลัก, เหลือ, คำเดิมกลับที่, ดูใหม่ } = แบ่งกองตรงแถว(คอลัมน์เทียบที่เปิด.value, บท, ข้อ)
  if (หลัก.length === ฉบับที่แสดง.value.length && คำเดิมกลับที่ < 0) return
  if (คำเดิมกลับที่ >= 0) {
    ตั้งฉบับ(หลัก, true, คำเดิมกลับที่)
    มุม.value = { ...มุม.value, ภาษาเดิม: true }
  } else ตั้งฉบับ(หลัก)
  คอลัมน์เทียบที่เปิด.value = เหลือ
  // ⭐ ทีละฉบับ ⇒ ผู้อ่านยังอ่านคอลัมน์เดิมอยู่ ⇒ ⛔ ไม่ให้จอเด้งไปคอลัมน์อื่นเพราะคอลัมน์ย้ายกอง (ใบ #143)
  if (ดูใหม่) ดูฉบับ(ดูใหม่)
}

/**
 * ⭐ **ส่วนคิดของ `รวมคอลัมน์ที่ตรงแถว` ⇒ ⛔ แตะหน้า** ⇒ คืนกองตาราง (`หลัก`) กับกองไหลเอง (`เหลือ`)
 *   ⇒ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/162 ⇒ `href` ของ ‹ › แถบล่างคิดหน้าหลังกดล่วงหน้าด้วยตัวนี้
 *     ⇒ ตัวเดียวกับที่การกดใช้จัดกองจริง ⇒ ที่อยู่บนลูกศรตรงกับที่อยู่หลังกดทุกตัวอักษร (เกณฑ์ข้อ 2)
 */
function แบ่งกองตรงแถว(เทียบ: คอลัมน์เทียบ[], บท: number, ข้อ?: number) {
  const หลัก = [...ฉบับที่แสดง.value]
  const เหลือ: คอลัมน์เทียบ[] = []
  // ⭐ ใบ #143 ⇒ คอลัมน์ที่ผู้อ่านเลือกข้อไว้ ⇒ เข้าตารางเฉพาะตอนข้อตรงกับคอลัมน์แรกด้วย (ที่เดียวกัน = เลื่อนคู่)
  //   ⇒ ⛔ ไม่ได้เลือกข้อ (ทั้งบท · ลิงก์เก่า) ⇒ ดูแค่เล่มกับบทเหมือนเดิม
  const ดู = มุม.value.ฉบับที่ดู
  let ดูใหม่ = ''
  // ⭐ ใบ #145 ก้อน ง. ⇒ คำภาษาเดิมคนละที่ที่กลับมาที่เดียวกับหน้า ⇒ กลับเข้าตารางต่อท้าย ⇒ ท่าเดียวกับฉบับแปล
  let คำเดิมกลับที่ = -1
  เทียบ.forEach((ค, i) => {
    const ฉ = ค.ฉบับ || หลัก[0] || ''
    const ที่เดียวกัน = ค.เล่ม === รหัสเล่ม && ค.บท === บท && (!ค.ข้อ || ค.ข้อ === ข้อ)
    if (ที่เดียวกัน && เป็นคำเดิม(ฉ) && !มุม.value.ภาษาเดิม && คำเดิมกลับที่ < 0) {
      คำเดิมกลับที่ = หลัก.length
      if (ดู === `เทียบ:${i}`) ดูใหม่ = ดูคำเดิม
      return
    }
    if (ที่เดียวกัน && ฉบับที่มี.value.includes(ฉ) && !หลัก.includes(ฉ)) {
      หลัก.push(ฉ)
      if (ดู === `เทียบ:${i}`) ดูใหม่ = ฉ
    } else {
      if (ดู === `เทียบ:${i}`) ดูใหม่ = `เทียบ:${เหลือ.length}`
      เหลือ.push(ค)
    }
  })
  return { หลัก, เหลือ, คำเดิมกลับที่, ดูใหม่ }
}

/**
 * ⭐⭐ **คอลัมน์แรกอยู่ที่ข้อเดิมบนจอ ตอนคอลัมน์อื่นย้ายกอง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/143)
 *   ⇒ ต้นเหตุ ⇒ คอลัมน์ออกจากตาราง ⇒ แถวของตารางเตี้ยลง (ตัวบทอังกฤษยาวกว่าไทย) ⇒ ที่เลื่อน (`scrollY`) เท่าเดิม
 *     ⇒ ตัวบทข้างบนหดลง ⇒ ข้อที่ผู้อ่านดูอยู่ไหลขึ้นพ้นจอ ⇒ จอกลายเป็นบทถัดไป ⇒ ที่อยู่กับแถบล่างเปลี่ยนเป็นบท 13 ทั้งที่ไม่ได้แตะ
 *   ⇒ ⭐ จดข้อแรกที่ผู้อ่านเห็นไว้เป็น *ข้อที่พาไป* **ก่อน** หน้าเปลี่ยน ⇒ แล้วพากลับไปที่ข้อนั้นหลังวาดใหม่ ⇒ ยึดไว้จนผู้อ่านขยับเอง
 *     ⇒ ที่อยู่ได้เลขข้อนี้ด้วย ⇒ รีเฟรชหรือส่งลิงก์แล้วคอลัมน์แรกอยู่ข้อเดิม ⇒ ⛔ ไม่จุดไฟส่อง ⇒ ผู้อ่านไม่ได้สั่งให้พาไปไหน
 *   ⇒ คืน ⇒ ข้อที่ผู้อ่านเห็น ⇒ `null` = คอลัมน์แรกไม่อยู่บนจอ (ทีละฉบับที่อ่านคอลัมน์อื่นอยู่) ⇒ ⛔ ไม่แตะ
 */
function จดที่คอลัมน์แรก(): { บท: number; ข้อ: number; ซ่อน?: boolean } | null {
  if (import.meta.server) return null
  const ที่ = หาข้อบนจอ()
  // ⭐ ทีละฉบับที่อ่านคอลัมน์คนละที่อยู่ ⇒ ฝั่งตารางซ่อน ⇒ ใช้ข้อที่จดไว้ครั้งก่อน ⇒ ที่เลื่อนของหน้าคืนเองตอนกลับไปอ่านตาราง (`ดูเทียบที่`)
  if (!ที่) return ข้อที่พาไป.value ? { บท: บทของข้อที่พาไป.value, ข้อ: ข้อที่พาไป.value, ซ่อน: true } : null
  ข้อที่พาไป.value = ที่.ข้อ
  บทของข้อที่พาไป.value = ที่.บท
  บทจับคู่.value = ที่.บท
  return ที่
}
async function คืนที่คอลัมน์แรก(ที่: { บท: number; ข้อ: number; ซ่อน?: boolean } | null) {
  if (!ที่ || ที่.ซ่อน) return
  await nextTick()
  if (ดูเทียบที่.value >= 0) return
  เลื่อนไปที่จุด()
  ยึดข้อที่พาไป = true
}

/**
 * ⭐ **ทีละฉบับ ⇒ ไปอ่านคอลัมน์คนละที่แล้วกลับมา ⇒ คอลัมน์แรกอยู่ที่เดิม** (ใบ #143 เกณฑ์ข้อ 2)
 *   ⇒ ตอนอ่านคอลัมน์คนละที่ ฝั่งตารางซ่อน ⇒ หน้าสั้นลง ⇒ เบราว์เซอร์หนีบที่เลื่อนของหน้า ⇒ กลับมาแล้วอยู่ต้นหน้า
 *   ⇒ จดที่เลื่อนไว้ก่อนซ่อน (`flush: 'pre'` ⇒ ก่อนหน้าวาดใหม่) ⇒ กลับมาแล้วเลื่อนคืน
 *   ⇒ ⚠️ ตอนอ่านคอลัมน์คนละที่ ⇒ ทุกบทของตารางซ่อน ⇒ ตัวต่อบทหยุดอยู่แล้ว (`นัดตรวจการเลื่อน`) ⇒ เลื่อนหน้าขึ้นบนสุด ⛔ ทำให้ต่อบทก่อนหน้า
 */
let ที่เลื่อนก่อนซ่อนตาราง: number | null = null
watch(
  ดูเทียบที่,
  (ใหม่, เก่า) => {
    if (import.meta.server) return
    // ⭐ ไปอ่านคอลัมน์คนละที่ ⇒ หน้าเหลือแค่กล่องของมัน ⇒ ขึ้นไปบนสุดของหน้า ⇒ ⛔ ไม่ค้างที่เลื่อนของตารางจนกล่องหลุดขึ้นไปเหนือจอ
    if (เก่า < 0 && ใหม่ >= 0) {
      ที่เลื่อนก่อนซ่อนตาราง = window.scrollY
      void nextTick(() => จำที่เลื่อนแล้วเลื่อน(0))
    }
    if (เก่า >= 0 && ใหม่ < 0 && ที่เลื่อนก่อนซ่อนตาราง !== null) {
      const y = ที่เลื่อนก่อนซ่อนตาราง
      ที่เลื่อนก่อนซ่อนตาราง = null
      void nextTick(() => จำที่เลื่อนแล้วเลื่อน(y))
    }
  },
  { flush: 'pre' },
)

/**
 * ⭐⭐ **คอลัมน์แรกจะขยับคนเดียว ⇒ คอลัมน์อื่นในตารางต้องอยู่ที่เดิม** (ข้อ 8)
 *   ⇒ ออกจากตารางไปเป็นคอลัมน์ไหลเองที่บทเดิม ⇒ วางหน้าคอลัมน์เทียบที่มีอยู่ ⇒ ลำดับบนจอ ⛔ ไม่เปลี่ยน
 */
function แยกคอลัมน์อื่นออกจากแถว() {
  const [แรก, ...อื่น] = ฉบับที่แสดง.value
  // ⭐⭐ ใบ #145 ก้อน ง. ⇒ คำภาษาเดิมเป็นคอลัมน์อื่นเหมือนฉบับแปล ⇒ ⛔ ตามคอลัมน์แรกไปอีกแล้ว ⇒ อยู่ที่เดิม ออกไปเลื่อนแยก
  //   ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 1.1) ⇒ กดที่คอลัมน์แรก ⇒ คำเดิมไปด้วย ⇒ พี่เอมเคาะ 6 พ.ย. 2569 *ทุกคอลัมน์เทียบเท่ากัน*
  //   ⇒ ลำดับของคอลัมน์ที่ออกไป ⇒ ตามลำดับเดิมในตาราง ⇒ คำเดิมนั่งตำแหน่งของมัน
  const ไปด้วยคำเดิม = มุม.value.ภาษาเดิม
  // ⭐ ใบ #164 ⇒ คอลัมน์ฉบับซ้ำที่เป็นช่องในตารางก็เป็นคอลัมน์อื่นของตาราง ⇒ อยู่ที่เดิมเหมือนกัน
  const เงา = new Set(เงาในตาราง.value)
  if (!แรก || (!อื่น.length && !ไปด้วยคำเดิม && !เงา.size)) return
  // ⭐ ใบ #143 ⇒ คอลัมน์ที่ออกไปเลื่อนแยก ⇒ อยู่ข้อที่ผู้อ่านเห็นตอนกด ⛔ ไม่ใช่กลับไปต้นบท
  const ที่ = หาข้อบนจอ()
  const บท = ที่?.บท ?? บทของคอลัมน์แรก()
  const ออก = ลำดับตาราง.value.filter((x) => x !== แรก).map((x) => (x === คำเดิมในลำดับ ? หัวคำเดิม.value.ตัวบท : x))
  const ไปที่ = (ฉ: string): คอลัมน์เทียบ => (ที่ ? { เล่ม: รหัสเล่ม, บท, ฉบับ: ฉ, ข้อ: ที่.ข้อ } : { เล่ม: รหัสเล่ม, บท, ฉบับ: ฉ })
  คอลัมน์เทียบที่เปิด.value = [
    ...ออก.map(ไปที่),
    ...คอลัมน์เทียบที่เปิด.value.map((ค, i) => (เงา.has(i) ? ไปที่(ฉบับของเทียบ(ค)) : ค)),
  ]
  if (ไปด้วยคำเดิม) มุม.value = { ...มุม.value, ภาษาเดิม: false }
  ตั้งฉบับ([แรก])
  for (const ค of คอลัมน์เทียบที่เปิด.value) void หยิบของเทียบ(ค)
}

/**
 * ⭐ **คอลัมน์ในตารางที่ไม่ใช่คอลัมน์แรก ขยับคนเดียว** (ข้อ 8)
 *   ⇒ ออกจากตารางไปไหลเอง ⇒ วางเป็นคอลัมน์เทียบอันแรก ⇒ ใกล้ที่เดิมที่สุดเท่าที่ตารางยอม
 *   ⇒ ไปที่บทเดียวกับคอลัมน์แรก ⇒ ⛔ ไม่ต้องทำอะไร ⇒ มันอยู่ตรงนั้นแล้ว
 */
function ย้ายช่องออกจากแถว(ฉ: string, ไป: { เล่ม: string; บท: number; ข้อ?: number }) {
  if (ฉ === คำเดิมในลำดับ) return ย้ายคำเดิมออกจากแถว(ไป)
  // ⭐⭐ ใบ #143 ⇒ พี่เอมเคาะ 5 พ.ย. 2569 *"ถ้าเลือก เล่ม บท ข้อ เดียวกันควร link scroll แต่ถ้าแยก หนังสือ บท ข้อ ต้องแยก scroll"*
  //   ⇒ ที่เดียวกับคอลัมน์แรก (เลือกทั้งบท ⇒ ดูแค่บท · เลือกข้อ ⇒ ข้อต้องตรงกับข้อที่ผู้อ่านเห็นด้วย) ⇒ อยู่ในตารางเลื่อนคู่เหมือนเดิม
  //   ⇒ ต่างกันแม้แค่ข้อ ⇒ ออกไปเลื่อนแยกในกล่องของตัวเอง ⇒ คอลัมน์แรกอยู่ข้อเดิม (`จดที่คอลัมน์แรก`)
  const ที่ = จดที่คอลัมน์แรก()
  if (ไป.เล่ม === รหัสเล่ม && ไป.บท === (ไป.ข้อ ? ที่?.บท : บทของคอลัมน์แรก()) && (!ไป.ข้อ || ไป.ข้อ === ที่?.ข้อ)) return
  เริ่มก้าว()
  ตั้งฉบับ(ฉบับที่แสดง.value.filter((x) => x !== ฉ))
  // ⭐ ทีละฉบับ ⇒ ผู้อ่านกำลังอ่านคอลัมน์นี้อยู่ ⇒ ตามไปอ่านมันในกล่องของมัน ⛔ ไม่เด้งกลับไปคอลัมน์แรก
  if (มุม.value.ฉบับที่ดู === ฉ) ดูฉบับ('เทียบ:0')
  ตั้งคอลัมน์เทียบ([{ ...ไป, ฉบับ: ฉ }, ...คอลัมน์เทียบที่เปิด.value])
  void คืนที่คอลัมน์แรก(ที่)
}

/**
 * ⭐⭐ **ปุ่มบทบนหัวคำภาษาเดิม ⇒ ขยับคอลัมน์คำเดิมคอลัมน์เดียว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 4 ⇒ ก้อน ง.)
 *   ⇒ ⚠️ ของเดิม (หัวข้อ *คำภาษาเดิมเป็นคอลัมน์ธรรมดา* ข้อ 5.3) ⇒ เปิดแผงของคอลัมน์แรก ⇒ สองคอลัมน์ไปด้วยกัน
 *   ⇒ ตารางยังมีฉบับแปล ⇒ แผงทำงานให้คำเดิมคนเดียว (`ช่อง:คำเดิม`) ⇒ ไปคนละที่ ⇒ ออกไปเลื่อนแยกในกล่องของตัวเอง (ใบ #143)
 *   ⇒ ตารางเหลือแต่คำเดิม ⇒ คำเดิมถือบทของหน้า ⇒ แผงของหน้า (ก้อน ก.)
 */
function เปิดแผงของคำเดิม() {
  เปิดแผงให้(ฉบับที่แสดง.value.length ? `ช่อง:${คำเดิมในลำดับ}` : null)
}
function ย้ายคำเดิมออกจากแถว(ไป: { เล่ม: string; บท: number; ข้อ?: number }) {
  const ที่ = จดที่คอลัมน์แรก()
  // ⭐ ที่เดียวกับคอลัมน์แรก ⇒ อยู่ในตารางเลื่อนคู่เหมือนเดิม ⇒ กติกาเดียวกับฉบับแปล (`ย้ายช่องออกจากแถว`)
  if (ไป.เล่ม === รหัสเล่ม && ไป.บท === (ไป.ข้อ ? ที่?.บท : บทของคอลัมน์แรก()) && (!ไป.ข้อ || ไป.ข้อ === ที่?.ข้อ)) return
  เริ่มก้าว()
  const ตัวบท = หัวคำเดิม.value.ตัวบท
  มุม.value = {
    ...มุม.value,
    ภาษาเดิม: false,
    ...(มุม.value.ฉบับที่ดู === ดูคำเดิม ? { ฉบับที่ดู: 'เทียบ:0' } : {}),
  }
  ตั้งคอลัมน์เทียบ([{ ...ไป, ฉบับ: ตัวบท }, ...คอลัมน์เทียบที่เปิด.value])
  void คืนที่คอลัมน์แรก(ที่)
}

// ⛔ **ปุ่ม ‹ › บนหัวคอลัมน์ถูกถอดแล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30302 ข้อ 3)
//   ⇒ ตัวรับของมัน `กดลูกศรบนหัวช่อง` ถอดตามไปด้วย ⇒ เปลี่ยนบทของคอลัมน์เดียวไปทางแผง *เปลี่ยนตอน* (`รับผลจากแผง`)

/**
 * ⭐⭐ **ลูกศรแถบล่าง ⇒ คอลัมน์ซ้ายสุดไปบทก่อนหรือบทถัดไป ⇒ คอลัมน์อื่นทุกคอลัมน์ไปเล่มและบทเดียวกับมัน**
 *   (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/162 ⇒ @krisada ตกลง 9 พ.ย. 2569)
 *   ⇒ *"ปุ่มเลือกข้างล่าง เล่ม บท ข้อ ไปซ้ายขวาข้างล่างควรจะ RE sync ทั้งหมดให้เหมือนทางซ้ายมือหมด"*
 *   ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 9.1) ⇒ แต่ละคอลัมน์ไปบทก่อนหรือบทถัดไปในเล่มของตัวเอง ⇒ คอลัมน์ที่ไม่มีบทนั้นอยู่ที่เดิม
 *   ⇒ ฉบับของแต่ละคอลัมน์คงเดิม ⇒ คอลัมน์ที่เปิดคนละตอน ⇒ กลับมาตอนเดียวกัน ⇒ เข้าตารางเลื่อนคู่ (`รวมคอลัมน์ที่ตรงแถว`)
 *     ⇒ ข้อเสียที่ @krisada รับแล้ว ⇒ กดครั้งเดียว คอลัมน์คนละตอนออกจากตอนที่เปิดไว้ ⇒ กดถอยหลังได้คืน (ใบ #125 ข้อ 13)
 *   ⇒ ฉบับที่ไม่มีบทนั้น ⇒ ทางเดิมของเว็บ ⇒ ไหลเองบอก *ตอนนี้ไม่มีในฉบับ…* ⇒ ⛔ ปิดคอลัมน์ทิ้ง
 *   ⇒ ฉบับเดียวกับที่ตารางมีแล้ว ⇒ ไหลเองที่ตอนเดียวกัน (ใบ #125 ข้อ 20) ⇒ ท่าเดียวกับปุ่ม *เปลี่ยนตอน* กลางแถบล่าง (ข้อ 9.2)
 *   ⇒ คอลัมน์ซ้ายสุดไม่มีบทให้ไป (บทแรก · บทท้ายของเล่ม) ⇒ ⛔ มีลูกศรด้านนั้น ⇒ ⛔ มีลูกศรที่กดแล้วเงียบ
 *   ⇒ ⭐ คิดผลไว้ที่เดียว ⇒ ทั้ง `href` และการกดใช้ผลตัวนี้ ⇒ ลิงก์ที่คัดลอกได้หน้าเดียวกับที่กด
 */
function ผลของลูกศรล่าง(ทิศ: -1 | 1) {
  const บท = ทิศ < 0 ? บทก่อน.value : บทถัด.value
  if (บท === null) return { บท, เทียบ: คอลัมน์เทียบที่เปิด.value, ขยับ: false, ที่อยู่: '' }
  // ⭐ ไปบทใหม่ ⇒ เริ่มต้นบท ⇒ ข้อที่เคยเลือกของบทเดิมหมดหน้าที่ (ใบ #143)
  const เทียบ = คอลัมน์เทียบที่เปิด.value.map((ค): คอลัมน์เทียบ => ({ เล่ม: รหัสเล่ม, บท, ฉบับ: ค.ฉบับ }))
  // ⭐ ที่อยู่หลังกด ⇒ จัดกองล่วงหน้าแบบเดียวกับการกด ⇒ คอลัมน์ที่เข้าตารางไปอยู่ใน `t` · ที่ยังไหลเองอยู่ใน `p`
  //   ⇒ คำภาษาเดิมนั่งที่เดิมในตาราง (`ที่คำเดิมหลังเปลี่ยน` ของฉบับที่ต่อท้าย ⇒ ตำแหน่งเดิม) · กลับเข้าตาราง ⇒ ต่อท้าย
  const กอง = แบ่งกองตรงแถว(เทียบ, บท)
  const ลำดับ = [...กอง.หลัก]
  const ที่คำเดิมหลังกด = กอง.คำเดิมกลับที่ >= 0 ? กอง.คำเดิมกลับที่ : มุม.value.ภาษาเดิม ? ตำแหน่งคำเดิม.value : -1
  if (ที่คำเดิมหลังกด >= 0) ลำดับ.splice(Math.min(ที่คำเดิมหลังกด, ลำดับ.length), 0, หัวคำเดิม.value.ตัวบท)
  // ⭐ ใบ #94 ⇒ ฉบับแรกหลังกดเป็นตัวบทภาษาเดิม ⇒ `c` เป็นเลขเดิม ⇒ ตัวเดียวกับ `ปรับที่อยู่`
  const ที่ = จุดในที่อยู่(บท, null, ลำดับ)
  return { บท, เทียบ, ขยับ: true, ที่อยู่: ที่อยู่หน้าอ่าน(รหัสเล่ม, ที่.บท, ที่.ข้อ, กอง.เหลือ, null, ลำดับ) }
}
const ลูกศรล่าง = computed(() => ({ ก่อน: ผลของลูกศรล่าง(-1), ถัด: ผลของลูกศรล่าง(1) }))
/** ลิงก์ *อ่านทั้งบท* ใต้ช่วง ⇒ ต้นช่วง ⇒ ใบ #94 ⇒ `c` `v` ตัวเดียวกับ `ปรับที่อยู่` */
const ที่อยู่อ่านทั้งบท = computed(() => {
  const ช = ช่วงที่ฟัง.value
  if (!ช) return ''
  const ที่ = จุดในที่อยู่(ช.จาก.บท, ช.จาก.ข้อ)
  return ที่อยู่หน้าอ่าน(รหัสเล่ม, ที่.บท, ที่.ข้อ, คอลัมน์เทียบที่เปิด.value, null, ฉบับในที่อยู่.value)
})
/** ⭐ ถ้อยคำของแถบล่าง ⇒ มากกว่า 1 คอลัมน์ ⇒ บอกว่าเปลี่ยนทุกคอลัมน์ (ข้อ 9.3) ⇒ ตัวถ้อยคำอยู่ที่ `app/utils/ถ้อยคำแถบล่าง.ts` */
// ⭐ ใบ #145 ⇒ นับคำภาษาเดิมเป็นคอลัมน์ด้วย ⇒ TCV + คำเดิม ⇒ ‹ › พาทั้งสองคอลัมน์ไป ⇒ ถ้อยคำ *ทุกคอลัมน์* ที่อนุมัติแล้วจึงจริง
//   ⇒ ⚠️ ของเดิมนับเฉพาะฉบับแปลกับคอลัมน์คนละที่ ⇒ ⛔ เปลี่ยนตัวหนังสือ ⇒ เปลี่ยนแค่ว่าชุดไหนขึ้นเมื่อไร
const คำแถบล่าง = computed(() => (ปิดได้ทุกคอลัมน์.value ? ถ้อยคำหลายคอลัมน์ : ถ้อยคำคอลัมน์เดียว))
function ที่อยู่ของลูกศรล่าง(ผล: ReturnType<typeof ผลของลูกศรล่าง>): string {
  return ผล.ที่อยู่
}
async function กดลูกศรล่าง(ทิศ: -1 | 1) {
  const ผล = ผลของลูกศรล่าง(ทิศ)
  if (!ผล.ขยับ || ผล.บท === null) return
  เริ่มก้าว()
  คอลัมน์เทียบที่เปิด.value = ผล.เทียบ
  คอลัมน์เทียบพัง.value = ''
  for (const ค of ผล.เทียบ) void หยิบของเทียบ(ค)
  // ⭐ ใบ #162 ⇒ ทุกคอลัมน์อยู่ตอนเดียวกับคอลัมน์ซ้ายสุดแล้ว ⇒ เข้าตารางเลื่อนคู่ (ยกเว้นฉบับซ้ำกับตาราง · ฉบับที่เล่มนี้ไม่มี)
  รวมคอลัมน์ที่ตรงแถว(ผล.บท)
  await ไปบท(ผล.บท)
}

/** ⭐ ตั้งค่าคอลัมน์เทียบใหม่ทั้งชุด ⇒ ที่อยู่เปลี่ยนตาม ⇒ คอลัมน์ที่มาอยู่บทเดียวกับคอลัมน์แรกเข้าตาราง
 *  ⛔ **ตัวนี้ ⛔ ไม่เปิดช่องถอยหลังเอง** ⇒ คนเรียกเรียก `เริ่มก้าว()` ก่อน ⇒ 1 การกด = 1 ช่องถอยหลัง (ใบ #125 ข้อ 13) */
function ตั้งคอลัมน์เทียบ(ใหม่: คอลัมน์เทียบ[], ที่แรก?: { บท: number; ข้อ: number } | null) {
  คอลัมน์เทียบที่เปิด.value = ใหม่.slice(0, เพดานคอลัมน์ในที่อยู่)
  คอลัมน์เทียบพัง.value = ''
  รวมคอลัมน์ที่ตรงแถว(ที่แรก?.บท, ที่แรก?.ข้อ)
  if (import.meta.server) return
  ปรับที่อยู่()
  for (const ค of คอลัมน์เทียบที่เปิด.value) void หยิบของเทียบ(ค)
}

function เปลี่ยนคอลัมน์เทียบ(i: number, แก้: Partial<คอลัมน์เทียบ>, ที่แรก?: { บท: number; ข้อ: number } | null) {
  เริ่มก้าว()
  ตั้งคอลัมน์เทียบ(
    คอลัมน์เทียบที่เปิด.value.map((ค, k) => (k === i ? { ...ค, ...แก้ } : ค)),
    ที่แรก,
  )
}

/**
 * ⭐ ใบ #161 ⇒ ช่องเลือกฉบับบนหัวคอลัมน์ตอนอื่น ⇒ เลือกฉบับไหนก็ได้ รวมฉบับที่คอลัมน์อื่นเปิดอยู่ (เกณฑ์ข้อ 7.3)
 *   ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9.7 ทาง ก.) ⇒ ฉบับที่คอลัมน์อื่นใช้อยู่ ⇒ ล็อกในตัวเลือกและกันซ้ำที่นี่
 *   ⇒ ⭐ ที่เดียวกับคอลัมน์แรก + ฉบับที่ตารางยังไม่มี ⇒ เข้าตาราง ⇒ หัวเดิมหายไป ⇒ โฟกัสตามไปที่หัวของมันในตาราง (SC 2.4.3)
 */
function เปลี่ยนฉบับของเทียบ(i: number, ฉบับ: string) {
  const ก่อน = คอลัมน์เทียบที่เปิด.value.length
  เปลี่ยนคอลัมน์เทียบ(i, { ฉบับ })
  void nextTick(() => {
    if (คอลัมน์เทียบที่เปิด.value.length >= ก่อน) return โฟกัสฉบับของเทียบ(i)
    โฟกัสฉบับในตาราง(ชื่อตัวบทเดิมทั้งหมด.includes(ฉบับ) ? คำเดิมในลำดับ : ฉบับ)
  })
}

function ถอดคอลัมน์เทียบ(i: number) {
  เริ่มก้าว()
  ตั้งคอลัมน์เทียบ(คอลัมน์เทียบที่เปิด.value.filter((_, k) => k !== i))
}

/**
 * ⭐⭐ **กดถอยหลังต้องกลับที่เดิม** ⇒ WCAG 2.2 SC 2.4.5 · ใบ #125 ข้อ 13
 *   ⇒ เราเขียนที่อยู่เองด้วย `history` ⇒ ตัวจัดการเส้นทางของ Nuxt ⛔ ไม่รู้เรื่องด้วย
 *   ⇒ **จึงต้องรับ `popstate` เอง** แล้วอ่านสภาพทั้งหน้ากลับมาจากที่อยู่ที่เบราว์เซอร์พาไป
 *   ⇒ ⭐ ใบ #125 ⇒ ฉบับของตาราง (`t`) บท (`c`) และช่วง (`r`) กลับมาด้วย ⇒ ของเดิมคืนแค่คอลัมน์เทียบ (`p`)
 *   ⇒ ⭐ ที่อยู่ที่ ⛔ ไม่มี `t` ⇒ ตารางมี TCV ฉบับเดียว ⇒ เพราะหน้าเติม `t` ให้ทุกครั้งที่ไม่ใช่ (ดู `onMounted`)
 * ⛔ **ที่นี่ ⛔ เรียก `เริ่มก้าว`** ⇒ เปิดช่องใหม่ตอนถอยหลัง ⇒ ปุ่มถอยหลังจะวนไม่จบ
 */
async function ตอนถอยหลัง() {
  const q = new URLSearchParams(location.search)
  คอลัมน์เทียบที่เปิด.value = อ่านคอลัมน์เทียบ(q.get('p'))
  คอลัมน์เทียบพัง.value = ''
  for (const ค of คอลัมน์เทียบที่เปิด.value) void หยิบของเทียบ(ค)
  const จากที่อยู่ = ฉบับของตารางจากที่อยู่(q.get('t'))
  // ⭐ ใบ #145 ⇒ ช่องที่ตารางเหลือแต่คำเดิม (`t=SBLGNT`) ⇒ คืนคำเดิมด้วย ⇒ ⛔ ไม่ตกกลับเป็น TCV
  // ⭐ ก้อน ข. ⇒ ระหว่างอยู่ในหน้า ⇒ คำเดิมที่เปิดอยู่ถูกเขียนลง `t` ทุกครั้ง ⇒ ช่องที่ ⛔ มีชื่อตัวบท = ตอนนั้นคำเดิมปิด
  //   ⇒ ⛔ ใช่ลิงก์จากที่อื่น (ลิงก์ที่ส่งมาตัดสินที่ `onMounted`) ⇒ ถอยหลังหลังติ๊กคำเดิมจึงได้หน้าก่อนติ๊กจริง
  if (มุม.value.ภาษาเดิม !== จากที่อยู่.คำเดิม) มุม.value = { ...มุม.value, ภาษาเดิม: จากที่อยู่.คำเดิม }
  ตั้งฉบับ(จากที่อยู่.มี ? จากที่อยู่.ฉบับ : [ฉบับตั้งต้น], false, จากที่อยู่.ที่)
  const ช่วง = อ่านช่วงฟัง(q.get('r'))
  const ช่วงเปลี่ยน = (ช่วง ? เขียนช่วงฟัง(ช่วง) : '') !== (ช่วงที่ฟัง.value ? เขียนช่วงฟัง(ช่วงที่ฟัง.value) : '')
  if (ช่วงเปลี่ยน) {
    เสียง.หยุด()
    ช่วงที่ฟัง.value = ช่วง && (await กางช่วง(ช่วง)) ? ช่วง : null
  }
  const cดิบ = Number(q.get('c'))
  const vดิบ = Number(q.get('v'))
  // ⭐ ใบ #94 ⇒ ที่อยู่ที่ฉบับแรกเป็นตัวบทภาษาเดิมเขียน `c` `v` เป็นเลขเดิม ⇒ แปลงกลับก่อนเทียบกับบทที่อ่านอยู่
  const ที่ =
    Number.isFinite(cดิบ) && cดิบ > 0
      ? await จุดจากที่อยู่(cดิบ, Number.isFinite(vดิบ) && vดิบ > 0 ? vดิบ : null, ที่อยู่บอกเลขเดิม(q.get('t')))
      : null
  if (ที่ && (ที่.บท !== บทที่อ่านอยู่.value || ช่วงเปลี่ยน))
    await ไปที่จุด({ รหัส: รหัสเล่ม, บท: ที่.บท, ข้อ: ที่.ข้อ })
  // ⭐ ช่องถอยหลังที่เกิดตอนจอยังกว้าง แล้วตอนนี้จอแคบ ⇒ เกิน 2 ⇒ ตัดแบบลิงก์เก่า ⇒ เขียนทับช่องนี้ ⛔ ไม่เปิดช่องใหม่
  if (ตัดให้พอจอแคบ()) ปรับที่อยู่()
}

// ---------------------------------------------------------------- แผงเลือกพระธรรมทำงานให้ใคร
// ⭐⭐ **แผงเลือกพระธรรมมีตัวเดียวทั้งเว็บ** (พี่เอมทัก 12 ต.ค. 2569) ⇒ ⛔ ไม่ทำแผงที่สองขึ้นมา
//   ⇒ ⭐ **จึงต้องจำไว้ว่ารอบนี้เปิดแผงให้ใคร**
//     · `null` = คอลัมน์แรก (หัวคอลัมน์แรก · แถบบน · พวงลิงก์ท้ายหน้า) ⇒ คอลัมน์อื่นอยู่ที่เดิม (ใบ #125 ข้อ 8)
//     · `'ทั้งหมด'` = ปุ่มกลางของแถบล่าง ⇒ ทุกคอลัมน์ไปตอนที่เลือก (ใบ #125 ข้อ 9.2)
//     · `'ช่อง:<ฉบับ>'` = คอลัมน์ในตารางที่ไม่ใช่คอลัมน์แรก ⇒ ไปคนเดียว
//     · เลข 0 ขึ้นไป = เปลี่ยนตอนของคอลัมน์เทียบอันนั้น
//     · ⛔ `-1` (เปิดคอลัมน์เทียบอันใหม่จากปุ่ม *เปิดอีกตอนมาวางข้างกัน*) ถูกถอดแล้ว (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 ข้อ 9.6)
//       ⇒ อยากเทียบตอนอื่น ⇒ ⭐ ใบ #161 ⇒ กด *เพิ่มคอลัมน์* แล้วเปลี่ยนตอนที่หัวคอลัมน์ใหม่ ⇒ ⚠️ ของเดิม ติ๊กฉบับเพิ่ม (ข้อ 6.3)
//   ⇒ ⛔ **ปุ่มที่เปิดแผงอยู่ติดคอลัมน์ที่มันคุมเสมอ** ⇒ การเคาะ 18 ต.ค. 2569
//     *ตัวคุมที่ผูกกับของชิ้นเดียว อยู่ติดของชิ้นนั้น* ⇒ WCAG 2.2 SC 1.3.1 (ระดับ A)
//     ⇒ ⭐ ปุ่มกลางของแถบล่างคุม *ทุกคอลัมน์* ⇒ จึงอยู่ที่แถบของทั้งหน้า ⇒ หลักเดียวกัน
type ผู้ใช้แผง = number | null | 'ทั้งหมด' | `ช่อง:${string}`
const แผงทำงานให้ = ref<ผู้ใช้แผง>(null)
/** ⭐ แผงเลือกเป็นช่วงได้เฉพาะตอนทำงานให้คอลัมน์แรกหรือทุกคอลัมน์ ⇒ ช่วงเป็นของตาราง ⛔ ไม่ใช่ของคอลัมน์เทียบ */
const แผงเลือกช่วงได้ = computed(() => แผงทำงานให้.value === null || แผงทำงานให้.value === 'ทั้งหมด')

function เปิดแผงให้(ใคร: ผู้ใช้แผง) {
  แผงทำงานให้.value = ใคร
  เปิดหน้าต่างเล่ม.value = true
}

/** ปุ่ม *เปลี่ยนตอน* บนหัวของคอลัมน์ในตาราง ⇒ คอลัมน์แรก = `null` · คอลัมน์อื่น = ไปคนเดียว */
function เปิดแผงของช่อง(ฉ: string) {
  เปิดแผงให้(ฉ === ฉบับที่แสดง.value[0] ? null : `ช่อง:${ฉ}`)
}

/** ตัวรับผลจากแผงเลือกพระธรรม ⇒ **แยกทางตามว่าแผงถูกเปิดให้ใคร** */
async function รับผลจากแผง(จุด: จุดอ่าน) {
  const ใคร = แผงทำงานให้.value
  แผงทำงานให้.value = null
  if (ใคร === null || ใคร === 'ทั้งหมด') {
    const เล่มเดิม = จุด.รหัส === รหัสเล่ม
    if (เล่มเดิม) เริ่มก้าว()
    if (ใคร === null) {
      แยกคอลัมน์อื่นออกจากแถว()
    } else {
      // ⭐ ทุกคอลัมน์ไปตอนที่เลือก ⇒ แต่ละคอลัมน์ยังเป็นฉบับเดิมของตัวเอง (ข้อ 9 · 9.2)
      // ⭐ ใบ #143 ⇒ ข้อที่เลือกติดไปด้วย ⇒ ทุกคอลัมน์อยู่ที่เดียวกัน ⇒ กลับเข้าตารางเลื่อนคู่กัน
      คอลัมน์เทียบที่เปิด.value = คอลัมน์เทียบที่เปิด.value.map((ค) =>
        จุด.ข้อ ? { เล่ม: จุด.รหัส, บท: จุด.บท, ฉบับ: ค.ฉบับ, ข้อ: จุด.ข้อ } : { เล่ม: จุด.รหัส, บท: จุด.บท, ฉบับ: ค.ฉบับ },
      )
      คอลัมน์เทียบพัง.value = ''
      for (const ค of คอลัมน์เทียบที่เปิด.value) void หยิบของเทียบ(ค)
    }
    // ⭐ **แผงของคอลัมน์แรกเป็นเจ้าของช่วง** ⇒ เลือกแค่ข้อเริ่ม = ล้างช่วง · เลือกเป็นช่วง = ตั้งช่วงใหม่
    //   ⇒ ⛔ เปลี่ยนช่วงระหว่างเล่นอยู่ ⇒ หยุดคิวเดิม ⇒ คิวเดิม ⛔ ไม่ตรงกับที่ผู้อ่านเลือกแล้ว
    const ใหม่ =
      จุด.ถึง && จุด.ข้อ && เล่มเดิม ? { จาก: { บท: จุด.บท, ข้อ: จุด.ข้อ }, ถึง: จุด.ถึง } : null
    const เดิม = ช่วงที่ฟัง.value ? เขียนช่วงฟัง(ช่วงที่ฟัง.value) : ''
    if ((ใหม่ ? เขียนช่วงฟัง(ใหม่) : '') !== เดิม) เสียง.หยุด()
    // ⭐ ช่วงใหม่ ⇒ กางบทในช่วงให้ครบก่อน ⇒ แล้วค่อยพาไปที่ต้นช่วง
    if (ใหม่ && !(await กางช่วง(ใหม่))) return
    ช่วงที่ฟัง.value = ใหม่
    // ⭐ ใบ #143 ⇒ เลือกทั้งบท = ต้นบท ⇒ คอลัมน์ที่เลือกข้อ 1 ของบทนั้นไว้ ⇒ ที่เดียวกัน ⇒ กลับเข้าตาราง
    if (เล่มเดิม) รวมคอลัมน์ที่ตรงแถว(จุด.บท, จุด.ข้อ ?? 1)
    void ไปที่จุด(จุด)
    return
  }
  const ไป: { เล่ม: string; บท: number; ข้อ?: number } = { เล่ม: จุด.รหัส, บท: จุด.บท }
  if (จุด.ข้อ) ไป.ข้อ = จุด.ข้อ
  if (typeof ใคร === 'string') {
    ย้ายช่องออกจากแถว(ใคร.slice('ช่อง:'.length), ไป)
    return
  }
  // ⭐ เปลี่ยนตอนของคอลัมน์เทียบ ⇒ ฉบับของคอลัมน์นั้นอยู่เหมือนเดิม (ข้อ 8)
  //   ⇒ ⭐ ใบ #143 ⇒ ข้อที่เลือกเก็บไว้กับคอลัมน์นั้น ⇒ กล่องของมันเลื่อนไปข้อนั้น ⇒ ไปตรงกับข้อที่คอลัมน์แรกอยู่ ⇒ กลับเข้าตาราง
  //   ⇒ คอลัมน์แรกอยู่ข้อเดิม (`จดที่คอลัมน์แรก`)
  const ที่ = จดที่คอลัมน์แรก()
  เปลี่ยนคอลัมน์เทียบ(ใคร, { ...ไป, ข้อ: ไป.ข้อ }, ที่)
  void คืนที่คอลัมน์แรก(ที่)
}

// ---------------------------------------------------------------- ชั้นคำภาษาเดิม (ใบงาน #95)
// ⭐⭐ **หยิบเฉพาะตอนผู้อ่านเปิด** ⇒ เกณฑ์ผ่านของใบสั่งเองว่า *คนที่ ⛔ ไม่กดเปิด ⛔ ไม่จ่ายไบต์เลย*
//   ⇒ ของกองนี้เฉลี่ยบทละ 13.7 กิโลไบต์ ⇒ ชั่งไว้ที่ `tools/ชั่งชั้นคำบนเว็บ.py` ⛔ ไม่จดซ้ำที่นี่
//
// ⛔⛔ **ห้ามเอาเลขข้อของชั้นคำไปจับคู่กับเลขข้อของฉบับแปล *ตรง ๆ*** ⇒ สองฝั่งแบ่งข้อไม่เท่ากันจริง
//   ⇒ วัดไว้แล้วใน `docs/ข้อมูล/tcv-ต้นฉบับชุดเดียวกับmacula-ไหม.md` ⇒ ต่างกัน 71 ข้อ ส่วนใหญ่ที่สดุดี
//   ⇒ ⭐ **คอลัมน์คำเรียงด้วยเลขข้อ *ของฝั่งตัวเอง* และพิมพ์เลขนั้นกำกับไว้เสมอ**
//   ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/117 ⇒ เลขบทขึ้นที่ข้อแรกของก้อน (แบบฉบับแปล) กับข้อเดิมที่อยู่คนละบทกับแถว ⇒ ดู `ป้ายเลขข้อ`
// ⭐⭐ **ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/112 ⇒ คำเดิมวางตรงแถวกับข้อแปลแล้ว** (พี่เอมสั่ง 26 ต.ค. 2569)
//   ⇒ ⛔ ของเดิม (ใบ #95) ⛔ ไม่วางให้ตรงบรรทัด เพราะยังไม่มีใครตรวจว่าข้อไหนคู่กับข้อไหน
//   ⇒ ⭐ ตอนนี้มีตารางที่ตรวจแล้ว ⇒ ช่อง `ข้อแปล` ของใบ #104 ⇒ จับคู่ด้วยตารางนั้นเท่านั้น ⛔ ไม่ใช่เลขตรง ๆ
//   ⇒ กติกาว่าข้อเดิมไปอยู่แถวไหน อยู่ที่ `app/utils/แถวคำเดิม.ts` ⛔ ไม่จดซ้ำที่นี่
/** ⭐ ช่องที่ 3 มีเฉพาะคำกริยากรีก ⇒ กาลกับมาลา 2 ตัวอักษร (ใบ #110) ⇒ เจ้าของคือ `server/utils/ชั้นคำ.ts` */
type คำเดิม = [ตัว: string, คำแปล: string, กาล?: string]
interface ผลชั้นคำ {
  บท: number
  ชั้น: Record<string, Record<string, คำเดิม[]>>
  ภาษาของชั้น: Record<string, string>
  ทิศของชั้น: Record<string, 'ltr' | 'rtl'>
  แหล่งของชั้น: Record<string, string>
  /** ข้อเดิมที่อยู่กับข้อแปลคนละเลขกับตัวเอง ⇒ ใช้ตัดตามช่วงเท่านั้น ⇒ เจ้าของกติกาคือ `server/utils/ชั้นคำ.ts` */
  ข้อแปล?: Record<string, [number, number][]>
  /** เครื่องหมายของ Levinsohn ของชั้นกรีก ⇒ `{<รหัส>: [<เครื่องหมาย>]}` (ใบ #146) ⇒ เจ้าของคือ `server/utils/ชั้นคำ.ts` */
  เครื่องหมาย?: Record<string, (number | string)[][]>
}

// ---------------------------------------------------------------- สัญลักษณ์กาล (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/110)
// ⭐⭐ **ชิ้นนี้เป็นก้อนโค้ดแยก ⇒ โหลดตอนคอลัมน์คำกรีกเปิดเท่านั้น** ⇒ ท่าเดียวกับการ์ดคำ
//   ⇒ เกณฑ์ข้อ 8 ⇒ *คนที่ไม่เปิดคอลัมน์คำภาษาเดิม ต้องไม่จ่ายไบต์เพิ่มเลย* ⇒ โค้ด ตาราง และ CSS อยู่ในก้อนนั้นหมด
//   ⇒ ตัวเฝ้าคือ `tools/ด่านกาลบนหน้า.mjs` ข้อ ① ⇒ วัดจากการจราจรจริงของเบราว์เซอร์
// ⭐ ตารางสัญลักษณ์ ชื่อ และเหตุผลของแบบ อยู่ที่ `app/utils/กาลกริยา.ts` ที่เดียว ⛔ ไม่จดซ้ำที่นี่
const กาลบนคำ = ชิ้นโหลดแยก(() => import('~/components/กาลบนคำ.vue'))

// ---------------------------------------------------------------- เครื่องหมายของ Levinsohn (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/146)
// ⭐ ท่าเดียวกับสัญลักษณ์กาล ⇒ ชิ้นเสียงกับ CSS เป็นก้อนแยก ⇒ โหลดตอนคอลัมน์คำกรีกเปิดเท่านั้น (ใบ #111 เกณฑ์ข้อ 11)
// ⭐ ชื่อไทย ถ้อยคำ และเครดิต อยู่ที่ `app/utils/คำเน้น.ts` ⇒ หน้าตาและการกางช่วงอยู่ `app/utils/เครื่องหมายบนคำ.ts`
const เน้นบนคำ = ชิ้นโหลดแยก(() => import('~/components/เน้นบนคำ.vue'))

/** ⭐ กางช่วงของทั้งบทครั้งเดียวต่อไฟล์ ⇒ ไฟล์ของบทไม่เปลี่ยนตัว ⇒ จำไว้กับตัวไฟล์ */
const คลังจุด = new WeakMap<object, Map<string, จุดบนคำ[]>>()
function จุดของข้อ(ไฟล์: ผลชั้นคำ, ชื่อ: string, ข้อ: string, จำนวน: number) {
  if (!ไฟล์.เครื่องหมาย || ชื่อ !== 'คำกรีก') return undefined
  let ของบท = คลังจุด.get(ไฟล์)
  if (!ของบท) {
    ของบท = กางเครื่องหมาย(ไฟล์.เครื่องหมาย, (v) => ไฟล์.ชั้น['คำกรีก']?.[String(v)]?.length ?? 0)
    คลังจุด.set(ไฟล์, ของบท)
  }
  const จุด = Array.from({ length: จำนวน }, (_, i) => ของบท!.get(`${ข้อ}:${i}`))
  return จุด.some(Boolean) ? จุด : undefined
}

// ---------------------------------------------------------------- กล่องของปุ่มเฟืองกับปุ่ม i บนหัวคอลัมน์คำภาษาเดิม (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154)
// ⭐⭐ **ชุดเดียวของทั้งคอลัมน์** ⇒ ⛔ ไม่อยู่หัวก้อนคำของทุกบท (ใบ #119) ⇒ ⛔ แถวใต้หัวหรือหมวดในหน้า Aa (ใบ #151) แล้ว
//   ⇒ สัญลักษณ์กาล · เครื่องหมายช่วยอ่าน · คำอธิบาย ⇒ เหตุผลของที่วาง ชื่อ และหน้าตา อยู่หัวไฟล์ `แถวปุ่มคำเดิม.vue`
// ⭐ ก้อนแยกเหมือนชิ้นอื่นของคอลัมน์นี้ ⇒ โหลดตอนกดปุ่มครั้งแรก ⇒ คนที่ไม่กด ⛔ ไม่จ่ายไบต์
const แถวปุ่มคำเดิม = ชิ้นโหลดแยก(() => import('~/components/แถวปุ่มคำเดิม.vue'))

/** `null` = หยิบแล้วและรู้ว่า **บทนี้ไม่มีชั้นคำ** ⛔ ไม่ใช่ *ยังไม่ได้หยิบ* */
const ชั้นคำที่หยิบมา = ref<Record<string, ผลชั้นคำ | null>>({})
const ชั้นคำพัง = ref('')

async function หยิบชั้นคำ(c: number) {
  const กุญแจ = `${รหัสเล่ม}/${c}`
  if (กุญแจ in ชั้นคำที่หยิบมา.value) return
  try {
    const ผล = await $fetch<ผลชั้นคำ>(ที่อยู่หลังบ้าน(`api/words/${รหัสเล่ม}/${c}.json`))
    ชั้นคำที่หยิบมา.value = { ...ชั้นคำที่หยิบมา.value, [กุญแจ]: ผล }
  } catch (e: unknown) {
    // ⭐ 404 = **บทนี้ไม่มีชั้นคำ** ⇒ เป็นคำตอบที่ถูกต้อง ⛔ ไม่ใช่ความพัง ⇒ จำไว้ว่าไม่มี
    const รหัส = (e as { statusCode?: number })?.statusCode
    if (รหัส === 404) {
      ชั้นคำที่หยิบมา.value = { ...ชั้นคำที่หยิบมา.value, [กุญแจ]: null }
      return
    }
    // ⛔ พังจริง ⇒ **บอกตรง ๆ และตัวบทแปลต้องอ่านต่อได้** ⛔ ห้ามเงียบ ⛔ ห้ามหน้าว่าง
    ชั้นคำพัง.value = 'โหลดคำภาษาเดิมไม่ได้ ⇒ ตัวบทแปลยังอ่านต่อได้ตามปกติ'
  }
}

/** ชั้นคำของบทนั้น ⇒ `undefined` = ยังไม่ได้หยิบ · `null` = หยิบแล้วและบทนี้ ⛔ ไม่มี */
function ชั้นคำของบท(c: number) {
  return ชั้นคำที่หยิบมา.value[`${รหัสเล่ม}/${c}`]
}

// ---------------------------------------------------------------- ชั้นคำตัดตามช่วง (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/104)
// ⭐⭐ **แบบเลือกเป็นช่วง ⇒ ชั้นคำแสดงเฉพาะข้อเดิมที่อยู่กับข้อแปลในช่วง** ⇒ ท่าเดียวกับตัวบทแปล (ใบ #102 ข้อ 19)
//   ⇒ ⛔ **ไม่เอาเลขข้อของช่วงไปตัดเลขข้อของชั้นคำตรง ๆ** ⇒ เลขสองฝั่งต่างกันจริง 2,045 ข้อเดิม
//   ⇒ ข้อเดิมข้อไหนอยู่กับข้อแปลข้อไหน ⇒ **หลังบ้านบอกมาในช่อง `ข้อแปล`** ⇒ กติกากับเหตุผลอยู่ที่ `server/utils/ชั้นคำ.ts`
//   ⇒ ⭐ **เลขที่พิมพ์กำกับยังเป็นเลขฝั่งภาษาเดิม** ⇒ อยู่คนละบทกับแถวจึงพิมพ์บทด้วย ⇒ เช่น วิวรณ์ 13:1–4 ได้ `12:18` (ใบ #117)
// ⭐ **ข้อเดิมอยู่ต่างบทกับข้อแปลได้** (เช่น โยเอล 2:28–32 = ฮีบรู 3:1–5) ⇒ จึงหยิบบทข้างเคียงมาด้วยข้างละบท
//   ⇒ วัดแล้วทุกจุดห่างไม่เกิน 1 บท
// ⭐⭐ **ใบ #112 ⇒ แบบเลือกแค่ข้อเริ่มก็ใช้ตารางเดียวกันแล้ว** ⇒ ข้อเดิมไปอยู่ก้อนบทของ *ข้อแปล* ที่มันอยู่ด้วย
//   ⇒ ⛔ ของเดิมเอาไฟล์บท c ทั้งไฟล์ไปวางก้อนบท c ⇒ ฮีบรูโยเอล 3:1–5 จึงไปอยู่ข้างข้อแปลบท 3 ทั้งที่เนื้อเป็นบท 2
//   ⇒ ⭐ วางตรงแถวแล้วต้องอยู่ถูกบท ⇒ **จึงหยิบบทข้างเคียงข้างละบทด้วยทั้งสองแบบ** ⇒ เฉพาะคนที่เปิดคอลัมน์
interface แถวคำเดิม {
  /** บทของฝั่งภาษาเดิม ⇒ ⛔ ไม่ใช่บทของก้อนที่มันไปอยู่ */
  บท: number
  ข้อ: string
  คำ: คำเดิม[]
  /** ข้อแปลที่ข้อเดิมนี้อยู่ด้วย ⇒ ไม่มีในตาราง = เลขเดียวกับตัวเอง (ใบ #104 · ใบ #112) */
  ไป: [number, number][]
  /** เครื่องหมายของ Levinsohn ทุกชนิดของแต่ละคำ (ใบ #146) */
  จุด?: (จุดบนคำ[] | undefined)[]
  /** หน้าตาของแต่ละคำตามตระกูลที่เปิด (ใบ #146) */
  ตา?: หน้าตาคำ[]
}
interface ชั้นในก้อน {
  ชื่อ: string
  ภาษา: string
  ทิศ: 'ltr' | 'rtl'
  แหล่ง: string
  ข้อ: แถวคำเดิม[]
}

/** บทของฝั่งเดิมที่ต้องหยิบ ⇒ บทที่กางอยู่ (หรือบทในช่วง) บวกข้างเคียงข้างละบท */
const บทเดิมที่ต้องหยิบ = computed<number[]>(() => {
  const ช = ช่วงที่ฟัง.value
  const ต้อง = new Set<number>()
  // ⭐ เพดานคือจำนวนบทของเล่มที่นับรวมสองฝั่ง ⇒ โยเอลฝั่งฮีบรูมี 4 บท ทั้งที่ฉบับแปลมี 3
  // ⭐ ใบ #94 ⇒ `บท` ของเล่มเป็นจำนวนบทของฉบับแปลแล้ว ⇒ บทของฝั่งเดิมอยู่ช่อง `บทเดิม` ⇒ เพดานยังนับรวมสองฝั่งเท่าเดิม
  const เพดาน = Math.max(เล่มนี้.value.บท, เล่มนี้.value.บทเดิม ?? 0)
  const ใส่ = (c: number) => {
    if (c >= 1 && c <= เพดาน) ต้อง.add(c)
  }
  if (ช) for (let c = ช.จาก.บท - 1; c <= ช.ถึง.บท + 1; c++) ใส่(c)
  // ⭐ บทของตัวเองมาก่อน ⇒ คำของบทที่กำลังอ่านถูกขอก่อนบทข้างเคียงเสมอ
  else for (const ก of บทที่แสดง.value) ใส่(ก.บท)
  if (!ช) for (const ก of บทที่แสดง.value) for (const c of [ก.บท - 1, ก.บท + 1]) ใส่(c)
  return [...ต้อง]
})

function ชั้นว่างของไฟล์(ไฟล์: ผลชั้นคำ, ชื่อ: string): ชั้นในก้อน {
  return {
    ชื่อ,
    ภาษา: ไฟล์.ภาษาของชั้น[ชื่อ] ?? '',
    ทิศ: ไฟล์.ทิศของชั้น[ชื่อ] ?? 'ltr',
    แหล่ง: ไฟล์.แหล่งของชั้น[ชื่อ] ?? '',
    ข้อ: [],
  }
}

/**
 * คำเดิมของแต่ละก้อนบทบนหน้า ⇒ `undefined` = ยังหยิบไม่ครบ · `null` = ⛔ ไม่มีคำเดิมให้ก้อนนี้
 *
 * ⭐ ข้อเดิมไปอยู่ก้อนบทของ **ข้อแปลข้อแรกที่อยู่บนหน้า** (และอยู่ในช่วง ถ้ามีช่วง)
 *   ⇒ ข้อเดิมที่ข้อแปลของมันไม่ได้อยู่บนหน้า ⇒ ⛔ ไม่วาง ⇒ มันจะโผล่เองตอนบทของมันถูกต่อเข้ามา
 * ⭐ **แบบเลือกแค่ข้อเริ่ม ⇒ ก้อนบท c ขึ้นทันทีที่ไฟล์บท c มาถึง** ⇒ ⛔ ไม่รอบทข้างเคียง
 *   ⇒ ข้อเดิมจากบทข้างเคียงเติมเข้ามาทีหลังได้ (มีแค่ไม่กี่เล่ม เช่นโยเอล มาลาคี)
 *   ⇒ แบบเลือกเป็นช่วงรอครบทุกไฟล์เหมือนเดิม (ใบ #104) ⇒ ด่านช่วงเทียบชุดข้อเดิมเป๊ะ
 */
const คำของก้อน = computed(() => {
  const ผล = new Map<number, ชั้นในก้อน[] | null | undefined>()
  if (!มุม.value.ภาษาเดิม) return ผล
  const ก้อน = บทที่แสดง.value.map((ก) => ก.บท)
  const บนหน้า = new Set(ก้อน)
  const มีช่วง = !!ช่วงที่ฟัง.value
  const ไฟล์ทั้งหมด = บทเดิมที่ต้องหยิบ.value.map((c) => ชั้นคำของบท(c))
  if (มีช่วง && ไฟล์ทั้งหมด.some((x) => x === undefined)) {
    for (const c of ก้อน) ผล.set(c, undefined)
    return ผล
  }
  const ตามก้อน = new Map<number, Map<string, ชั้นในก้อน>>()
  for (const ไฟล์ of ไฟล์ทั้งหมด) {
    if (!ไฟล์) continue
    for (const [ชื่อ, ข้อทั้งหมด] of Object.entries(ไฟล์.ชั้น)) {
      for (const [ข้อ, คำ] of Object.entries(ข้อทั้งหมด)) {
        const ไป: [number, number][] = ไฟล์.ข้อแปล?.[ข้อ] ?? [[ไฟล์.บท, Number(ข้อ)]]
        // ⭐ ข้อแปลข้อใดข้อหนึ่งอยู่บนหน้า (และในช่วง) ⇒ ข้อเดิมนี้อยู่บนหน้า ⇒ ฝั่งกว้างไว้ก่อน ⇒ คำ ⛔ ไม่หาย (ใบ #104 ข้อ 6.1)
        const ที่ = ไป.find(([บ, ข]) => บนหน้า.has(บ) && อยู่ในช่วง(บ, ข))
        if (!ที่) continue
        const ของก้อน = ตามก้อน.get(ที่[0]) ?? new Map<string, ชั้นในก้อน>()
        ตามก้อน.set(ที่[0], ของก้อน)
        const ชั้น = ของก้อน.get(ชื่อ) ?? ชั้นว่างของไฟล์(ไฟล์, ชื่อ)
        ของก้อน.set(ชื่อ, ชั้น)
        const จุด = จุดของข้อ(ไฟล์, ชื่อ, ข้อ, คำ.length)
        // ⭐ หน้าตาขึ้นกับตระกูลที่เปิด ⇒ อ่าน `มุม.เครื่องหมาย` ที่นี่ ⇒ กดสวิตช์แล้วแถวคิดใหม่เอง
        const ตา = จุด && มุม.value.เครื่องหมาย.length ? จุด.map((จ) => หน้าตาของคำ(จ, มุม.value.เครื่องหมาย)) : undefined
        ชั้น.ข้อ.push({ บท: ไฟล์.บท, ข้อ, คำ, ไป, จุด, ตา })
      }
    }
  }
  for (const c of ก้อน) {
    // ⭐ แบบเลือกแค่ข้อเริ่ม ⇒ ไฟล์ของบทตัวเองยังไม่มา = ยังไม่รู้ ⇒ ⛔ ไม่บอกว่า *ไม่มี* ก่อนเวลา
    if (!มีช่วง && ชั้นคำของบท(c) === undefined) {
      ผล.set(c, undefined)
      continue
    }
    const ของก้อน = ตามก้อน.get(c)
    if (!ของก้อน) {
      ผล.set(c, null)
      continue
    }
    const ชั้น = [...ของก้อน.values()]
    for (const ช of ชั้น) ช.ข้อ.sort((a, b) => a.บท - b.บท || Number(a.ข้อ) - Number(b.ข้อ))
    ผล.set(c, ชั้น)
  }
  return ผล
})

/**
 * ภาษาของชั้นคำที่ขึ้นบนหน้าแล้ว ⇒ ตัดสินว่าแถวปุ่มของคอลัมน์มีปุ่มอะไร (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/119)
 * ⭐ ว่าง = ยังไม่มีก้อนคำไหนขึ้น ⇒ แถวปุ่มซ่อนอยู่ ⇒ ท่าเดียวกับหัวก้อนคำของเดิมที่ขึ้นพร้อมก้อน
 *   ⇒ ⛔ ไม่มีปุ่มที่ขึ้นมาก่อนแล้วกดไม่เกิดอะไร · ⛔ ไม่มีปุ่มกรีกโผล่ทีหลังแล้วดันปุ่มอื่น
 */
/**
 * ⭐⭐ **ชั้นคำที่อยู่บนหน้า ⇒ ชื่อภาษากับแหล่ง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 11.2)
 *   ⇒ ใช้เป็นป้ายบนหัวคอลัมน์คำภาษาเดิมที่หนึบตลอด ⇒ เลื่อนไปข้อไหนก็รู้ว่าคอลัมน์นี้คือภาษาอะไร มาจากไหน
 *   ⇒ ชั้นของบทที่อ่านอยู่มาก่อน ⇒ ชื่อมาจากไฟล์ชั้นคำตรงตัว (ข้อ 21) ⛔ ไม่ได้พิมพ์เอง
 */
const ชั้นบนหน้า = computed(() => {
  const ได้ = new Map<string, { ชื่อ: string; แหล่ง: string }>()
  const ก่อน = คำของก้อน.value.get(บทที่อ่านอยู่.value) || []
  for (const ชั้นทั้งหมด of [ก่อน, ...คำของก้อน.value.values()])
    for (const ช of ชั้นทั้งหมด || []) if (!ได้.has(ช.ชื่อ)) ได้.set(ช.ชื่อ, { ชื่อ: ช.ชื่อ, แหล่ง: ช.แหล่ง })
  return [...ได้.values()]
})
/** ⭐ ชื่อตัวบทบนหัวคอลัมน์คำภาษาเดิม ⇒ SBLGNT หรือ WLC (ข้อ 11.2) ⇒ ที่เดียวกับช่องชื่อฉบับของหัวอื่น */
const ตัวบทบนหัว = computed(() =>
  ชั้นบนหน้า.value.map((ช) => ({ ชื่อ: ช.ชื่อ, ตัวบท: ชื่อตัวบท(ช.ชื่อ) })).filter((x) => x.ตัวบท),
)

/**
 * ⭐⭐ **ที่พอให้แทรกคำภาษาเดิมเป็นช่องของตัวเองไหม** (ข้อ 11)
 *   ⇒ ช่องละ 1 ส่วนเท่ากัน ⇒ แต่ละช่องต้องกว้างอย่างน้อย **23em** ⇒ เลขเดียวกับที่ตารางใช้ตัดสินว่าฉบับวางข้างกันได้ไหม (`main.css` `.pk-คอลัมน์ .pk-ช่องทั้งหมด`)
 *   ⇒ ⚠️ ของเดิม ⇒ ⛔ ไม่พอ ⇒ ฉบับในตารางซ้อนกันในช่องแรก · คำภาษาเดิมได้ช่องของตัวเองขวาติดช่องนั้น ⇒ คำเดิม ⛔ อยู่ในการนับ
 *     ⇒ ⭐ ใบ #145 ข้อ 4 (พี่เอมเคาะ 7 พ.ย. 2569) ⇒ ⛔ ไม่พอ ⇒ คำเดิมเป็นช่องหนึ่งในตารางฉบับ (`คำเดิมในช่อง`) ⇒ วางข้างกันหรือห่อลงแถวกฎเดียวกับฉบับแปล
 *     ⇒ ฉบับแปลฉบับเดียวกับคำเดิมก็ใช้เส้นเดียวกัน ⇒ ⚠️ ของเดิมคู่ TCV กับคำเดิมวางข้างกันเสมอแม้ช่องแคบกว่า 23em
 *   ⇒ ⭐ วัดความกว้างจริงของฝั่งตาราง ⇒ เปลี่ยนเองตอนจอเปลี่ยน ตอนขยายตัวอักษร และตอนเปิดปิดคอลัมน์เทียบ
 *   ⇒ ตัวแปร `แทรกคำเดิมได้` ประกาศไว้ข้าง `คำเดิมในช่อง` ⇒ ใช้ก่อนถึงบรรทัดนี้
 */
let ตัวเฝ้าฝั่งหลัก: ResizeObserver | undefined
function ทานที่แทรกคำเดิม() {
  const ฝั่ง = document.querySelector<HTMLElement>('.pk-ฝั่งหลัก')
  if (!ฝั่ง) return
  const em = parseFloat(getComputedStyle(ฝั่ง).fontSize) || 16
  const rem = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
  const ช่อง = ฉบับที่แสดง.value.length + 1
  const กว้างช่อง = (ฝั่ง.getBoundingClientRect().width - (ช่อง - 1) * 1.5 * rem) / ช่อง
  แทรกคำเดิมได้.value = กว้างช่อง >= 23 * em
}
watch([() => ฉบับที่แสดง.value.length, () => มุม.value.ภาษาเดิม], () => nextTick(ทานที่แทรกคำเดิม))

/**
 * ⭐⭐ **เส้นแบ่งคอลัมน์ ⇒ แถวละกี่ช่อง และกล่องไหนขึ้นแถวใหม่** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/144)
 *   ⇒ เส้นอยู่ซ้ายมือของช่องที่มีช่องอื่นอยู่ข้างซ้าย ⇒ ช่องที่ห่อลงไปเป็นต้นแถวใหม่ต้อง ⛔ มีเส้น (ไม่งั้นเส้นไปโผล่ในช่องเลขข้อ)
 *   ⇒ จอกว้างตารางใช้ `auto-fit` 23em ⇒ แถวละกี่ช่องเป็นผลของความกว้าง ⇒ CSS อ่านเองไม่ได้ ⇒ วัดจากตารางจริงแล้วส่งเป็นคลาส
 *     ⇒ นับช่องของตาราง (`grid-template-columns` ที่คำนวณแล้ว) ⇒ ⛔ นับหัวที่อยู่แถวแรก ⇒ เพิ่มฉบับแล้วช่องว่างที่ยุบไว้ก็นับด้วย
 *     ⇒ ตารางที่ยืมช่องจากตารางแม่ (`subgrid`) หรือแถบหัวที่ไม่ใช่ตาราง (บนล่าง) ⇒ ⛔ ห่อ ⇒ 0 = ไม่ใส่คลาส
 *   ⇒ หัวกับตัวบทวัดแยกกัน ⇒ บนล่างจอแคบหัวเรียงข้างกันในแถบเดียว · ตัวบทซ้อนกันทีละช่อง
 *   ⇒ คอลัมน์คนละบทคนละข้อเป็นกล่องในแถว `flex` ที่ห่อได้ ⇒ กล่องที่ขึ้นต้นแถวเอง (บนไม่ตรงกับกล่องก่อนหน้า) ได้ `pk-ต้นแถว`
 *   ⇒ คลาสไม่เปลี่ยนขนาดของอะไรเลย (เส้นลอยอยู่กลางช่อง) ⇒ วัดซ้ำไม่วนกลับมาทำให้ตัวเองเปลี่ยน
 */
const หัวห่อทุก = ref(0)
/** ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/150 ⇒ บนล่างจอแคบ หัวไม่พอแถวเดียวแล้วขึ้นแถวใหม่ ⇒ คลาส `pk-หัวหลายแถว` */
const หัวหลายแถว = ref(false)
const ตัวบทห่อทุก = ref(0)
const ตอนเทียบต้นแถว = ref<boolean[]>([])
function ช่องต่อแถว(ตาราง: Element | null): number {
  if (!ตาราง || !ตาราง.getClientRects().length) return 0
  const ส = getComputedStyle(ตาราง)
  // ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/150 ⇒ แถบหัวของบนล่างจอแคบเป็น `flex` ที่ห่อได้ ⇒ ไม่พอแถวเดียว ⇒ หัวขึ้นแถวใหม่
  //   ⇒ นับหัวที่อยู่แถวแรก (ขอบบนเท่าหัวแรก) ⇒ ทุกหัวอยู่แถวเดียว ⇒ 0 = ⛔ ห่อ ⇒ คลาสนี้เปลี่ยนแค่ความสูง ⛔ เปลี่ยนความกว้าง ⇒ วัดซ้ำไม่วนกลับ
  if (ส.display === 'flex' && ส.flexWrap === 'wrap') {
    const หัว = [...ตาราง.children].filter((x) => x.getClientRects().length)
    if (หัว.length < 2) return 0
    const บนแรก = หัว[0]!.getBoundingClientRect().top
    const แถวแรก = หัว.filter((x) => Math.abs(x.getBoundingClientRect().top - บนแรก) <= 1).length
    return แถวแรก < หัว.length ? แถวแรก : 0
  }
  if (ส.display !== 'grid' || !ส.gridTemplateColumns || /^(none|subgrid)/.test(ส.gridTemplateColumns)) return 0
  return ส.gridTemplateColumns.replace(/\[[^\]]*\]/g, ' ').trim().split(/\s+/).filter(Boolean).length
}
function วัดเส้นแบ่ง() {
  const ฝั่ง = document.querySelector('.pk-ฝั่งหลัก')
  if (!ฝั่ง) return
  const แถบหัว = ฝั่ง.querySelector(':scope > .pk-หัวคอลัมน์ > .pk-ช่องทั้งหมด')
  const หัว = ช่องต่อแถว(แถบหัว)
  // ⭐ ใบ #150 ⇒ แถบหัวที่ห่อจริง ⇒ เก็บช่องว่างแนวตั้งให้แถบหนึบไม่เกินเพดาน (`main.css` ก้อน *หัวหลายแถว*)
  const หลายแถว = หัว > 0 && !!แถบหัว && getComputedStyle(แถบหัว).display === 'flex'
  if (หัวหลายแถว.value !== หลายแถว) หัวหลายแถว.value = หลายแถว
  const ตัวบท = ช่องต่อแถว(
    ฝั่ง.querySelector(':scope > .pk-ตัวบท .pk-ช่องทั้งหมด:not(.pk-แถวหัวข้อ)'),
  )
  if (หัวห่อทุก.value !== หัว) หัวห่อทุก.value = หัว
  if (ตัวบทห่อทุก.value !== ตัวบท) ตัวบทห่อทุก.value = ตัวบท
  const กล่อง = [...document.querySelectorAll<HTMLElement>('.pk-พื้นที่อ่าน > .pk-ตอนเทียบ')]
  let ก่อน: DOMRect | null = ฝั่ง.getClientRects().length ? ฝั่ง.getBoundingClientRect() : null
  // ⭐ ใบ #164 ⇒ คืนตามลำดับของคอลัมน์ (`data-เทียบ`) ⇒ คอลัมน์ที่เป็นช่องในตาราง ⛔ มีกล่อง ⇒ ลำดับในหน้า ⛔ ตรงกับลำดับของคอลัมน์
  const ต้นแถว = คอลัมน์เทียบที่เปิด.value.map(() => false)
  for (const x of กล่อง) {
    const i = Number(x.getAttribute('data-เทียบ'))
    if (!x.getClientRects().length) {
      ต้นแถว[i] = true
      continue
    }
    const r = x.getBoundingClientRect()
    // 🔴 ใบ #164 ข้อ 4 ⇒ **ตัดสินด้วยแนวนอนอย่างเดียว** ⇒ กล่องที่ขึ้นแถวใหม่ของ `flex` ที่ห่อ ⇒ เริ่มซ้ายกว่าขอบขวาของกล่องก่อนหน้า
    //   ⇒ ⚠️ ของเดิมดูขอบบนด้วย (`|r.top − ก่อน.top| > 1`) ⇒ แต่จอแคบกล่องนี้หนึบใต้แถบบน (`sticky` ⇒ ใบ #143)
    //     ⇒ ขอบบนของมันขึ้นกับที่เลื่อน ⛔ ขึ้นกับแถว ⇒ หน้าเลื่อนอยู่ 38 จุดตอนเพิ่งเพิ่มคอลัมน์ ⇒ ขอบบนต่างกัน ⇒ นับเป็นต้นแถว ⇒ เส้นคั่นหาย
    //     ⇒ เลื่อนไปจนวัดใหม่ตอนขอบบนบังเอิญตรงกัน ⇒ เส้นโผล่ ⇒ ตรงกับที่ @krisada เห็น *"เส้นขึ้นมาทีหลัง"*
    //   ⇒ แนวนอนของ `sticky` ⛔ ขยับตามการเลื่อนขึ้นลง ⇒ ผลเหมือนกันทุกที่เลื่อน
    if (Number.isInteger(i)) ต้นแถว[i] = !ก่อน || r.left < ก่อน.right - 1
    ก่อน = r
  }
  if (ต้นแถว.join() !== ตอนเทียบต้นแถว.value.join()) ตอนเทียบต้นแถว.value = ต้นแถว
}
watch(
  () => [
    ฉบับที่แสดง.value.length,
    มุม.value.ภาษาเดิม,
    คอลัมน์เทียบที่แสดง.value.length,
    เงาในตาราง.value.length,
    วางที่ใช้.value,
    หัวเต็มแถว.value,
    จอแคบ.value,
    แทรกคำเดิมได้.value,
  ],
  () => nextTick(วัดเส้นแบ่ง),
)

/**
 * ⭐ ปุ่ม × บนหัวคอลัมน์คำภาษาเดิม ⇒ ปิดแล้วปุ่มหายไปกับหัว ⇒ โฟกัสกลับไปปุ่ม *เทียบ* ซึ่งเป็นทางเปิดคืน ⇒ WCAG 2.2 SC 2.4.3
 *   ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161 ⇒ ทางเปิดคืนคือปุ่ม *เพิ่มคอลัมน์* ในเมนู *เทียบ* แล้วเลือกตัวบทที่ช่องเลือกฉบับ ⇒ ⚠️ ของเดิม ⇒ ช่องติ๊กคำภาษาเดิม
 */
function ปิดคำเดิม() {
  if (!ปิดได้ทุกคอลัมน์.value) return
  ถอดคำเดิม()
  void nextTick(() => คืนโฟกัสให้ปุ่ม('ฉบับ'))
}
/**
 * ⭐ ปิดคอลัมน์คำภาษาเดิม ⇒ ตัวของ ×
 *   ⇒ ⭐ ใบ #145 ⇒ ตารางเหลือแต่คำเดิม ⇒ ปิดแล้วตารางว่าง ⇒ ตอนเทียบอันแรกขึ้นเป็นเจ้าของหน้า (ทางเดียวกับปิดฉบับแปลฉบับสุดท้าย)
 *   ⇒ ⭐ ตารางเหลือแต่คำเดิม ⇒ ที่อยู่บอกชื่อตัวบท (`t=SBLGNT`) ⇒ ปิดแล้วต้องเขียนที่อยู่ใหม่ ⇒ 1 การกด 1 ช่องถอยหลัง
 */
function ถอดคำเดิม() {
  if (!มุม.value.ภาษาเดิม) return
  const ตารางว่าง = !ฉบับที่แสดง.value.length
  if (ตารางว่าง && !คอลัมน์เทียบที่เปิด.value.length) return
  if (!ตารางว่าง) เริ่มก้าว()
  มุม.value = { ...มุม.value, ภาษาเดิม: false }
  if (ตารางว่าง) ยกตอนเทียบเป็นเจ้าของหน้า()
  else ปรับที่อยู่()
}

// ---------------------------------------------------------------- หัวของคอลัมน์คำภาษาเดิม (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30490)
// ⭐⭐ **ชิ้นส่วนหัวเดียวกับทุกคอลัมน์** (`หัวคอลัมน์.vue`) ⇒ ช่องตัวบท ▾ · ชื่อย่อเล่มกับบท · × ⇒ SC 3.2.4
//   ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 11.2) ⇒ ป้ายตอน · ชื่อตัวบทที่กดไม่ได้ · × ⇒ เรียงไม่เหมือนหัวอื่น
// ⭐ **ช่องตัวบท ▾** ⇒ ตัวเลือกแรกคือตัวบทของคอลัมน์นี้ (SBLGNT หรือ WLC) ⇒ ตามด้วยฉบับแปล ⇒ ⭐ ใบ #161 ⇒ เลือกฉบับที่คอลัมน์อื่นเปิดอยู่ได้ (`เปลี่ยนช่องตาราง`) ⇒ ⚠️ ของเดิมล็อกไว้ (ใบ #131 ข้อ 9.7 ทาง ก.)
//   ⇒ เลือกฉบับแปล ⇒ คอลัมน์นี้กลายเป็นฉบับนั้น **ที่ตำแหน่งเดิม** (ขวาติดคอลัมน์แรก) ⇒ ท่าเดียวกับเปลี่ยนฉบับในหัวอื่น (ใบ #125 ข้อ 8)
//   ⇒ ⛔ ไม่ใช่ตัวเลือกที่มีทางเดียว ⇒ ช่องที่เลือกแล้วไม่มีอะไรเกิดขึ้นขัด Nielsen ข้อ 1 ⇒ ⚠️ การตัดสินของคนทำ ⇒ รอพี่เอมเคาะ
// ⭐ **ชื่อย่อเล่มกับบท** ⇒ คำภาษาเดิมตรงแถวกับคอลัมน์แรก (ใบ #125 ข้อ 1.1) ⇒ กดแล้วเปิดแผงของคอลัมน์แรก ⇒ สองคอลัมน์ไปด้วยกัน
//   ⇒ ชื่อย่อเป็นภาษาไทย ⇒ ต้นฉบับกรีกฮีบรู ⛔ มี `toc3` ⇒ ยืมของฉบับไทยแบบที่ THKJV ยืม (หัวข้อ *หัวคอลัมน์แถวเดียวทุกจอ* ข้อ 2.3)
const หัวคำเดิม = computed(() => {
  // ⭐ ก้อนคำยังไม่มา ⇒ รู้จากพันธสัญญาของเล่ม ⇒ หัว ⛔ กระพริบจากช่องว่างเป็นชื่อตัวบท ⇒ ชื่อเดียวกับ `ถ้อยคำคำเดิม.ts`
  const ตัวบท =
    ตัวบทบนหัว.value[0]?.ตัวบท || ชื่อตัวบท(เล่มนี้.value.พันธสัญญา === 'เดิม' ? 'คำฮีบรู' : 'คำกรีก')
  const ไทย = ฉบับที่มี.value.find((ฉ) => ภาษาของชั้น.value[ฉ] === 'th')
  return {
    ตัวบท,
    ชื่อภาษา: ตัวบทบนหัว.value[0]?.ชื่อ || (เล่มนี้.value.พันธสัญญา === 'เดิม' ? 'คำฮีบรู' : 'คำกรีก'),
    ชื่อย่อ: (ไทย && ของเล่ม.value?.ชื่อย่อของชั้น?.[ไทย]) || undefined,
    ตัวเลือก: ตัวเลือกหัว.value,
  }
})
/**
 * ⭐⭐ **ช่องเลือกฉบับของทุกหัวในตาราง ⇒ รายการเดียวกัน** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 3 ⇒ ก้อน ค.)
 *   ⇒ ฉบับแปลทุกฉบับของเล่ม แล้วตามด้วยตัวบทภาษาเดิมของเล่ม (SBLGNT หรือ WLC) ⇒ หัวคำเดิมก็รายการนี้
 *   ⇒ ⚠️ ของเดิม ⇒ ตัวบทภาษาเดิมมีแค่ในหัวคำเดิมและอยู่บนสุด ⇒ หัวฉบับแปลเลือกคำเดิมไม่ได้
 *   ⇒ ป้ายเป็นชื่อตัวบทตรงตัวแบบรหัสฉบับอื่น ⇒ ⛔ คำใหม่
 */
const ตัวเลือกหัว = computed(() => {
  const ตัวบท = ชื่อตัวบท(เล่มนี้.value.พันธสัญญา === 'เดิม' ? 'คำฮีบรู' : 'คำกรีก')
  return ตัวบท ? [...ฉบับที่มี.value, ตัวบท] : ฉบับที่มี.value
})
/**
 * ⭐ **ภาษาของทุกตัวเลือกในช่องเลือกฉบับ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/175) ⇒ รหัส BCP 47
 *   ⇒ ฉบับแปล ⇒ ภาษาของชั้นจากหลังบ้าน (ตัวเดียวกับ `lang` ของกล่องฉบับ) · ตัวบทภาษาเดิม ⇒ `ภาษาของตัวบท()`
 *   ⇒ หัวคอลัมน์เขียนตัวเลือก *SBLGNT · กรีก* ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำภาษาฉบับ.ts`
 */
const ภาษาของตัวเลือก = computed<Record<string, string>>(() =>
  Object.fromEntries(ตัวเลือกหัว.value.map((ฉ) => [ฉ, ภาษาของชั้น.value[ฉ] || ภาษาของตัวบท(ฉ)])),
)
/**
 * ⭐⭐ **ฉบับของตารางที่เขียนลงที่อยู่ (`t`)** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 5)
 *   ⇒ เหลือแต่คำเดิม ⇒ เขียนชื่อตัวบท ⇒ `t=SBLGNT` หรือ `t=WLC` ⇒ เปิดลิงก์แล้วได้คำเดิมคอลัมน์เดียวเหมือนคนส่ง
 *   ⇒ ⛔ ไม่เขียน ⇒ ที่อยู่ไม่มี `t` ⇒ คนที่เปิดได้ฉบับที่ตัวเองจำไว้ ⇒ ไม่ใช่หน้าที่คนส่งเห็น
 *   ⇒ ⭐ นอกนั้นเหมือนเดิมทุกตัวอักษร ⇒ คำเดิมที่เปิดคู่ฉบับแปล ⛔ ยังไม่อยู่ใน `t` ⇒ ลำดับของคำเดิมในที่อยู่เป็นของก้อน ข. ของใบนี้
 *   ⇒ คนอ่านที่อยู่คือ `ฉบับของตารางจากที่อยู่` ⇒ ตัวบททั้งสองชื่อแปลว่า *เปิดคำเดิม* ⇒ ข้ามเล่มไปพันธสัญญาอื่นยังเปิดถูก
 */
// ⭐ ก้อน ข. ⇒ คำเดิมที่เปิดอยู่เขียนลง `t` เสมอ ที่ตำแหน่งของมัน ⇒ `t=TCV,SBLGNT,LSV` ⇒ ลิงก์ได้ชุดและลำดับเดิม (ข้อ 5)
const ฉบับในที่อยู่ = computed(() => ลำดับตาราง.value.map((x) => (x === คำเดิมในลำดับ ? หัวคำเดิม.value.ตัวบท : x)))

/** ของที่ส่งให้ `หัวคอลัมน์.vue` ⇒ ชุดเดียวทั้งจอกว้างและจอแคบ */
const พร็อปหัวคำเดิม = computed(() => ({
  ป้าย: ป้ายที่ของหน้า.value,
  ชื่อย่อ: หัวคำเดิม.value.ชื่อย่อ,
  เลข: เลขบนแถบล่าง.value,
  ภาษา: 'th',
  ลำดับ: 2,
  ชื่อคอลัมน์: ถ้อยคำคำเดิม.เปิด,
  ชื่อภาษา: หัวคำเดิม.value.ชื่อภาษา,
  ฉบับ: หัวคำเดิม.value.ตัวบท,
  ฉบับที่มี: หัวคำเดิม.value.ตัวเลือก,
  ภาษาของตัวเลือก: ภาษาของตัวเลือก.value,
  // ⭐ ใบ #145 ข้อ 1 ⇒ เหลือคำเดิมคอลัมน์เดียว ⇒ ⛔ ไม่มี × เหมือนคอลัมน์อื่น ⇒ ⚠️ ของเดิมมี × เสมอ
  ปิดได้: ปิดได้ทุกคอลัมน์.value,
  ปุ่มปิด: 'ปิดคำเดิม',
}))
const ภาษาบนหน้า = computed(() => {
  const ผล = new Set<string>()
  for (const ชั้นทั้งหมด of คำของก้อน.value.values()) for (const ช of ชั้นทั้งหมด || []) ผล.add(ช.ภาษา)
  return ผล
})

// ---------------------------------------------------------------- ปุ่มเฟืองกับปุ่ม i บนหัวคอลัมน์คำภาษาเดิม (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154)
// ⭐⭐ **เครื่องมือกับคำอธิบายอยู่บนหัวคอลัมน์ที่อ่านเอง ทุกขนาดจอ** ⇒ หัวหนึบ ⇒ ปุ่มอยู่ใกล้มือตลอดการเลื่อน
//   ⇒ ⚠️ แทนการเคาะของใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/151 ⇒ ปุ่ม *เครื่องมือ* ▾ กับแถวที่กางใต้หัว (จอกว้าง)
//     และหมวด *เครื่องมือภาษาเดิม* ในหน้า Aa (มือถือ) ⇒ @krisada ลองบนจอพับแล้วเห็นว่าหน้า Aa อยู่ไกลจากคอลัมน์ที่อ่าน (ใบ #154 หมายเหตุข้อ 3)
//   ⇒ กล่องเปิดได้ทีละกล่อง ⇒ จอแคบหน้าเต็มจอ · จอกว้างแผงลงมา (กล่องเด้งของใบ #153) ⇒ เหตุผลอยู่หัวไฟล์ `แถวปุ่มคำเดิม.vue`
// ⭐⭐ **เฟืองมีบนหัวคอลัมน์ภาษาเดิมทุกคอลัมน์ ทั้งคำกรีกและคำฮีบรู** (พี่เอมขอ 17 พ.ย. 2569 ⇒ *"ควรอยู่ในเฟืองที่ heading ไม่ใช่ที่ตัว Aa"*)
//   ⇒ บนสุดของกล่องเฟืองคือสวิตช์ *แสดงตัวอักษรกรีก/ฮีบรู* (`แสดงตัวเดิม`) ⇒ ย้ายมาจากแผง Aa ⇒ ใช้ได้กับทุกภาษาเดิม
//   ⇒ ⚠️ ของเดิม ⇒ มีเฉพาะชั้นกรีก (ฮีบรูไม่มีอะไรให้คุม) ⇒ ตอนนี้ฮีบรูมีสวิตช์ตัวเดิมให้คุมแล้ว
//   ⇒ คอลัมน์คนละเล่มคนละบทที่เป็นคำภาษาเดิมก็ได้เฟืองด้วย ⇒ ⛔ งั้นหน้าที่มีแต่คอลัมน์แบบนั้นจะไม่มีที่ปิดตัวอักษร
// ⭐ **สัญลักษณ์กาล · เครื่องหมาย · ปุ่มตัว i ⇒ ยังมีเฉพาะคอลัมน์คำกรีกของหน้า** ⇒ ฮีบรูยังไม่มีข้อมูล · คอลัมน์คนละที่ ⛔ วาดสัญลักษณ์กาล
//   ⇒ ⛔ ไม่มีปุ่มที่กดแล้วไม่เกิดอะไร (ท่าเดียวกับแถวเดิม)
// ⭐ **⛔ จำว่ากล่องไหนเปิด** ⇒ ท่าเดียวกับ Aa · เทียบ ⇒ ⚠️ ค่า `เครื่องมือ` (กางพับแถวของใบ #151) ในเครื่องผู้อ่านถูกอ่านข้ามเงียบ ๆ (`app/utils/มุมมอง.ts`)
//   ⇒ สวิตช์ข้างใน (สัญลักษณ์กาล · เครื่องหมาย) ยังจำค่าเหมือนเดิมทุกตัว (เกณฑ์ข้อ 5)
type กล่องคำเดิมที่มี = 'เครื่องมือ' | 'คำอธิบาย'
const กล่องคำเดิม = ref<'' | กล่องคำเดิมที่มี>('')
/** ⭐ กล่องที่เปิดเป็นของหัวไหน ⇒ `-1` = คอลัมน์คำภาษาเดิมของหน้า · ตัวเลข = ลำดับในคอลัมน์คนละเล่มคนละบท ⇒ เปิดได้ทีละกล่องทั้งหน้า */
const เจ้าของกล่องคำเดิม = ref(-1)
const ไอดีกล่องคำเดิม = { เครื่องมือ: 'pk-เครื่องมือภาษาเดิม', คำอธิบาย: 'pk-คำอธิบายสัญลักษณ์' } as const
/** `id` ของกล่องบนหัวคอลัมน์คนละที่ ⇒ ต่อท้ายลำดับ ⇒ ⛔ ซ้ำกับของหน้า (`aria-controls` ต้องชี้ได้ที่เดียว) */
const ไอดีกล่องของเทียบ = (i: number) => ({ เครื่องมือ: `pk-เครื่องมือภาษาเดิม-${i}`, คำอธิบาย: `pk-คำอธิบายสัญลักษณ์-${i}` })
const มีเครื่องมือภาษาเดิม = computed(() => มุม.value.ภาษาเดิม && ภาษาบนหน้า.value.size > 0)
/** สัญลักษณ์กาล · เครื่องหมาย · ปุ่มตัว i ⇒ มีชั้นกรีกเท่านั้น */
const คำเดิมเป็นกรีก = computed(() => ภาษาบนหน้า.value.has('grc'))
/** ปุ่มบนหัวคอลัมน์ภาษาเดิมของหน้า ⇒ `null` = ⛔ วาดปุ่ม */
const ปุ่มเครื่องมือ = computed(() =>
  มีเครื่องมือภาษาเดิม.value
    ? {
        เปิด: เจ้าของกล่องคำเดิม.value === -1 ? กล่องคำเดิม.value : ('' as const),
        ไอดี: ไอดีกล่องคำเดิม,
        คำอธิบาย: คำเดิมเป็นกรีก.value,
      }
    : null,
)
/** ปุ่มบนหัวคอลัมน์คนละเล่มคนละบท ⇒ มีเฉพาะคอลัมน์ที่เป็นคำภาษาเดิม ⇒ เฟืองอย่างเดียว (สวิตช์ตัวเดิม) */
function ปุ่มเครื่องมือของเทียบ(i: number, คำเดิม: unknown) {
  if (!คำเดิม) return null
  return { เปิด: เจ้าของกล่องคำเดิม.value === i ? กล่องคำเดิม.value : ('' as const), ไอดี: ไอดีกล่องของเทียบ(i), คำอธิบาย: false }
}
/** ของที่กล่องเครื่องมือต้องรู้ ⇒ ค่าเดียวกับทั้งหน้า (`มุม`) ⇒ จำค่าเหมือนเดิม (เกณฑ์ข้อ 5) */
const พร็อปแถวปุ่ม = computed(() => ({
  กาล: มุม.value.สัญลักษณ์กาล,
  เครื่องหมาย: มุม.value.เครื่องหมาย,
  ตัวเดิม: มุม.value.แสดงตัวเดิม,
  เลขStrong: มุม.value.แสดงเลขStrong,
  จุดคั่น: มุม.value.จุดคั่นคำ,
}))
function สลับกาลคำเดิม() {
  มุม.value.สัญลักษณ์กาล = !มุม.value.สัญลักษณ์กาล
}
function ตั้งเครื่องหมายคำเดิม(x: ตระกูลเครื่องหมาย[]) {
  มุม.value.เครื่องหมาย = x
}
function ตั้งตัวเดิม(x: boolean) {
  มุม.value.แสดงตัวเดิม = x
}
/** ⭐ ใบ #178 ⇒ เลข Strong ท้ายคำ ⇒ ค่าอยู่ใน `มุม` (จำค่าเหมือนสวิตช์ตัวเดิม) ⇒ ชิ้นที่วาดคำอ่านจาก `แสดงเลขStrong` ใน `app/utils/เลขStrong.ts` */
function ตั้งเลขStrong(x: boolean) {
  มุม.value.แสดงเลขStrong = x
}
/** ⭐ จุดจาง ๆ คั่นคำแปลตอนซ่อนตัวเดิม (@krisada ขอ 20 พ.ย. 2569) ⇒ ค่าอยู่ใน `มุม` ⇒ จำค่าเหมือนสวิตช์ตัวเดิม */
function ตั้งจุดคั่น(x: boolean) {
  มุม.value.จุดคั่นคำ = x
}
watchEffect(() => {
  ตัวสลับเลขStrong.value = มุม.value.แสดงเลขStrong
})
/** กดปุ่มเฟืองหรือ i ⇒ ปุ่มของกล่องที่เปิดอยู่ = ปิด · อีกปุ่ม = สลับไปกล่องนั้น
 *  ⇒ `เจ้าของ` ⇒ `-1` หัวของหน้า · ตัวเลข = หัวคอลัมน์คนละที่ลำดับนั้น */
function สลับกล่องคำเดิม(แบบ: กล่องคำเดิมที่มี, เจ้าของ = -1) {
  const ปิด = กล่องคำเดิม.value === แบบ && เจ้าของกล่องคำเดิม.value === เจ้าของ
  เจ้าของกล่องคำเดิม.value = เจ้าของ
  กล่องคำเดิม.value = ปิด ? '' : แบบ
}
/** ปิดกล่อง ⇒ × กับ Escape คืนโฟกัสให้ปุ่มที่เปิด ⇒ WAI-ARIA APG Disclosure · WCAG 2.2 SC 2.4.3
 *  ⇒ แตะนอกกล่อง ⇒ ⛔ ย้ายโฟกัส ⇒ ผู้อ่านแตะที่ไหน โฟกัสไปที่นั่น (ท่าเดียวกับเมนูบนแถบบน)
 *  ⇒ ⭐ หาปุ่มที่เปิดจาก `aria-controls` ก่อนปิด ⇒ หน้ามีเฟืองหลายตัวได้ (คอลัมน์คนละที่) ⇒ คืนให้ตัวที่เปิดจริง */
function ปิดกล่องคำเดิม(คืนโฟกัส: boolean) {
  const แบบ = กล่องคำเดิม.value
  if (!แบบ) return
  const ไอดี = (เจ้าของกล่องคำเดิม.value === -1 ? ไอดีกล่องคำเดิม : ไอดีกล่องของเทียบ(เจ้าของกล่องคำเดิม.value))[แบบ]
  const ปุ่ม = [...document.querySelectorAll<HTMLElement>(`[aria-controls="${ไอดี}"]`)].find((x) => x.getClientRects().length)
  กล่องคำเดิม.value = ''
  if (!คืนโฟกัส) return
  void nextTick(() => ปุ่ม?.focus({ preventScroll: true }))
}
// ⭐ คอลัมน์คำภาษาเดิมปิด · เปลี่ยนภาษา · คอลัมน์คนละที่ถูกถอด ⇒ ปุ่มหาย ⇒ กล่องปิดตาม ⇒ ⛔ ค้างกล่องที่ไม่มีปุ่มให้ปิด
const เจ้าของกล่องยังอยู่ = computed(() => {
  const ข = เจ้าของกล่องคำเดิม.value
  if (ข === -1) return มีเครื่องมือภาษาเดิม.value && (กล่องคำเดิม.value !== 'คำอธิบาย' || คำเดิมเป็นกรีก.value)
  return !!คอลัมน์เทียบที่แสดง.value[ข]?.คำเดิม && กล่องคำเดิม.value === 'เครื่องมือ'
})
watch(เจ้าของกล่องยังอยู่, (มี) => {
  if (!มี) กล่องคำเดิม.value = ''
})

// ---------------------------------------------------------------- คำเดิมตรงแถวกับข้อแปล (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/112)
// ⭐⭐ **พี่เอมสั่ง 26 ต.ค. 2569** ⇒ *"เปิดใบแก้คำกรีกเรียงตรงข้อกับย่อหน้า และให้ปุ่มพอดีย่อให้พอดีแถวจริง"*
//   ⇒ ⛔ ของเดิมวางคำทั้งบทเป็นก้อน float ข้างตัวบท ⇒ ตรงกันแค่ต้นบท ⇒ มาระโก 10 ข้อ 10:46 ไปอยู่ข้างคำกรีก 10:22
//   ⇒ ⛔ และ float มีรูจริง ⇒ ปิดเลขบท/ข้อ ⇒ หมุดบทหลุดจากหน้า ⇒ ก้อนบทถัดไปลอยไปทับคอลัมน์ TCV (ใบ #112 ข้อ 13.1)
// ⭐ **จอกว้าง ⇒ `.pk-ตัวบท` เป็นตาราง 2 คอลัมน์ที่ใช้แถวชุดเดียวกัน** ⇒ ฉบับแปลอยู่ซ้าย ก้อนคำอยู่ขวา
//   ⇒ ก้อนคำของแต่ละบทยังเป็นกล่องเดียว (หัวคอลัมน์ ปุ่ม จุดหยุด Tab เดิมทุกอย่าง) ⇒ ข้างในใช้แถวร่วมด้วย `subgrid`
//   ⇒ ⭐ แถวถัดไปเริ่มเมื่อฝั่งที่ยาวกว่าจบ ⇒ **ข้อ n ของสองฝั่งเริ่มระดับเดียวกันเสมอ** ⇒ ⛔ ไม่ต้องคำนวณตำแหน่งเอง
//   ⇒ กฎหน้าตาอยู่ที่ `app/assets/css/แถวคำเดิม.css` ⇒ โหลดมากับ `ตัวจัดแถวคำ.vue` ⇒ คนที่ ⛔ ไม่เปิดคอลัมน์ ⛔ ไม่จ่าย
// ⭐ **1 บท = แถวหัว 1 แถว (หมุดบท + หัวคอลัมน์คำ) + แถวเนื้อ** ⇒ แถวเนื้อตามแบบจัดวาง
//   ⇒ *แยกตามข้อ* 1 ข้อ 1 แถว · *แยกตามย่อหน้า* แถวของใบ #109 · *ไหลต่อเนื่อง* 1 บท 1 แถว (ใบ #112 ข้อ 10)
// ⛔ **ปิดคอลัมน์คำ ⇒ ไม่มีผังเลย** ⇒ ⛔ ไม่มี `style` ⛔ ไม่มี `data-แถว` ⇒ หน้าของคนที่ไม่เปิดเหมือนเดิมทุกจุด
const ตัวจัดแถวคำ = ชิ้นโหลดแยก(() => import('~/components/ตัวจัดแถวคำ.vue'))
/** ⭐ กฎหน้าตาของแถวมากับก้อนโค้ดแยก ⇒ **ก้อนคำขึ้นหลังกฎมาถึงแล้วเท่านั้น** ⇒ ⛔ ไม่มีจังหวะที่ก้อนคำวางผิดที่ */
const ตัวจัดแถวพร้อม = ref(false)

interface ผังบท {
  /** แถวแรกของบทในตาราง (แถวหัว) ⇒ นับจาก 1 ตามเลขแถวของ CSS grid */
  ฐาน: number
  /** จำนวนแถวเนื้อ ⇒ อย่างน้อย 1 */
  จำนวน: number
  ข้อแปล: ข้อแปลในแถว[]
}

const ผังแถว = computed(() => {
  const ผล = new Map<number, ผังบท>()
  if (!มุม.value.ภาษาเดิม) return ผล
  let ต่อไป = 1
  for (const ก of บทที่แสดง.value) {
    let ข้อแปล: ข้อแปลในแถว[] = []
    let จำนวน = 1
    if (มุม.value.จัดวาง === 'แยกตามข้อ') {
      ข้อแปล = ก.แถว.map((x, แถว) => ({ บท: x.บท, ข้อ: Number(x.เลข), แถว }))
      จำนวน = ก.แถว.length
    } else if (มุม.value.จัดวาง === 'แยกตามย่อหน้า') {
      const กลุ่ม = กลุ่มย่อหน้าของบท.value.get(ก.บท) || []
      ข้อแปล = ข้อแปลของกลุ่ม(กลุ่ม)
      จำนวน = กลุ่ม.length
    }
    จำนวน = Math.max(1, จำนวน)
    ผล.set(ก.บท, { ฐาน: ต่อไป, จำนวน, ข้อแปล })
    ต่อไป += 1 + จำนวน
  }
  return ผล
})

/** คำเดิมของก้อนบทหนึ่ง จัดเป็นแถว ⇒ `{<ชื่อชั้น>: [{แถว, ข้อ}]}` ⇒ แถวที่ไม่มีคำเดิม ⛔ ไม่มีกลุ่ม */
const กลุ่มคำของก้อน = computed(() => {
  const ผล = new Map<number, Map<string, { แถว: number; ข้อ: แถวคำเดิม[] }[]>>()
  for (const [บท, ชั้นทั้งหมด] of คำของก้อน.value) {
    if (!ชั้นทั้งหมด) continue
    const ผัง = ผังแถว.value.get(บท)
    const ตามชั้น = new Map<string, { แถว: number; ข้อ: แถวคำเดิม[] }[]>()
    for (const ชั้น of ชั้นทั้งหมด) {
      const แถว = จัดข้อเดิมลงแถว(ชั้น.ข้อ, ผัง?.ข้อแปล || [])
      const กลุ่ม: { แถว: number; ข้อ: แถวคำเดิม[] }[] = []
      ชั้น.ข้อ.forEach((x, i) => {
        const r = Math.min(แถว[i] ?? 0, (ผัง?.จำนวน ?? 1) - 1)
        const ท้าย = กลุ่ม[กลุ่ม.length - 1]
        if (ท้าย && ท้าย.แถว === r) ท้าย.ข้อ.push(x)
        else กลุ่ม.push({ แถว: r, ข้อ: [x] })
      })
      ตามชั้น.set(ชั้น.ชื่อ, กลุ่ม)
    }
    ผล.set(บท, ตามชั้น)
  }
  return ผล
})

/**
 * ที่ของชิ้นหนึ่งในตารางแถว ⇒ คืน `style` ⇒ ⛔ ปิดคอลัมน์คำ = `undefined` ⇒ ⛔ ไม่มี style ติดหน้าเลย
 *   `หมุด` แถวหัวของบท · `ชั้นคำ` ก้อนคำทั้งบท · `กล่องคำ` แถวเนื้อทั้งหมดในก้อน · `เนื้อ` แถวเนื้อที่ `แถว` · `กอง` กองย่อหน้าทั้งบท
 */
function ช่องกริด(บท: number, ส่วน: 'หมุด' | 'ชั้นคำ' | 'กล่องคำ' | 'เนื้อ' | 'กอง', แถว = 0) {
  const ผ = ผังแถว.value.get(บท)
  if (!ผ) return undefined
  if (ส่วน === 'หมุด') return { gridRow: String(ผ.ฐาน) }
  if (ส่วน === 'ชั้นคำ') return { gridRow: `${ผ.ฐาน} / span ${ผ.จำนวน + 1}` }
  if (ส่วน === 'กล่องคำ') return { gridRow: `2 / span ${ผ.จำนวน}` }
  if (ส่วน === 'กอง') return { gridRow: `${ผ.ฐาน + 1} / span ${ผ.จำนวน}` }
  return { gridRow: String(ผ.ฐาน + 1 + แถว) }
}

// ⭐⭐ **ยึดที่ที่ผู้อ่านอ่านค้างไว้ ตอนคอลัมน์คำเปลี่ยนความสูงของแถว** (ใบ #112)
//   ⇒ แบบ *ตามขนาดจริง* แถวยืดตามคำเดิม ⇒ คำเดิมมาถึง **หลัง** หน้าพาไปข้อที่ขอแล้ว ⇒ แถวข้างบนสูงขึ้น ⇒ ข้อที่ขอไหลลง
//     ⇒ วัดเองที่จอ 2000 เปิด `?c=11&v=15` ⇒ ข้อ 15 ไหลจากใต้แถบหนึบลงไป 330 จุด ⇒ ตัวยึดของเบราว์เซอร์ (scroll anchoring) ช่วยไม่หมด
//   ⇒ ⭐ ตัวจัดแถวบอก `จัดแล้ว` ทุกครั้ง ⇒ หน้าดึงที่อ่านค้างกลับมาที่เดิม ⇒ **ยึดไว้จนกว่าผู้อ่านขยับเอง** (ล้อ · นิ้ว · แป้น · คลิก)
//     ⇒ ⛔ ไม่ดึงจอกลับมาขัดผู้อ่านที่เลื่อนไปที่อื่นแล้ว
let ยึดข้อที่พาไป = false
let ที่ยึด: { e: HTMLElement; บน: number } | null = null

/** จดตัวบทแถวแรกที่ผู้อ่านเห็นใต้แถบหนึบ กับระดับของมันบนจอ ⇒ เรียก **ก่อน** หน้าเปลี่ยน */
function จำที่ยึด() {
  if (import.meta.server || ยึดข้อที่พาไป) return
  const ขอบ = ขอบล่างแถบหนึบ()
  for (const e of document.querySelectorAll<HTMLElement>('.pk-ตัวบท [data-ข้อ]')) {
    const r = e.getBoundingClientRect()
    if (r.bottom > ขอบ) {
      ที่ยึด = { e, บน: r.top }
      return
    }
  }
}

function คืนที่ยึด() {
  if (ยึดข้อที่พาไป) {
    เลื่อนไปที่จุด()
    return
  }
  const ย = ที่ยึด
  if (!ย?.e.isConnected) return
  const ห่าง = ย.e.getBoundingClientRect().top - ย.บน
  if (Math.abs(ห่าง) > 1) จำที่เลื่อนแล้วเลื่อน(window.scrollY + ห่าง)
}

function ปล่อยที่ยึด() {
  ยึดข้อที่พาไป = false
  ที่ยึด = null
}

// ⭐ จดที่อ่านค้าง **ก่อน** หน้าวาดใหม่ (`flush: 'pre'`) ⇒ ทุกตัวเลือกที่ทำให้แถวคำเดิมสูงต่ำเปลี่ยน
watch(
  () => [มุม.value.ภาษาเดิม, มุม.value.ขนาดคำเดิม, มุม.value.จัดวาง, มุม.value.สัญลักษณ์กาล, มุม.value.เครื่องหมาย.join(), มุม.value.แสดงเลข, มุม.value.แสดงตัวเดิม, ขนาด.เปอร์เซ็นต์.value, ย่อที่ใช้.value],
  () => จำที่ยึด(),
  { flush: 'pre' },
)

// ⭐⭐ **กดสวิตช์หัวข้อย่อย ⇒ ข้อที่อ่านอยู่ต้องยังอยู่ที่เดิมบนจอ** (ใบ #134 ข้อ 14)
//   ⇒ หัวข้อเกิดหรือหายเหนือข้อที่อ่านอยู่ ⇒ ตัวบทข้างล่างขยับขึ้นลงเท่าความสูงหัวข้อ
//   ⇒ ⭐ จดตัวบทแถวแรกที่เริ่มใต้แถบหนึบ **ก่อน** หน้าวาดใหม่ ⇒ วาดเสร็จแล้วเลื่อนจอชดเชยให้มันกลับมาระดับเดิม
//   ⇒ ⛔ ยึดที่ *ตัวหนังสือของข้อ* ⛔ ไม่ใช่กล่อง `[data-ข้อ]` ⇒ แบบแยกตามข้อ แถวหัวข้ออยู่ในกล่องข้อ ⇒ ยอดกล่องไม่ขยับแต่ตัวหนังสือขยับ
//   ⇒ ⛔ ไม่ใช้ `requestAnimationFrame` ⇒ แท็บที่ซ่อนอยู่ไม่เดินเฟรม ⇒ `nextTick` พอ เพราะวัดกล่องบังคับให้เบราว์เซอร์จัดหน้าเอง
let ที่ยึดหัวข้อ: { e: HTMLElement; บน: number } | null = null
watch(
  () => มุม.value.หัวข้อย่อย,
  () => {
    ที่ยึดหัวข้อ = null
    if (import.meta.server) return
    const ขอบ = ขอบล่างแถบหนึบ()
    for (const e of document.querySelectorAll<HTMLElement>(
      '.pk-ตัวบท .pk-ข้อ > .pk-ช่องทั้งหมด:not(.pk-แถวหัวข้อ), .pk-ตัวบท .pk-ข้อไหล',
    )) {
      const r = e.getBoundingClientRect()
      // ⭐ ข้อแรกที่ **เริ่ม** ใต้แถบหนึบ ⛔ ไม่ใช่ข้อที่แค่ท้ายโผล่มา ⇒ หัวข้อที่เกิดหรือหายอยู่ *เหนือ* ข้อนี้เสมอ
      //   ⇒ ข้อนี้กับทุกอย่างข้างล่างอยู่ที่เดิม ⇒ ข้อที่ท้ายโผล่อยู่ข้างบนก็ ⛔ ขยับ เพราะหัวข้ออยู่ใต้มัน
      if (r.height && r.top >= ขอบ - 1) {
        const ข้อ = e.closest<HTMLElement>('[data-ข้อ]')
        ที่ยึดหัวข้อ = { e: ข้อ && ข้อ.classList.contains('pk-ข้อไหล') ? ข้อ : e, บน: r.top }
        break
      }
    }
  },
  { flush: 'pre' },
)
watch(
  () => มุม.value.หัวข้อย่อย,
  async () => {
    await nextTick()
    const ย = ที่ยึดหัวข้อ
    ที่ยึดหัวข้อ = null
    // ⭐ กล่องเดิมถูกวาดใหม่ (แบบไหลต่อเนื่องเปลี่ยนจากกล่องเดียวเป็นหลายตอน) ⇒ หาตัวใหม่ที่ข้อเดียวกัน
    let e = ย?.e
    if (ย && !e?.isConnected) {
      const ข้อ = ย.e.dataset.ข้อ
      e = ข้อ ? document.querySelector<HTMLElement>(`.pk-ตัวบท .pk-ข้อไหล[data-ข้อ="${ข้อ}"]`) || undefined : undefined
    }
    if (!ย || !e) return
    const ห่าง = e.getBoundingClientRect().top - ย.บน
    if (Math.abs(ห่าง) > 1) จำที่เลื่อนแล้วเลื่อน(window.scrollY + ห่าง)
  },
  { flush: 'post' },
)

/** ป้ายจับคู่แถวเนื้อของสองฝั่ง ⇒ ตัวจัดขนาด *พอดี* กับด่านใช้ ⇒ ⛔ ปิดคอลัมน์คำ = ไม่มีป้าย */
function ป้ายแถว(บท: number, แถว: number) {
  return ผังแถว.value.has(บท) ? `${บท}:${แถว}` : undefined
}

// ---------------------------------------------------------------- คำเดิมบนจอแคบ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/124)
// ⭐⭐ **จอแคบกว่า 768 จุด ⇒ คำเดิมของแต่ละแถวอยู่ใต้แถวนั้น ⛔ ไม่ใช่ก้อนเดียวที่ต้นบท**
//   ⇒ ⛔ ของเดิม ⇒ ก้อนคำทั้งบทอยู่ใต้ชื่อบท ⇒ มาระโก 11 จอ 375 ⇒ ตัวบทข้อ 12 ห่างคำกรีกข้อ 12 ราว 10,000 จุด
//   ⇒ ⭐ แถวเดียวกับจอกว้าง ⇒ หยิบจาก `กลุ่มคำของก้อน` ตัวเดิม ⇒ ⛔ ไม่จับคู่ข้อกับแถวเอง (ข้อ 5.2)
//   ⇒ ⭐ วาดชิ้น `คำเดิมใต้แถว.vue` ต่อท้ายแถวในโครงหน้าจริง ⇒ โปรแกรมอ่านหน้าจออ่านตามลำดับที่ตาเห็น (WCAG 2.2 SC 1.3.2)
// ⭐ **ไหลต่อเนื่อง ⇒ ทั้งบทเป็นแถวเดียว ⇒ ก้อนคำทั้งบทไปอยู่ท้ายบท** ⇒ ป้ายใต้ชื่อบทบอกทาง ⇒ ถ้อยคำอยู่ที่ `app/utils/คำเดิมจอแคบ.ts`
// ⛔ **จอกว้างไม่ผ่านทางนี้เลย** ⇒ `section` ตัวเดิมของทั้งบทยังอยู่ที่เดิม ⇒ หน้าตาเหมือนเดิมทุกจุด (ข้อ 10)
//   ⇒ เส้นแบ่งคือ `จอแคบ` ⇒ `matchMedia('(min-width: 768px)')` ตัวเดียวกับทั้งเว็บ
const ทางคำเดิมจอแคบ = computed<'ใต้แถว' | 'ท้ายบท' | 'ในช่อง' | null>(() => {
  // ⭐ ใบ #131 note_30490 ⇒ ซ้ายขวากับทีละฉบับ ⇒ คำเดิมเป็นคอลัมน์ ⇒ ใต้แถวเหลือเฉพาะบนล่าง
  // ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ ไม่มีแถวฉบับแปลให้ต่อท้าย ⇒ เป็นคอลัมน์เต็มกว้างทุกแบบวาง
  // ⭐ ใบ #145 ข้อ 4 ⇒ จอกว้างที่คำเดิมเป็นช่องในตารางฉบับ ⇒ ใช้กลุ่มคำของแถวชุดเดียวกัน ⇒ วาดเป็นช่องในแถว (`ลำดับช่อง`)
  if (คำเดิมในช่อง.value) return 'ในช่อง'
  if (!จอแคบ.value || !มุม.value.ภาษาเดิม || !บนล่างอยู่.value || เหลือแต่คำเดิม.value) return null
  return มุม.value.จัดวาง === 'ไหลต่อเนื่อง' ? 'ท้ายบท' : 'ใต้แถว'
})

/**
 * ⭐ ลำดับช่องของแถวในตารางฉบับ ⇒ เลขช่องของฉบับแปล · −1 = ช่องคำภาษาเดิม (ใบ #145 ข้อ 4)
 *   ⇒ มีช่องคำเดิมเฉพาะตอน `คำเดิมในช่อง` ⇒ อยู่ตำแหน่งของมันตามลำดับที่เปิด ⇒ ⛔ เรียงด้วยหน้าตา ⇒ ลำดับในโครงหน้า = ลำดับที่ตาเห็น (SC 1.3.2)
 *   ⇒ ทุกแถวมีช่องครบทุกคอลัมน์ ⇒ แถวที่ไม่มีคำเดิม ⇒ ช่องว่าง ⇒ ⛔ ไม่ให้ช่องถัดไปเลื่อนมานั่งผิดคอลัมน์
 */
function ลำดับช่อง(n: number): number[] {
  const ล = Array.from({ length: n }, (_, i) => i)
  if (คำเดิมในช่อง.value) ล.splice(Math.min(ตำแหน่งคำเดิม.value, n), 0, -1)
  return ล
}
/** ⭐ คำเดิมของแถวนี้ที่จะวางในช่อง ⇒ ⛔ มี ⇒ ช่องว่าง */
function คำเดิมของช่อง(บท: number, แถว: number) {
  return ตัวจัดแถวพร้อม.value ? คำใต้แถว.value.get(บท)?.get(แถว) : undefined
}

/** คำเดิมของแต่ละแถวบนจอแคบ ⇒ `{บท → {แถว → ชั้น[]}}` ⇒ แถวที่ไม่มีคำเดิม ⛔ ไม่มีรายการ */
const คำใต้แถว = computed(() => {
  const ผล = new Map<number, Map<number, ชั้นของแถว[]>>()
  if (!ทางคำเดิมจอแคบ.value) return ผล
  for (const [บท, ตามชั้น] of กลุ่มคำของก้อน.value) {
    const ชั้นทั้งหมด = คำของก้อน.value.get(บท)
    if (!ชั้นทั้งหมด) continue
    const ตามแถว = new Map<number, ชั้นของแถว[]>()
    for (const ชั้น of ชั้นทั้งหมด) {
      const รับTab = คำที่รับTab(บท, ชั้น)
      ;(ตามชั้น.get(ชั้น.ชื่อ) || []).forEach((กล, k) => {
        const รายการ = ตามแถว.get(กล.แถว) ?? []
        ตามแถว.set(กล.แถว, รายการ)
        รายการ.push({
          ชื่อ: ชั้น.ชื่อ,
          ภาษา: ชั้น.ภาษา,
          ทิศ: ชั้น.ทิศ,
          แหล่ง: ชั้น.แหล่ง,
          ข้อแรก: ชั้น.ข้อ[0],
          แรก: k === 0,
          ข้อ: กล.ข้อ,
          รับTab,
        })
      })
    }
    ผล.set(บท, ตามแถว)
  }
  return ผล
})

/** ของที่ชิ้น `คำเดิมใต้แถว.vue` ยืมจากหน้าอ่าน ⇒ การ์ด โฟกัส แป้นพิมพ์ชุดเดียวกับจอกว้าง */
const ช่วยคำเดิม: ตัวช่วยคำเดิม = {
  กุญแจคำ: (บท, ชั้น, ข้อ, i) => กุญแจคำ(บท, ชั้น, ข้อ, i),
  เปิดอยู่: (บท, ชั้น, ข้อ, i) => {
    const ค = คำที่เปิด.value
    return ค?.บท === บท && ค.ชั้น === ชั้น && ค.ข้อ === ข้อ && ค.ลำดับ === i
  },
  กดคำ: (e, บท, ชั้น, ข้อ, i, คำ, จุด) => กดคำ(e, บท, ชั้น, ข้อ, i, คำ, จุด),
  โฟกัสคำ: (e, บทก้อน, ชั้น, บท, ข้อ, i) => โฟกัสคำ(e, บทก้อน, ชั้น, บท, ข้อ, i),
  แป้น: (e) => แป้นในกล่องคำ(e),
  เลข: (บท, ชั้น, ข้อ, i, ภาษา) => เลขบนคำ(รหัสเล่ม, บท, ชั้น, ข้อ, i, ภาษา),
}

/**
 * ลิงก์บนป้ายแบบไหลต่อเนื่อง ⇒ พาลงไปที่ก้อนคำท้ายบท แล้ว **ย้ายโฟกัสไปด้วย** ⇒ คนใช้แป้นพิมพ์อ่านต่อจากตรงนั้น (WCAG 2.2 SC 2.4.3)
 *   ⇒ ⛔ ไม่ปล่อยให้ `#` ของลิงก์ทำงานเอง ⇒ `scrollIntoView` ซุกของใต้แถบหนึบ ⇒ หักขอบล่างแถบหนึบเองท่าเดียวกับ `เลื่อนไปที่จุด`
 */
function ไปที่คำเดิมท้ายบท(บท: number) {
  const el = document.getElementById(`คำเดิม-${บท}`)
  if (!el) return
  ปล่อยที่ยึด()
  el.focus({ preventScroll: true })
  จำที่เลื่อนแล้วเลื่อน(window.scrollY + el.getBoundingClientRect().top - ขอบล่างแถบหนึบ() - 8)
}

/**
 * ปุ่มบนป้ายแบบไหลต่อเนื่อง ⇒ เปลี่ยนเป็นแยกตามข้อ ⇒ คำเดิมขึ้นใต้แต่ละข้อทันที
 *   ⇒ ที่อ่านค้างอยู่ไม่หาย ⇒ ตัวยึดของคอลัมน์คำ (`จำที่ยึด` · `คืนที่ยึด`) จับการเปลี่ยนแบบจัดวางอยู่แล้ว
 *   ⇒ ⭐ ปุ่มหายไปพร้อมป้าย ⇒ โฟกัสต้อง ⛔ ไม่หล่นไปต้นหน้า ⇒ ย้ายไปหมุดบทของบทนั้น (WCAG 2.2 SC 2.4.3)
 */
async function ดูคำเดิมทีละข้อ(บท: number) {
  มุม.value = { ...มุม.value, จัดวาง: 'แยกตามข้อ' }
  await nextTick()
  const หมุด = document.getElementById(`บท-${บท}`)
  if (!หมุด) return
  หมุด.setAttribute('tabindex', '-1')
  หมุด.focus({ preventScroll: true })
}

// ---------------------------------------------------------------- การ์ดความหมายคำ (ใบงาน #103)
// ⭐⭐ **ตัวการ์ดเป็นก้อนโค้ดแยก ⇒ โหลดตอนกดคำครั้งแรกเท่านั้น** ⇒ เกณฑ์ข้อ 11 ของใบ
//   ⇒ *คนที่ไม่กดคำ ต้องไม่ต้องโหลดข้อมูลพจนานุกรมเลยสักไบต์* ⇒ ทั้งข้อมูลและโค้ดที่หยิบข้อมูล
//   ⇒ ตัวเฝ้าคือ `tools/ด่านการ์ดคำบนหน้า.mjs` ข้อ ① ⇒ วัดจากการจราจรจริงของเบราว์เซอร์
const การ์ดคำ = ชิ้นโหลดแยก(() => import('~/components/การ์ดคำ.vue'))

interface คำที่เปิดการ์ด {
  บท: number
  ชั้น: string
  ข้อ: string
  ลำดับ: number
  ตัว: string
  คำแปล: string
  ภาษา: 'grc' | 'hbo'
  /** เครื่องหมายของ Levinsohn ทุกชนิดของคำนี้ (ใบ #146) ⇒ การ์ดขึ้นทุกชนิด ⛔ ไม่ขึ้นกับตระกูลที่เปิด */
  จุด?: จุดบนคำ[]
  /** ⭐ ใบ #145 ก้อน ง. ⇒ คำของคอลัมน์คำภาษาเดิมคนละเล่ม ⇒ เล่มกับชื่อเล่มของคอลัมน์นั้น ⇒ ว่าง = เล่มของหน้า */
  เล่ม?: string
  ชื่อเล่ม?: string
  /** ⭐ ใบ #149 ⇒ คำของคอลัมน์คำภาษาเดิมคนละที่ ⇒ ตัวบทของคอลัมน์นั้น ⇒ ลิงก์ที่แชร์พกไปเป็น `t` ⇒ ว่าง = ฉบับของตาราง */
  ฉบับ?: string
}
const คำที่เปิด = ref<คำที่เปิดการ์ด | null>(null)
/** ปุ่มคำที่กดล่าสุด ⇒ ปิดการ์ดแล้วโฟกัสกลับมาที่นี่ (เกณฑ์ข้อ 6.1) */
let ปุ่มคำที่กด: HTMLElement | null = null

const กุญแจคำ = (บท: number, ชั้น: string, ข้อ: string | number, i: number) => `${บท}|${ชั้น}|${ข้อ}|${i}`

/**
 * ⭐⭐ **กล่องคำหนึ่งกล่อง = จุดหยุด Tab จุดเดียว** ⇒ ⛔ ไม่ใช่ 600 จุดตามจำนวนคำ
 *   ⇒ ท่า *roving tabindex* ของ WAI-ARIA Authoring Practices ⇒ คำที่ได้ `tabindex=0` มีตัวเดียวต่อกล่อง
 *   ⇒ เข้ากล่องแล้วเลื่อนทีละคำด้วยลูกศร ⇒ Tab อีกครั้งออกจากกล่องไปของถัดไปเลย
 *   ⇒ WCAG 2.2 SC 2.1.1 Keyboard (ระดับ A) ⇒ ทำได้ด้วยแป้นพิมพ์ทุกคำ ⛔ ไม่ต้องกด Tab ผ่านทั้งบท
 */
const จุดเข้ากล่อง = ref<Record<string, string>>({})
/** ข้อของแต่ละกล่อง ⇒ คิดครั้งเดียวต่อกล่อง ⛔ ไม่ใช่คิดใหม่ทุกปุ่ม (บทยาวมีคำหลายพันคำ) */
const ข้อของกล่อง = new WeakMap<object, { แรก: string; มี: Set<string> }>()
/**
 * คำที่ได้ `tabindex=0` ของกล่อง ⇒ `บทก้อน` คือก้อนบทบนหน้า · กุญแจคำใช้ **บทของฝั่งเดิม** (ใบ #104)
 *   ⇒ ⛔ คำที่จำไว้หลุดออกจากกล่องแล้ว (เปลี่ยนช่วง) ⇒ กลับไปคำแรก ⇒ ⛔ ไม่ปล่อยกล่องที่ไม่มีจุดหยุด Tab เลย
 */
function คำที่รับTab(บทก้อน: number, ชั้น: ชั้นในก้อน) {
  let ข้อ = ข้อของกล่อง.get(ชั้น)
  if (!ข้อ) {
    const แรก = ชั้น.ข้อ[0]
    ข้อ = {
      แรก: แรก ? กุญแจคำ(แรก.บท, ชั้น.ชื่อ, แรก.ข้อ, 0) : '',
      มี: new Set(ชั้น.ข้อ.map((x) => `${x.บท}|${ชั้น.ชื่อ}|${x.ข้อ}|`)),
    }
    ข้อของกล่อง.set(ชั้น, ข้อ)
  }
  const เลือกไว้ = จุดเข้ากล่อง.value[`${บทก้อน}|${ชั้น.ชื่อ}`]
  if (เลือกไว้ && ข้อ.มี.has(เลือกไว้.slice(0, เลือกไว้.lastIndexOf('|') + 1))) return เลือกไว้
  return ข้อ.แรก
}

/** ⭐ ใบ #145 ก้อน ง. ⇒ กดคำในคอลัมน์คำภาษาเดิมคนละที่ ⇒ การ์ดเดียวกับคำในตาราง ⇒ ของเล่มและบทของคอลัมน์นั้น */
function กดคำเทียบ(e: Event, ต: ก้อนเทียบ, บท: number, ข้อ: string, i: number, คำ: คำเดิม) {
  ปุ่มคำที่กด = e.currentTarget as HTMLElement
  คำที่เปิด.value = {
    บท,
    ชั้น: ต.คำเดิม?.ชั้น || '',
    ข้อ,
    ลำดับ: i,
    ตัว: คำ[0],
    คำแปล: คำ[1],
    ภาษา: ต.ภาษา === 'hbo' ? 'hbo' : 'grc',
    เล่ม: ต.เล่ม,
    ชื่อเล่ม: ต.ชื่อเล่ม,
    ฉบับ: ต.ฉบับ,
  }
}
function กดคำ(e: Event, บท: number, ชั้น: string, ข้อ: string | number, i: number, คำ: คำเดิม, จุด?: จุดบนคำ[]) {
  ปุ่มคำที่กด = e.currentTarget as HTMLElement
  const ภาษา = ชั้นคำของบท(บท)?.ภาษาของชั้น[ชั้น] === 'hbo' ? 'hbo' : 'grc'
  คำที่เปิด.value = { บท, ชั้น, ข้อ: String(ข้อ), ลำดับ: i, ตัว: คำ[0], คำแปล: คำ[1], ภาษา, จุด }
  void จัดคำให้พ้นการ์ด()
}

/**
 * ⭐⭐ **การ์ดห้ามบังคำที่กดอยู่** (เกณฑ์ข้อ 6.2)
 *   ⇒ การ์ดเป็นแผ่นล่างจอ สูงไม่เกิน `--pk-สูงการ์ด` ⇒ ตั้ง `scroll-margin-bottom` ของคำให้เท่าแผ่น
 *     แล้วสั่ง `scrollIntoView({block:'nearest'})` ⇒ **เลื่อนเฉพาะตอนที่คำจมอยู่ใต้แผ่น**
 *   ⇒ ⛔ ไม่วัดความสูงจริงของการ์ด ⇒ การ์ดสูงขึ้นทีหลังตอนความหมายโหลดเสร็จ ⇒ เผื่อเต็มเพดานไว้ก่อนเลย
 *   ⇒ และหน้าอ่านถ่างท้ายหน้าเท่าแผ่นตอนการ์ดเปิด (`pk-มีการ์ด`) ⇒ คำบรรทัดท้ายบทก็ยังเลื่อนพ้นได้
 */
async function จัดคำให้พ้นการ์ด() {
  await nextTick()
  const ปุ่ม = ปุ่มคำที่กด
  if (!ปุ่ม) return
  ปุ่ม.scrollIntoView({ block: 'nearest', inline: 'nearest' })
}

/**
 * ⭐⭐ **`?w=12.1.4` ⇒ เปิดการ์ดของคำที่ 4 ของข้อ 12:1 ให้เลย** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/149 ข้อ 9)
 *   ⇒ ลิงก์ที่แชร์คำอธิบายไป ⇒ คนเปิดเห็นการ์ดเดียวกับคนส่ง ⇒ รูปที่อยู่อยู่ `app/utils/ที่อยู่.ts` (`อ่านคำที่แชร์`)
 *   ⇒ ⭐ **กดปุ่มคำบนหน้าเอง ⛔ ไม่ประกอบการ์ดเอง** ⇒ ทางเดียวกับนิ้วกด ⇒ ได้คำ คำแปล เครื่องหมาย และคืนโฟกัสครบ
 *     ⇒ ⭐ ปุ่มคำขึ้นหลังหยิบชั้นคำเสร็จ ⇒ รอปุ่มของข้อนั้นขึ้นจริง ⇒ ⛔ ไม่รอเป็นเวลาตายตัว ⇒ เพดาน 20 วินาทีแล้วเลิกเงียบ ๆ
 *   ⇒ ⛔ หาไม่เจอ (คำที่เกินจำนวนคำในข้อ · ข้อที่ไม่มี) ⇒ เลิกเงียบ ๆ ⇒ หน้ายังอ่านได้ปกติ ⛔ ไม่ใช่หน้าพัง (ข้อ 10)
 *   ⇒ ผู้อ่านกดคำอื่นไปก่อน ⇒ เลิก ⛔ ไม่แย่งการ์ดคืน
 */
async function เปิดการ์ดจากที่อยู่(ค: คำในเล่ม) {
  const หมดเวลา = Date.now() + 20000
  while (Date.now() < หมดเวลา) {
    if (คำที่เปิด.value) return
    const ข้อ = document.querySelector(`.pk-ชั้นคำ .pk-ข้อคำ[data-ข้อเดิม="${ค.บท}:${ค.ข้อ}"]`)
    if (ข้อ) {
      ข้อ.querySelectorAll<HTMLElement>('.pk-คำ')[ค.คำที่ - 1]?.click()
      return
    }
    await new Promise((r) => setTimeout(r, 100))
  }
}

/**
 * ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/94 ⇒ `c` `v` ของลิงก์แชร์คำ ⇒ เลขของฉบับแรกใน `t`
 *   ⇒ คำในตาราง + ฉบับแรกเป็นฉบับแปล ⇒ ข้อแปลที่อยู่แถวเดียวกับคำ (ตาราง `ข้อแปล`) ⇒ ⚠️ ของเดิมเขียนเลขเดิมของคำ ⇒ โยเอลฮีบรู 4:1 ได้ `c=4` ที่ฉบับแปลไม่มี
 *   ⇒ ฉบับแรกเป็นตัวบทภาษาเดิม · คำของคอลัมน์คนละที่ (ลิงก์พกตัวบทนั้นตัวเดียว) ⇒ เลขเดิมของคำเหมือนก่อนใบนี้
 */
const ที่ในลิงก์คำ = computed(() => {
  const ค = คำที่เปิด.value
  if (!ค || ค.ฉบับ || ที่อยู่ใช้เลขเดิม(ฉบับในที่อยู่.value, ชื่อตัวบทเดิมทั้งหมด)) return null
  const ได้ = เดิมไปแปล(ไฟล์เดิมที่มี(ค.บท), Number(ค.ข้อ))
  return ได้ ? { บท: ได้[0], ข้อ: ได้[1] } : null
})

function ปิดการ์ด() {
  คำที่เปิด.value = null
  // ⭐ โฟกัสกลับคำเดิม ⇒ คนใช้แป้นพิมพ์อ่านต่อจากที่เดิมได้ทันที (เกณฑ์ข้อ 6.1)
  ปุ่มคำที่กด?.focus({ preventScroll: true })
}

function โฟกัสคำ(e: FocusEvent, บทก้อน: number, ชั้น: string, บท: number, ข้อ: string | number, i: number) {
  if (e.target === e.currentTarget)
    จุดเข้ากล่อง.value = { ...จุดเข้ากล่อง.value, [`${บทก้อน}|${ชั้น}`]: กุญแจคำ(บท, ชั้น, ข้อ, i) }
}

/** ลูกศรซ้ายขวาเลื่อนทีละคำ · Home End ไปต้นท้ายกล่อง ⇒ ฝั่งฮีบรูอ่านขวาไปซ้าย ⇒ ลูกศรซ้าย = คำถัดไป */
function แป้นในกล่องคำ(e: KeyboardEvent) {
  const ปุ่ม = (e.target as HTMLElement).closest?.('.pk-คำ') as HTMLElement | null
  const กล่อง = e.currentTarget as HTMLElement
  if (!ปุ่ม || !กล่อง.contains(ปุ่ม)) return
  // ⭐ จอแคบ (ใบ #124) ⇒ คำของบทเดียวกันชั้นเดียวกันแยกอยู่ใต้หลายแถว ⇒ ลูกศรเดินข้ามกล่องของชุดเดียวกัน
  //   ⇒ จุดหยุด Tab ยังจุดเดียวต่อบทต่อชั้น ⇒ ⛔ ไม่มีคำไหนที่แป้นพิมพ์ไปไม่ถึง (WCAG 2.2 SC 2.1.1)
  const ชุด = กล่อง.dataset.ชุดคำ
  const ทั้งหมด = ชุด
    ? [...document.querySelectorAll<HTMLElement>(`[data-ชุดคำ="${CSS.escape(ชุด)}"] .pk-คำ`)]
    : [...กล่อง.querySelectorAll<HTMLElement>('.pk-คำ')]
  const ที่ = ทั้งหมด.indexOf(ปุ่ม)
  const ขวาไปซ้าย = กล่อง.getAttribute('dir') === 'rtl'
  let ไป = -1
  if (e.key === 'ArrowRight') ไป = ที่ + (ขวาไปซ้าย ? -1 : 1)
  else if (e.key === 'ArrowLeft') ไป = ที่ + (ขวาไปซ้าย ? 1 : -1)
  else if (e.key === 'Home') ไป = 0
  else if (e.key === 'End') ไป = ทั้งหมด.length - 1
  else return
  e.preventDefault()
  ทั้งหมด[Math.max(0, Math.min(ทั้งหมด.length - 1, ไป))]?.focus()
}

/**
 * ⭐ **ทิ้งเนื้อบทที่อยู่ไกลจากหน้าต่างที่กางอยู่** ⇒ ⛔ ไม่ใช่แค่ทิ้งของบนหน้า
 *   **ทำไม** ⇒ อ่านเล่มยาวจนจบคือเก็บเนื้อทุกบทค้างไว้ในหน่วยความจำของเครื่องผู้อ่าน
 *   ⇒ เก็บเผื่อไว้ข้างละ 2 บท ⇒ เลื่อนกลับไปกลับมาใกล้ ๆ ก็ยัง ⛔ ไม่ต้องโหลดซ้ำ
 */
function เก็บกวาดเนื้อที่ไกล() {
  const เก็บ: Record<string, ผลบท> = {}
  for (let i = iแรก.value - 2; i <= iท้าย.value + 2; i++) {
    const c = ลำดับบท.value[i]
    if (c === undefined) continue
    const กุญแจ = `${รหัสเล่ม}/${c}`
    const ของ = บทที่หยิบมา.value[กุญแจ]
    if (ของ) เก็บ[กุญแจ] = ของ
  }
  บทที่หยิบมา.value = เก็บ
}

const กำลังโหลด = ref(false)
const คำเตือน = ref('')

// ---------------------------------------------------------------- เลขเดิมในที่อยู่ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/94)
// ⭐⭐ **ฉบับแรกของ `t` เป็นตัวบทภาษาเดิม ⇒ `c` `v` เป็นเลขฝั่งเดิม** ⇒ ทั้งตอนอ่านลิงก์และตอนเขียนที่อยู่
//   ⇒ ในหน้าเก็บเลขของฉบับแปลเหมือนเดิมทุกตัว (`บทที่อ่านอยู่` · `ข้อที่พาไป` · `ลำดับบท`) ⇒ แปลงที่ขอบเท่านั้น
//   ⇒ กติกาและเหตุผลอยู่หัวไฟล์ `app/utils/เลขเดิมในที่อยู่.ts` ⇒ ตารางคือ `ข้อแปล` ตัวเดียว ⛔ ไม่ตั้งกติกาที่สอง
/** ไฟล์ชั้นคำของบทเดิมที่หยิบมาแล้ว ⇒ ตัวหาเลขเดิมย้อนกลับใช้ */
const ไฟล์เดิมที่มี = (c: number) => ชั้นคำของบท(c) as ไฟล์เลขเดิม | null | undefined
/** จุดของหน้า ⇒ `c` `v` ที่จะเขียนลงที่อยู่ ⇒ ฉบับแรกเป็นฉบับแปล ⇒ เลขเดิมของตัวเองเหมือนก่อนใบนี้ */
function จุดในที่อยู่(บท: number, ข้อ: number | null, ฉบับ: readonly string[] = ฉบับในที่อยู่.value) {
  if (!ที่อยู่ใช้เลขเดิม(ฉบับ, ชื่อตัวบทเดิมทั้งหมด)) return { บท, ข้อ }
  return จุดเป็นเลขเดิม(ไฟล์เดิมที่มี, บท, ข้อ)
}
/** ไฟล์คำเดิมของเล่มอื่น ⇒ ใช้ตอนข้ามเล่มเท่านั้น ⇒ ⛔ ไม่ปนกับของเล่มนี้ */
const ไฟล์เดิมเล่มอื่น = new Map<string, ไฟล์เลขเดิม | null>()
async function จุดของเล่มอื่นในที่อยู่(เล่ม: string, บท: number, ข้อ: number | null) {
  if (!ที่อยู่ใช้เลขเดิม(ฉบับในที่อยู่.value, ชื่อตัวบทเดิมทั้งหมด)) return { บท, ข้อ }
  await Promise.all(
    [บท - 1, บท, บท + 1].map(async (c) => {
      const กุญแจ = `${เล่ม}/${c}`
      if (c < 1 || ไฟล์เดิมเล่มอื่น.has(กุญแจ)) return
      const ได้ = await $fetch<ไฟล์เลขเดิม>(ที่อยู่หลังบ้าน(`api/words/${กุญแจ}.json`)).catch(() => null)
      ไฟล์เดิมเล่มอื่น.set(กุญแจ, ได้)
    }),
  )
  return จุดเป็นเลขเดิม((c) => ไฟล์เดิมเล่มอื่น.get(`${เล่ม}/${c}`), บท, ข้อ)
}
/**
 * `c` `v` จากที่อยู่ ⇒ จุดของหน้า (เลขฉบับแปล) ⇒ `เลขเดิม` = ฉบับแรกของ `t` ในที่อยู่เป็นตัวบทภาษาเดิม
 *   ⇒ ⛔ บทเดิมนั้นไม่มี ⇒ ข้อความเดิมของหน้า *ไม่มีบท* ด้วยเลขที่ลิงก์ส่งมา ⇒ คืน `null`
 *   ⇒ หยิบไฟล์ไม่สำเร็จ (เน็ตหลุด) ⇒ ใช้เลขตรง ๆ แบบก่อนใบนี้ ⇒ ⛔ ไม่ทิ้งผู้อ่านไว้หน้าเปล่า
 */
async function จุดจากที่อยู่(บท: number, ข้อ: number | null, เลขเดิม: boolean) {
  if (!เลขเดิม) return { บท, ข้อ }
  await หยิบชั้นคำ(บท)
  const ไฟล์ = ไฟล์เดิมที่มี(บท)
  if (ไฟล์ === undefined) return { บท, ข้อ }
  const ได้ = จุดจากเลขเดิม(ไฟล์, ข้อ)
  if (!ได้) คำเตือน.value = `${เล่มนี้.value.ชื่อไทย} ⛔ ไม่มีบท ${บท}`
  return ได้
}
/** ⭐ `t` ในที่อยู่บอกว่าฉบับแรกเป็นตัวบทภาษาเดิมไหม ⇒ อ่านจากที่อยู่ตรง ๆ ⇒ ⛔ ไม่รอสภาพของหน้า */
function ที่อยู่บอกเลขเดิม(t: unknown) {
  const จาก = ฉบับของตารางจากที่อยู่(t)
  return จาก.คำเดิม && จาก.ที่ === 0
}

/**
 * พาไปที่จุดหนึ่ง ⇒ **เลื่อนไปหยุดตรงนั้น แล้วอ่านต่อได้เหมือนเดิม**
 * ⛔ ⛔ **ห้ามตัดเนื้อที่เหลือทิ้ง** — คนตรวจจับได้ 6 ก.ย. 2569 ว่ากดข้อแล้วได้หน้าตันข้อเดียว
 */
async function ไปที่จุด(จุด: จุดอ่าน) {
  คำเตือน.value = ''
  // ⛔ ข้ามเล่มไม่ได้ในหน้าเดียว ⇒ คนละเล่มให้เปิดหน้าของเล่มนั้นแทน
  //   ⭐ **ตอนที่เอามาเทียบติดไปด้วย** ⇒ มันเป็นที่ของตัวเอง ⛔ ไม่ได้ผูกกับเล่มของคอลัมน์แรก
  //     ⇒ ⛔ ไม่ติดไปด้วย = ผู้อ่านที่กดเปลี่ยนเล่มคอลัมน์แรก **เสียตอนที่เทียบไปเงียบ ๆ**
  if (จุด.รหัส !== รหัสเล่ม) {
    const ช่วงเล่มนั้น =
      จุด.ถึง && จุด.ข้อ ? { จาก: { บท: จุด.บท, ข้อ: จุด.ข้อ }, ถึง: จุด.ถึง } : null
    // ⭐ ใบ #94 ⇒ ฉบับแรกเป็นตัวบทภาษาเดิม ⇒ หน้าของเล่มนั้นอ่าน `c` `v` เป็นเลขเดิม ⇒ แปลงด้วยตารางของเล่มนั้นก่อนไป
    const ที่ = await จุดของเล่มอื่นในที่อยู่(จุด.รหัส, จุด.บท, จุด.ข้อ)
    // ⭐ ฉบับของตารางติดไปด้วย (ใบ #125 ข้อ 13) ⇒ หน้าของเล่มนั้นเห็นคอลัมน์ครบตามที่สั่งมา
    location.href = ที่อยู่หน้าอ่าน(
      จุด.รหัส,
      ที่.บท,
      ที่.ข้อ,
      คอลัมน์เทียบที่เปิด.value,
      ช่วงเล่มนั้น,
      ฉบับในที่อยู่.value,
    )
    return
  }
  // ⭐ ผู้อ่านสั่งไปที่อื่นเองระหว่างเล่นอยู่ ⇒ **หยุดเลื่อนตามเสียง** ⇒ ⛔ ไม่ดึงจอกลับไปขัดเขา
  //   ⇒ เสียงยังเล่นต่อ ⇒ ปุ่ม *กลับไปที่กำลังอ่าน* โผล่ให้กดกลับ (ใบ #101 ข้อ 10)
  if (เสียง.ทำงานอยู่.value) เสียง.ตามอ่าน.value = false
  const iจุด = ลำดับบท.value.indexOf(จุด.บท)
  if (iจุด < 0) {
    คำเตือน.value = `${เล่มนี้.value.ชื่อไทย} ⛔ ไม่มีบท ${จุด.บท}`
    return
  }
  // บทที่ยังไม่ได้กางอยู่ ⇒ ตั้งม้วนใหม่ให้เริ่มที่บทนั้น ⛔ ไม่ทิ้งของที่กางอยู่แล้วโดยไม่จำเป็น
  if (iจุด < iแรก.value || iจุด > iท้าย.value) {
    กำลังโหลด.value = true
    const ได้ = await หยิบบท(รหัสเล่ม, จุด.บท)
    กำลังโหลด.value = false
    if (!ได้) {
      คำเตือน.value = `โหลดเนื้อบท ${จุด.บท} ไม่ได้ · ลองใหม่อีกครั้ง`
      return
    }
    iแรก.value = iจุด
    iท้าย.value = iจุด
  }
  ข้อที่พาไป.value = จุด.ข้อ
  บทของข้อที่พาไป.value = จุด.บท
  จุดไฟส่อง()
  บทที่อ่านอยู่.value = จุด.บท
  // ⭐ บนล่างคู่ทีละข้อกับบทที่คอลัมน์แรกถูกพามา ⇒ ⛔ ไม่ใช่บทที่เลื่อนผ่าน (ใบ #131 note_30367 · ดู `จับคู่บนล่าง`)
  บทจับคู่.value = จุด.บท
  ปรับที่อยู่()
  await nextTick()
  เลื่อนไปที่จุด()
  // ⭐ ยึดข้อที่พาไปไว้จนกว่าผู้อ่านขยับเอง ⇒ คอลัมน์คำมาทีหลังแล้วดันแถวข้างบนก็ยังอยู่ที่เดิม (ใบ #112)
  ยึดข้อที่พาไป = true
}

/** ⭐ เน้นข้อที่พาไป **ให้เห็นสักครู่** ⇒ แล้วจางหายไป ⛔ ไม่ค้างเป็นแถบถาวรบนตัวบท */
function จุดไฟส่อง() {
  clearTimeout(ตัวนับไฟส่อง)
  ไฟส่องติด.value = ข้อที่พาไป.value !== null
  if (!ไฟส่องติด.value) return
  ตัวนับไฟส่อง = setTimeout(() => (ไฟส่องติด.value = false), 2500)
}

/** ความสูงของแถบบนที่หนึบอยู่ ⇒ ⭐ **วัดเอาจากของจริง** ⛔ ไม่ฝังตัวเลขไว้ในโค้ด
 *  **ทำไม** ⇒ แถบสูงไม่เท่ากันในแต่ละจอ และสูงขึ้นอีกเมื่อผู้อ่านขยายตัวอักษรจนปุ่มตกแถว
 *  (โค้ดเดิมฝังไว้ว่า 96 จุด ⇒ คนตรวจวัดจริงที่จอ 412 ได้ 159 จุด · ที่ 200% ได้ 251 จุด) */
function ความสูงแถบบน(): number {
  return document.querySelector('.pk-แถบบน')?.getBoundingClientRect().height || 0
}

/** ความสูงของแถบล่างที่หนึบอยู่ ⇒ **วัดจากของจริงเหมือนแถบบน** ⛔ ไม่ฝังตัวเลข
 *  ⇒ ใช้หาว่าช่องที่ผู้อ่านมองเห็นจริง ๆ สิ้นสุดตรงไหน */
function ความสูงแถบล่าง(): number {
  return document.querySelector('.pk-แถบล่าง')?.getBoundingClientRect().height || 0
}

/**
 * ⭐⭐ **ขอบล่างของแถบหนึบทุกแถบที่บังคอลัมน์อ่าน** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/104)
 *   ⇒ แถบบน **บวกหัวคอลัมน์** ⇒ หัวคอลัมน์หนึบอยู่ใต้แถบบนทุกจอ (ใบ #102 จอกว้าง · ใบ #131 note_30365 ข้อ 3.1 จอแคบ)
 *     ⇒ จอแคบ ⇒ หัวของคอลัมน์ที่อยู่คนละเล่มคนละบทหนึบเองด้วย (`.pk-ตอนเทียบ .pk-หัวช่อง`) ⇒ จอกว้างทั้งกล่องหนึบ ⇒ หัวในกล่อง ⛔ หนึบซ้อน
 *   ⛔⛔ **ของเดิมหักแค่แถบบน** ⇒ เปิด `?c=10&v=13` จอ 1950×850 ⇒ แถบหนึบกินถึง y=120 แต่ข้อ 13 ไปเริ่มที่ y=74
 *     ⇒ **บรรทัดแรกของข้อที่พาไปถูกหัวคอลัมน์บัง 46 จุด** ⇒ WCAG 2.2 SC 2.4.11 Focus Not Obscured (ระดับ AA)
 *   ⭐ **วัดจากของจริงทุกครั้ง ⛔ ไม่มีตัวเลขเผื่อ** ⇒ หัวคอลัมน์สูงไม่เท่ากันตามจอ ขนาดตัวอักษร และจำนวนคอลัมน์ที่ห่อ
 *     ⇒ หนึบหรือไม่ อ่านจาก `position` ที่เบราว์เซอร์คำนวณ ⇒ ⛔ ไม่เทียบความกว้างจอเองซ้ำกับ CSS
 */
function ขอบล่างแถบหนึบ(): number {
  let ล่าง = ความสูงแถบบน()
  // ⭐ ใบ #151 ⇒ แถวปุ่มคำเดิม (`.pk-หัวคำเดิม`) ⛔ หนึบเองแล้ว ⇒ ลอยอยู่ในหัวที่หนึบ ⇒ ⛔ นับ (ของเดิมใบ #119 หนึบเองได้)
  //   ⇒ แถวที่ผู้อ่านกางเองทับตัวบทได้ ⇒ ผู้อ่านพับเองได้ทุกเมื่อ ⇒ เหตุผลอยู่หัวไฟล์ `แถวปุ่มคำเดิม.vue`
  for (const หัว of document.querySelectorAll<HTMLElement>('.pk-หัวคอลัมน์, .pk-ชื่อคำเดิม, .pk-ตอนเทียบ .pk-หัวช่อง')) {
    if (getComputedStyle(หัว).position !== 'sticky') continue
    ล่าง = Math.max(ล่าง, (parseFloat(getComputedStyle(หัว).top) || 0) + หัว.getBoundingClientRect().height)
  }
  return ล่าง
}

/** บอก CSS ว่าแถบบนสูงเท่าไร ⇒ **หัวคอลัมน์หนึบจะได้ไปเกาะใต้แถบพอดี ⛔ ไม่ซุกอยู่ใต้แถบ**
 *  ⇒ เจ้าของตัวเลขคือของจริงบนหน้า ⛔ ไม่ใช่ตัวเลขที่พิมพ์ไว้ใน CSS */
function บอกความสูงแถบบน() {
  if (import.meta.server) return
  document.documentElement.style.setProperty('--pk-สูงแถบบน', `${ความสูงแถบบน()}px`)
  // ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30365 ข้อ 3.1 ⇒ จอแคบหัวคอลัมน์หนึบแล้ว
  //   ⇒ ของที่ได้โฟกัสต้อง ⛔ ไม่ซุกใต้หัว ⇒ WCAG 2.2 SC 2.4.11 ⇒ `main.css` ใช้ค่านี้ตั้ง `scroll-padding-top` ของจอแคบ
  //   ⇒ ตั้งหลัง `--pk-สูงแถบบน` ⇒ `top` ของหัวที่หนึบอ่านจากตัวนั้น
  document.documentElement.style.setProperty('--pk-ขอบล่างหนึบ', `${ขอบล่างแถบหนึบ()}px`)
}

/** กล่องของจุดที่พาไปบนหน้า ⇒ ข้อที่พาไป · ไม่มีข้อ = หมุดบท ⇒ ⛔ ยังไม่อยู่บนหน้า = `null` */
function กล่องของที่พาไป(): HTMLElement | null {
  const หมาย =
    ข้อที่พาไป.value === null
      ? `บท-${บทของข้อที่พาไป.value}`
      : `ข้อ-${บทของข้อที่พาไป.value}-${ข้อที่พาไป.value}`
  const เป้า = document.getElementById(หมาย)
  // ⭐ ใบ #145 ⇒ ตารางเห็นแต่คำเดิม ⇒ ข้อของฉบับแปล ⛔ ถูกวาด ⇒ พาไปแถวคำเดิมของแถวเดียวกันแทน (`กล่องที่ตาเห็น`)
  return เป้า && ข้อที่พาไป.value !== null ? กล่องที่ตาเห็น(เป้า) : เป้า
}

/** เอาจุดที่พาไปมาไว้หัวจอ ⇒ *"ให้ตรงนั้นอยู่หัว"* (พี่เอมเคาะ 5 ก.ย. 2569) */
function เลื่อนไปที่จุด() {
  const el = กล่องของที่พาไป()
  if (!el) return
  // ⛔ `scrollIntoView` เอาของไปซุกใต้แถบบนที่หนึบอยู่ ⇒ ต้องหักความสูงแถบออกเอง
  //   ⇒ ⭐ หักถึงขอบล่างของ **ทุกแถบหนึบ** รวมหัวคอลัมน์ (ใบ #104) ⇒ เหตุผลอยู่ที่ `ขอบล่างแถบหนึบ`
  //   ⇒ ⭐ ขอบบนเอาของที่สูงที่สุดในบรรทัดแรก ⇒ เลขข้อยกตัวสูงกว่ากล่องของข้อในแบบไหลต่อเนื่อง
  //     ⇒ วัดเองที่ตัวอักษร 200% ⇒ เลขข้อโผล่พ้นกล่อง 1–2 จุด แล้วไปซุกใต้แถบ
  //   ⛔ **เลขข้อที่ถูกซ่อน (ผู้อ่านปิดเลขบท/ข้อ) เป็น `position: absolute`** ⇒ กรอบ 1 จุดของมัน ⛔ ไม่ได้อยู่ในบรรทัด
  //     ⇒ ของเดิมเอามาคิด ⇒ ได้ขอบบนติดลบ ⇒ **ทั้งหน้าไปหยุดบนสุดแทนข้อที่ขอ** (เจอตอนลองซ้ำใบ #112 ข้อ 13
  //       ⇒ ปิดเลขแล้วเปิด `?c=11&v=15` ⇒ หน้าค้างที่ต้นบท 11 ⇒ เลื่อนขึ้นต่อบท 10 ไม่ได้เพราะอยู่บนสุดแล้ว)
  const ลูก = el.firstElementChild
  const ลูกแรก = ลูก && getComputedStyle(ลูก).position !== 'absolute' ? ลูก.getClientRects()[0] : undefined
  const บนสุด = Math.min(el.getBoundingClientRect().top, ลูกแรก ? ลูกแรก.top : Infinity)
  const บน = window.scrollY + บนสุด - ขอบล่างแถบหนึบ() - 8
  // ⭐ **หมุดบทแรกของหน้า ⇒ เลื่อนไปบนสุด** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/119)
  //   ⇒ เหนือมันมีแต่หัวคอลัมน์ ⛔ ไม่มีตัวบทให้ซ่อน ⇒ หัวคอลัมน์คำภาษาเดิมที่ห่อ 2 แถวแล้ว ⛔ ไม่หนึบ ต้องเห็นทั้งแถว
  //     ⇒ ⛔ ไม่ทำ ⇒ จอ 1100 ตัวอักษร 130% แถวบนของปุ่มไปซุกใต้แถบบน เหลือให้เห็นแค่ปุ่ม *ความหมาย* (เจอเองระหว่างทำใบนี้)
  //   ⇒ ⭐ **เฉพาะตอนเปิดคอลัมน์คำภาษาเดิม** ⇒ หน้าที่ไม่เปิดเลื่อนเหมือนก่อนใบนี้ทุกจุด
  //     ⇒ ⛔ รอบแรกทำทุกหน้า ⇒ ยอห์น 1 จอ 1920 4 ฉบับ (ไม่เปิดคอลัมน์) เลื่อน 0 แทน 38 จุด
  //       ⇒ `tools/ด่านจังหวะการอ่าน.mjs` บนตัวรันนับตัวไทยต่อบรรทัดได้ 39 แทน 43 (งาน 59823) ⇒ เครื่อง Windows นับได้ 43 ทั้งสองแบบ
  //       ⇒ หาต้นเหตุบนเครื่องนี้ไม่ได้ ⇒ ตัดสินใจไม่แตะหน้าของคนที่ไม่เปิดคอลัมน์ ⇒ ของที่ใบนี้ไม่ได้ขอ ⛔ ไม่เปลี่ยน
  const บนสุดของหน้า =
    มุม.value.ภาษาเดิม && ข้อที่พาไป.value === null && el.parentElement?.firstElementChild === el
  จำที่เลื่อนแล้วเลื่อน(บนสุดของหน้า ? 0 : Math.max(0, บน))
  // ⭐ เพิ่งพาไปถึงจุด ⇒ **พักการต่อขึ้นไว้ก่อน** ⇒ การเลื่อนที่ตามมาโดยเรา ⛔ ไม่ได้สั่ง
  //   จะได้ ⛔ ไม่ถูกอ่านว่าผู้อ่านขอย้อนขึ้น (เหตุผลเต็มอยู่ที่ `พักการต่อขึ้น`)
  พักการต่อขึ้น()
}

/** ที่อยู่บนแถบต้องบอกจุดที่อ่านอยู่เสมอ ⇒ ผู้อ่านคัดลอกไปแชร์ได้ทุกวินาที */
function ปรับที่อยู่() {
  if (import.meta.server) return
  const c = บทที่อ่านอยู่.value
  // ⭐ เลื่อนพ้นบทของข้อที่พาไปแล้ว ⇒ เลขข้อในที่อยู่หมดหน้าที่ ⇒ ที่อยู่กลับเป็นบทเปล่า
  const v = c === บทของข้อที่พาไป.value ? ข้อที่พาไป.value : null
  // ⭐ **คอลัมน์เทียบติดไปกับที่อยู่ทุกครั้ง** ⇒ เลื่อนอ่านไปไหนก็ยังคัดลอกลิงก์ไปแชร์ได้ครบทั้งหน้า
  // ⭐ **ช่วงที่ฟังติดไปด้วยทุกครั้ง** ⇒ เลื่อนอ่านพ้นช่วงไปแล้วก็ยังส่งที่อยู่ให้คนอื่นฟังช่วงเดิมได้
  // ⭐ **ฉบับของตารางติดไปด้วย** (ใบ #125 ข้อ 13) ⇒ คอลัมน์ย้ายเข้าออกตารางได้แล้ว ⇒ ไม่ติด = คอลัมน์ที่เข้าตารางหายจากลิงก์
  // ⭐ ใบ #94 ⇒ ฉบับแรกเป็นตัวบทภาษาเดิม ⇒ `c` `v` เขียนเป็นเลขเดิม ⇒ คัดลอกไปเปิดแล้วได้แถวเดิม
  const ที่ = จุดในที่อยู่(c, v)
  history.replaceState(
    null,
    '',
    ที่อยู่หน้าอ่าน(รหัสเล่ม, ที่.บท, ที่.ข้อ, คอลัมน์เทียบที่เปิด.value, ช่วงที่ฟัง.value, ฉบับในที่อยู่.value),
  )
}

/**
 * ⭐⭐ **1 การกด = 1 ช่องถอยหลัง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 13)
 *   ⇒ ก๊อปที่อยู่ตอนนี้เป็นช่องใหม่ก่อน ⇒ แล้วการกดค่อยเขียนสภาพใหม่ทับช่องใหม่นั้นด้วย `ปรับที่อยู่`
 *   ⇒ ช่องเดิมจึงเก็บสภาพ *ก่อนกด* ไว้ครบ ⇒ กดถอยหลังแล้วกลับไปตรงนั้น ⇒ WCAG 2.2 SC 2.4.5
 *   ⇒ ⛔ การเลื่อนอ่าน ⛔ เรียกตัวนี้ ⇒ มันแค่เขียนทับช่องเดิม ⇒ ⛔ ไม่ควรกินปุ่มถอยหลัง
 */
function เริ่มก้าว() {
  if (import.meta.server) return
  history.pushState(null, '', location.href)
}

/** ⭐ เติม `t` อย่างเดียว ⇒ ส่วนอื่นของที่อยู่อยู่เหมือนเดิม ⇒ ใช้ตอนเปิดหน้าที่ยังไม่มีบทในที่อยู่ */
function เติมฉบับในที่อยู่() {
  const t = เขียนฉบับในที่อยู่(ฉบับในที่อยู่.value, คอลัมน์เทียบที่เปิด.value.length > 0)
  const ส่วน = location.search
    .replace(/^\?/, '')
    .split('&')
    .filter((x) => x && !x.startsWith('t='))
  if (t) ส่วน.push(`t=${t}`)
  history.replaceState(null, '', location.pathname + (ส่วน.length ? `?${ส่วน.join('&')}` : '') + location.hash)
}

// ---------------------------------------------------------------- ประกอบข้อที่จะแสดง
interface แถว {
  กุญแจ: string
  บท: number
  เลข: string
  /** ⭐ **ป้ายที่ตาเห็น** ⇒ ข้อแรกของบทเป็น `บท:ข้อ` · ข้ออื่นเป็น `ข้อ` เปล่า ๆ ⇒ `ป้ายเลขข้อ` (คอลัมน์คำภาษาเดิมใช้ตัวเดียวกัน ใบ #117)
   *  ⇒ ผู้อ่านรู้ว่าขึ้นบทใหม่จากตัวเลขในเนื้อ ⛔ ไม่ต้องรอหัวข้อคั่น (ท่าของรุ่น 2)
   *  ⇒ **เก็บด้วยจุด แสดงผลด้วยทวิภาค** ⇒ กฎการอ้างอิงพระคัมภีร์ ⇒ ที่นี่คือฝั่ง *แสดงผล* */
  ป้าย: string
  /** ⭐ **เก็บเป็น *ชิ้น* ⛔ ไม่ใช่ข้อความก้อนเดียว** ⇒ ชิ้นที่พระเยซูพูดต้องใส่สีได้
   *  ⇒ `เนื้อ` เก็บไว้ด้วยเพราะด่านกับการวัดความยาวยังใช้ของเดิม */
  ช่อง: { ฉบับ: string; เนื้อ: string; ชิ้น: ชิ้นเนื้อ[] }[]
}
interface ก้อนบท {
  บท: number
  แถว: แถว[]
}

// ⭐⭐ **แบบเลือกแค่ข้อเริ่ม ⇒ วาดทุกข้อของทุกบทที่กางอยู่ ⛔ ไม่หนีบปลายทั้งสองข้าง**
//   ⇒ ข้อที่ผู้อ่านเลือกเป็นแค่จุดที่พาไป ⇒ ⛔ **ไม่ใช่ตัวตัดว่าอ่านได้ถึงแค่ไหน**
// ⭐⭐ **แบบเลือกเป็นช่วง ⇒ วาดเฉพาะข้อในช่วง** (ใบงาน #102 ข้อ 19) ⇒ ทางออกคือลิงก์ *อ่านทั้งบท* ใต้ช่วง
const บทที่แสดง = computed<ก้อนบท[]>(() => {
  const out: ก้อนบท[] = []
  for (let i = iแรก.value; i <= iท้าย.value; i++) {
    const c = ลำดับบท.value[i]
    if (c === undefined) continue
    const ของบท = บทที่หยิบมา.value[`${รหัสเล่ม}/${c}`]
    if (!ของบท) continue
    const เลขทั้งหมด = new Set<string>()
    // ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ แถวมาจากโครง (`ฉบับโครง`) ⇒ ช่องของโครงอยู่ในแถวแต่ ⛔ มีหัว ⛔ ถูกวาดให้ตาเห็น
    for (const ฉ of ฉบับโครง.value) {
      for (const n of Object.keys(ของบท.ชั้น[ฉ] || {})) {
        if (อยู่ในช่วง(c, Number(n))) เลขทั้งหมด.add(n)
      }
    }
    const เรียง = [...เลขทั้งหมด].sort((a, b) => Number(a) - Number(b))
    const แถว: แถว[] = []
    for (const n of เรียง) {
      แถว.push({
        กุญแจ: `${c}:${n}`,
        บท: c,
        เลข: n,
        ป้าย: ป้ายเลขข้อ(c, n, c, แถว.length === 0),
        ช่อง: ฉบับโครง.value.map((ฉ) => {
          const เนื้อ = ของบท.ชั้น[ฉ]?.[n] || ''
          return {
            ฉบับ: ฉ,
            เนื้อ,
            ชิ้น: แทรกเชิงอรรถ(
              ตัดเนื้อตามคำพระเยซู(เนื้อ, Number(n), ของบท.คำพระเยซู?.[ฉ]),
              Number(n),
              ของบท.เชิงอรรถ?.[ฉ],
              ฉ,
              ภาษาของชั้น.value?.[ฉ],
            ),
          }
        }),
      })
    }
    if (แถว.length) out.push({ บท: c, แถว })
  }
  return out
})

const จำนวนข้อ = computed(() => บทที่แสดง.value.reduce((n, ก) => n + ก.แถว.length, 0))

/** ฉบับที่ยังไม่มีย่อหน้าให้ใช้ ⇒ ประโยคเหตุผลมาจากซอง ⛔ ไม่ได้พิมพ์ที่นี่ */
const ฉบับที่ยังไม่มีย่อหน้า = computed(() => ของเล่ม.value?.ฉบับที่ยังไม่มีย่อหน้า || {})

/**
 * ⭐⭐ **โหมด *แยกตามย่อหน้า*** (ใบงาน v3/phrakham#98)
 *   ⇒ **1 ช่อง = ฉบับเดียว** ⇒ ตัวบทของคนละฉบับ ⛔ ไม่มีทางไหลมาปนกัน
 *     ⇒ ⭐ ใบ #109 ⇒ ช่องถูกจัดเป็นแถว ⇒ ย่อหน้าเดียวกันของทุกคอลัมน์เริ่มระดับเดียวกัน ⇒ ดู `กลุ่มย่อหน้าของบท`
 *   ⇒ ⭐ ข้างในช่อง ตัวบทถูกหั่นเป็น `<p>` **คนละกล่องต่อหนึ่งย่อหน้า**
 *     ⇒ **นี่คือย่อหน้าจริง** ⛔ ไม่ใช่ถ่างช่องไฟใต้ข้อแบบของเดิมที่ถูกถอดทิ้งเมื่อ 7 ก.ย. 2569
 *     ⇒ โปรแกรมอ่านหน้าจอจึงได้ยินว่า *ขึ้นย่อหน้าใหม่* ⛔ ไม่ใช่เห็นแค่ช่องว่างด้วยตา
 *
 * ⛔ **คำนวณเมื่อถูกใช้เท่านั้น** ⇒ `computed` ขี้เกียจ และกิ่งนี้ถูก `v-if` คุมอยู่
 *   ⇒ คนที่ ⛔ ไม่ได้เลือกโหมดนี้ ⛔ ไม่จ่ายค่าคำนวณเลย
 */
interface คอลัมน์ย่อหน้า {
  ฉบับ: string
  ย่อหน้า: ย่อหน้า[]
  /** ว่างเปล่า = ฉบับนี้มีย่อหน้าให้ใช้ ⇒ ไม่ว่าง = **ประโยคเหตุผลที่เครื่องนับเอง** */
  ยังไม่มี: string
  /** หัวข้อย่อยที่เปิดย่อหน้าแต่ละย่อหน้า ⇒ ยาวเท่า `ย่อหน้า` ⇒ ปิดสวิตช์ = `null` ทุกตัว (ใบ #134) */
  หัว: (หัวข้อย่อย | null)[]
}

const ย่อหน้าของบท = computed(() => {
  const ตาราง = new Map<number, คอลัมน์ย่อหน้า[]>()
  for (const ก of บทที่แสดง.value) {
    const ของบท = บทที่หยิบมา.value[`${รหัสเล่ม}/${ก.บท}`]
    ตาราง.set(
      ก.บท,
      // ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ แถวย่อหน้ามาจากโครง ⇒ คำเดิมไหลต่อกันเป็นย่อหน้าเดียวกับที่เคยเห็น
      ฉบับโครง.value.map((ฉ, i) => {
        // ⭐ ฉบับที่ซองบอกว่า ⛔ ไม่มีย่อหน้าของตัวเอง ⇒ **ยืมจุดขึ้นย่อหน้าจากต้นแบบ** (ใบ #106)
        //   ⇒ ไม่มีต้นแบบให้ยืมเลย ⇒ ได้ย่อหน้าเดียวยาวทั้งบท **แล้วบอกผู้อ่านตรง ๆ** ด้วยป้ายในกล่อง
        const หัว = หัวข้อของฉบับ(ก.บท, ฉ)
        const { ย่อหน้า, ยังไม่มี } = จัดย่อหน้าของฉบับ(
          ฉ,
          ก.แถว
            .map((x) => ({ บท: x.บท, เลข: x.เลข, ป้าย: x.ป้าย, ชิ้น: x.ช่อง[i]?.ชิ้น || [] }))
            .filter((x) => x.ชิ้น.length),
          ของบท?.ย่อหน้า,
          ฉบับที่ยังไม่มีย่อหน้า.value,
          หัว,
        )
        return { ฉบับ: ฉ, ย่อหน้า, ยังไม่มี, หัว: หัวข้อของย่อหน้า(ย่อหน้า, หัว) }
      }),
    )
  }
  return ตาราง
})

/**
 * ⭐⭐ **แถวของแบบแยกตามย่อหน้า** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/109 ข้อ 6)
 *   ⇒ ย่อหน้าของทุกคอลัมน์ในบทเดียวกัน ⇒ จัดเป็นแถวที่ทุกคอลัมน์เริ่มระดับเดียวกัน
 *   ⇒ กติกาว่าตัดแถวตรงไหน อยู่ที่ `จับคู่ย่อหน้า` ใน `app/utils/ย่อหน้า.ts` ⛔ ไม่จดซ้ำที่นี่
 *   ⇒ ⭐ คำนวณจาก `ย่อหน้าของบท` ตัวเดิม ⇒ ย่อหน้าของแต่ละฉบับเป็นก้อนเดิมทุกก้อน แค่ถูกจัดลงแถว
 */
// ⭐⭐ **ใบ #134 ⇒ แถวหัวข้อแทรกเหนือแถวย่อหน้าที่ฉบับใดฉบับหนึ่งเปิดด้วยหัวข้อ** ⇒ กติกาอยู่หัวไฟล์ `app/utils/หัวข้อย่อย.ts`
//   ⇒ แถวหัวข้อเป็นแถวหนึ่งในรายการนี้ ⇒ ผังแถวของคอลัมน์คำเดิม (`ผังแถว`) นับมันเองโดยไม่ต้องแก้ ⇒ คำเดิม ⛔ ไม่ลงแถวหัวข้อเพราะแถวนี้ไม่มีข้อ
//   ⇒ หัวข้อที่ ⛔ ได้แถว ⇒ อยู่ใน `หัวในช่องย่อหน้า` ⇒ วาดในช่องของฉบับนั้นเหนือย่อหน้าของมัน
const ตารางแถวย่อหน้า = computed(() => {
  const ตาราง = new Map<number, ReturnType<typeof แทรกแถวหัวข้อ>>()
  for (const [บท, คอลัมน์] of ย่อหน้าของบท.value) {
    const ย่อ = คอลัมน์.map((คอ) => คอ.ย่อหน้า)
    ตาราง.set(
      บท,
      แทรกแถวหัวข้อ(
        จับคู่ย่อหน้า(ย่อ),
        ย่อ,
        คอลัมน์.map((คอ) => คอ.หัว),
      ),
    )
  }
  return ตาราง
})
const กลุ่มย่อหน้าของบท = computed(() => {
  const ตาราง = new Map<number, แถวย่อหน้า[]>()
  for (const [บท, ผล] of ตารางแถวย่อหน้า.value) ตาราง.set(บท, ผล.แถว)
  return ตาราง
})
/** หัวข้อที่วาดในช่อง ⇒ `<คอลัมน์>|<กุญแจย่อหน้า>` ⇒ ไม่มี = ย่อหน้านั้นไม่มีหัวข้อ หรือหัวข้อขึ้นแถวของตัวเองแล้ว */
function หัวในช่องย่อหน้า(บท: number, i: number, กุญแจ: string) {
  return ตารางแถวย่อหน้า.value.get(บท)?.ในช่อง.get(`${i}|${กุญแจ}`)
}

// ---------------------------------------------------------------- หัวข้อย่อย (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134)
// ⭐ กติกาตอนเทียบหลายคอลัมน์ อยู่หัวไฟล์ `app/utils/หัวข้อย่อย.ts` ที่เดียว ⛔ ไม่จดซ้ำที่นี่
// ⭐ **ปิดสวิตช์ = ไม่มีหัวข้อในหน้าเลย** ⇒ ⛔ ไม่ใช่ซ่อนด้วย CSS ⇒ เหตุผลของข้อ 12 อยู่หัวไฟล์เดียวกัน
//   ⇒ ⭐ ปิดแล้วหน้ากลับเป็นแบบก่อนมีใบนี้ ⇒ เนื้อความต่อกันเหมือนไม่เคยมีหัวข้อ (ข้อ 11)
/** หัวข้อของฉบับหนึ่งในบทหนึ่ง ⇒ ปิดสวิตช์ = `[]` */
function หัวข้อของฉบับ(บท: number, ฉ: string): หัวข้อย่อย[] {
  if (!มุม.value.หัวข้อย่อย) return []
  return บทที่หยิบมา.value[`${รหัสเล่ม}/${บท}`]?.หัวข้อ?.[ฉ] || []
}

/**
 * ⭐ **บนหน้ามีหัวข้อให้เปิดปิดไหม** ⇒ ⛔ ไม่มี = ⛔ ไม่วาดสวิตช์
 *   ⇒ ใบงาน v3/phrakham#76 ⇒ *ตัวเลือกที่กดแล้วไม่เกิดอะไร ห้ามมีบนหน้า* (`tools/ด่านตัวเลือกเปลี่ยนหน้า.mjs`)
 *   ⇒ เช่น 3 ยอห์น 1 ฉบับ TCV ⇒ ไม่มีหัวข้อในข้อมูล ⇒ สวิตช์ไม่ขึ้น ⇒ เปิด THKJV เพิ่ม ⇒ สวิตช์ขึ้นเอง
 *   ⇒ ⭐ ดูจากข้อมูลตรง ๆ ⛔ ไม่ขึ้นกับว่าสวิตช์ปิดอยู่ไหม ⇒ ปิดอยู่ก็ยังเห็นสวิตช์ไว้เปิดกลับได้ (Nielsen ข้อ 3)
 */
const หัวข้อมีบนหน้า = computed(() => {
  for (const ก of บทที่แสดง.value) {
    const ของบท = บทที่หยิบมา.value[`${รหัสเล่ม}/${ก.บท}`]
    if (ฉบับที่แสดง.value.some((ฉ) => ของบท?.หัวข้อ?.[ฉ]?.length)) return true
  }
  return คอลัมน์เทียบที่เปิด.value.some(
    (ค) => เนื้อของเทียบ.value[`${ค.เล่ม}/${ค.บท}`]?.หัวข้อ?.[ฉบับของเทียบ(ค)]?.length,
  )
})

/** *แยกตามข้อ* ⇒ แถวหัวข้อของข้อหนึ่ง ⇒ `บท → เลขข้อ → หัวข้อของแต่ละคอลัมน์` ⇒ ⛔ ไม่มีหัวข้อสักคอลัมน์ = ไม่มีกุญแจ */
const หัวข้อของแถว = computed(() => {
  const ตาราง = new Map<number, Map<string, (หัวข้อย่อย | null)[]>>()
  if (!มุม.value.หัวข้อย่อย || มุม.value.จัดวาง !== 'แยกตามข้อ') return ตาราง
  for (const ก of บทที่แสดง.value) {
    const ตามฉบับ = ฉบับที่แสดง.value.map((ฉ) => หัวข้อตามข้อ(หัวข้อของฉบับ(ก.บท, ฉ)))
    const ของบท = new Map<string, (หัวข้อย่อย | null)[]>()
    for (const x of ก.แถว) {
      // ⭐ ฉบับที่ไม่มีข้อนี้ ⇒ ⛔ ไม่ได้หัวข้อ ⇒ หัวข้อต้องเกาะตัวบทที่มีอยู่จริง
      const หัว = ตามฉบับ.map((m, i) => (x.ช่อง[i]?.เนื้อ ? m.get(Number(x.เลข)) || null : null))
      if (หัว.some(Boolean)) ของบท.set(x.เลข, หัว)
    }
    ตาราง.set(ก.บท, ของบท)
  }
  return ตาราง
})

/** ผ่าตัวบทของคอลัมน์หนึ่งเป็นตอนตามหัวข้อ ⇒ ใช้ `จัดย่อหน้า` ตัวเดิม ⇒ ผ่ากลางข้อได้ตรงตัวอักษร และตัวบทครบทุกตัวอักษร */
function ผ่าตอนไหล(ข้อ: { บท: number; เลข: string; ป้าย: string; ชิ้น: ชิ้นเนื้อ[] }[], หัว: หัวข้อย่อย[]) {
  const ย่อ = จัดย่อหน้า(ข้อ, รอยของหัวข้อ(หัว))
  return { ย่อหน้า: ย่อ, หัว: หัวข้อของย่อหน้า(ย่อ, หัว) }
}

/** *ไหลต่อเนื่อง* ⇒ `บท → [ตอนของคอลัมน์ i | null]` ⇒ `null` = คอลัมน์นี้ไม่มีหัวข้อในบทนี้ ⇒ วาดกล่อง `<p>` เดียวแบบเดิม */
const ตอนไหลของบท = computed(() => {
  const ตาราง = new Map<number, ({ ย่อหน้า: ย่อหน้า[]; หัว: (หัวข้อย่อย | null)[] } | null)[]>()
  if (!มุม.value.หัวข้อย่อย || มุม.value.จัดวาง !== 'ไหลต่อเนื่อง') return ตาราง
  for (const ก of บทที่แสดง.value) {
    ตาราง.set(
      ก.บท,
      ฉบับที่แสดง.value.map((ฉ, i) => {
        const หัว = หัวข้อของฉบับ(ก.บท, ฉ)
        if (!หัว.length) return null
        return ผ่าตอนไหล(
          ก.แถว
            .map((x) => ({ บท: x.บท, เลข: x.เลข, ป้าย: x.ป้าย, ชิ้น: x.ช่อง[i]?.ชิ้น || [] }))
            .filter((x) => x.ชิ้น.length),
          หัว,
        )
      }),
    )
  }
  return ตาราง
})

// ---------------------------------------------------------------- เดินบท
const บทที่อ่านอยู่ = ref(Number(เลขบท))
// ⭐ **ชื่อบอกแค่ *ตำแหน่งตอนนี้*** ⛔ ไม่ใช่ทุกบทที่เลื่อนผ่านมา
//   ⇒ ก่อนหน้านี้ชื่อโตขึ้นเรื่อย ๆ เป็น `สดุดี 119-125` ยิ่งอ่านยิ่งยาว (คนตรวจจับได้ 6 ก.ย. 2569)
// ⭐ **กำลังดูช่วง ⇒ ชื่อคือช่วงทั้งช่วง** เช่น `มาระโก 10:13–16` ⇒ หัวเรื่องของหน้ายังบอกโปรแกรมอ่านหน้าจอได้ (ข้อ 20.2)
const ชื่อที่อ่านอยู่ = computed(() =>
  ช่วงที่ฟัง.value
    ? `${เล่มนี้.value.ชื่อไทย} ${แสดงช่วงฟัง(ช่วงที่ฟัง.value)}`
    : แสดงเป็นข้อความ(
        {
          รหัส: รหัสเล่ม,
          บท: บทที่อ่านอยู่.value,
          ข้อ: บทที่อ่านอยู่.value === บทของข้อที่พาไป.value ? ข้อที่พาไป.value : null,
        },
        เล่มนี้.value.ชื่อไทย,
      ),
)
/** ชื่อบนแถบล่าง ⇒ ⛔ ไม่มีเลขข้อ — แถบล่างบอก **บท** ที่กำลังอ่านอยู่ */
const บทบนแถบล่าง = computed(() => `${เล่มนี้.value.ชื่อไทย} ${บทที่อ่านอยู่.value}`)
/**
 * ⭐ **ส่วนตัวเลขของป้ายบนปุ่มกลางของแถบล่าง (จอแคบ)** ⇒ บท หรือช่วงที่ดูอยู่ (ใบ #113 ข้อ 7.1)
 *   ⇒ ⭐ **ต่อกับชื่อเล่มแล้วได้ `ป้ายที่ของหน้า` ตรงตัว** ⇒ ⛔ ไม่ใช่ป้ายที่สอง
 *   ⇒ แยกเป็น 2 ท่อนเพราะชื่อเล่มหดได้ แต่ตัวเลข ⛔ ห้ามถูกตัด (ข้อ 7.3) ⇒ กฎอยู่ที่ `main.css`
 */
const เลขบนแถบล่าง = computed(() =>
  ช่วงที่ฟัง.value ? แสดงช่วงฟัง(ช่วงที่ฟัง.value) : `${บทที่อ่านอยู่.value}`,
)
/** ⭐ ป้ายบนหัวคอลัมน์ของที่เดียวกับหน้า ⇒ **ช่วงบอกไว้ที่นี่ที่เดียว** (ข้อ 20) ⇒ ⛔ ไม่บอกซ้ำบนปุ่มเล่น */
const ป้ายที่ของหน้า = computed(() =>
  ช่วงที่ฟัง.value
    ? `${เล่มนี้.value.ชื่อไทย} ${แสดงช่วงฟัง(ช่วงที่ฟัง.value)}`
    : บทบนแถบล่าง.value,
)
// ⭐ **กำลังดูช่วง ⇒ บทก่อน = บทก่อนบทต้นช่วง · บทถัดไป = บทหลังบทท้ายช่วง** (ข้อ 21)
//   ⇒ ⛔ ไม่ใช่บทที่ช่วงคร่อมอยู่เอง ⇒ อันนั้นมีลิงก์ *อ่านทั้งบท* พาไปแล้ว
const ที่ยืนอยู่ = computed(() =>
  เล่มนี้.value.บทที่มี.indexOf(ช่วงที่ฟัง.value ? ช่วงที่ฟัง.value.จาก.บท : บทที่อ่านอยู่.value),
)
const บทก่อน = computed(() =>
  ที่ยืนอยู่.value > 0 ? เล่มนี้.value.บทที่มี[ที่ยืนอยู่.value - 1]! : null,
)
const บทถัด = computed(() => {
  const ท้าย = ช่วงที่ฟัง.value ? ช่วงที่ฟัง.value.ถึง.บท : บทที่อ่านอยู่.value
  return เล่มนี้.value.บทที่มี.find((c) => c > ท้าย) ?? null
})
/** บทที่ช่วงคร่อมอยู่ ⇒ ใช้เป็นป้ายของลิงก์ *อ่านทั้งบท* ⇒ บทเดียว `10` · คร่อมบท `4–5` */
const บทของช่วง = computed(() => {
  const ช = ช่วงที่ฟัง.value
  if (!ช) return ''
  return ช.จาก.บท === ช.ถึง.บท ? `${ช.จาก.บท}` : `${ช.จาก.บท}–${ช.ถึง.บท}`
})

// ---------------------------------------------------------------- เลื่อนอ่านทะลุบท
// ⭐⭐ **นี่คือหัวใจของใบ #65** ⇒ *"อ่านไหลยาวเหมือนหนังสือทั้งเล่ม"*
//   ⇒ เลื่อนจนใกล้ท้ายม้วน ⇒ ต่อบทถัดไปให้เอง ⛔ ไม่มีปุ่มให้กด
//
// ⛔⛔ **ไม่มีเงื่อนไขไหนหยุดการต่อได้ นอกจากจบเล่ม** ⇒ ผู้อ่านเลือกข้อไว้ก็ยังต่อ
//   ⇒ คนตรวจจับได้ 6 ก.ย. 2569 ว่ากด `เฉพาะข้อ 3:16` แล้วได้หน้าตันข้อเดียว เลื่อนต่อไม่ได้เลย
//   ⇒ ⭐ **ข้อคือไฟส่อง ⛔ ไม่ใช่กำแพง**
//
// ⛔ **ยังไม่เลื่อน = ยังไม่ต่อ** ⇒ เปิดมาแล้วยังไม่ได้อ่านอะไรเลย
//   การดึงบทถัดไปคือการดึงของที่ ⛔ ไม่มีใครขอ ⇒ กินเน็ตของผู้อ่านฟรี ๆ
const ปลายม้วน = ref<HTMLElement | null>(null)
const กำลังต่อ = ref(false)

// ⭐⭐ **กางไว้ได้มากสุดกี่บท** (ใบงาน v3/phrakham#73 · เกณฑ์ผ่านข้อ 6)
//   **ทำไมต้องมีเพดาน** ⇒ เล่มที่ยาวที่สุดกางค้างไว้ทั้งเล่มแล้ว **หน้าจะหน่วง**
//     เพราะเบราว์เซอร์ต้องคิดตำแหน่งของทุกข้อใหม่ทุกครั้งที่มีอะไรเปลี่ยน
//   ⇒ **วิธีดูของจริงว่าหน่วงแค่ไหน** ⇒ `node tools/วัดเลื่อนสดุดี.mjs <ที่อยู่เว็บ> 250 6`
//   ⇒ **เลื่อนพ้นไปไกลแล้วต้องทิ้ง** ⇒ เลื่อนย้อนกลับมาก็หยิบกลับมาใหม่ (ดู `ต่อบทก่อนหน้า`)
//   ⇒ 6 บทคือ *เห็นบทที่อ่านอยู่ + เผื่อหน้าหลังอย่างละ 2-3 บท* ⇒ เลื่อนเร็ว ๆ ก็ยังมีของรออยู่
const เพดานบทที่กาง = 6

// ⭐ **เหลือทางอีกเท่าไรถึงต่อบทถัดไปให้ล่วงหน้า** ⇒ ใช้ทั้งทางขึ้นและทางลง
//   ⇒ ⭐ **ค่าเดียวใช้สองทาง** ⇒ ขึ้นกับลงจึงรู้สึกเหมือนกัน และแก้ทีเดียวขยับทั้งคู่
//     ⛔ เคยเขียนเลขไว้ 2 ที่แล้วเอาคอมเมนต์ยืนยันว่าเท่ากัน ⇒ ใครแก้ที่เดียวคอมเมนต์ก็โกหกทันที
//     (คนตรวจ !64 ทัก ก. · 7 ก.ย. 2569)
const ระยะเผื่อต่อบท = 800

/** จำนวนบทที่กางอยู่ตอนนี้ */
const นับบทที่กาง = () => iท้าย.value - iแรก.value + 1

/**
 * ⭐⭐ **ทิ้งบทบนสุดที่เลื่อนพ้นไปไกลแล้ว**
 *
 * ⛔⛔ **ตัดของที่อยู่ *เหนือ* จอ แล้วหน้าจะกระโดดขึ้นเท่ากับความสูงที่หายไป**
 *   ⇒ ต้องวัดความสูงก่อนกับหลัง แล้วเลื่อนชดเชยเอง ⇒ ⛔ ไม่ชดเชย = ผู้อ่านเสียที่ที่กำลังอ่านอยู่
 */
async function ทิ้งบทบน() {
  while (นับบทที่กาง() > เพดานบทที่กาง) {
    const สูงก่อน = document.documentElement.scrollHeight
    const ที่เลื่อนก่อน = window.scrollY
    iแรก.value += 1
    await nextTick()
    const หาย = สูงก่อน - document.documentElement.scrollHeight
    if (หาย > 0) จำที่เลื่อนแล้วเลื่อน(Math.max(0, ที่เลื่อนก่อน - หาย))
  }
  เก็บกวาดเนื้อที่ไกล()
}

/** ทิ้งบทล่างสุด ⇒ ⛔ ไม่ต้องชดเชย เพราะของที่หายอยู่ *ใต้* จอ ⇒ ที่ที่อ่านอยู่ไม่ขยับ */
function ทิ้งบทล่าง() {
  while (นับบทที่กาง() > เพดานบทที่กาง) iท้าย.value -= 1
  เก็บกวาดเนื้อที่ไกล()
}

async function ต่อบทถัดไป() {
  if (กำลังต่อ.value) return
  // ⛔ กำลังดูช่วง ⇒ ⛔ ไม่ต่อบทนอกช่วง (ใบงาน #102 ข้อ 19) ⇒ ทางออกคือลิงก์ *อ่านทั้งบท*
  if (ช่วงที่ฟัง.value) return
  if (iท้าย.value >= ลำดับบท.value.length - 1) return
  const ถัด = ลำดับบท.value[iท้าย.value + 1]!
  กำลังต่อ.value = true
  const ได้ = await หยิบบท(รหัสเล่ม, ถัด)
  // ⛔ ต่อไม่ได้ก็เงียบ ⇒ ผู้อ่านยังอ่านของที่มีอยู่ต่อได้ ⛔ ไม่ใช่หน้าพัง
  if (ได้) {
    iท้าย.value += 1
    await nextTick()
    await ทิ้งบทบน()
  }
  กำลังต่อ.value = false
  ทำคำขอที่ค้าง()
}

/**
 * ⭐ **เลื่อนย้อนขึ้นไปใกล้หัวม้วน ⇒ ต่อบทก่อนหน้ากลับเข้ามา**
 *   ⇒ นี่คือของที่ทำให้ *ทิ้งบทที่เลื่อนพ้นไปแล้ว* ⛔ ไม่กลายเป็นการทำให้อ่านย้อนไม่ได้
 * ⛔ **เติมของ *เหนือ* จอ แล้วหน้าจะกระโดดลง** ⇒ ต้องเลื่อนชดเชยเท่าความสูงที่เพิ่มมา
 */
async function ต่อบทก่อนหน้า() {
  // ⛔ กำลังต่อบทถัดไปอยู่ ⇒ **จำคำขอไว้ ⛔ ไม่ทิ้ง** ⇒ ทิ้ง = ตันถาวร (เหตุผลเต็มอยู่ที่ `ทำคำขอที่ค้าง`)
  if (กำลังต่อ.value) {
    ค้างขอต่อขึ้น = true
    return
  }
  if (ช่วงที่ฟัง.value) return
  if (iแรก.value <= 0) return
  const ก่อน = ลำดับบท.value[iแรก.value - 1]!
  กำลังต่อ.value = true
  const ได้ = await หยิบบท(รหัสเล่ม, ก่อน)
  if (ได้) {
    const สูงก่อน = document.documentElement.scrollHeight
    const ที่เลื่อนก่อน = window.scrollY
    iแรก.value -= 1
    await nextTick()
    const เพิ่ม = document.documentElement.scrollHeight - สูงก่อน
    if (เพิ่ม > 0) จำที่เลื่อนแล้วเลื่อน(ที่เลื่อนก่อน + เพิ่ม)
    ทิ้งบทล่าง()
  }
  กำลังต่อ.value = false
  ทำคำขอที่ค้าง()
}

/**
 * ⭐⭐ **คำขอต่อบทที่มาตอนหน้ากำลังต่ออีกทางอยู่ ⇒ จำไว้ แล้วทำต่อเองเมื่องานเดิมเสร็จ**
 *   (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/108 ข้อ 14–15 · ข้อบกพร่องแบบ WPA.04)
 *
 * **ของจริงที่พังมาแล้ว** ⇒ เลื่อนลงจนหน้าเริ่มหยิบบทถัดไป ⇒ ระหว่างไฟล์ยังมาไม่ถึง ผู้อ่านเลื่อนขึ้นถึงหัวหน้า
 *   ⇒ ตัววัดการเลื่อนเห็น `กำลังต่อ` ⇒ **ทิ้งคำขอขึ้นเงียบ ๆ** ⇒ จออยู่ที่ `scrollY = 0` แล้ว
 *     ⇒ เลื่อนขึ้นต่อเท่าไรก็ ⛔ ไม่เกิดเหตุการณ์เลื่อนมาปลุกอีก ⇒ **อ่านย้อนขึ้นต่อไม่ได้ถาวร**
 *   ⇒ ด่าน ⑪ ของ `tools/ด่านไปถึงข้อ.mjs` แดงบ้างผ่านบ้างบนตัวรัน 2 แกนเพราะเรื่องนี้
 *   ⇒ ⭐ **ตัวเฝ้าที่ทำให้เกิดทุกครั้งคือข้อ ⑭ ของด่านเดียวกัน** ⇒ กั้นไฟล์บทถัดไปไว้แล้วเลื่อนขึ้น
 *
 * ⭐ **ทางกลับกัน (กำลังต่อบทก่อนหน้า แล้วผู้อ่านเลื่อนลงถึงท้าย) ⛔ ไม่ตัน** ⇒ ข้อ ⑮ ของด่านเดียวกันพิสูจน์แล้ว
 *   ⇒ เพราะต่อบทก่อนหน้าเสร็จแล้ว **เลื่อนชดเชยเสมอ** ⇒ เกิดเหตุการณ์เลื่อนมาปลุกตัววัดเอง
 *   ⇒ ถึงอย่างนั้นก็จำคำขอลงไว้ด้วย ⇒ **กติกาเดียวกันทั้งสองทาง** ⛔ ไม่พึ่งผลข้างเคียงของการชดเชย
 *
 * ⭐ **ทำซ้ำผ่านทางเดิมทุกครั้ง** ⇒ ขึ้นผ่าน `ขอต่อบทก่อนหน้า` (เคารพช่วงพัก · เช็กว่ายังใกล้หัวม้วนจริง)
 *   ⇒ ลงเช็กว่าปลายม้วนยังใกล้จอจริง ⇒ ผู้อ่านเลื่อนหนีไปแล้ว ⇒ ⛔ ไม่ต่อของที่ไม่มีใครขอแล้ว
 */
let ค้างขอต่อขึ้น = false
let ค้างขอต่อลง = false
function ทำคำขอที่ค้าง() {
  if (ค้างขอต่อขึ้น) {
    ค้างขอต่อขึ้น = false
    ขอต่อบทก่อนหน้า()
    // เริ่มต่อขึ้นแล้ว ⇒ คำขอลงที่ค้างอยู่รอให้งานนี้เสร็จก่อน ⇒ ตอนจบมันเรียกตัวนี้อีกรอบ
    if (กำลังต่อ.value) return
  }
  if (ค้างขอต่อลง) {
