  // ⭐ ช่องอ่านคือ **ระหว่างแถบบนกับแถบล่างที่วัดจริง** ⛔ ไม่ฝังตัวเลข — แถบสูงไม่เท่ากันในแต่ละจอ
  const ขอบบน = ความสูงแถบบน()
  const ขอบล่าง = window.innerHeight - ความสูงแถบล่าง()
  const ปลายตัวบท =
    document.querySelector('.pk-ตัวบท')?.getBoundingClientRect().bottom ?? window.innerHeight
  let ได้ = Number(หมุด[0]!.getAttribute('data-หมุดบท'))
  let กินมากสุด = -Infinity
  for (let i = 0; i < หมุด.length; i++) {
