  //     ⇒ ผู้อ่านเลื่อนเองเมื่อไร ⇒ ปล่อยที่ยึด ⇒ กลับมานับพื้นที่เหมือนเดิม ⇒ อ่านต่อไปบทถัดไปแล้วที่อยู่ยังตาม
  //     ⇒ จุดที่พาไปพ้นจอแล้ว (โค้ดอื่นเลื่อนหนี) ⇒ นับพื้นที่เหมือนเดิม ⇒ ⛔ ไม่ค้างบทเก่าทั้งที่จอเป็นบทอื่น
