      return
    }
    // ⭐ **เลื่อนขึ้นจนใกล้หัวม้วน ⇒ ต่อบทก่อนหน้ากลับเข้ามา** ⇒ อ่านย้อนขึ้นไปได้จนต้นเล่ม
    //   ⛔ **ต้องเป็นการเลื่อน *ขึ้น* เท่านั้น** — ไม่งั้นคนที่เพิ่งถูกพาไปสดุดี 119
    //     จะถูกยัดสดุดี 118 มาให้ทันทีโดยที่เขา ⛔ ไม่ได้ขอ (เจอเองด้วยด่าน ⑩ · 7 ก.ย. 2569)
    if (เลื่อนขึ้น && ตอนนี้ < ระยะเผื่อต่อบท) ขอต่อบทก่อนหน้า()
  })
}

// ⭐ ที่อยู่ต้องเปลี่ยนตามการเลื่อน ⇒ ไม่งั้นผู้อ่านคั่นหน้าตรงที่อ่านอยู่ไม่ได้
watch(บทที่อ่านอยู่, () => {
  if (import.meta.server) return
  ปรับที่อยู่()
})

// ---------------------------------------------------------------- เสียงอ่าน (ใบงาน #101)
// ⭐⭐ **อ่านกับฟังในหน้าเดียว** ⇒ ปุ่มอยู่ที่แถบล่าง ⇒ ตัวคุมอยู่ที่ `app/composables/เสียงบนหน้าอ่าน.ts`
//   ⇒ หน้านี้ส่งให้มัน 2 อย่างที่ต้องรู้ผังของหน้า ⇒ **หาข้อแรกบนจอ** กับ **พาข้อที่กำลังอ่านมาให้เห็น**

/**
 * ⭐⭐ **ตารางเห็นแต่คอลัมน์คำภาษาเดิม ⇒ ของที่ตาเห็นแทนข้อของฉบับแปล** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 5)
 *   ⇒ แถวของฉบับแปลยังอยู่ในหน้าแต่ ⛔ ถูกวาด ⇒ วัดตำแหน่งไม่ได้ ⇒ ลิงก์ `v=12` ไปไม่ถึง
 *   ⇒ ⭐ ใช้แถวคำเดิมของแถวเดียวกัน (`data-แถว` ชุดเดียวกับตาราง) ⇒ แถวนั้นไม่มีคำเดิม ⇒ แถวก่อนหน้าที่ใกล้ที่สุดในบทเดียวกัน
 *   ⇒ ⭐ ข้อที่ตาเห็นอยู่แล้ว ⇒ คืนตัวเดิม ⇒ หน้าที่มีฉบับแปลทำงานเหมือนเดิมทุกจุด
 */
function กล่องที่ตาเห็น(el: HTMLElement): HTMLElement | null {
  if (el.getClientRects().length) return el
  const ป้าย = el.closest<HTMLElement>('[data-แถว]')?.getAttribute('data-แถว') || ''
  const [บท, แถว] = ป้าย.split(':').map(Number)
  if (!บท || !Number.isFinite(แถว)) return null
  for (let r = แถว!; r >= 0; r--)
    for (const x of document.querySelectorAll<HTMLElement>(`.pk-ตัวบท .pk-แถวคำ[data-แถว="${บท}:${r}"]`))
      if (x.getClientRects().length) return x
  return null
}

/** กล่องของข้อที่ตาเห็นจริง ⇒ ⛔ ไม่นับกล่องที่ถูกซ่อน (จอแคบอ่านทีละฉบับซ่อนฉบับอื่นไว้) */
function กล่องข้อ(บท: number, ข้อ: number): HTMLElement | null {
  const ทั้งหมด = document.querySelectorAll<HTMLElement>(`.pk-ตัวบท [data-ข้อ="${บท}:${ข้อ}"]`)
  for (const el of ทั้งหมด) if (el.getClientRects().length) return el
  return null
}

/** ⭐ **ข้อแรกที่ผู้อ่านเห็นบนจอ** ⇒ ข้อแรกที่ขอบล่างพ้นแถบบนลงมาแล้ว (ใบ #101 ข้อ 8) */
function หาข้อบนจอ(): { บท: number; ข้อ: number } | null {
  // ⭐ ขอบบนของช่องอ่าน = ขอบล่างของทุกแถบหนึบ รวมหัวคอลัมน์ (ใบ #104)
  //   ⇒ ข้อที่ซุกอยู่ใต้หัวคอลัมน์ ⛔ ใช่ข้อที่ผู้อ่านเห็น ⇒ ⛔ ไม่ใช่จุดเริ่มเสียง
  //   ⇒ ⛔ หักแค่แถบบน = พาไปที่ 4:10 แล้วเสียงเริ่มที่ 4:9 ที่ซ่อนใต้หัว (`ด่านฟังพระคำบนหน้า` ข้อ ④ จับได้)
  const ขอบบน = ขอบล่างแถบหนึบ() + 8
  for (const el of document.querySelectorAll<HTMLElement>('.pk-ตัวบท [data-ข้อ]')) {
    if (!el.getClientRects().length) continue
    if (el.getBoundingClientRect().bottom <= ขอบบน) continue
    const [บท, ข้อ] = (el.getAttribute('data-ข้อ') || '').split(':').map(Number)
    if (บท && ข้อ) return { บท, ข้อ }
  }
  // ⭐ ใบ #145 ⇒ ตารางเห็นแต่คำเดิม ⇒ ข้อแปล ⛔ ถูกวาด ⇒ ดูแถวคำเดิมที่ตาเห็นแทน ⇒ ข้อแรกของแถวนั้นในตาราง
  if (!ตารางเห็นแต่คำเดิม.value) return null
  for (const el of document.querySelectorAll<HTMLElement>('.pk-ตัวบท .pk-แถวคำ[data-แถว]')) {
    if (!el.getClientRects().length || el.getBoundingClientRect().bottom <= ขอบบน) continue
    const แถว = document.querySelector<HTMLElement>(`.pk-ตัวบท [data-แถว="${el.getAttribute('data-แถว')}"]:not(.pk-แถวคำ)`)
    const ข้อของแถว = แถว?.hasAttribute('data-ข้อ') ? แถว : แถว?.querySelector<HTMLElement>('[data-ข้อ]')
    const [บท, ข้อ] = (ข้อของแถว?.getAttribute('data-ข้อ') || '').split(':').map(Number)
    if (บท && ข้อ) return { บท, ข้อ }
  }
  return null
}

/**
 * ⭐⭐ **พาข้อที่กำลังอ่านมาให้เห็น** (ใบ #101 ข้อ 10)
 *   ⇒ บทนั้นยังไม่ได้กาง ⇒ ต่อบทถัดไป หรือตั้งม้วนใหม่ที่บทนั้น ⇒ ท่าเดียวกับ `ไปที่จุด`
 *   ⇒ ⭐ **เห็นอยู่แล้วทั้งข้อ ⇒ ⛔ ไม่เลื่อน** ⇒ จอนิ่งให้อ่านตามได้ ⇒ เลื่อนเฉพาะตอนข้อหลุดจากช่องอ่าน
 *   ⛔ **ไม่แตะไฟส่องและเลขข้อในที่อยู่** ⇒ ของพวกนั้นเป็นของ *จุดที่ผู้อ่านเลือก* ⛔ ไม่ใช่ของเสียง
 */
async function พาไปข้อที่เล่น(ต: { บท: number; ข้อ: number }, บังคับ: boolean) {
  const i = ลำดับบท.value.indexOf(ต.บท)
  if (i < 0) return
  if (i < iแรก.value || i > iท้าย.value) {
    if (i === iท้าย.value + 1) await ต่อบทถัดไป()
    if (i < iแรก.value || i > iท้าย.value) {
      const ได้ = await หยิบบท(รหัสเล่ม, ต.บท)
      if (!ได้) return
      iแรก.value = i
      iท้าย.value = i
    }
    await nextTick()
  }
  const el = กล่องข้อ(ต.บท, ต.ข้อ)
  if (!el) return
  const ก = el.getBoundingClientRect()
  // ⭐ ขอบบนของช่องอ่าน = ขอบล่างของทุกแถบหนึบ รวมหัวคอลัมน์ (ใบ #104) ⇒ ข้อที่เล่นต้อง ⛔ ไม่ซุกใต้หัว
  const บน = ขอบล่างแถบหนึบ()
  const ล่าง = window.innerHeight - ความสูงแถบล่าง()
  if (!บังคับ && ก.top >= บน + 4 && ก.bottom <= ล่าง - 4) return
  จำที่เลื่อนแล้วเลื่อน(Math.max(0, window.scrollY + ก.top - บน - 8))
  พักการต่อขึ้น()
}

/**
 * ⭐⭐ **กติกาเดียวของ *ปุ่มฟังอ่านฉบับไหน*** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/132 ข้อ 11.2)
 *   ① **อ่านทีละคอลัมน์ และคอลัมน์ที่เปิดดูอยู่เป็นคำแปล** ⇒ ฉบับของคอลัมน์นั้น
 *   ② **นอกนั้น** ⇒ ฉบับของคอลัมน์คำแปลคอลัมน์แรก ⇒ ซ้ายสุดเมื่อวางซ้ายขวา · บนสุดเมื่อวางบนล่าง
 *   ⇒ ⭐ **ผู้อ่านเดาได้** ⇒ คอลัมน์แรกคือคอลัมน์ที่เขาวางเอง (ใบ #125 ข้อ 8) ⇒ และชื่อฉบับขึ้นบนปุ่มให้เห็นก่อนกดอยู่แล้ว
 *   ⛔ **คอลัมน์คำภาษาเดิมไม่นับ** (ข้อ 11.1) ⇒ ยังไม่มีเสียง ⇒ เปิดดูคำเดิมอยู่ ⇒ ใช้ข้อ ②
 *   ⛔ **คอลัมน์ที่เปิดคนละเล่มคนละบทไม่นับ** ⇒ เสียงเดินตามเล่มและบทของหน้า ⇒ เปิดดูคอลัมน์นั้นอยู่ ⇒ ใช้ข้อ ②
 *   ⛔ **ฉบับนั้นไม่มีเสียง ⇒ ⛔ ไม่สลับไปฉบับอื่น** ⇒ ปุ่มหายแล้วบอกว่าฉบับนั้นยังไม่มีเสียง (ข้อ 11.3)
 */
const ฉบับที่ฟัง = computed(
  () => (กำลังแสดงฉบับเดียว.value && ฉบับที่กำลังดู.value) || ฉบับที่แสดง.value[0] || '',
)

const เสียง = ใช้เสียงบนหน้าอ่าน({
  รหัสเล่ม,
  ชื่อเล่ม: computed(() => เล่มนี้.value.ชื่อไทย),
  ดัชนีทุกฉบับ: computed(() => ของเล่ม.value?.เสียง),
  ฉบับ: ฉบับที่ฟัง,
  บทที่มี: ลำดับบท,
  ช่วง: ช่วงที่ฟัง,
  บทที่อ่านอยู่,
  หาข้อบนจอ,
  พาไปข้อ: พาไปข้อที่เล่น,
})

// ---------------------------------------------------------------- เรื่องเล่าของช่วงข้อ (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/105 หัวข้อ *รอบ 2*)
// ⭐⭐ **ทางเข้าเรื่องเล่ามีทางเดียว ⇒ ปุ่มบนแถบล่าง ก่อนปุ่ม ▶ ฟัง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 ⇒ พี่เอมสั่ง 3 พ.ย. 2569)
//   ⇒ **เดิม (รอบ 1)** ปุ่มอยู่ใต้หมุดชื่อบท ⇒ เลื่อนผ่านชื่อบทแล้วไม่เห็นว่ามีเรื่องเล่า ⇒ **รอบ 2** ย้ายมาอยู่กับแถบล่างที่ตามคนอ่านไปตลอด
//   ⇒ ⚠️ **รอบ 2 เป็นแถวบางของตัวเองเหนือแถบล่าง** (เกณฑ์รอบ 2 ข้อ 1.2) ⇒ พี่เอมเปลี่ยนแล้ว ⇒ ปุ่มย้ายลงแถวเดียวกับปุ่ม *ฟัง*
//     ⇒ ป้าย *เรื่องเล่า มก. 10:1–12* ⇒ ชื่อย่อจาก `toc3` ของ TCV (ใบ #131 note_30489) ⇒ ⛔ ชื่อย่อของคอลัมน์ ⇒ เรื่องเล่าเป็นภาษาไทยเสมอ
//     ⇒ ที่ไม่พอ ⇒ เหลือ *เรื่องเล่า* ⇒ ยังไม่พออีก (จอ 320) ⇒ ทางเดินบทขึ้นแถวบน ⇒ ดู `จัดปุ่มเรื่องเล่า`
//   ⇒ แถวบางเหนือแถบล่างยังอยู่ ⇒ เหลือแค่ปุ่มหยุดเสียงเรื่องเล่า ⇒ โผล่เฉพาะตอนเสียงยังไม่จบ (รอบ 2 ข้อ 3)
// ⭐⭐ **กติกาทับซ้อน (เกณฑ์รอบ 2 ข้อ 1 · 1.1)** ⇒ แถบโผล่เมื่อ **ข้อบนจออย่างน้อย 1 ข้อ อยู่ในช่วงของเรื่อง**
//   ⇒ *ข้อบนจอ* = ข้อที่กล่องของมันอยู่ในช่องอ่าน ⇒ ระหว่างขอบล่างของแถบหนึบบน กับขอบบนของแถวนำทางล่าง
//   ⇒ ⛔ **ไม่นับแถบบางเองเป็นขอบล่าง** ⇒ นับแล้ววนไม่จบ ⇒ แถบโผล่ ⇒ ช่องอ่านหด ⇒ ข้อท้ายช่วงหลุด ⇒ แถบหาย ⇒ กระพริบ
//   ⇒ ⭐ **คิดใหม่ทุกเฟรมที่เลื่อน** ⛔ ไม่ใช่ดูแค่ตอนเปิดหน้า ⇒ ผูกกับ `นัดตรวจการเลื่อน`
//   ⇒ ตัวอย่าง ⇒ มาระโก 10 บนสุด มี · เลื่อนไปถึง 10:20 หาย · ช่วง 10:10–20 มี · ช่วง 10:13–16 ⛔ ไม่มี · มาระโก 9 ⛔ ไม่มี
//   ⛔ **ช่วงที่ไม่มีเรื่องเล่า ⛔ ไม่มีปุ่ม** (เกณฑ์ข้อ 7.2) ⇒ ⛔ ไม่มีปุ่มที่กดแล้วว่าง
//   ⇒ ตัวเฝ้าคือ `tools/ด่านเรื่องเล่าบนหน้า.mjs` ข้อ ② กับ ⑦
// ⭐⭐ **ตัวแผ่นเป็นก้อนโค้ดแยก ⇒ ตัวเรื่องกับเสียงถูกขอตอนกดเปิดเท่านั้น** (เกณฑ์ข้อ 10) ⇒ ท่าเดียวกับการ์ดคำ
const แผงเรื่องเล่า = ชิ้นโหลดแยก(() => import('~/components/แผงเรื่องเล่า.vue'))
/** เรื่องที่แผ่นเปิดอยู่ ⇒ จำทั้งก้อน ⛔ ไม่ใช่แค่รหัส ⇒ แผ่นยังรู้ชื่อเรื่องแม้แถบเปลี่ยนเรื่องไปแล้ว */
const เรื่องที่เปิด = ref<ดัชนีเรื่องเล่า | null>(null)
// ⭐ ปุ่มเป็นชิ้นส่วน `Button` (ใบ #141) ⇒ `ref` ได้ตัวชิ้นส่วน ⇒ ตัวปุ่มจริงบนหน้าคือ `$el` ของมัน
const ปุ่มเรื่องเล่าชิ้น = ref<{ $el: HTMLButtonElement } | null>(null)
const ปุ่มเรื่องเล่า = computed<HTMLButtonElement | null>(() => ปุ่มเรื่องเล่าชิ้น.value?.$el ?? null)

const ก่อนหรือเท่า = (ก: { บท: number; ข้อ: number }, ข: { บท: number; ข้อ: number }) =>
  ก.บท < ข.บท || (ก.บท === ข.บท && ก.ข้อ <= ข.ข้อ)

/** ข้อแรกกับข้อท้ายที่ตาเห็นในช่องอ่าน ⇒ `null` = ยังไม่ได้วัด หรือไม่มีข้อบนจอ (ฝั่งเซิร์ฟเวอร์ก็เป็น `null` ⇒ ⛔ ไม่ชนตอนรับหน้า) */
const ข้อบนจอ = ref<{ แรก: { บท: number; ข้อ: number }; ท้าย: { บท: number; ข้อ: number } } | null>(null)

function วัดข้อบนจอ() {
  const บน = ขอบล่างแถบหนึบ()
  const นำทาง = document.querySelector('.pk-นำทางล่าง')
  const ล่าง = นำทาง ? นำทาง.getBoundingClientRect().top : window.innerHeight
  let แรก: { บท: number; ข้อ: number } | null = null
  let ท้าย: { บท: number; ข้อ: number } | null = null
  for (const el of document.querySelectorAll<HTMLElement>('.pk-ตัวบท [data-ข้อ]')) {
    if (!el.getClientRects().length) continue
    const ก = el.getBoundingClientRect()
    if (ก.bottom <= บน || ก.top >= ล่าง) continue
    const [บท, ข้อ] = (el.getAttribute('data-ข้อ') || '').split(':').map(Number)
    if (!บท || !ข้อ) continue
    const ที่ = { บท, ข้อ }
    if (!แรก || ก่อนหรือเท่า(ที่, แรก)) แรก = ที่
    if (!ท้าย || ก่อนหรือเท่า(ท้าย, ที่)) ท้าย = ที่
  }
  const ใหม่ = แรก && ท้าย ? { แรก, ท้าย } : null
  // ⭐ เปลี่ยนค่าเฉพาะตอนต่างจริง ⇒ เลื่อนทีละนิดในข้อเดิม ⛔ ไม่ปลุกหน้าให้วาดใหม่ทุกเฟรม
  if (JSON.stringify(ใหม่) !== JSON.stringify(ข้อบนจอ.value)) ข้อบนจอ.value = ใหม่
}

/** เรื่องที่ช่วงของมันทับข้อบนจอ ⇒ ข้อบนจอเป็นช่วงต่อเนื่อง ⇒ ทับกัน = ต้นเรื่อง ≤ ข้อท้ายบนจอ และ ข้อแรกบนจอ ≤ ท้ายเรื่อง
 *  ⭐ ทับหลายเรื่อง (เรื่องติดกัน เช่น 10:1-12 กับ 10:13-31) ⇒ แถบมีปุ่มเดียว ⇒ เอาเรื่องที่มีข้อบนสุดของจอ = เรื่องที่กำลังอ่าน
 *    ⇒ ข้อบนสุดไม่อยู่ในเรื่องไหน ⇒ เอาเรื่องแรกที่ทับ (เคาะ 4 พ.ย. 2569 ตอนเรื่องเล่ามาระโกมีเรื่องติดกันครั้งแรก) */
const เรื่องบนจอ = computed<ดัชนีเรื่องเล่า | null>(() => {
  const จอ = ข้อบนจอ.value
  if (!จอ) return null
  const ทับ = (ของเล่ม.value?.เรื่องเล่า || []).filter((ร) => ก่อนหรือเท่า(ร.จาก, จอ.ท้าย) && ก่อนหรือเท่า(จอ.แรก, ร.ถึง))
  return ทับ.find((ร) => ก่อนหรือเท่า(ร.จาก, จอ.แรก)) || ทับ[0] || null
})

// ⭐⭐ **ตัวเล่นเสียงเรื่องเล่าอยู่ที่หน้านี้ ⛔ ไม่อยู่ในแผ่น** (เกณฑ์ข้อ 8 · 10 · รอบ 2 ข้อ 3)
//   ⇒ ตัวเล่นคือ `สร้างตัวเล่นเสียง` ตัวเดิม ⇒ `<audio>` ของตัวเอง 1 ตัว ⇒ เกิดตอนกดฟังครั้งแรกเท่านั้น
//   ⇒ ⛔ **ให้แผ่นสร้างเองไม่ได้** ⇒ วัดแล้ว 25 ต.ค. 2569 ⇒ ทุกหน้าอ่านหนักขึ้น 38 กิโลไบต์ ⇒ เหตุผลเต็มอยู่หัวไฟล์แผ่น
//   ⇒ ⭐ **รอบ 2 ⇒ ปิดแผ่นแล้วเสียงเล่นต่อ** ⇒ หยุดได้จากปุ่มในแถบบาง ⇒ ปุ่มนั้นบอกชื่อเรื่องที่กำลังเล่น
//   ⇒ ⛔ **เสียงพระคำกับเสียงเรื่องเล่าห้ามดังพร้อมกัน** ⇒ กดอันหนึ่ง อีกอันหยุด ⇒ ตัวเฝ้าคือ `ด่านเรื่องเล่าบนหน้า` ข้อ ⑤
const สภาพเสียงเรื่อง = ref<สภาพตัวเล่น>({ สถานะ: 'ยังไม่เริ่ม', ที่ข้อ: -1 })
let ตัวเล่นเรื่อง: ReturnType<typeof สร้างตัวเล่นเสียง> | null = null
/** เรื่องที่อยู่ในตัวเล่น ⇒ แถบบางใช้บอกว่ากำลังเล่นเสียงของเรื่องไหน */
const เรื่องในตัวเล่น = ref<ดัชนีเรื่องเล่า | null>(null)
/** เสียงเรื่องเล่ายังไม่จบ ⇒ เล่นอยู่ หรือหยุดพักไว้ */
const เสียงเรื่องค้าง = computed(() => !!เรื่องในตัวเล่น.value && สภาพเสียงเรื่อง.value.สถานะ !== 'ยังไม่เริ่ม')

/** ⭐ **เรื่องที่แถบบางบอก** ⇒ เสียงเรื่องเล่ายังไม่จบ ⇒ เรื่องที่อยู่ในตัวเล่น **แม้เลื่อนออกนอกช่วงแล้ว**
 *  ⇒ ⛔ ไม่งั้นปุ่มหยุดหายไปกับตาตอนเสียงยังดัง (เกณฑ์รอบ 2 ข้อ 3) ⇒ เสียงจบหรือถูกหยุด ⇒ กลับไปใช้กติกาทับซ้อน */
const เรื่องในแถบ = computed<ดัชนีเรื่องเล่า | null>(() => (เสียงเรื่องค้าง.value ? เรื่องในตัวเล่น.value : เรื่องบนจอ.value))

const คำบนปุ่มเสียงเรื่อง = computed(() => (สภาพเสียงเรื่อง.value.สถานะ === 'กำลังเล่น' ? 'หยุดพัก' : 'ฟังต่อ'))

interface เรื่องที่จะฟัง extends ดัชนีเรื่องเล่า {
  ชื่อเล่ม: string
  เสียง: { ไฟล์: string; วินาที: number } | null
}

/** ⛔ **ต้องสั่งเล่นในจังหวะเดียวกับการกด** ⇒ ทุกอย่างที่ต้องใช้อยู่ในมือแล้ว ⛔ ไม่มี `await` */
function กดฟังเรื่องเล่า(ร: เรื่องที่จะฟัง) {
  if (!ร.เสียง) return
  if (!ตัวเล่นเรื่อง) ตัวเล่นเรื่อง = สร้างตัวเล่นเสียง((ส) => (สภาพเสียงเรื่อง.value = ส))
  if (เรื่องในตัวเล่น.value?.รหัส !== ร.รหัส) {
    เรื่องในตัวเล่น.value = { รหัส: ร.รหัส, จาก: ร.จาก, ถึง: ร.ถึง }
    ตัวเล่นเรื่อง.ตั้งคิว([
      {
        รหัส: ร.รหัส,
        เล่ม: รหัสเล่ม,
        ชื่อเล่ม: ร.ชื่อเล่ม,
        บท: ร.จาก.บท,
        ข้อ: ร.จาก.ข้อ,
        ที่อยู่ไฟล์: ที่อยู่หลังบ้าน(ร.เสียง.ไฟล์),
        วินาที: ร.เสียง.วินาที,
        หัวเรื่อง: `เรื่องเล่า ${ร.ชื่อเล่ม} ${แสดงช่วงฟัง(ร)}`,
        ผู้ทำ: 'พระคำ.ชีวิต',
      },
    ])
  }
  if (สภาพเสียงเรื่อง.value.สถานะ !== 'กำลังเล่น') เสียง.หยุด()
  ตัวเล่นเรื่อง.กดปุ่มเดียว()
}

/** ปุ่มเสียงเรื่องเล่าในแถบบาง ⇒ หยุดพัก · ฟังต่อ ⇒ ฟังต่อเมื่อไร เสียงพระคำหยุดก่อน */
function กดเสียงเรื่องในแถบ() {
  if (!ตัวเล่นเรื่อง) return
  if (สภาพเสียงเรื่อง.value.สถานะ !== 'กำลังเล่น') เสียง.หยุด()
  ตัวเล่นเรื่อง.กดปุ่มเดียว()
}

/** หยุดเสียงเรื่องเล่า ⇒ ใช้ตอนผู้อ่านกดฟังพระคำ */
function หยุดเสียงเรื่องเล่า() {
  ตัวเล่นเรื่อง?.หยุด()
  เรื่องในตัวเล่น.value = null
}

function เปิดเรื่องเล่า() {
  if (เรื่องในแถบ.value) เรื่องที่เปิด.value = เรื่องในแถบ.value
}

/** ⭐ ชื่อย่อเล่มบนปุ่มเรื่องเล่า ⇒ `toc3` ของ TCV ⇒ เรื่องเล่าเป็นภาษาไทย ⇒ ⛔ ใช้ชื่อย่อของคอลัมน์แรกที่อาจเป็นอังกฤษ */
const ชื่อย่อเรื่อง = computed(() => ของเล่ม.value?.ชื่อย่อของชั้น?.['TCV'] || เล่มนี้.value.ชื่อไทย)

/**
 * ⭐⭐ **ปุ่มเรื่องเล่าบนแถบล่างมี 4 แบบ ⇒ เลือกจากของจริงบนจอ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131)
 *   ⇒ `เต็ม` ⇒ *เรื่องเล่า มก. 10:1–12* ⇒ อยู่แถวเดียวกับทางเดินบทและปุ่มฟัง ⇒ และชื่อเล่มกลางแถบ ⛔ ถูกหด
 *   ⇒ `สั้น` ⇒ *เรื่องเล่า* ⇒ แถวเดียวกัน ⇒ ชื่อเล่มกลางแถบ ⛔ ถูกหดเหมือนแบบเต็ม (แถบล่างล้นขอบ 8 พ.ย. 2569)
 *     ⇒ ⚠️ ของเดิมแบบนี้ยอมให้ชื่อเล่มหด ⇒ จอนอกของ Galaxy Fold ได้ *มาระ… 10* ทั้งที่แบบสองแถวให้ชื่อเต็มได้
 *   ⇒ `สองแถว` ⇒ สั้นแล้วยังไม่พอ ⇒ ทางเดินบทกว้างเต็มแถวบน · ปุ่มเรื่องเล่า (ป้ายเต็ม) กับปุ่มฟังอยู่แถวล่าง
 *     ⇒ วัดแล้ว 4 พ.ย. 2569 ⇒ จอ 320 ⇒ แถบ 288 จุด ⇒ ‹ › 88 · ชื่อบทหดเหลือเลข · *เรื่องเล่า* · ฟัง 104 ⇒ ยังเกินแถบ
 *     ⇒ สูงเท่าแถวบาง + แถบล่างของเดิม ⇒ ⛔ ไม่บีบปุ่มใดต่ำกว่า 44 จุด (SC 2.5.8) ⛔ ไม่เลื่อนข้าง (SC 1.4.10)
 *   ⇒ `สองแถวสั้น` ⇒ สองแถวแล้วป้ายเต็มกับปุ่มฟังยังไม่พอแถวล่าง ⇒ แถวล่างเหลือ *เรื่องเล่า* กับปุ่มฟัง
 *     ⛔⛔ **ของเดิมไม่วัดแบบสองแถว ⇒ ถือว่าป้ายเต็มพอเสมอ** ⇒ จริงแค่เรื่องที่ช่วงสั้น
 *       ⇒ จอ 320 เลื่อนถึง *เรื่องเล่า มก. 10:13–31* ⇒ ป้ายยาวกว่า *10:1–12* ⇒ ปุ่มฟังตกไปแถวที่ 3
 *       ⇒ แถบล่างโตจาก 105 เป็น 155 จุด ระหว่างเลื่อนอ่าน ⇒ กินช่องอ่านอีก 50 จุด และคำที่อยู่ขอบล่างจอถูกแถบที่โตขึ้นทับ
 *       ⇒ ท่อ 11643 `ด่านการ์ดคำ` จอ 320 ⇒ *จุดที่จะกดคำถูก BUTTON.pk-ปุ่มตอนนี้ ทับอยู่*
 *   ⇒ ลองจากแบบที่บอกมากที่สุดก่อน ⇒ วัดหลังวาดแต่ก่อนเบราว์เซอร์ระบายจอ ⇒ ผู้อ่าน ⛔ เห็นแบบที่ถูกทิ้ง
 *   ⭐ **ชื่อที่ได้ยินขึ้นต้นด้วยคำที่ตาเห็นทุกแบบ** ⇒ *เรื่องเล่า …* แล้วต่อด้วยชื่อเต็มกับช่วง ⇒ SC 2.5.3 ⇒ ท่าเดียวกับปุ่มชื่อย่อบนหัวคอลัมน์
 *   ⇒ ตัวเฝ้าคือ `tools/ด่านเรื่องเล่าบนหน้า.mjs` ข้อ ⑪
 */
const แบบปุ่มเรื่อง = ref<'เต็ม' | 'สั้น' | 'สองแถว' | 'สองแถวสั้น'>('เต็ม')
const เรื่องสองแถว = computed(() => แบบปุ่มเรื่อง.value === 'สองแถว' || แบบปุ่มเรื่อง.value === 'สองแถวสั้น')
const ป้ายเรื่องสั้น = computed(() => แบบปุ่มเรื่อง.value === 'สั้น' || แบบปุ่มเรื่อง.value === 'สองแถวสั้น')
let รอบจัดปุ่มเรื่อง = 0
function แถวเดียวกัน(ก: Element, ข: Element) {
  const a = ก.getBoundingClientRect()
  const b = ข.getBoundingClientRect()
  return a.top < b.bottom - 1 && b.top < a.bottom - 1
}
async function จัดปุ่มเรื่องเล่า() {
  if (import.meta.server || !เรื่องในแถบ.value) return
  const รอบ = ++รอบจัดปุ่มเรื่อง
  for (const แบบ of ['เต็ม', 'สั้น', 'สองแถว'] as const) {
    แบบปุ่มเรื่อง.value = แบบ
    await nextTick()
    if (รอบ !== รอบจัดปุ่มเรื่อง) return
    const ปุ่ม = ปุ่มเรื่องเล่า.value
    const นำทาง = document.querySelector('.pk-นำทางล่าง')
    if (!ปุ่ม || !นำทาง) return
    const ถัด = ปุ่ม.nextElementSibling
    // ⭐ แบบสองแถว ⇒ ทางเดินบทอยู่แถวบนเองโดยตั้งใจ ⇒ วัดแค่ว่าปุ่มเรื่องเล่ากับปุ่มฟังยังอยู่แถวล่างแถวเดียวกัน
    const แถวเดียว = (แบบ === 'สองแถว' || แถวเดียวกัน(ปุ่ม, นำทาง)) && (!ถัด || แถวเดียวกัน(ปุ่ม, ถัด))
    // ⭐ ชื่อเล่มต้องครบทั้งแบบเต็มและแบบสั้น ⇒ หดแล้วยังมีทางขึ้นสองแถวให้ชื่อได้ทั้งแถว ⇒ ⛔ หดชื่อทั้งที่ยังมีที่
    //   ⇒ ⚠️ ของเดิมแบบสั้นยอมให้ชื่อหด ⇒ พี่เอมเห็น *มาระ… 10* คู่กับ *เรื่องเล่า* บน Galaxy Fold จอนอก (8 พ.ย. 2569)
    //   ⇒ แบบสองแถวทางเดินบทได้ทั้งแถวแล้ว ⇒ ยังหดอีก (ตัวอักษร 200% จอแคบ) คือไม่มีที่จริง ⇒ ยอมตามใบ #113 ข้อ 7.3
    const ชื่อเล่มครบ =
      แบบ === 'สองแถว' ||
      ![...นำทาง.querySelectorAll<HTMLElement>('.pk-ป้ายเล่ม')].some((e) => e.scrollWidth > e.clientWidth + 0.5)
    if (แถวเดียว && ชื่อเล่มครบ) return
  }
  แบบปุ่มเรื่อง.value = 'สองแถวสั้น'
}
/** ⭐ จัดใหม่เฉพาะตอนความกว้างหรือขนาดตัวอักษรของแถบเปลี่ยน ⇒ แบบที่เปลี่ยนทำให้แถบสูงต่ำ ⇒ ⛔ ไม่วนจัดไม่จบ */
let ตัวเฝ้าแถบล่าง: ResizeObserver | undefined
let ขนาดแถบล่าง = ''
function ตอนแถบล่างเปลี่ยน() {
  const แถบ = document.querySelector<HTMLElement>('.pk-แถบล่าง')
  if (!แถบ) return
  const ขนาดใหม่ = `${แถบ.clientWidth}|${getComputedStyle(แถบ).fontSize}`
  if (ขนาดใหม่ === ขนาดแถบล่าง) return
  ขนาดแถบล่าง = ขนาดใหม่
  void จัดปุ่มเรื่องเล่า()
}
watch(
  () => [เรื่องในแถบ.value?.รหัส, เลขบนแถบล่าง.value, ป้ายที่ของหน้า.value],
  () => void จัดปุ่มเรื่องเล่า(),
  { flush: 'post' },
)

/** ⭐ ปิดแผ่น ⇒ **โฟกัสกลับปุ่ม *เรื่องเล่า*** ⇒ WAI-ARIA APG Dialog (Modal) ⇒ WCAG 2.2 SC 2.4.3 Focus Order (ระดับ A)
 *  ⛔ **ไม่หยุดเสียง** (เกณฑ์รอบ 2 ข้อ 3) ⇒ หยุดได้จากปุ่มในแถบบาง */
function ปิดเรื่องเล่า() {
  เรื่องที่เปิด.value = null
  void nextTick(() => ปุ่มเรื่องเล่า.value?.focus({ preventScroll: true }))
}

// ⭐ เนื้อบนหน้าเปลี่ยน (ต่อบท · กางช่วง · เปิดคอลัมน์) ⇒ ข้อบนจอเปลี่ยนได้โดยไม่มีการเลื่อน ⇒ วัดใหม่หลังวาดเสร็จ
//   ⛔⛔ **วัดอย่างเดียว ⛔ ห้ามเรียก `นัดตรวจการเลื่อน`** ⇒ ตัวนั้นต่อบทถัดไปเองเมื่อปลายม้วนอยู่ในจอ
//     ⇒ ลองแล้ว 25 ต.ค. 2569 ⇒ เปิดสดุดี 1 (6 ข้อ) แล้วสดุดี 2 ถูกต่อเข้ามาเองโดยไม่มีใครเลื่อน ⇒ `ด่านหน้าเว็บ` ข้อ ⑦ จับได้
watch(
  บทที่แสดง,
  () => {
    if (import.meta.server) return
    void nextTick(() => requestAnimationFrame(วัดข้อบนจอ))
  },
  { flush: 'post' },
)

// ⭐ **ฉบับของคอลัมน์ที่อ่านเปลี่ยน ⇒ หยุดเสียง** (ใบ #132 ข้อ 11) ⇒ คิวเดิมเป็นเสียงของอีกฉบับ
//   ⇒ ⛔ ไม่ปล่อยให้ได้ยินฉบับเก่าทั้งที่ปุ่มบอกฉบับใหม่แล้ว ⇒ กดอีกครั้งได้ฉบับใหม่ตั้งแต่ข้อบนจอ
watch(ฉบับที่ฟัง, () => เสียง.หยุด())

/** ปุ่มฟังพระคำบนแถบล่าง ⇒ หยุดเสียงเรื่องเล่าก่อน ⇒ แล้วค่อยทำงานเดิมทุกอย่าง */
function กดฟังพระคำ() {
  หยุดเสียงเรื่องเล่า()
  เสียง.กดปุ่มฟัง()
}

/** กุญแจของข้อที่กำลังอ่าน ⇒ `บท:ข้อ` ⇒ กล่องข้อทุกฉบับทุกคอลัมน์ที่ตรงกุญแจนี้ได้ไฮไลต์ (ข้อ 9) */
const กุญแจที่เล่น = computed(() =>
  เสียง.ข้อที่เล่นอยู่.value ? `${เสียง.ข้อที่เล่นอยู่.value.บท}:${เสียง.ข้อที่เล่นอยู่.value.ข้อ}` : '',
)

// ---------------------------------------------------------------- เมนูที่กางได้
//
// ⭐⭐ **เมนูเดินตามแบบแผน Menu Button ของ WAI-ARIA Authoring Practices** (ใบงาน v3/phrakham#86)
//   ⇒ 8 ก.ย. 2569 พี่เอมเปิดที่ทดลอง กดปุ่ม *ปรับหน้าจอ* ที่มุมขวาบน
//     แต่กล่องไปโผล่มุมซ้ายบน **ทับตัวบทข้อ 1 ถึง 4 จนอ่านไม่ได้** และกดที่ว่างแล้วก็ไม่ปิด
//   ⇒ แบบแผนสั่งไว้ 2 ข้อ ⇒ **กดนอกเมนูต้องปิด** และ **Escape ต้องปิดแล้วคืนโฟกัสให้ปุ่ม**
//     ⇒ คืนโฟกัส ⇒ WCAG SC 2.4.3 Focus Order (ระดับ A)
//   ⇒ **ตัวเฝ้าคือ `tools/ด่านเมนูปรับหน้าจอ.mjs`** ⛔ ไม่จดซ้ำที่นี่ว่ามันวัดอะไรบ้าง
const เมนูที่กาง = ref<'' | 'ฉบับ' | 'หน้าจอ'>('')
// ⭐ ใบ #161 ⇒ เมนูปิดหรือสลับ ⇒ ข้อความตอนเต็มเป็นผลของการกดครั้งนั้น ⇒ เปิดเมนูใหม่ได้เมนูสะอาด ⇒ ⛔ ข้อความเก่าค้าง
watch(เมนูที่กาง, () => (ข้อความเต็ม.value = ''))
const เปิดหน้าต่างเล่ม = ref(false)

// ⭐ กล่องที่ห่อ **ปุ่ม + เมนู** ของแต่ละอัน ⇒ ใช้ตอบ 2 คำถาม
//   ① ที่กดอยู่ในกล่องหรือนอกกล่อง ② ปุ่มไหนคือปุ่มที่ต้องคืนโฟกัสให้ตอนกด Escape
const กล่องฉบับ = ref<HTMLElement | null>(null)
const กล่องหน้าจอ = ref<HTMLElement | null>(null)
const กล่องของเมนู = (ชื่อ: string) =>
  ชื่อ === 'ฉบับ' ? กล่องฉบับ.value : ชื่อ === 'หน้าจอ' ? กล่องหน้าจอ.value : null

// ⭐ เมนูเกาะ **ขอบขวาของปุ่มที่กด** ด้วย CSS (`right: 0`) ⇒ ⛔ ไม่ต้องคำนวณตำแหน่งเอง
//   แต่ปุ่มที่อยู่ค่อนไปทางซ้ายบนจอแคบ จะทำให้กล่องยื่นพ้นขอบซ้ายจอ
//   ⇒ จึง **เลื่อนกลับเข้าจอเท่าที่ขาด** ⛔ ไม่ย้ายไปเกาะที่อื่น
//   ⇒ WCAG SC 1.4.10 Reflow (ระดับ AA) ⇒ ที่ 320 จุดต้องไม่มีการเลื่อนซ้ายขวา
// ⭐⭐ **ห่างขอบจออย่างน้อย 16 จุด ทั้ง 4 ด้าน** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/109 ข้อ 9)
//   ⛔ ของเดิมเผื่อแค่ 4 จุด และ ⛔ ไม่ดูขอบล่างเลย ⇒ พี่เอมเปิดบนมือถือ 26 ต.ค. 2569 ⇒ เมนู *คอลัมน์* ตกขอบซ้าย
//     ตัวแรกของ *เพิ่มฉบับอื่นของตอนนี้* ถูกตัด ⇒ และที่จอ 320 ตัวอักษร 200% เมนูยาวเลยขอบล่างจอ 704 จุด
//     ⇒ แถบบนหนึบอยู่ ⇒ เลื่อนหน้าแล้วเมนูเลื่อนตาม ⇒ **ของที่เลยขอบล่างกดไม่ได้เลย**
//   ⇒ ⭐ 16 จุด = ขอบหน้าของเว็บบนจอแคบ (`1rem`) ⇒ เมนูอยู่ในแนวเดียวกับตัวบท
//   ⇒ ⭐ ความกว้างกับความสูงสุดของเมนูถูกส่งให้ CSS จากที่นี่ ⇒ วัดจากจอจริงตอนกาง ⛔ ไม่เดาจาก `vw`
//     ⇒ `vw` นับรวมแถบเลื่อนของเบราว์เซอร์จอกว้าง ⇒ ได้กว้างเกินที่วางได้จริง
//   ⇒ ⭐ **วัดใหม่ทุกครั้งที่เมนูเปลี่ยนขนาด** (`ResizeObserver`) ⇒ ฟอนต์มาช้า · ตัวเลือกโผล่หรือหาย · ผู้อ่านกด ก+
//     ⇒ ⛔ ของเดิมวัดครั้งเดียวตอนกาง ⇒ เมนูโตทีหลังแล้วตกขอบได้โดยไม่มีอะไรจัดให้ใหม่
const ระยะเผื่อขอบจอ = 16
const เลื่อนเมนู = ref(0)
const กว้างเมนูสุด = ref(0)
const สูงเมนูสุด = ref(0)
// ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/153 ⇒ เมนูที่กางเป็นกล่องเด้ง ⇒ ระหว่างกาง วัดขอบล่างของแถบบนให้หน้าเต็มจอ
//   ⇒ ⚠️ ของเดิม (ใบ #151) วัดครั้งเดียวตอนเปิดแล้วดันของลงด้วยขอบใน ⇒ เหตุผลที่เปลี่ยนอยู่หัว `app/composables/กล่องเด้ง.ts`
ใช้กล่องเด้ง(() => !!เมนูที่กาง.value)
// ⭐ เชิงอรรถของผู้แปลที่เปิดอยู่ ⇒ แตะเครื่องหมาย = ทีละอัน ⇒ กดเครื่องหมายเดิมซ้ำ = ปิด
//   ⇒ ⭐ ปุ่ม *เชิงอรรถ* ในแถบข้อที่เลือก = ทุกอันของข้อที่เลือก ⇒ ทางของแป้นพิมพ์และโปรแกรมอ่านหน้าจอ (เหตุผลอยู่หัว `แผ่นเชิงอรรถ.vue`)
const เชิงอรรถที่เปิด = ref<{ รายการ: เครื่องหมายเชิงอรรถ[]; ปุ่ม: HTMLElement | null; จากแถบ: boolean } | null>(null)
function สลับเชิงอรรถ(ก้อน: เครื่องหมายเชิงอรรถ, e: MouseEvent) {
  const เดิม = เชิงอรรถที่เปิด.value
  if (เดิม && !เดิม.จากแถบ && เดิม.รายการ[0] === ก้อน) return ปิดเชิงอรรถ()
  เชิงอรรถที่เปิด.value = { รายการ: [ก้อน], ปุ่ม: e.currentTarget as HTMLElement, จากแถบ: false }
}
function ปิดเชิงอรรถ() {
  const เดิม = เชิงอรรถที่เปิด.value
  เชิงอรรถที่เปิด.value = null
  // ⭐ เปิดจากปุ่มในแถบ ⇒ คืนโฟกัสให้ปุ่ม ⇒ คนใช้แป้นพิมพ์ไม่หลงตำแหน่ง (WCAG 2.4.3)
  if (เดิม?.จากแถบ && เดิม.ปุ่ม?.isConnected) เดิม.ปุ่ม.focus()
}
/** เครื่องหมายบนหน้า → ก้อนของมัน ⇒ ปุ่มในแถบหาเชิงอรรถของข้อที่เลือกจากของที่วาดอยู่จริง ⇒ ลำดับตามที่ตาเห็น
 *  ⇒ ติดเลขไว้บนเครื่องหมาย (`data-เลขเชิงอรรถ`) ⇒ ⚠️ `ref` แบบฟังก์ชันในวงนี้ ⛔ ถูกเรียกบนเว็บที่สร้างแล้ว (ลองจริง 22 พ.ย. 2569) */
const เลขของก้อน = new WeakMap<เครื่องหมายเชิงอรรถ, string>()
const ก้อนของเลข = new Map<string, WeakRef<เครื่องหมายเชิงอรรถ>>()
let เลขถัดไป = 0
function เลขเชิงอรรถ(ก้อน: เครื่องหมายเชิงอรรถ): string {
  let เลข = เลขของก้อน.get(ก้อน)
  if (!เลข) {
    เลข = String(++เลขถัดไป)
    เลขของก้อน.set(ก้อน, เลข)
    ก้อนของเลข.set(เลข, new WeakRef(ก้อน))
  }
  return เลข
}
const เชิงอรรถของข้อที่เลือก = ref<เครื่องหมายเชิงอรรถ[]>([])
function หาเชิงอรรถของข้อที่เลือก() {
  if (import.meta.server) return
  const ออก: เครื่องหมายเชิงอรรถ[] = []
  for (const ม of document.querySelectorAll('[aria-pressed="true"] .pk-เครื่องหมายเชิงอรรถ')) {
    const ก = ก้อนของเลข.get(ม.getAttribute('data-เลขเชิงอรรถ') || '')?.deref()
    // ⛔ นับเฉพาะที่ตาเห็น ⇒ บางวางมีสำเนาที่ซ่อนอยู่
    if (ก && ม.getClientRects().length && !ออก.includes(ก)) ออก.push(ก)
  }
  เชิงอรรถของข้อที่เลือก.value = ออก
}
function เปิดเชิงอรรถของข้อที่เลือก(e: MouseEvent) {
  หาเชิงอรรถของข้อที่เลือก()
  if (!เชิงอรรถของข้อที่เลือก.value.length) return
  เชิงอรรถที่เปิด.value = { รายการ: [...เชิงอรรถของข้อที่เลือก.value], ปุ่ม: e.currentTarget as HTMLElement, จากแถบ: true }
}
function ไปที่จากเชิงอรรถ(ที่อยู่: string, ก้อน: เครื่องหมายเชิงอรรถ) {
  ปิดเชิงอรรถ()
  เปิดข้ออื่น(ที่อยู่, ก้อน.ฉบับ)
}
/** ⭐ ที่อยู่ข้ออื่นที่ผู้แปลเขียนไว้ (เชิงอรรถ · บรรทัดคู่ขนานใต้หัวข้อ) ⇒ เปิดคอลัมน์ใหม่ฉบับเดียวกัน ⇒ คอลัมน์เต็ม ⇒ พาไป */
function เปิดข้ออื่น(ที่อยู่: string, ฉบับ: string) {
  const m = /^([1-3A-Z]{3}) (\d+):(\d+)/.exec(ที่อยู่)
  if (!m) return
  const [, เล่ม, บท, ข้อ] = m
  if (ครบเพดาน.value) {
    void ไปที่จุด({ รหัส: เล่ม!, บท: Number(บท), ข้อ: Number(ข้อ) })
    return
  }
  เริ่มก้าว()
  ตั้งคอลัมน์เทียบ([...คอลัมน์เทียบที่เปิด.value, { เล่ม: เล่ม!, บท: Number(บท), ฉบับ, ข้อ: Number(ข้อ) }])
}
// ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154 ⇒ กล่องของปุ่มเฟืองกับ i เป็นกล่องเด้งชิ้นเดียวกัน ⇒ ขอตัววัดขอบแถบบนเหมือนกัน
ใช้กล่องเด้ง(() => !!กล่องคำเดิม.value)
let ตัวเฝ้าขนาดเมนู: ResizeObserver | null = null

async function จัดที่เมนู() {
  if (import.meta.server) return
  const จอ = document.documentElement
  กว้างเมนูสุด.value = จอ.clientWidth - 2 * ระยะเผื่อขอบจอ
  เลื่อนเมนู.value = 0
  await nextTick()
  const เมนู = กล่องของเมนู(เมนูที่กาง.value)?.querySelector<HTMLElement>('.pk-เมนู')
  if (!เมนู) return
  // ⭐ ใบ #151 · #153 ⇒ หน้าเต็มจอของมือถือ (Aa · เทียบ) ⇒ ⛔ เลื่อน ⛔ หนีบขนาด ⇒ ขอบบนของหน้าคือขอบล่างของแถบบน
  //   ⇒ ตัววัดขอบอยู่ที่ `ใช้กล่องเด้ง` ⇒ ที่นี่ ⛔ ต้องทำอะไร
  if (เมนู.classList.contains('pk-เต็มจอ')) return
  const กรอบ = เมนู.getBoundingClientRect()
  // ⛔⛔ **เลื่อนเท่าที่ขาดพอดี ⛔ ห้ามปัดขึ้น (`Math.ceil`)** (ใบ #113)
  //   ⇒ เมนูจอแคบกว้างเท่าที่ว่างพอดี (`--pk-กว้างเมนูสุด`) ⇒ ปัดขอบซ้ายขึ้นเศษจุดเดียว = ขอบขวาเกินเข้าไปในระยะ 16 จุดเท่านั้น
  //   ⇒ ของจริง ⇒ ปุ่ม *เทียบ* สั้นกว่า *คอลัมน์* ⇒ ขอบซ้ายของเมนูตกที่เศษ .78 ⇒ ปัดขึ้นแล้วขอบขวาเหลือ 15.2 จุด
  //     ⇒ `tools/ด่านเมนูปรับหน้าจอ.mjs` ข้อ ④ จับได้ ⇒ ของเดิมรอดเพราะเศษตกที่ .36 พอดี ⛔ ไม่ใช่เพราะถูก
  if (กรอบ.left < ระยะเผื่อขอบจอ) {
    เลื่อนเมนู.value = ระยะเผื่อขอบจอ - กรอบ.left
  } else if (กรอบ.right > จอ.clientWidth - ระยะเผื่อขอบจอ) {
    เลื่อนเมนู.value = -(กรอบ.right - (จอ.clientWidth - ระยะเผื่อขอบจอ))
  }
  // ⭐ สูงเกินจอ ⇒ เลื่อนข้างในเมนู ⛔ ไม่ล้นจอ ⇒ ⛔ ไม่ตั้งต่ำกว่าปุ่มเมนู 2 ปุ่ม (44 จุด) ⇒ ยังใช้ได้บนจอเตี้ยมาก
  สูงเมนูสุด.value = Math.max(2 * 44, Math.floor(จอ.clientHeight - กรอบ.top - ระยะเผื่อขอบจอ))
  if (!ตัวเฝ้าขนาดเมนู && typeof ResizeObserver !== 'undefined') {
    let ขนาดเดิม = ''
    ตัวเฝ้าขนาดเมนู = new ResizeObserver(([ร]) => {
      // ⛔ จัดใหม่เฉพาะตอนขนาดเปลี่ยนจริง ⇒ การเลื่อน (`transform`) ⛔ ไม่เปลี่ยนขนาด ⇒ ⛔ ไม่วนไม่จบ
      const ขนาด = `${Math.round(ร!.contentRect.width)}x${Math.round(ร!.contentRect.height)}`
      if (ขนาด === ขนาดเดิม) return
      const ครั้งแรก = !ขนาดเดิม
      ขนาดเดิม = ขนาด
      if (!ครั้งแรก) จัดที่เมนู()
    })
    ตัวเฝ้าขนาดเมนู.observe(เมนู)
  }
}

/** ค่าที่ส่งให้ CSS ของเมนู ⇒ ⛔ ยังไม่ได้วัด (ศูนย์) = ปล่อยให้ CSS ใช้ค่าสำรองของมันเอง */
const สไตล์เมนู = computed(() => ({
  '--pk-เลื่อนเมนู': `${เลื่อนเมนู.value}px`,
  ...(กว้างเมนูสุด.value > 0 ? { '--pk-กว้างเมนูสุด': `${กว้างเมนูสุด.value}px` } : {}),
  ...(สูงเมนูสุด.value > 0 ? { '--pk-สูงเมนูสุด': `${สูงเมนูสุด.value}px` } : {}),
}))

function เลิกเฝ้าขนาดเมนู() {
  ตัวเฝ้าขนาดเมนู?.disconnect()
  ตัวเฝ้าขนาดเมนู = null
}

/** โฟกัสกลับไปที่ปุ่มที่เปิดเมนูอันนั้น ⇒ ⛔ ห้ามปล่อยโฟกัสหล่นไปอยู่ที่ `<body>` */
function คืนโฟกัสให้ปุ่ม(ชื่อ: string) {
  กล่องของเมนู(ชื่อ)?.querySelector<HTMLElement>('.pk-ปุ่มแถบ')?.focus()
}

function ปิดเมนู(คืนโฟกัส: boolean) {
  const ชื่อ = เมนูที่กาง.value
  if (!ชื่อ) return
  เมนูที่กาง.value = ''
  if (คืนโฟกัส) คืนโฟกัสให้ปุ่ม(ชื่อ)
}

// ⛔ **ดักที่ `pointerdown` ⛔ ไม่ใช่ `click`** — กดค้างแล้วลากออกไปปล่อยนอกกล่อง
//   จะ ⛔ ไม่เกิด `click` เลย ⇒ เมนูค้างเปิดอยู่ทั้งที่ผู้อ่านกดที่อื่นไปแล้ว
function กดที่ไหนบนหน้า(e: PointerEvent) {
  const กล่อง = กล่องของเมนู(เมนูที่กาง.value)
  // ⛔ ที่กดอยู่ในกล่อง = ปุ่มของเมนูเอง หรือช่องติ๊กในเมนู ⇒ ⛔ ไม่ปิด
  if (กล่อง && e.target instanceof Node && กล่อง.contains(e.target)) return
  ปิดเมนู(false)
}

function กดปุ่มบนแป้น(e: KeyboardEvent) {
  if (e.key === 'Escape') ปิดเมนู(true)
}

function สลับเมนู(ชื่อ: 'ฉบับ' | 'หน้าจอ') {
  เมนูที่กาง.value = เมนูที่กาง.value === ชื่อ ? '' : ชื่อ
}

// ⭐⭐ **หน้าเต็มจอของมือถือ ⇒ ปิดแล้วกลับมาที่ข้อเดิมที่อ่านค้าง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/151 เกณฑ์ข้อ 1.3)
//   ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/153 ⇒ ทุกกล่องเด้งที่เป็นหน้าเต็มจอ (Aa · เทียบ) ⛔ เฉพาะ Aa ⇒ ปุ่ม *กลับไปอ่าน* ถูกถอด ⇒ ปิดด้วย × แทน
//   ⇒ จดข้อแรกที่เห็นใต้แถบหนึบกับระดับของมันบนจอ **ตอนเปิดหน้า** ⇒ ปิดหน้า (× · ปุ่มที่เปิด · Escape · ที่ว่างบนแถบ) ⇒ เลื่อนให้ข้อนั้นกลับมาที่ระดับเดิม
//   ⇒ สลับจากหน้าหนึ่งไปอีกหน้าตรง ๆ (Aa ⇒ เทียบ) ⇒ ยังถือข้อที่จดตอนเปิดหน้าแรก ⇒ ปิดหน้าสุดท้ายแล้วกลับที่เดิม
//   ⇒ ⭐ ระหว่างเปิดหน้า ผู้อ่านเปลี่ยนขนาดตัวอักษร การจัดวาง สัญลักษณ์กาลได้ ⇒ ตัวบทข้างหลังจัดใหม่ ⇒ ข้อที่อ่านไหลไปที่อื่น
//     ⇒ ⛔ พึ่งตัวยึดเดิม (`จำที่ยึด`) อย่างเดียวไม่ได้ ⇒ ตัวนั้นปล่อยทันทีที่ผู้อ่านแตะอะไร (`ปล่อยที่ยึด`) ⇒ ซึ่งคือทุกครั้งที่แตะในหน้า Aa
//   ⇒ ⭐ ยึด *ตัวหนังสือของข้อ* (`[data-ข้อ]`) ท่าเดียวกับ `จำที่ยึด` ⇒ กล่องที่ถูกวาดใหม่ทั้งกล่อง ⇒ หาด้วยกุญแจของข้อซ้ำ
//   ⇒ กุญแจเดียวกันมีได้หลายกล่อง (ข้อเดียวกันของหลายคอลัมน์) ⇒ จดลำดับของกล่องในกุญแจนั้นด้วย
let ที่อ่านก่อนเต็มจอ: { ข้อ: string; ที่: number; บน: number } | null = null
const กล่องของข้อ = (ข้อ: string) =>
  [...document.querySelectorAll<HTMLElement>('.pk-ตัวบท [data-ข้อ]')].filter((x) => x.getAttribute('data-ข้อ') === ข้อ)
function จดที่อ่านก่อนเต็มจอ() {
  ที่อ่านก่อนเต็มจอ = null
  const ขอบ = ขอบล่างแถบหนึบ()
  for (const e of document.querySelectorAll<HTMLElement>('.pk-ตัวบท [data-ข้อ]')) {
    const r = e.getBoundingClientRect()
    if (r.height > 0 && r.bottom > ขอบ) {
      const ข้อ = e.getAttribute('data-ข้อ') || ''
      ที่อ่านก่อนเต็มจอ = { ข้อ, ที่: กล่องของข้อ(ข้อ).indexOf(e), บน: r.top }
      return
    }
  }
}
function กลับไปที่อ่านก่อนเต็มจอ() {
  const ท = ที่อ่านก่อนเต็มจอ
  ที่อ่านก่อนเต็มจอ = null
  if (!ท?.ข้อ) return
  /** ที่เลื่อนที่เราเพิ่งสั่ง ⇒ หน้าเลื่อนไปที่อื่นที่ไม่ใช่ค่านี้ = มีคนอื่นสั่ง (ผู้อ่านหรือโค้ดส่วนอื่น) ⇒ ปล่อย */
  let ที่ตั้งใจ = -1
  const ดึงกลับ = () => {
    const ทุก = กล่องของข้อ(ท.ข้อ)
    const e = ทุก[ท.ที่]?.getClientRects().length ? ทุก[ท.ที่] : ทุก.find((x) => x.getClientRects().length > 0)
    if (!e) return
    const ห่าง = e.getBoundingClientRect().top - ท.บน
    if (Math.abs(ห่าง) > 1) จำที่เลื่อนแล้วเลื่อน(window.scrollY + ห่าง)
    ที่ตั้งใจ = window.scrollY
  }
  // ⭐ รอหน้าวาดเสร็จ 2 เฟรม ⇒ แผงถูกถอดแล้ว · ตัวจัดแถวคำจัดของที่เปลี่ยนแล้ว ⇒ ⛔ วัดจังหวะกลางทาง
  requestAnimationFrame(() => requestAnimationFrame(ดึงกลับ))
  // ⭐⭐ ใบ #153 ⇒ **ยึดข้อนั้นไว้ต่ออีกครู่จนกว่าผู้อ่านขยับเอง** ⇒ ท่าเดียวกับ `ที่ยึด` ข้างบน
  //   ⇒ หน้าเทียบติ๊กฉบับใหม่ ⇒ ตัวบทของฉบับนั้นโหลดมาถึง **หลัง** ปิดหน้า ⇒ แถวข้างบนสูงขึ้น ⇒ ข้อที่อ่านไหลลง
  //     ⇒ วัดเองที่จอ 375 ⇒ ติ๊ก THKJV แล้วปิดทันที ⇒ ข้อ 2:12 ไหลจาก 151 ไป 224 ⇒ ดึงครั้งเดียวไม่พอ
  //   ⇒ หน้าเปลี่ยนความสูงเมื่อไร ⇒ ดึงกลับอีก ⇒ ปล่อยเมื่อผู้อ่านแตะ เลื่อน กดแป้น · หน้าเลื่อนไปที่ที่เรา ⛔ ได้สั่ง · หรือครบ 3 วินาที
  //     ⇒ ⛔ ดึงจอขัดผู้อ่าน หรือขัดโค้ดส่วนอื่นที่พาไปข้ออื่น
  if (typeof ResizeObserver === 'undefined') return
  let รอเฟรม = 0
  const ตัวเฝ้า = new ResizeObserver(() => {
    cancelAnimationFrame(รอเฟรม)
    รอเฟรม = requestAnimationFrame(ดึงกลับ)
  })
  ตัวเฝ้า.observe(document.body)
  const ชนิดที่ปล่อย = ['wheel', 'touchstart', 'pointerdown', 'keydown'] as const
  const ดูการเลื่อน = () => {
    if (ที่ตั้งใจ >= 0 && Math.abs(window.scrollY - ที่ตั้งใจ) > 2) ปล่อย()
  }
  const ปล่อย = () => {
    ตัวเฝ้า.disconnect()
    cancelAnimationFrame(รอเฟรม)
    clearTimeout(หมดเวลา)
    for (const ช of ชนิดที่ปล่อย) window.removeEventListener(ช, ปล่อย, true)
    window.removeEventListener('scroll', ดูการเลื่อน)
  }
  const หมดเวลา = setTimeout(ปล่อย, 3000)
  for (const ช of ชนิดที่ปล่อย) window.addEventListener(ช, ปล่อย, { capture: true, passive: true })
  window.addEventListener('scroll', ดูการเลื่อน, { passive: true })
}

// ⭐ ตัวดักติดอยู่ **เฉพาะตอนเมนูกางอยู่** ⇒ ปิดแล้วถอดทิ้ง ⛔ ไม่ค้างไว้กินแรงเครื่อง
watch(เมนูที่กาง, (ค่า, เดิม) => {
  if (import.meta.server) return
  if (ค่า && !เดิม && จอแคบ.value) จดที่อ่านก่อนเต็มจอ()
  else if (!ค่า && เดิม) void nextTick(กลับไปที่อ่านก่อนเต็มจอ)
  // ⭐ สลับจากเมนูหนึ่งไปอีกเมนูตรง ๆ ⇒ ตัวเฝ้าขนาดยังเกาะเมนูเก่าที่หายไปแล้ว ⇒ ถอดก่อนเสมอ
  เลิกเฝ้าขนาดเมนู()
  if (ค่า) {
    จัดที่เมนู()
    document.addEventListener('pointerdown', กดที่ไหนบนหน้า, true)
    document.addEventListener('keydown', กดปุ่มบนแป้น)
    // ⭐ จอเปลี่ยนขนาดตอนเมนูกางอยู่ ⇒ ต้องวัดระยะเลื่อนใหม่ ⛔ ไม่ใช้ค่าเดิมที่วัดไว้ตอนเปิด
    window.addEventListener('resize', จัดที่เมนู)
  } else {
    document.removeEventListener('pointerdown', กดที่ไหนบนหน้า, true)
    document.removeEventListener('keydown', กดปุ่มบนแป้น)
    window.removeEventListener('resize', จัดที่เมนู)
    เลิกเฝ้าขนาดเมนู()
    เลื่อนเมนู.value = 0
  }
})

// ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154 ⇒ กล่องเฟืองกับ i บนจอแคบเป็นหน้าเต็มจอ ⇒ ปิดแล้วกลับข้อที่อ่านค้างเหมือน Aa กับ เทียบ
//   ⇒ ข้างในเปลี่ยนสัญลักษณ์กาลหรือเครื่องหมายได้ ⇒ คำกรีกข้างหลังจัดแถวใหม่ ⇒ ข้อที่อ่านไหล ⇒ ตัวพากลับชุดเดียวกัน
//   ⇒ สลับจากกล่องหนึ่งไปอีกกล่องตรง ๆ ⇒ ยังถือข้อที่จดตอนเปิดกล่องแรก
watch(กล่องคำเดิม, (ค่า, เดิม) => {
  if (import.meta.server) return
  if (ค่า && !เดิม && จอแคบ.value) จดที่อ่านก่อนเต็มจอ()
  else if (!ค่า && เดิม) void nextTick(กลับไปที่อ่านก่อนเต็มจอ)
})

// ---------------------------------------------------------------- ตอนหน้าติดแล้ว
// ---------------------------------------------------------------- แตะข้อเพื่อเลือก แล้วแชร์ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/139)
// ⭐ กติกาการแตะ แป้นพิมพ์ และเหตุผล ⇒ `app/composables/เลือกข้อ.ts` · ข้อความที่ส่ง ⇒ `app/utils/แชร์ข้อ.ts` ⛔ ไม่จดซ้ำที่นี่
// ⭐ ใบ #159 ⇒ บอกเล่มของหน้า ⇒ ข้อในคอลัมน์คนละตอนที่อยู่เล่มเดียวกับหน้าได้กุญแจเดียวกับข้อในตาราง
const เลือก = ใช้การเลือกข้อ(() => บทที่แสดง.value[0]?.แถว[0]?.กุญแจ ?? '', รหัสเล่ม)
// ⭐ ข้อที่เลือกเปลี่ยน ⇒ นับเชิงอรรถของข้อที่เลือกใหม่ ⇒ ปุ่ม *เชิงอรรถ* ในแถบโผล่หรือหาย ⇒ ⛔ ย้ายขึ้นไปก่อน `เลือก` (ตัวแปรยังไม่เกิด)
watch(() => เลือก.ที่เลือก.value, หาเชิงอรรถของข้อที่เลือก, { deep: true, flush: 'post' })
/** ⭐ กล่องของข้อในคอลัมน์ไหนถือจุดหยุด Tab ⇒ คอลัมน์ที่อ่านอยู่บนจอแคบทีละฉบับ ⇒ ไม่งั้นคอลัมน์แรก */
function ถือTabได้(ฉ: string) {
  return ฉ === (ฉบับที่กำลังดู.value || ฉบับที่แสดง.value[0])
}
/**
 * ⭐⭐ **ข้อในคอลัมน์คนละตอนเลือกได้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/159)
 *   ⇒ ⚠️ ของเดิม ⇒ `เนื้อตอนเทียบ.vue` ⛔ มีที่รับการแตะข้อ ⇒ แตะแล้วเงียบ ⇒ คัดลอกและแชร์จากคอลัมน์นั้นไม่ได้
 *   ⇒ ของที่ติดบนกล่องของข้อ ⇒ ตัวเดียวกับคอลัมน์ในตาราง (`เลือก.ของข้อ`) ⇒ หน้าตา แป้นพิมพ์ และเสียงเหมือนกัน
 *   ⇒ `กล่องตัวเอง` ⇒ กล่องที่เลื่อนเองนอกตัวบท ⇒ ถือจุดหยุด Tab ของตัวเอง 1 จุด
 *     ⇒ ⛔ (บนล่างจอแคบ แทรกในตัวบท) ⇒ ⛔ ถือ ⇒ ท่าเดียวกับคอลัมน์ในตารางที่ไม่ใช่คอลัมน์ที่อ่านอยู่
 *   ⇒ คอลัมน์คำภาษาเดิม ⇒ ⛔ ส่ง ⇒ คำยังเป็นปุ่มเปิดการ์ด (หัวข้อ *แตะข้อเลือกได้เลย* ข้อ 4.1)
 */
function ตัวเลือกของเทียบ(ต: ก้อนเทียบ, กล่องตัวเอง: boolean) {
  if (ต.คำเดิม) return undefined
  const แรก = ต.แถว.find((x) => x.ชิ้น.length)
  // ⭐ ใบ #161 ⇒ คอลัมน์ฉบับเดียวกันเล่มเดียวกันตัวที่ 2 ขึ้นไป ⇒ กุญแจแยกด้วยลำดับซ้ำ (`นับซ้ำ`)
  const ซ้ำ = ซ้ำของเทียบ.value[คอลัมน์เทียบที่แสดง.value.indexOf(ต)] ?? 1
  const ที่ = { เล่ม: ต.เล่ม, ข้อแรก: แรก ? `${แรก.บท}:${แรก.เลข}` : '', ซ้ำ }
  return (บท: number, เลข: string, ท่อนแรก: boolean) =>
    เลือก.ของข้อ(`${บท}:${เลข}`, ต.ฉบับ, กล่องตัวเอง && ท่อนแรก, ที่)
}
// ⭐⭐ **เนื้อของบทที่มีข้อถูกเลือก ⇒ ถือไว้เองจนเลิกเลือก**
//   ⇒ `บทที่หยิบมา` ทิ้งบทที่เลื่อนพ้นไปไกล (`เก็บกวาดเนื้อที่ไกล`) ⇒ เลือกบท 1 แล้วเลื่อนไปบท 9 ตัวบทของบท 1 ต้องยังอยู่
//   ⇒ และกดแชร์แล้ว ⛔ ต้องรอโหลดอะไร ⇒ Safari เปิดเมนูแชร์ได้เฉพาะตอนที่ยังนับว่าคนเพิ่งกด
const เนื้อที่เลือก = shallowRef<Record<number, ผลบท>>({})
/** ⭐ ใบ #159 ⇒ เนื้อบทของเล่มอื่นที่มีข้อถูกเลือกในคอลัมน์คนละตอน ⇒ กุญแจ `เล่ม/บท` ⇒ ถือไว้แม้คอลัมน์ย้ายไปบทอื่นแล้ว */
const เนื้อเทียบที่เลือก = shallowRef<Record<string, ผลบท>>({})
const เครดิตฉบับ = shallowRef<Record<string, { สัญญา: string; ลิงก์สัญญา: string; เครดิต: string }> | null>(null)
watch(
  () => เลือก.ที่เลือก.value,
  async (กุญแจ) => {
    // ⭐ ใบ #159 ⇒ ข้อของเล่มหน้า (`เล่ม` ว่าง) ⇒ ท่าเดิม · ข้อของเล่มอื่น ⇒ ถือแยกใน `เนื้อเทียบที่เลือก`
    const ชิ้น = กุญแจ.map(แยกชิ้น)
    const บทอื่น = new Set(ชิ้น.filter((x) => x.เล่ม).map((x) => `${x.เล่ม}/${Number(x.ข้อ.split(':')[0])}`))
    const เก็บอื่น: Record<string, ผลบท> = {}
    for (const k of บทอื่น) if (เนื้อเทียบที่เลือก.value[k]) เก็บอื่น[k] = เนื้อเทียบที่เลือก.value[k]!
    เนื้อเทียบที่เลือก.value = เก็บอื่น
    for (const k of บทอื่น) {
      if (เนื้อเทียบที่เลือก.value[k]) continue
      const ของ =
        เนื้อของเทียบ.value[k] ??
        (await $fetch<ผลบท>(ที่อยู่หลังบ้าน(`api/chapter/${k}.json`)).catch(() => null))
      if (ของ) เนื้อเทียบที่เลือก.value = { ...เนื้อเทียบที่เลือก.value, [k]: ของ }
    }
    const บท = new Set(ชิ้น.filter((x) => !x.เล่ม).map((x) => Number(x.ข้อ.split(':')[0])))
    // ⭐ เลิกเลือกหมดบทแล้ว ⇒ ปล่อยเนื้อบทนั้น
    const เก็บ: Record<number, ผลบท> = {}
    for (const c of บท) if (เนื้อที่เลือก.value[c]) เก็บ[c] = เนื้อที่เลือก.value[c]!
    เนื้อที่เลือก.value = เก็บ
    for (const c of บท) {
      if (เนื้อที่เลือก.value[c]) continue
      const ของ =
        บทที่หยิบมา.value[`${รหัสเล่ม}/${c}`] ??
        (await $fetch<ผลบท>(ที่อยู่หลังบ้าน(`api/chapter/${รหัสเล่ม}/${c}.json`)).catch(() => null))
      if (ของ) เนื้อที่เลือก.value = { ...เนื้อที่เลือก.value, [c]: ของ }
    }
    // ⭐ เครดิตหยิบครั้งเดียว ตอนเริ่มเลือกข้อแรก ⇒ คนที่ ⛔ ไม่เลือกข้อ ⛔ ไม่ต้องโหลด
    if (กุญแจ.length && !เครดิตฉบับ.value) {
      เครดิตฉบับ.value = await $fetch<typeof เครดิตฉบับ.value>(ที่อยู่หลังบ้าน('api/credits.json')).catch(() => null)
    }
  },
)

/**
 * ⭐⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/159 ⇒ ชิ้นนี้เป็นของคอลัมน์ไหน ⇒ ลำดับจากซ้ายไปขวา ⇒ −1 = ⛔ มีคอลัมน์ที่วาดมันอยู่
 *   ⇒ ข้อของเล่มหน้า ⇒ คอลัมน์ในตารางของฉบับนั้นก่อน ⇒ ไม่มี ⇒ คอลัมน์คนละตอนของฉบับนั้น (เล่มเดียวกันก่อน)
 *   ⇒ ข้อของเล่มอื่น ⇒ คอลัมน์คนละตอนของฉบับนั้นเท่านั้น ⇒ ⭐ คอลัมน์เลื่อนไปบทอื่นแล้ว ⇒ ชิ้นยังเป็นของมัน (ท่าเดียวกับตารางที่เลื่อนพ้นบทแล้วการเลือกยังอยู่)
 *   ⇒ ⛔ คอลัมน์คำภาษาเดิม ⇒ ⛔ มีข้อให้เลือก (หัวข้อ *แตะข้อเลือกได้เลย* ข้อ 4.1)
 */
function คอลัมน์ของชิ้น(ฉบับ: string, เล่ม: string, ซ้ำ = 1): number {
  const กี่ = ฉบับที่แสดง.value.length
  const เทียบ = คอลัมน์เทียบที่แสดง.value
  const ล = เล่ม || รหัสเล่ม
  // ⭐ ใบ #161 ⇒ ฉบับเดียวกันตัวที่ 2 ขึ้นไป ⇒ คอลัมน์ตอนอื่นที่ลำดับซ้ำตรงกันเท่านั้น ⇒ ⛔ ตกไปเป็นของคอลัมน์ตัวแรก
  if (ซ้ำ > 1) {
    const j = เทียบ.findIndex((ต, k) => !ต.คำเดิม && ต.ฉบับ === ฉบับ && ต.เล่ม === ล && ซ้ำของเทียบ.value[k] === ซ้ำ)
    return j < 0 ? -1 : กี่ + j
  }
  if (!เล่ม) {
    const i = ฉบับที่แสดง.value.indexOf(ฉบับ)
    if (i >= 0) return i
  }
  let j = เทียบ.findIndex((ต, k) => !ต.คำเดิม && ต.ฉบับ === ฉบับ && ต.เล่ม === ล && ซ้ำของเทียบ.value[k] === 1)
  if (j < 0) j = เทียบ.findIndex((ต) => !ต.คำเดิม && ต.ฉบับ === ฉบับ)
  return j < 0 ? -1 : กี่ + j
}

/**
 * ⭐⭐ **ชิ้นที่เลือก ⇒ ฉบับ + บท + ข้อ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/148)
 *   ⇒ นับเฉพาะชิ้นของคอลัมน์คำแปลที่เปิดอยู่ ⇒ ปิดคอลัมน์แล้วชิ้นของมัน ⛔ ไม่ถูกนับ ⛔ ไม่ถูกส่ง ⇒ ของที่ส่งตรงกับที่เห็น
 *   ⇒ เรียงตามคอลัมน์จากซ้ายไปขวา แล้วบท แล้วข้อ
 *   ⇒ ⭐ ใบ #159 ⇒ ชิ้นมีเล่มด้วย ⇒ คอลัมน์คนละตอนนับเป็นคอลัมน์ต่อท้ายตาราง (`คอลัมน์ของชิ้น`)
 */
const ชิ้นที่เลือก = computed<(ข้อที่จะแชร์ & { ฉบับ: string; ช่อง: number; ซ้ำ: number })[]>(() => {
  const ลำดับเล่ม = ['', ...คอลัมน์เทียบที่แสดง.value.map((ต) => (ต.เล่ม === รหัสเล่ม ? '' : ต.เล่ม))]
  const ที่เล่ม = (ล: string) => (ลำดับเล่ม.includes(ล) ? ลำดับเล่ม.indexOf(ล) : ลำดับเล่ม.length)
  return เลือก.ที่เลือก.value
    .map((k) => {
      const { ฉบับ: ฉในกุญแจ, เล่ม, ข้อ } = แยกชิ้น(k)
      const { ฉบับ, ซ้ำ } = แยกฉบับซ้ำ(ฉในกุญแจ)
      const [บท, เลข] = ข้อ.split(':')
      return { ฉบับ, ซ้ำ, ...(เล่ม ? { เล่ม } : {}), บท: Number(บท), เลข: เลข || '', ช่อง: คอลัมน์ของชิ้น(ฉบับ, เล่ม, ซ้ำ) }
    })
    .filter((x) => x.ช่อง >= 0)
    .sort(
      (a, b) =>
        a.ช่อง - b.ช่อง ||
        ที่เล่ม(a.เล่ม || '') - ที่เล่ม(b.เล่ม || '') ||
        a.บท - b.บท ||
        Number(a.เลข) - Number(b.เลข),
    )
})
/**
 * ข้อที่มีชิ้นถูกเลือกอย่างน้อย 1 ฉบับ ⇒ บรรทัดอ้างอิงของข้อความที่ส่ง ⇒ เรียงตามบทแล้วข้อ
 * ⭐ **ตัวเลขบนแถบนับและปุ่มแชร์นับจากตัวนี้** ⇒ ข้อเดียวกันเลือกหลายคอลัมน์ ⇒ นับ 1
 *   ⇒ พี่เอมเคาะ 7 พ.ย. 2569 *"นับตามจำนวนข้อจริง ถ้าซ้ำก็นับ 1"* (ใบ #148)
 */
const ข้อที่จะแชร์ = computed<ข้อที่จะแชร์[]>(() => {
  // ⭐ ใบ #159 ⇒ *ข้อเดียวกัน* = เล่ม บท และข้อเดียวกัน ⇒ มาระโก 13:31 กับยอห์น 13:31 เป็นคนละข้อ ⇒ นับ 2
  const เห็น = new Set<string>()
  const ลำดับเล่ม = ['']
  for (const x of ชิ้นที่เลือก.value) if (!ลำดับเล่ม.includes(x.เล่ม || '')) ลำดับเล่ม.push(x.เล่ม || '')
  return ชิ้นที่เลือก.value
    .filter((x) => {
      const k = `${x.เล่ม || ''}|${x.บท}:${x.เลข}`
      if (เห็น.has(k)) return false
      เห็น.add(k)
      return true
    })
    .map((x) => ({ บท: x.บท, เลข: x.เลข, ...(x.เล่ม ? { เล่ม: x.เล่ม } : {}) }))
    .sort(
      (a, b) =>
        ลำดับเล่ม.indexOf(a.เล่ม || '') - ลำดับเล่ม.indexOf(b.เล่ม || '') ||
        a.บท - b.บท ||
        Number(a.เลข) - Number(b.เลข),
    )
})

/** ⭐ ข้อความที่ส่ง ⇒ ประกอบตอนกดเท่านั้น ⇒ ไม่เลือก = ทั้งหน้า (ข้อ 5) · เลือก = เฉพาะชิ้นที่เลือก (ข้อ 6 · ใบ #148 ข้อ 3) */
async function ข้อความที่จะแชร์(): Promise<string> {
  const ต้น = location.origin
  if (!ข้อที่จะแชร์.value.length) {
    const c = บทที่อ่านอยู่.value
    const v = c === บทของข้อที่พาไป.value ? ข้อที่พาไป.value : null
    // ⭐ ใบ #94 ⇒ ฉบับแรกเป็นตัวบทภาษาเดิม ⇒ `c` `v` เป็นเลขเดิม ⇒ ตัวเดียวกับ `ปรับที่อยู่`
    const ที่ = จุดในที่อยู่(c, v)
    return ประกอบข้อความหน้า(
      ชื่อที่อ่านอยู่.value,
      ถ้อยคำแชร์.ชื่อเว็บ,
      ต้น + ที่อยู่หน้าอ่าน(รหัสเล่ม, ที่.บท, ที่.ข้อ, คอลัมน์เทียบที่เปิด.value, ช่วงที่ฟัง.value, ฉบับในที่อยู่.value),
    )
  }
  // ⛔ เครดิตยังโหลดไม่เสร็จ ⇒ รอ ⇒ ⛔ ห้ามส่งตัวบทออกไปโดยไม่มีเครดิตที่เจ้าของบังคับ
  if (!เครดิตฉบับ.value) {
    เครดิตฉบับ.value = await $fetch<typeof เครดิตฉบับ.value>(ที่อยู่หลังบ้าน('api/credits.json')).catch(() => null)
  }
  const ชิ้น = ชิ้นที่เลือก.value
  // ⭐ ใบ #148 ข้อ 3 ⇒ เฉพาะฉบับที่มีชิ้นถูกเลือก ⇒ ฉบับที่ไม่ได้เลือก ⛔ ไม่ติดไป ทั้งตัวบทและเครดิต
  //   ⇒ ⭐ ใบ #159 ⇒ ฉบับของคอลัมน์คนละตอนนับด้วย ⇒ เรียงตามคอลัมน์จากซ้ายไปขวา (`ชิ้นที่เลือก` เรียงไว้แล้ว)
  const ฉบับที่ส่ง = [...new Set(ชิ้น.map((x) => x.ฉบับ))]
  const เทียบ = คอลัมน์เทียบที่แสดง.value
  const ชื่อเล่มอื่น: Record<string, string> = {}
  for (const x of ชิ้น)
    if (x.เล่ม) ชื่อเล่มอื่น[x.เล่ม] = เล่มของเทียบ.value[x.เล่ม]?.เล่ม.ชื่อไทย || ชื่อเล่มอื่น[x.เล่ม] || x.เล่ม
  // ⭐ ใบ #159 ⇒ คอลัมน์คนละตอนที่มีข้อถูกเลือก ⇒ พกไปในลิงก์ (`p`) ที่ข้อแรกที่เลือก ⇒ คนรับเห็นเส้นใต้ในคอลัมน์นั้น
  const เทียบที่ส่ง: คอลัมน์เทียบ[] = []
  /** ⭐ ใบ #161 ⇒ คอลัมน์ตอนอื่นของคนส่ง (ลำดับในหน้า) ⇒ ลำดับใน `เทียบที่ส่ง` */
  const ที่ในที่ส่ง = new Map<number, number>()
  เทียบ.forEach((ต, i) => {
    const แรก = ชิ้น.find((x) => x.ช่อง === ฉบับที่แสดง.value.length + i)
    if (!แรก) return
    ที่ในที่ส่ง.set(i, เทียบที่ส่ง.length)
    เทียบที่ส่ง.push({ เล่ม: แรก.เล่ม || รหัสเล่ม, บท: แรก.บท, ฉบับ: ต.ฉบับ, ข้อ: Number(แรก.เลข) })
  })
  // ⭐ ใบ #161 ⇒ ลำดับซ้ำนับใหม่ตามหน้าของคนรับ ⇒ ลิงก์พกเฉพาะคอลัมน์ตอนอื่นที่มีข้อถูกเลือก ⇒ ลำดับของคนส่งอาจไม่ตรง
  const ซ้ำของที่ส่ง = นับซ้ำ(ฉบับในที่อยู่.value, เทียบที่ส่ง)
  const ซ้ำของชิ้น = (x: (typeof ชิ้น)[number]) => {
    const j = ที่ในที่ส่ง.get(x.ช่อง - ฉบับที่แสดง.value.length)
    return j === undefined ? 1 : (ซ้ำของที่ส่ง[j] ?? 1)
  }
  // ⭐ เขียน `~n` เฉพาะฉบับที่หน้าของคนรับมีหลายคอลัมน์ในเล่มเดียวกัน (ตัวแรกก็ `~1`) ⇒ ท่อนที่ ⛔ มี `~` เป็นของทุกคอลัมน์ฉบับนั้น (ลิงก์เก่า)
  const มีซ้ำ = (x: (typeof ชิ้น)[number]) => {
    const ล = x.เล่ม || รหัสเล่ม
    const ในตาราง = ล === รหัสเล่ม && ฉบับในที่อยู่.value.includes(x.ฉบับ) ? 1 : 0
    return ในตาราง + เทียบที่ส่ง.filter((ค) => ค.ฉบับ === x.ฉบับ && ค.เล่ม === ล).length > 1
  }
  return ประกอบข้อความข้อ(
    เล่มนี้.value.ชื่อไทย,
    ข้อที่จะแชร์.value,
    ฉบับที่ส่ง.map((ฉ): ฉบับที่จะแชร์ => {
      const ชื่อ = แหล่งของชั้น.value[ฉ] || เทียบ.find((ต) => ต.ฉบับ === ฉ)?.ชื่อฉบับ || ฉ
      const ค = เครดิตฉบับ.value?.[ชื่อ]
      return {
        ชื่อ,
        // ⭐ ใบ #161 ⇒ ข้อเดียวกันเลือกไว้ใน 2 คอลัมน์ฉบับเดียวกัน ⇒ ตัวบทเหมือนกันทุกตัวอักษร ⇒ ส่งครั้งเดียว
        ข้อ: ชิ้น
          .filter((x, k) => x.ฉบับ === ฉ && ชิ้น.findIndex((y) => y.ฉบับ === ฉ && y.เล่ม === x.เล่ม && y.บท === x.บท && y.เลข === x.เลข) === k)
          .map((x) => ({ บท: x.บท, เลข: x.เลข, ...(x.เล่ม ? { เล่ม: x.เล่ม } : {}) })),
        เนื้อ: (บท: number, เลข: string, เล่ม: string) =>
          (เล่ม
            ? (เนื้อเทียบที่เลือก.value[`${เล่ม}/${บท}`] ?? เนื้อของเทียบ.value[`${เล่ม}/${บท}`])
            : (เนื้อที่เลือก.value[บท] ?? บทที่หยิบมา.value[`${รหัสเล่ม}/${บท}`])
          )?.ชั้น[ฉ]?.[เลข] || '',
        สัญญา: ค?.สัญญา || '',
        ลิงก์สัญญา: ค?.ลิงก์สัญญา || '',
        // ⭐ หยิบเครดิตไม่สำเร็จ ⇒ ชี้ไปหน้าแหล่งข้อมูลที่มีเครดิตเต็ม ⇒ ⛔ ไม่ส่งตัวบทเปล่า ๆ
        เครดิต: ค ? ค.เครดิต : ต้น + ที่อยู่หน้าแหล่งข้อมูล(),
      }
    }),
    ถ้อยคำแชร์.หัวที่มา,
    ต้น +
      ที่อยู่ข้อที่แชร์(
        รหัสเล่ม,
        ชิ้น.map((x) => ({
          บท: x.บท,
          ข้อ: Number(x.เลข),
          ฉบับ: x.ฉบับ,
          ...(x.เล่ม ? { เล่ม: x.เล่ม } : {}),
          ...(มีซ้ำ(x) ? { ซ้ำ: ซ้ำของชิ้น(x) } : {}),
        })),
        ฉบับในที่อยู่.value,
        เทียบที่ส่ง,
        {
          บท: บทที่อ่านอยู่.value,
          ข้อ: บทที่อ่านอยู่.value === บทของข้อที่พาไป.value ? ข้อที่พาไป.value : null,
        },
        // ⭐ ใบ #94 ⇒ `c` `v` ของลิงก์ ⇒ ตัวเดียวกับ `ปรับที่อยู่` ⇒ ฉบับแรกเป็นตัวบทภาษาเดิมแล้วเป็นเลขเดิม
        (บท, ข้อ) => จุดในที่อยู่(บท, ข้อ),
      ),
    ชื่อเล่มอื่น,
  )
}

onMounted(async () => {
  // ⭐⭐ **`?t=TCV,LSV` คือฉบับของตาราง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 13)
  //   ⇒ ที่อยู่มี `t` ⇒ ใช้ตามที่อยู่ ⇒ คนที่ได้ลิงก์เห็นคอลัมน์เหมือนคนส่ง ⇒ ⛔ ไม่เขียนทับความชอบที่จำไว้ในเครื่อง
  //   ⇒ ไม่มี `t` (ลิงก์เก่า · เปิดเว็บเฉย ๆ) ⇒ ใช้ฉบับที่ผู้อ่านจำไว้เหมือนเดิม ⇒ ลิงก์เก่ายังเปิดได้
  // ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 5 ⇒ `t=SBLGNT` ⇒ ตารางเหลือแต่คำภาษาเดิม ⇒ ดู `ฉบับของตารางจากที่อยู่`
  const จากที่อยู่ = ฉบับของตารางจากที่อยู่(route.query['t'])
  const ฉบับจากที่อยู่ = จากที่อยู่.ฉบับ
  const มีtในที่อยู่ = จากที่อยู่.มี
  มุม.value = อ่านมุมมอง()
  // ⭐ ไม่มี `t` ⇒ ความชอบในเครื่อง ⇒ ใบ #145 ⇒ คนที่ปิดฉบับแปลหมดเหลือแต่คำเดิม ⇒ เปิดเว็บใหม่ได้แบบเดิม ⛔ ไม่เด้งกลับเป็น TCV
  ฉบับที่เลือก.value = มีtในที่อยู่ ? ฉบับจากที่อยู่ : อ่านฉบับที่เลือก(ฉบับที่มี.value, มุม.value.ภาษาเดิม)
  // ⭐ ใบ #145 ทาง ข. ⇒ คำเดิมจากลิงก์เป็นของการเปิดครั้งนี้ ⇒ ⛔ เขียนลงความชอบในเครื่อง ⇒ จดค่าเดิมไว้ให้ `watch(มุม)` ใช้แทน
  if (จากที่อยู่.คำเดิม && !มุม.value.ภาษาเดิม) ภาษาเดิมของเครื่อง = false
  if (จากที่อยู่.คำเดิม) มุม.value = { ...มุม.value, ภาษาเดิม: true }
  // ⭐ ก้อน ข. ⇒ ลำดับของคำเดิม ⇒ ลิงก์บอก ⇒ ใช้ลิงก์ · ⛔ บอก ⇒ ที่ที่เครื่องจำไว้ (ตั้งต้น 1 = ขวาติดคอลัมน์แรกแบบก่อนใบ #145)
  ที่คำเดิม.value = จากที่อยู่.คำเดิม ? จากที่อยู่.ที่ : อ่านที่คำเดิม()

  // ⭐ ฟังการเปลี่ยนความกว้างจอ **ด้วย `matchMedia`** ⛔ ไม่ใช่ `resize` แล้วมาเทียบตัวเลขเอง
  //   ⇒ เทียบเลขเองแล้วเลขในโค้ดกับเลขใน CSS จะแยกกันเดินโดยไม่มีใครรู้
  ตัววัดจอ = window.matchMedia('(min-width: 768px)')
  ทานความกว้างจอ()
  // ⭐ ตัวฟังการเปลี่ยนจอ ⇒ ติดหลังอ่านคอลัมน์ตอนอื่นจากที่อยู่แล้ว (ข้างล่าง) ⇒ ⛔ ไม่ให้ตัดเพดานจอแคบก่อนรู้ว่ามีกี่คอลัมน์
  await nextTick()
  บอกความสูงแถบบน()
