  // ⭐ **`?s=12.1-3.TCV,12.2.LSV` คือข้อที่คนส่งเลือกไว้ พร้อมฉบับ** (ใบ #139 ข้อ 9 · ใบ #148 ข้อ 5) ⇒ เส้นใต้ขึ้นที่คอลัมน์ที่ส่งมา ⇒ `c` `v` พาไปข้อแรก
  //   ⇒ ⭐ **ลิงก์เก่าก่อนใบ #148 (`s=12.1-3` ไม่มีฉบับ)** ⇒ ให้เป็นของทุกคอลัมน์คำแปลที่เปิด ⇒ เห็นเหมือนก่อนใบ #148 (ข้อ 6)
