  const ฉบับเทียบตอนเปิด = คอลัมน์เทียบที่เปิด.value.map((ค) => ({ ฉบับ: ฉบับของเทียบ(ค), เล่ม: ค.เล่ม }))
  const ซ้ำตอนเปิด = นับซ้ำ(ฉบับที่แสดง.value, ฉบับเทียบตอนเปิด)
  เลือก.ตั้ง(
    อ่านข้อที่แชร์(route.query['s']).flatMap((x) => {
