    if (ไม้บรรทัด.value) ตัวเฝ้าที่ว่าง.observe(ไม้บรรทัด.value)
    // ⭐ ใบ #131 note_30367 ⇒ ไม้บรรทัดของเส้นซ้ายขวา ⇒ ตัวเฝ้าของตัวเอง ⇒ วัดใหม่อย่างเดียว ⛔ ไม่ตัดคอลัมน์
