  void document.fonts?.ready.then(() => วัดที่ว่าง())

  const cดิบ = Number(route.query['c'])
  const vดิบ = Number(route.query['v'])
  const มีจุดในที่อยู่ = (Number.isFinite(cดิบ) && cดิบ > 0) || (Number.isFinite(vดิบ) && vดิบ > 0)
  // ⭐ ใบ #94 ⇒ ฉบับแรกของ `t` เป็นตัวบทภาษาเดิม ⇒ `c` `v` เป็นเลขเดิม ⇒ แปลงเป็นข้อแปลที่อยู่แถวเดียวกันด้วยตาราง `ข้อแปล`
