  //   ⇒ ⛔ กางไม่ได้ (บทในช่วงไม่มีในเล่มนี้) ⇒ ทิ้งช่วงเงียบ ๆ ⇒ ตกกลับเป็นแบบเลือกแค่ข้อเริ่ม ⛔ ไม่ใช่หน้าว่าง
  const ช่วงจากที่อยู่ = ช่วงที่ฟัง.value
