  รวมคอลัมน์ที่ตรงแถว(บทของคอลัมน์แรก(), มีจุดในที่อยู่ ? (Number.isFinite(v) && v > 0 ? v : 1) : undefined)
  if (คอลัมน์เทียบที่เปิด.value.length !== ก่อนรวม || ตัดตอนเปิด) ปรับที่อยู่()
  else if (!route.query['t'] && เขียนฉบับในที่อยู่(ฉบับในที่อยู่.value, คอลัมน์เทียบที่เปิด.value.length > 0))
