  //   ⇒ จึงเขียนซ้ำ 1 ครั้งหลังการเปลี่ยนเส้นทางครั้งถัดไปของหน้าเดียวกัน ⇒ ยังเป็น `replaceState` ⇒ ⛔ ไม่เพิ่มช่องถอยหลัง
