      เลิกฟังเส้นทาง = undefined
      if (ไป.path === ทางของหน้า) void nextTick(ปรับที่อยู่)
    })
  }

  // ⛔ **เพิ่งเปิดหน้ามา ⇒ ยังไม่ต่อบทก่อนหน้า** — ตัวจัดการหน้าของ Nuxt ยังเลื่อนหน้าเองอยู่
  พักการต่อขึ้น()
  ที่เลื่อนล่าสุด = window.scrollY
  window.addEventListener('scroll', ตอนเลื่อน, { passive: true })
  window.addEventListener('resize', ตอนปรับขนาดจอ, { passive: true })
  // ⭐ ผู้อ่านขยับเอง ⇒ เลิกยึดที่อ่านค้าง (ใบ #112) ⇒ ฟังของที่มาจากมือผู้อ่านเท่านั้น ⛔ ไม่ใช่ `scroll` ที่หน้าเลื่อนเองก็เกิดได้
  for (const ชื่อ of ['wheel', 'touchstart', 'keydown', 'pointerdown'] as const)
    window.addEventListener(ชื่อ, ปล่อยที่ยึด, { passive: true, capture: true })
  // ⭐ วัดข้อบนจอครั้งแรก ⇒ ⛔ ไม่รอให้ผู้อ่านเลื่อนก่อน ⇒ เปิดหน้ามาตรงช่วงที่มีเรื่องเล่าก็เห็นปุ่มทันที
  await nextTick()
  วัดข้อบนจอ()
  // ⭐ ใบ #149 ⇒ `?w=` ⇒ เปิดการ์ดของคำที่แชร์มา ⇒ ไม่มี `w` (ลิงก์เก่าทุกแบบ) ⇒ ⛔ ไม่มีอะไรเปลี่ยน
  const คำจากที่อยู่ = อ่านคำที่แชร์(route.query['w'])
  if (คำจากที่อยู่) void เปิดการ์ดจากที่อยู่(คำจากที่อยู่)
})

onBeforeUnmount(() => {
  ตัวเล่นเรื่อง?.ปิด()
  window.removeEventListener('scroll', ตอนเลื่อน)
  window.removeEventListener('resize', ตอนปรับขนาดจอ)
  for (const ชื่อ of ['wheel', 'touchstart', 'keydown', 'pointerdown'] as const)
    window.removeEventListener(ชื่อ, ปล่อยที่ยึด, { capture: true })
  window.removeEventListener('popstate', ตอนถอยหลัง)
  clearTimeout(ตัวนับขอต่อขึ้น)
  clearTimeout(ตัวนับไฟส่อง)
  ตัววัดจอ?.removeEventListener('change', ตอนจอเปลี่ยน)
  ตัวเฝ้าที่ว่าง?.disconnect()
  ตัวเฝ้าไม้บรรทัดซ้ายขวา?.disconnect()
  ตัวเฝ้าแถบล่าง?.disconnect()
  เลิกฟังเส้นทาง?.()
  ตัวเฝ้าแถบ?.disconnect()
  ตัวเฝ้าฝั่งหลัก?.disconnect()
  // ⛔ ออกจากหน้าไปตอนเมนูยังกางอยู่ ⇒ ตัวดักของเมนูจะค้างอยู่บน `document` ตลอดไป
  document.removeEventListener('pointerdown', กดที่ไหนบนหน้า, true)
  document.removeEventListener('keydown', กดปุ่มบนแป้น)
  window.removeEventListener('resize', จัดที่เมนู)
  เลิกเฝ้าขนาดเมนู()
})

function ทานความกว้างจอ() {
  จอแคบ.value = !!ตัววัดจอ && !ตัววัดจอ.matches
}
/** ⭐ จอข้ามเส้น 768 หรือที่ว่างเปลี่ยน ⇒ เกินเพดาน ⇒ ตัดเหลือเท่าเพดาน ⇒ ที่อยู่เขียนทับช่องเดิม ⇒ กว้างขึ้น ⇒ ⛔ ไม่คืนคอลัมน์ที่ปิดไป */
function ตอนจอเปลี่ยน() {
  ทานความกว้างจอ()
  วัดที่ว่าง()
  if (ตัดให้พอจอแคบ()) ปรับที่อยู่()
}

/**
 * ⭐⭐ **ลิงก์ที่เปิดคำภาษาเดิม (`t=SBLGNT` · `t=WLC`) ⛔ เขียนลงความชอบในเครื่อง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ⇒ พี่เอมเลือกทาง ข.)
 *   ⇒ ลิงก์คือ *ที่ที่กำลังอ่าน* ⛔ ไม่ใช่ *ความชอบ* ⇒ กติกาเดียวกับฉบับแปลจาก `t` (ใบ #125 ข้อ 13) ⇒ เปิดเว็บครั้งหน้าได้แบบที่ตัวเองตั้งไว้
 *   ⇒ ⚠️ ของเดิม (ก้อน ก. ถึง ง.) ⇒ เปิดลิงก์แล้วความชอบ *เปิดคำภาษาเดิม* ถูกเขียนเป็นเปิดเงียบ ๆ
 *   ⇒ ค่าที่จดไว้ใช้จนผู้อ่านปิดคำเดิมเอง ⇒ หลังจากนั้นทุกการเปิดปิดเป็นของผู้อ่าน ⇒ จำตามปกติ
 *   ⇒ ⭐ ค่าอื่นในมุมมอง (การจัดวาง · แสดงเลข ฯลฯ) ⇒ ยังจำตามปกติทุกตัว
 */
let ภาษาเดิมของเครื่อง: boolean | null = null
watch(
  มุม,
  (ค่า) => {
    if (ภาษาเดิมของเครื่อง !== null && !ค่า.ภาษาเดิม) ภาษาเดิมของเครื่อง = null
    จำมุมมอง(ภาษาเดิมของเครื่อง === null ? ค่า : { ...ค่า, ภาษาเดิม: ภาษาเดิมของเครื่อง })
  },
  { deep: true },
)

// ⭐⭐ **เปิดปุ่มภาษาเดิมเมื่อไร ⇒ หยิบคำของ *บทที่กางอยู่* เท่านั้น** (ใบงาน #95)
//   ⇒ เลื่อนอ่านต่อไปบทถัดไป ตัวนี้วิ่งอีกรอบเอง เพราะ `บทที่แสดง` เปลี่ยน
//   ⛔ **ปิดปุ่มแล้ว ⛔ ไม่หยิบอะไรอีก** ⇒ ของที่หยิบมาแล้วค้างไว้ได้ ⇒ เปิดซ้ำจะได้ ⛔ ไม่ต้องโหลดใหม่
//   ⇒ ⭐ หยิบบทข้างเคียงด้วยข้างละบท ⇒ เหตุผลอยู่ที่ `บทเดิมที่ต้องหยิบ` (ใบ #104 · ใบ #112)
watch(
  [() => มุม.value.ภาษาเดิม, บทเดิมที่ต้องหยิบ],
  ([เปิด, บททั้งหมด]) => {
    // ⭐ ปิดชั้นคำ ⇒ การ์ดปิดตาม ⇒ ⛔ ไม่ค้างการ์ดของคำที่ไม่อยู่บนหน้าแล้ว
    if (!เปิด) คำที่เปิด.value = null
    if (!เปิด) return
    ชั้นคำพัง.value = ''
    for (const c of บททั้งหมด) void หยิบชั้นคำ(c)
  },
  { immediate: true },
)

// WCAG SC 2.4.2 (ระดับ A) — ทุกหน้ามีชื่อที่บอกว่าเป็นหน้าอะไร
useHead({
  title: () => `${ชื่อที่อ่านอยู่.value} — อ่านพระคัมภีร์`,
})
</script>

<template>
  <!-- ⭐⭐ **จำนวนคอลัมน์อยู่ที่ตัวหน้าอ่าน ⛔ ไม่ใช่แค่กล่องคอลัมน์** (ใบงาน #102 ข้อ 8)
         ⇒ ทั้งหน้า (แถบบน · คอลัมน์ · แถบล่าง) กว้างตามจำนวนคอลัมน์ ⇒ ใช้ด้านข้างที่เหลือ
         ⇒ `--pk-กี่ช่องหลัก` = น้ำหนักของฝั่งที่อยู่ที่เดียวกับหน้า ตอนแบ่งความกว้างกับตอนที่เอามาเทียบ
         ⇒ กฎความกว้างทั้งหมดอยู่ที่ `main.css` ⛔ ไม่จดซ้ำที่นี่ -->
  <article
    v-if="บท"
    class="pk-เนื้อ pk-หน้าอ่าน pk-ม้วน"
    :class="{ 'pk-มีการ์ด': !!คำที่เปิด, 'pk-ซ่อนตัวเดิม': !มุม.แสดงตัวเดิม, 'pk-จุดคั่นคำ': !มุม.แสดงตัวเดิม && มุม.จุดคั่นคำ }"
    :style="{ '--pk-กี่ฉบับ': กี่คอลัมน์ทั้งหน้า, '--pk-กี่ช่องหลัก': กี่ช่องฝั่งหลัก }"
  >
    <!-- ================= ① แถบบน — บาง หนึบอยู่กับขอบบน =================
         ⛔ **คลาส `pk-แถบเครื่องมือ` ขาดไม่ได้** — ด่าน `ด่านเลือกฉบับ.mjs` รอปุ่มตัวแรกในแถบนี้
         ⭐ ทุกปุ่ม **มีข้อความกำกับ ⛔ ไม่ใช่รูปเปล่า ๆ** ⇒ ผู้อ่านอายุ 55 ขึ้นไปเดารูปไม่ออก -->
    <!-- ⛔ ชื่อแท็กต้องเป็นตัวอักษรอังกฤษ ⇒ ชื่อชิ้นส่วนภาษาไทยต้องผ่าน `<component :is>` -->
    <!-- ⛔ **หน้าอ่านของเล่ม ⛔ ไม่ส่ง `หน้านี้`** ⇒ หัวเมนู *อ่านพระคัมภีร์* ต้องยังเป็นลิงก์
           ⇒ มันชี้ไปหน้าสารบัญ ซึ่งเป็นคนละหน้ากับหน้านี้ -->
    <!-- ⭐⭐ **แผงเลือกพระธรรมเป็นของแถบนำทาง** ⇒ หน้านี้ส่ง 2 อย่างให้มัน
           ① สถานะว่ากางอยู่ไหม ⇒ เพราะหน้านี้มีปุ่มเปิดของตัวเองอีก 2 ปุ่ม
           ② **ตัวรับผลของตัวเอง** ⇒ เลือกบทในเล่มเดียวกันคือ **เลื่อนในหน้าเดิม** (ใบงาน #73)
              ⇒ ⛔ ไม่ส่งข้อนี้ = กดเลือกบทแล้ว **โหลดหน้าใหม่ทั้งหน้า** ซึ่งผิดหลักของใบนั้น -->
    <component
      :is="แถบนำทาง"
      มีเครื่องมือ
      :เปิดแผง="เปิดหน้าต่างเล่ม"
      :เมื่อเลือก="รับผลจากแผง"
      :เลือกช่วงได้="แผงเลือกช่วงได้"
      :เริ่มเป็นช่วง="แผงเลือกช่วงได้ && !!ช่วงที่ฟัง"
      @เปิดแผง="เปิดแผงให้(null)"
      @ปิดแผง="เปิดหน้าต่างเล่ม = false"
    >
        <!-- ⭐⭐ **ปุ่ม *เลือกบท* กับ *ฉบับ* ถูกถอดจากแถบบนแล้ว** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/102 ข้อ 6.2)
               ⇒ สองอย่างนั้นย้ายไปอยู่ในหัวของทุกคอลัมน์ ⇒ ⛔ ห้ามของอย่างเดียวกันมี 2 ที่
               ⇒ แถบบนเหลือแค่ของที่คุม *ทั้งหน้า* ⇒ ⭐ **ใบ #131 note_30332 ข้อ 2 ⇒ 2 ปุ่มทุกจอ ⇒ *เทียบ* · *Aa***
                 ⇒ ของเดิม (ใบ #102) ⇒ เทียบ · ปรับหน้าจอ · ก− ขนาด ก+ ⇒ ปรับหน้าจอกับขนาดตัวอักษรรวมเข้า Aa แล้ว
               ⇒ ⭐ แถบบนของจอมือถือจึงเตี้ยลง ⛔ ไม่สูงขึ้น (ข้อ 6.3) ⇒ จอ 320 ถึง 412 ปุ่มขึ้นแถวเดียวกับชื่อเว็บ
                 ⇒ ตัวเฝ้าคือ `tools/ด่านปุ่มAa.mjs` ⇒ ตัวเลขที่วัดอยู่ในคำขอรวมของใบ #131 -->

        <!-- ② เทียบ ⇒ **ปุ่ม *เพิ่มคอลัมน์* กับการวางคอลัมน์** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161)
               ⇒ เปลี่ยนเล่ม บท และฉบับ อยู่ที่หัวของคอลัมน์นั้นเอง ⇒ ปิดด้วย × บนหัว ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9) ช่องติ๊กของทุกฉบับ
             ⭐⭐ **คำบนปุ่มคือ *เทียบ* ⛔ ไม่ใช่ *คอลัมน์*** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/113)
               ⇒ ของในเมนูทั้ง 2 อย่างคือการเทียบ ⇒ ฉบับอื่น · คำภาษาเดิม ⇒ ⛔ ไม่มีอันไหนเป็นการเลือกเล่ม
                 ⇒ ของเดิมมี 3 อย่าง ⇒ *ตอนอื่น* ถูกถอดแล้ว (ใบ #131 ข้อ 9.6) ⇒ เปลี่ยนตอนที่หัวคอลัมน์แทน
               ⇒ *คอลัมน์* เป็นคำของคนทำเว็บ ⛔ ไม่ใช่คำของคนอ่าน ⇒ Nielsen ข้อ 2 · คำบนปุ่มบอกว่ากดแล้วได้อะไร ⇒ WCAG 2.2 SC 2.4.6
               ⇒ ⛔ ไม่ใช่ *เลือกเล่ม* ⇒ ซ้ำกับงานของปุ่ม *เปลี่ยนตอน* ⇒ Nielsen ข้อ 4
             ⛔ **ชื่อที่โปรแกรมอ่านหน้าจอได้ยิน = คำที่ตาเห็นตรงตัว** ⇒ ⛔ ห้ามเติม `aria-label` ทับ ⇒ SC 2.5.3
               ⇒ ด่านหลายตัวกดปุ่มนี้ด้วยชื่อ *เทียบ* แบบตรงตัว ⇒ ท่าอยู่ที่ `ปุ่มเทียบของหน้า` ใน `tools/หน้าที่ตรวจ.mjs` -->
        <div ref="กล่องฉบับ" class="pk-กล่องเมนู">
          <Button
            id="pk-ปุ่มเทียบ"
            type="button"
            class="pk-ปุ่มแถบ"
            aria-haspopup="true"
            :aria-expanded="เมนูที่กาง === 'ฉบับ'"
            :aria-controls="เมนูที่กาง === 'ฉบับ' ? 'pk-แผงเทียบ' : undefined"
            @click="สลับเมนู('ฉบับ')"
          >
            เทียบ
          </Button>
          <!-- ⭐⭐ **กล่องเด้งแบบเดียวกับ Aa และแชร์** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/153 เกณฑ์ข้อ 1)
                 ⇒ จอแคบกว่า 768 ⇒ หน้าเต็มจอใต้แถบบน · จอกว้าง ⇒ แผงใต้ปุ่มที่เดิม ⇒ × มุมขวาบนกับ Escape ปิด ⇒ โฟกัสกลับปุ่ม *เทียบ*
                 ⇒ ⛔ ไม่มีหัวที่ตาเห็น (⛔ คำใหม่) ⇒ ชื่อกลุ่มที่ได้ยินมาจากปุ่ม *เทียบ* (`aria-labelledby`) ⇒ ⭐ ใบ #161 ⇒ ปุ่ม *เพิ่มคอลัมน์* อยู่ใต้ × ⇒ ⚠️ ของเดิมเป็นหัวกลุ่ม *ฉบับที่เปิดเทียบ* -->
          <component
            :is="กล่องเด้ง"
            v-if="เมนูที่กาง === 'ฉบับ'"
            id="pk-แผงเทียบ"
            class="pk-เมนู"
            role="group"
            aria-labelledby="pk-ปุ่มเทียบ"
            :เต็มจอ="จอแคบ"
            :style="สไตล์เมนู"
            @ปิด="ปิดเมนู(true)"
          >
            <!-- ⭐⭐ **ปุ่ม *เพิ่มคอลัมน์* ปุ่มเดียว แบบ Bible Gateway** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/161 เกณฑ์ข้อ 7 · 9)
                   ⇒ กดแล้วได้คอลัมน์ใหม่ทันที ⇒ ฉบับและตอนเดียวกับคอลัมน์แรก ⇒ เลือกฉบับที่ช่องเลือกฉบับบนหัวคอลัมน์นั้น
                   ⇒ ⚠️ ของเดิม (ใบ #131 ข้อ 9) ⇒ ช่องติ๊กของทุกฉบับกับช่องติ๊กคำภาษาเดิม ⇒ ถอดแล้ว ⇒ เหตุผลอยู่หัวหัวข้อ *ปุ่มเพิ่มคอลัมน์* ในสคริปต์
                 ⛔ **ชื่อที่โปรแกรมอ่านหน้าจอได้ยิน = คำที่ตาเห็นตรงตัว** ⇒ ⛔ `aria-label` ⇒ WCAG 2.2 SC 2.5.3 ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำเมนูเทียบ.ts`
                 ⭐ **เต็มแล้วยังกดได้** ⇒ `aria-disabled` ⛔ `disabled` ⇒ กดแล้วข้อความเดิมขึ้นใต้ปุ่มในกล่อง `role="status"` (เกณฑ์ข้อ 8 ⇒ SC 4.1.3)
                   ⇒ กล่องอยู่ในหน้าตลอดแม้ยังว่าง ⇒ โปรแกรมอ่านหน้าจอเฝ้ากล่องที่มีอยู่ก่อนเท่านั้น ⇒ ใส่ข้อความทีหลังจึงถูกอ่าน
                 ⭐ `data-ปุ่ม="เพิ่มคอลัมน์"` ⇒ ด่านหาปุ่มด้วยชื่อที่ได้ยิน ⇒ ท่าอยู่ที่ `tools/หน้าที่ตรวจ.mjs` -->
            <Button
              type="button"
              class="pk-ปุ่มแถบ pk-ปุ่มเพิ่มคอลัมน์"
              data-ปุ่ม="เพิ่มคอลัมน์"
              :aria-disabled="ครบเพดาน ? 'true' : undefined"
              :aria-describedby="ข้อความเต็ม ? 'pk-เหตุเพดานจอแคบ' : undefined"
              @click="กดเพิ่มคอลัมน์"
            >
              {{ ถ้อยคำเมนูเทียบ.เพิ่มคอลัมน์ }}
            </Button>
            <p id="pk-เหตุเพดานจอแคบ" class="pk-หมายเหตุเมนู pk-เหตุเต็ม" role="status">{{ ข้อความเต็ม }}</p>

            <!-- ⭐ จอแคบ + เลือกไว้เกิน 1 ฉบับ ⇒ ต้องเลือกได้ว่า **จะวางยังไง** และ **จะอ่านฉบับไหน**
                 ⛔ ไม่โผล่บนจอกว้าง เพราะจอกว้างวางเคียงกันอยู่แล้ว ⇒ ปุ่มนี้จะไม่มีผลอะไร
                 ⭐ **อยู่ในเมนู `เทียบ` ⛔ ไม่ใช่แผง `ปรับหน้าจอ`** ⇒ มันคุม *คอลัมน์ฉบับที่เปิดไว้*
                   ⇒ วางไว้ติดของที่มันคุม ⇒ WCAG 2.2 SC 1.3.1 Info and Relationships (ระดับ A)
                   ⇒ เมนูนี้คือเมนู `ฉบับ` เดิมที่เปลี่ยนชื่อ (ใบ #102) ⇒ ⛔ ไม่ได้ตั้งที่ใหม่ของตัวเอง -->
            <template v-if="จอแคบ && กี่คอลัมน์ข้างกัน > 1">
              <hr />
              <!-- ⭐⭐ **ตัวเลือกเดียว 3 ทาง** ⇒ ซ้ายขวา · บนล่าง · ทีละฉบับ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30367 ข้อ 3)
                     ⇒ กลุ่มเดิมของใบ #97 ⇒ ⛔ ไม่เพิ่มปุ่มใหม่ ⇒ ⛔ ไม่ใช่ช่องกรอกจำนวนคอลัมน์
                     ⇒ โผล่เมื่อมีมากกว่า 1 คอลัมน์ ⇒ นับคอลัมน์คนละเล่มคนละบทด้วย ⇒ กติกาเดียวทุกคอลัมน์ (ข้อ 5)
                   ⭐ `<fieldset>` + `<legend>` ⇒ โปรแกรมอ่านหน้าจออ่านชื่อกลุ่มก่อนชื่อปุ่ม ⇒ WCAG 2.2 SC 1.3.1 ⇒ ท่าเดียวกับกลุ่มช่องฉบับข้างบน
                   ⭐ **เว็บวางบนล่างเอง ⇒ ปุ่มกลม *ซ้ายขวา* ยังติ๊กอยู่** ⇒ ค่าที่ผู้อ่านเลือก ⛔ ถูกเขียนทับ
                     ⇒ ตัวหนังสือใต้ปุ่มบอกว่าตอนนี้วางแบบไหนและทำไม ⇒ ผูกกับปุ่มกลมนั้นด้วย `aria-describedby` (ข้อ 4)
                     ⇒ ⛔ ไม่ล็อกปุ่ม ⇒ ผู้อ่านยังเลือกบนล่างหรือทีละฉบับเองได้ทุกเมื่อ ⇒ Nielsen ข้อ 3
                   ⛔ คำบนจอ ⛔ มีลูกศร ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำการวางจอแคบ.ts` -->
              <fieldset class="pk-กลุ่มเมนู" data-กลุ่ม="วางคอลัมน์">
                <legend class="pk-หัวเมนู">{{ ถ้อยคำการวางจอแคบ.หัว }}</legend>
                <label v-for="ว in การวางจอแคบที่มี" :key="`วาง-${ว}`" class="pk-ช่องติ๊ก">
                  <input
                    type="radio"
                    name="วางคอลัมน์"
                    :value="ว"
                    :checked="มุม.วางคอลัมน์ === ว"
                    :aria-describedby="
                      ว === 'ซ้ายขวา' && วางบนล่างเอง
                        ? 'pk-เหตุวางบนล่าง'
                        : ว === 'ซ้ายขวา' && ย่อให้ซ้ายขวา
                          ? 'pk-เหตุย่อซ้ายขวา'
                          : undefined
                    "
                    @change="มุม.วางคอลัมน์ = ว"
                  />
                  <span>{{ ถ้อยคำการวางจอแคบ.ชื่อ[ว] }}</span>
                </label>
                <p v-if="วางบนล่างเอง" id="pk-เหตุวางบนล่าง" class="pk-หมายเหตุเมนู">
                  {{ ถ้อยคำการวางจอแคบ.เหตุวางบนล่างเอง }}
                </p>
                <!-- ⭐ 20 พ.ย. 2569 ⇒ ซ้ายขวาที่หน้าย่อตัวหนังสือให้ ⇒ ที่เดียวกับเหตุผลของบนล่าง ⇒ ผูกกับปุ่มกลมซ้ายขวาเหมือนกัน -->
                <p v-else-if="ย่อให้ซ้ายขวา" id="pk-เหตุย่อซ้ายขวา" class="pk-หมายเหตุเมนู">
                  {{ ถ้อยคำการวางจอแคบ.เหตุย่อซ้ายขวา }}
                </p>
              </fieldset>

              <!-- ⛔ **เลือกคอลัมน์ที่จะอ่าน มีความหมายเฉพาะตอน *ทีละฉบับ*** ⇒ ซ้ายขวากับบนล่างเห็นครบอยู่แล้ว
                     ⭐ ใบ #131 note_30367 ข้อ 5 ⇒ คอลัมน์คนละเล่มคนละบทเลือกอ่านได้ด้วย ⇒ ⚠️ ของเดิมมันไปต่อท้ายใต้คอลัมน์แรกเสมอ -->
              <template v-if="ทีละฉบับอยู่">
                <hr />
                <!-- ⭐ ใบ #145 ก้อน ข. ⇒ เรียงตามลำดับจริงของตาราง ⇒ คำเดิมอยู่ตำแหน่งของมัน -->
                <template v-for="ฉ in ลำดับตาราง" :key="`ดู-${ฉ}`">
                <label v-if="ฉ !== คำเดิมในลำดับ" class="pk-ช่องติ๊ก">
                  <input
                    type="radio"
                    name="ดูฉบับ"
                    :checked="ที่ดูอยู่ === ฉ"
                    @change="ดูฉบับ(ฉ)"
                  />
                  <span>{{ ป้ายอ่านฉบับ(ฉ, คอลัมน์เทียบที่แสดง.length ? ป้ายที่ของหน้า : '') }}</span>
                </label>
                <!-- ⭐ ใบ #131 note_30490 ⇒ คำภาษาเดิมเลือกอ่านได้เหมือนฉบับ ⇒ ลำดับเดียวกับที่วางคอลัมน์ ⇒ ป้ายทรงเดียวกับฉบับ *อ่าน SBLGNT* -->
                <label v-else-if="หัวคำเดิม.ตัวบท" class="pk-ช่องติ๊ก">
                  <input
                    type="radio"
                    name="ดูฉบับ"
                    data-ดู="คำเดิม"
                    :checked="ที่ดูอยู่ === ดูคำเดิม"
                    @change="ดูฉบับ(ดูคำเดิม)"
                  />
                  <span>{{ ป้ายอ่านฉบับ(หัวคำเดิม.ตัวบท, คอลัมน์เทียบที่แสดง.length ? ป้ายที่ของหน้า : '') }}</span>
                </label>
                </template>
                <label v-for="(ต, i) in คอลัมน์เทียบที่แสดง" :key="`ดูเทียบ-${i}`" class="pk-ช่องติ๊ก">
                  <input
                    type="radio"
                    name="ดูฉบับ"
                    :checked="ที่ดูอยู่ === `เทียบ:${i}`"
                    @change="ดูฉบับ(`เทียบ:${i}`)"
                  />
                  <span>{{ ป้ายอ่านฉบับ(ต.ฉบับ, `${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท}`) }}</span>
                </label>
              </template>
            </template>

            <!-- ⛔⛔ **ไม่มี *เทียบตอนอื่น · เปิดอีกตอนมาวางข้างกัน* แล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 ข้อ 9.6)
                   ⇒ พี่เอมเลือกเอง 1 พ.ย. 2569 *"เทียบตอนอื่นไม่ควรมีแล้ว"* ⇒ ตั้งแต่ใบ #125 ทุกคอลัมน์เปลี่ยนเล่มและบทของตัวเองได้
                     ⇒ อยากเทียบตอนอื่น ⇒ ⭐ ใบ #161 ⇒ กด *เพิ่มคอลัมน์* ⇒ แล้วกดชื่อเล่มที่หัวคอลัมน์ใหม่ ⇒ ฉบับเดียวกันได้หลายคอลัมน์แล้ว ⇒ ⚠️ ของเดิม 1 ฉบับได้ 1 คอลัมน์ (ข้อ 6.3)
                   ⇒ ⭐ **ลิงก์เก่าที่มีคอลัมน์ตอนอื่น (`p=`) ยังเปิดได้ครบ** ⇒ ตัวอ่านที่อยู่ ⛔ ไม่ถูกแตะ ⇒ ตัวเฝ้าคือ `tools/ด่านคอลัมน์คนละที่.mjs` -->
          </component>
        </div>

        <!-- ⑥ แชร์ ⇒ **อยู่แถวบนสุดตลอด ⛔ ไม่ต้องเลือกอะไรก่อน** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/139 ข้อ 1)
               ⇒ ไม่เลือกข้อ = แชร์ทั้งหน้า · เลือกแล้ว = แชร์เฉพาะข้อ ⇒ หน้าตาและเหตุผลอยู่ที่ `ปุ่มแชร์.vue`
             ⚠️ ของเดิม ⇒ ท้ายแถบหลัง Aa ⇒ ใบ #173 ⇒ เรียงตามเว็บเพลง ⇒ ค้นหา · แชร์ · Aa · เมนู ⇒ *เทียบ* ยังเป็นปุ่มตัวแรกในแถบ (`tools/ด่านเลือกฉบับ.mjs` รอตัวนั้น)
             ⭐ ใบ #173 ⇒ ส่งผ่านช่อง `#แชร์` ⇒ แถบวางไว้หลัง *ค้นหา* ก่อน *Aa* ทุกหน้า ⇒ หน้านี้ส่งตัวที่รู้จักข้อที่เลือก ⇒ แถบ ⛔ วางปุ่มแชร์ของตัวเองซ้อน -->
        <template #แชร์>
          <component :is="ปุ่มแชร์" :จำนวน="ข้อที่จะแชร์.length" :ข้อความ="ข้อความที่จะแชร์" />
        </template>

        <!-- ③ Aa ⇒ **ขนาดตัวอักษร · การจัดวาง · แสดงผล อยู่ในแผงเดียว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30332 ข้อ 2)
               ⇒ ⚠️ ของเดิม ⇒ ปุ่ม *ปรับหน้าจอ* (การจัดวาง · แสดงผล) กับ ก− ขนาด ก+ วางเปล่าบนแถบ (ใบ #65)
                 ⇒ จอ 320 ถึง 412 ปุ่มพวกนี้ตกลงไปแถวที่ 2 ใต้ชื่อเว็บ ⇒ แถบหนึบสูง 108 ถึง 187 จุด ⇒ กินที่อ่าน
               ⇒ ท่าเดียวกับแอปอ่านหนังสือ (Apple Books · Kindle) ⇒ Nielsen ข้อ 4 ⇒ พี่เอมเคาะ 2 พ.ย. 2569
             ⭐ **ทรง WAI-ARIA APG Disclosure** ⇒ ปุ่มบอกสถานะด้วย `aria-expanded` ⇒ `aria-controls` ชี้แผงตอนกาง
               ⇒ ⛔ ไม่มี `aria-haspopup` ⇒ แผงนี้ ⛔ ไม่ใช่ `role="menu"` ⇒ ใส่แล้วโปรแกรมอ่านหน้าจอบอกผิดว่าเป็นเมนู (N ตรวจ ⇒ SC 4.1.2)
               ⇒ กดนอกแผง · Escape ⇒ ปิดแล้วคืนโฟกัสให้ปุ่ม ⇒ ใช้ตัวดักชุดเดียวกับเมนู *เทียบ* ⇒ ตัวเฝ้าคือ `tools/ด่านเมนูปรับหน้าจอ.mjs`
             ⭐ **ตาเห็น *Aa* ⇒ ชื่อที่ได้ยิน *Aa ปรับตัวอักษรและหน้าจอ*** ⇒ SC 2.5.3 ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำแผงAa.ts`
             ⛔ **ห้ามซ่อนในเมนูขีด 3 ขีด** ⇒ ปุ่ม *เทียบ* ก็ยังเป็นตัวหนังสือ ⇒ เหตุผลอยู่ที่ `แถบนำทาง.vue`
             ⭐ `ref="กล่องหน้าจอ"` กับชื่อเมนู `'หน้าจอ'` คงเดิม ⇒ ตัวดักทั้งชุดใช้ชื่อนี้
             ⭐⭐ **ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/173 ⇒ ปุ่มกับแผงยกไปเป็น `ปุ่มAa.vue` ⇒ ชิ้นเดียวกับแถบบนของทุกหน้า**
               ⇒ ปุ่ม · หัวแผง · ก− ขนาด ก+ อยู่ในชิ้นนั้น ⇒ หน้านี้ส่งแค่ *การจัดวาง · แสดงผล* ลงแผงทางช่องว่าง ⇒ คำ คลาส ไอดี เดิมทุกตัว
               ⇒ ส่งผ่านช่อง `#Aa` ของแถบ ⇒ แถบวางที่เดิมของทุกหน้า (ค้นหา · แชร์ · Aa · เมนู) ⇒ ⛔ แถบวาง Aa ของตัวเองซ้อนอีกชุด -->
        <template #Aa>
        <div ref="กล่องหน้าจอ" class="pk-กล่องเมนู">
          <component
            :is="ปุ่มAa"
            :เปิด="เมนูที่กาง === 'หน้าจอ'"
            :เต็มจอ="จอแคบ"
            :สไตล์แผง="สไตล์เมนู"
            @สลับ="สลับเมนู('หน้าจอ')"
            @ปิด="ปิดเมนู(true)"
          >

            <!-- ⑤ การจัดวาง · แสดงผล ⇒ ของในเมนู *ปรับหน้าจอ* เดิมทุกตัว ⛔ ไม่เปลี่ยนคำหรือลำดับ
                 ⇒ ยุบ "การจัดวาง" กับ "ตัวเลือกการแสดงผล" ของรุ่น 2 เข้าด้วยกัน -->
            <!-- ⛔⛔ **ทุกตัวเลือกในแผงนี้ต้องทำให้หน้าเปลี่ยนจริง** (ใบงาน v3/phrakham#76)
                 ⇒ ตัวเฝ้าคือ `tools/ด่านตัวเลือกเปลี่ยนหน้า.mjs` ⇒ เพิ่มตัวที่ไม่ทำอะไรเมื่อไร ด่านแดง
                 ⇒ ⭐ *แยกตามย่อหน้า* เคยถูกถอดออกด้วยเหตุนี้ และ **กลับมาแล้ว** (ใบ #98)
                    ⇒ **เหตุผลกับเงื่อนไขที่ตั้งไว้ อยู่ที่ `app/utils/มุมมอง.ts`** ⛔ ไม่จดซ้ำที่นี่ -->
            <!-- ⭐⭐ **เลือกการจัดวางได้เสมอ แม้เทียบหลายฉบับอยู่** (ใบงาน v3/phrakham#87)
                 ⛔ ของเดิมซ่อนกลุ่มนี้ตอนเลือกหลายฉบับ ⇒ แต่ค่าที่เว็บ *จำไว้* ยังเป็น
                    *ไหลต่อเนื่อง* ได้ ⇒ ผู้อ่านติ๊กฉบับที่สองเพิ่ม แล้วได้หน้าที่ตัวบทไทย
                    กับอังกฤษต่อกันเป็นประโยคเดียว **โดยที่ปิดตัวเลือกนั้นไปแล้ว**
                    (พี่เอมเปิดของจริงเจอ 8 ก.ย. 2569)
                 ⇒ ⭐ ทางแก้คือทำให้ *ไหลต่อเนื่อง* หมายถึง **ไหลอยู่ในฉบับของตัวเอง**
                    ⇒ ตอนนี้มันใช้ได้กับทุกจำนวนฉบับ ⇒ จึง ⛔ ไม่ต้องซ่อนอีกแล้ว -->
            <p class="pk-หัวเมนู">การจัดวาง</p>
            <label
              v-for="j in (['ไหลต่อเนื่อง', 'แยกตามข้อ', 'แยกตามย่อหน้า'] as const)"
              :key="j"
              class="pk-ช่องติ๊ก"
            >
              <input v-model="มุม.จัดวาง" type="radio" name="จัดวาง" :value="j" />
              <span>{{ j === 'แยกตามข้อ' ? 'แยกตามข้อ (เทียบบรรทัด)' : j }}</span>
            </label>
            <hr />
            <p class="pk-หัวเมนู">แสดงผล</p>
            <label class="pk-ช่องติ๊ก">
              <input v-model="มุม.แสดงเลข" type="checkbox" />
              <span>แสดงเลขบท/ข้อ</span>
            </label>
            <!-- ⭐ สวิตช์หัวข้อย่อย (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134) ⇒ คู่กับเลขบท/ข้อ ทรงเดียวกัน
                 ⇒ ช่องติ๊กจริง ⇒ โปรแกรมอ่านหน้าจอบอกสถานะติ๊กหรือไม่ติ๊กเอง (WCAG 2.2 SC 4.1.2)
                 ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำแผงAa.ts` พร้อมที่มา
                 ⇒ ⛔ บนหน้าไม่มีหัวข้อให้เปิดปิด ⇒ ⛔ ไม่วาด ⇒ เหตุผลอยู่ที่ `หัวข้อมีบนหน้า` ในสคริปต์ -->
            <label v-if="หัวข้อมีบนหน้า" class="pk-ช่องติ๊ก">
              <input v-model="มุม.หัวข้อย่อย" type="checkbox" data-สวิตช์="หัวข้อย่อย" />
              <span>{{ ถ้อยคำแผงAa.หัวข้อย่อย }}</span>
            </label>
            <!-- ⚠️ **สวิตช์ *แสดงตัวอักษรกรีก/ฮีบรู* ⛔ อยู่ในแผงนี้แล้ว** (พี่เอมขอ 17 พ.ย. 2569 ⇒ *"ควรอยู่ในเฟืองที่ heading ไม่ใช่ที่ตัว Aa"*)
                   ⇒ ของเดิม (คำขอรวม !243) ⇒ กลุ่ม *คำภาษาเดิม* ท้ายแผงนี้ ⇒ ตอนนี้อยู่บนสุดของกล่องเฟืองบนหัวคอลัมน์ภาษาเดิมทุกคอลัมน์ (`แถวปุ่มคำเดิม.vue`)
                   ⇒ ตัวเฝ้าคือ `tools/ด่านซ่อนตัวเดิม.mjs` ⇒ ข้อ ⑥ แดงถ้าสวิตช์กลับมาที่นี่ -->
            <!-- ⚠️ **หมวด *เครื่องมือภาษาเดิม* ถูกถอดจากหน้านี้แล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154 เกณฑ์ข้อ 5)
                   ⇒ ของเดิม (ใบ #151) ⇒ มือถือที่เปิดคอลัมน์คำกรีกมีหมวดนี้ท้ายแผง ⇒ ตอนนี้อยู่ที่ปุ่มรูปเฟืองบนหัวคอลัมน์ภาษาเดิมทุกจอ
                   ⇒ ของเดิมในแผงทุกตัวอยู่ที่เดิม ลำดับเดิม -->
          </component>
        </div>
        </template>

    </component>

    <!-- ================= ② ตัวบท =================
         ⭐ **คำโปรยย้ายไปอยู่หน้าแรกแล้ว** (พี่เอมเคาะ 11 ต.ค. 2569) ⇒ เจ้าของคือ `app/pages/index.vue`
           ⇒ ⛔ หน้าอ่าน ⛔ ไม่มีคำโปรยอีกแล้ว ⇒ เปิดหน้าอ่านมาคือเจอตัวบททันที -->
    <!-- ⭐ **ทุกอย่างที่ผู้อ่านอ่าน อยู่ในคอลัมน์เดียวกัน** ⇒ ขอบซ้ายตรงกันทั้งหน้า
         ⛔ ไม่ให้ตัวบทมีคอลัมน์ของตัวเองต่างหาก — ขอบซ้ายไม่ตรงกัน ตาจะสะดุดที่รอยต่อ -->
    <!-- ⭐ บอก CSS ว่ากำลังวางกี่ฉบับเทียบกัน ⇒ คอลัมน์อ่านจะได้กว้างพอ ⛔ ไม่บีบจนบรรทัดละ 2 คำ
         ⇒ วาดฉบับเดียว (จอแคบ หรือเลือกไว้ฉบับเดียว) = 1 เสมอ -->
    <!-- ⭐⭐ **เปิดชั้นคำ = มีอีก 1 คอลัมน์บนจอกว้าง** (คนตรวจ !102 ทัก ② · ใบงาน v3/phrakham#95)
           ⇒ `pk-มีชั้นคำ` เป็นสวิตช์ให้ไฟล์หน้าตาจัดคำเดิมเคียงคำแปล ⇒ เจ้าของกฎคือ `main.css`
           ⇒ และ **บวกเข้า `--pk-กี่ฉบับ` ด้วย** ⇒ ไม่งั้นคอลัมน์อ่านถูกผ่าครึ่งจนบรรทัดละ 2 คำ
             ⇒ วัดเองที่จอ 1280 ⇒ ⛔ ไม่บวก ได้คอลัมน์ละ **310 จุด** · บวกแล้วได้ **468 จุด**
           ⛔ **ไม่เช็ก `จอแคบ` ที่นี่** ⇒ บนจอแคบเพดานความกว้างกว้างกว่าจอ ⇒ ⛔ ไม่มีผลอยู่แล้ว
             ⇒ ของที่ตัดสินว่าเคียงหรือบนล่าง คือเส้น 768 จุดในไฟล์หน้าตา **ที่เดียว** -->
    <div
      class="pk-คอลัมน์"
      :class="{
        'pk-มีชั้นคำ': มุม.ภาษาเดิม,
        'pk-ขนานกันจอแคบ': ขนานกันอยู่,
        // ⭐ ใบ #131 note_30367 ⇒ แบบที่หน้าใช้จริงบนจอแคบ ⇒ กฎหน้าตาอยู่ที่ `main.css` หัวข้อ *การวางคอลัมน์บนจอแคบ*
        'pk-ซ้ายขวาจอแคบ': ซ้ายขวาอยู่,
        'pk-หัวเต็มแถว': หัวเต็มแถว,
        'pk-บนล่างจอแคบ': บนล่างอยู่,
        'pk-ทีละฉบับจอแคบ': ทีละฉบับอยู่,
        // ⭐ ใบ #131 note_30490 ⇒ คำภาษาเดิมเป็นคอลัมน์ของตัวเอง ⇒ กฎตารางของ `แถวคำเดิม.css` ผูกกับคลาสนี้ ⛔ ไม่ใช่เส้น 768 แล้ว
        'pk-คำเดิมเป็นคอลัมน์': คำเดิมเป็นคอลัมน์,
        'pk-หัวคำเดิมในแถว': หัวคำเดิมในแถว,
        // ⭐ ใบ #145 ⇒ เหลือแต่คำเดิม ⇒ หน้าตาเดียวกับเลือกอ่านคำเดิมของทีละฉบับ ⇒ คำเดิมเต็มกว้าง ⇒ ทุกจอ
        'pk-อ่านคำเดิม': ตารางเห็นแต่คำเดิม,
        'pk-เหลือแต่คำเดิม': เหลือแต่คำเดิม,
        // ⭐ ใบ #125 ข้อ 11 ⇒ ตารางมีฉบับมากกว่า 1 ⇒ คำภาษาเดิมแทรกขวาติดคอลัมน์แรก ⇒ กฎอยู่ที่ `แถวคำเดิม.css`
        //   ⇒ ⭐ ใบ #131 note_30490 ⇒ จอแคบซ้ายขวา ⇒ ช่องเลขข้อ 1 ช่อง แล้วช่องละ 1 ส่วนเท่ากันทุกคอลัมน์ ⇒ แม้มีฉบับเดียว
        //     ⇒ ไม้บรรทัดของ `ซ้ายขวาพอ` คิดแบบนี้อยู่แล้ว ⇒ ช่องตัวบทของทุกคอลัมน์ไม่แคบกว่า 6em ⇒ ⛔ ใช้เส้น 23em ของจอกว้าง
        'pk-มีฉบับอื่น':
          มุม.ภาษาเดิม &&
          (เหลือแต่คำเดิม ||
            (จอแคบ ? ซ้ายขวาอยู่ || ดูคำเดิมอยู่ : !กำลังแสดงฉบับเดียว && ฉบับที่แสดง.length > 1 && แทรกคำเดิมได้)),
        // ⭐ กรอบคู่ ⇒ เฉพาะตอนคอลัมน์แรกกับคำภาษาเดิมเป็นคู่ที่ติดกันจริง ⇒ ฉบับอื่นซ้อนอยู่ในช่องแรกเมื่อไร กรอบจะคลุมฉบับนั้นด้วย ⇒ ⛔ ไม่วาด
        //   ⇒ ⭐ ใบ #131 note_30490 ⇒ จอแคบ ⛔ วาด ⇒ คำภาษาเดิมเป็นคอลัมน์ธรรมดาเหมือนฉบับอื่น ⇒ กรอบกินที่ซ้ายขวาของจอแคบ
        'pk-คู่คำเดิม':
          มุม.ภาษาเดิม &&
          !จอแคบ &&
          !เหลือแต่คำเดิม &&
          ตำแหน่งคำเดิม === 1 &&
          // ⭐ ใบ #145 ข้อ 4 ⇒ คำเดิมเป็นช่องในตารางฉบับ ⇒ ⛔ เป็นคอลัมน์คู่ที่ติดกันแน่นอน ⇒ ⛔ วาด
          !คำเดิมในช่อง &&
          (กำลังแสดงฉบับเดียว || ฉบับที่แสดง.length <= 1 || แทรกคำเดิมได้),
        // ⭐ ใบ #145 ข้อ 4 ⇒ จอกว้างที่วางทุกคอลัมน์ข้างกันไม่พอ ⇒ คำเดิมเป็นช่องหนึ่งของตารางฉบับ ⇒ กฎอยู่ที่ `main.css`
        'pk-คำเดิมในช่อง': คำเดิมในช่อง,
        // ⭐ ใบ #145 ก้อน ข. ⇒ คำเดิมอยู่ซ้ายสุดของตาราง ⇒ ตารางสองช่องสลับข้าง (`แถวคำเดิม.css`)
        'pk-คำเดิมหน้าสุด': มุม.ภาษาเดิม && ตำแหน่งคำเดิม === 0 && !ตารางเห็นแต่คำเดิม,
      }"
      :data-ที่คำเดิม="มุม.ภาษาเดิม ? (ตารางเห็นแต่คำเดิม ? 1 : ตำแหน่งคำเดิม) : undefined"
      :data-ย่อ="ย่อให้ซ้ายขวา ? ย่อที่ใช้ : undefined"
      :style="ย่อให้ซ้ายขวา ? { '--pk-ย่อจอแคบ': String(ย่อที่ใช้) } : undefined"
    >
    <!-- ⭐ ไม้บรรทัดของเพดานคอลัมน์บนจอแคบ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30332 ข้อ 1)
           ⇒ ยาวเท่าความกว้างขั้นต่ำของ 1 คอลัมน์ ⇒ เป็น `em` ของตัวบท ⇒ ตัวอักษรใหญ่ขึ้นมันยาวขึ้นเอง ⇒ สคริปต์วัดมันไปหารที่ว่าง
           ⇒ สูง 0 ⇒ ⛔ ไม่กินที่ ⛔ ไม่มีอะไรให้ตาเห็นหรือหูได้ยิน ⇒ เลขอยู่ที่ `main.css` -->
    <div ref="ไม้บรรทัด" class="pk-ไม้บรรทัดคอลัมน์" aria-hidden="true" />
    <!-- ⭐ ไม้บรรทัดของเส้นตัดสินซ้ายขวา (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30367 ข้อ 4)
           ⇒ ช่องตัวบทขั้นต่ำที่คำไม่ขาด + ช่องไฟ 1 ช่อง · ช่องเลขข้อ ⇒ สคริปต์เทียบกับที่ว่างใน `ซ้ายขวาพอ` ⇒ เลขอยู่ที่ `main.css` -->
    <div ref="ไม้บรรทัดซ้ายขวา" class="pk-ไม้บรรทัดซ้ายขวา" aria-hidden="true" />
    <div ref="ไม้บรรทัดเลขข้อ" class="pk-ไม้บรรทัดเลขข้อ" aria-hidden="true" />
    <!-- ⭐ ตัวจัดแถวของคอลัมน์คำภาษาเดิม (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/112)
           ⇒ ก้อนโค้ดแยกที่ถือกฎหน้าตาของแถวกับตัวย่อแบบ *พอดี* ⇒ ⛔ ไม่วาดอะไรเอง
           ⇒ โหลดตอนเปิดคอลัมน์เท่านั้น ⇒ คนที่ ⛔ ไม่เปิด ⛔ ไม่จ่ายไบต์ของมัน (ข้อ 15) -->
    <component
      :is="ตัวจัดแถวคำ"
      v-if="มุม.ภาษาเดิม"
      :ขนาดคำ="มุม.ขนาดคำเดิม"
      :ขนาดตัวอักษร="ขนาด.เปอร์เซ็นต์.value * ย่อที่ใช้"
      :ตัวเดิม="มุม.แสดงตัวเดิม"
      :จุดคั่น="!มุม.แสดงตัวเดิม && มุม.จุดคั่นคำ"
      @พร้อม="ตัวจัดแถวพร้อม = true"
      @จัดแล้ว="คืนที่ยึด"
    />
    <!-- หัวเรื่องบอกว่ากำลังอ่านตอนไหน แต่ **หลบให้ตัวบท**
         ⇒ ของที่ตาเห็นคือหมุดเลขบทในเนื้อ ⛔ ไม่ใช่หัวเรื่องตัวโต ๆ ที่ซ้ำหน้าที่กัน -->
    <h1 class="pk-เฉพาะเสียง">{{ ชื่อที่อ่านอยู่ }}</h1>

    <p v-if="คำเตือน" class="pk-เตือน" role="alert">{{ คำเตือน }}</p>
    <!-- ⛔ หยิบคำภาษาเดิมไม่สำเร็จ ⇒ **บอกตรง ๆ** และตัวบทแปลยังอ่านต่อได้ ⛔ ห้ามเงียบ -->
    <p v-if="ชั้นคำพัง" class="pk-เตือน" role="alert">{{ ชั้นคำพัง }}</p>
    <!-- ⛔ เปิดตอนที่เอามาเทียบไม่ได้ ⇒ **บอกตรง ๆ** และตัวบทที่อ่านอยู่ยังอ่านต่อได้ ⛔ ห้ามเงียบ -->
    <p v-if="คอลัมน์เทียบพัง" class="pk-เตือน" role="alert">{{ คอลัมน์เทียบพัง }}</p>
    <p v-if="!ฉบับที่แสดง.length && !มุม.ภาษาเดิม" class="pk-เตือน">ยังไม่ได้เปิดฉบับไหนเลย ⇒ กดปุ่ม “คอลัมน์” แล้วเพิ่มอย่างน้อย 1 ฉบับ</p>

    <!-- ⭐ เนื้อเปลี่ยนเองเมื่อผู้อ่านกดตัวเลือก ⇒ ต้องบอกโปรแกรมอ่านหน้าจอ
         ⇒ WCAG SC 4.1.3 Status Messages (ระดับ AA) -->
    <p class="pk-เฉพาะเสียง" role="status" aria-live="polite">
      {{ กำลังโหลด ? 'กำลังโหลด' : `${ชื่อที่อ่านอยู่} · ${จำนวนข้อ} ข้อ` }}
    </p>

    <!-- ================= ③ ตัวบท — พระเอกของหน้า =================
         ⭐⭐ **จอกว้าง + หลายฉบับ ⇒ หัวคอลัมน์หนึบ 1 แถว** (ใบงาน v3/phrakham#76)
           ⇒ ชื่อฉบับโผล่ **แถวเดียวต่อ 1 จอ** ⛔ ไม่ใช่ 1 ครั้งต่อข้อต่อฉบับ (เดิม 30 ข้อ × 4 = 120)
           ⇒ ผู้อ่านรู้ว่าคอลัมน์ไหนเป็นฉบับไหนจาก **การเรียงตรงกันในแนวตั้ง** ⛔ ไม่ใช่จากสี
             ⇒ WCAG SC 1.4.1 Use of Color (ระดับ A) ⇒ ชื่อฉบับเป็น **ตัวหนังสือ** ⛔ ไม่ใช่แถบสี
         ⛔ **จอแคบ ⛔ ไม่มีหัวคอลัมน์** — เพราะจอแคบอ่านทีละฉบับ ⇒ ชื่อฉบับอยู่บนปุ่ม `ฉบับ` แล้ว
           ⇒ ⭐ **แถบหนึบบนจอแคบจึงไม่สูงขึ้นเลย** ⇒ วัดได้เอง ⛔ ไม่ต้องเชื่อบรรทัดนี้ -->
    <!-- ================= พื้นที่อ่าน — คอลัมน์แรก กับตอนที่เอามาเทียบ (ใบงาน v3/phrakham#99) =================
         ⭐⭐ **คอลัมน์แรกเป็นเจ้าของหน้า** ⇒ ชื่อหน้า · หมุดบท · ลูกศรเปลี่ยนบท · แถบล่างหนึบ
           ⇒ **เดินตามคอลัมน์แรกตัวเดียว** ⇒ ⛔ ห้ามให้ทุกคอลัมน์แย่งกันเป็นเจ้าของ
           ⇒ ผู้อ่านต้องรู้เสมอว่า *ฉันอยู่ที่ไหน* ⇒ เกณฑ์ผ่านของ us07 สั่งไว้เอง
         ⛔ **ยังไม่ได้เปิดตอนเทียบ ⇒ กล่องนี้เป็นกล่องเปล่าที่ ⛔ ไม่มีกฎอะไรเลย**
           ⇒ **หน้าของคนที่ ⛔ ไม่แตะอะไร จึงเหมือนเดิมทุกจุด** ⇒ เกณฑ์ผ่านข้อแรกของ us07 -->
    <!-- ⭐ ใบ #131 note_30367 ⇒ บนล่างจอแคบ ⇒ คอลัมน์คนละบทคู่ทีละข้อในฝั่งหลัก ⇒ ⛔ ไม่มีกล่องของตัวเอง ⇒ ⛔ ไม่ใส่ `pk-มีตอนเทียบ`
           ⇒ ทีละฉบับแล้วอ่านคอลัมน์คนละบทอยู่ ⇒ ฝั่งหลักซ่อน (`pk-ซ่อนฝั่งหลัก`) ⇒ กฎอยู่ที่ `main.css` หัวข้อ *การวางคอลัมน์บนจอแคบ* -->
    <!-- ⭐ ใบ #144 ⇒ `--pk-หัวขั้นต่ำ` ลงมาถึงหัวของคอลัมน์คนละบทด้วย ⇒ หัวเต็มแถวจอแคบกินช่องไฟเท่าที่หัวขาด ⛔ กินทั้งช่อง (`main.css`)
           ⇒ ตารางห่อลงแถวใหม่ ⇒ ช่องต้นแถว ⛔ มีเส้นแบ่งคอลัมน์ ⇒ ดู `วัดเส้นแบ่ง`
           ⇒ ⭐ คลาสห่ออยู่ที่กล่องนี้ ⛔ ที่ `.pk-คอลัมน์` ⇒ วัดใหม่แล้วคลาสเปลี่ยน ⇒ Vue เขียนคลาสของกล่องนี้กล่องเดียว
             ⇒ ⚠️ ลองที่ `.pk-คอลัมน์` แล้ว ⇒ Vue เขียนคลาสของกล่องนั้นใหม่ทั้งชุด ⇒ ฝาแฝดของ `ด่านคำเดิมคู่คอลัมน์แรก.mjs` ที่ถอด `pk-มีฉบับอื่น` ด้วยมือถูกคืนคลาสเอง ⇒ ด่านตายบางส่วน -->
    <div
      class="pk-พื้นที่อ่าน"
      :class="{
        // ⭐ ใบ #164 ⇒ คอลัมน์ฉบับซ้ำที่เป็นช่องในตาราง ⛔ มีกล่อง ⇒ ⛔ นับ
        'pk-มีตอนเทียบ': คอลัมน์เทียบที่แสดง.length > เงาในตาราง.length && !จับคู่บนล่าง,
        [`pk-หัวห่อทุก-${หัวห่อทุก}`]: หัวห่อทุก > 0,
        'pk-หัวหลายแถว': หัวหลายแถว,
        [`pk-ตัวบทห่อทุก-${ตัวบทห่อทุก}`]: ตัวบทห่อทุก > 0,
      }"
      :style="{ '--pk-หัวขั้นต่ำ': กว้างหัวขั้นต่ำ ? `${Math.ceil(กว้างหัวขั้นต่ำ)}px` : undefined }"
    >
    <div class="pk-ฝั่งหลัก" :class="{ 'pk-ซ่อนฝั่งหลัก': ดูเทียบที่ >= 0 }">
    <!-- ⭐⭐ **หัวคอลัมน์ของทุกฉบับ ⇒ ชิ้นส่วนเดียวกับหัวของตอนที่เอามาเทียบ** (ใบงาน #102 ข้อ 6)
           ⇒ ⛔ ของเดิมมีแค่ชื่อฉบับ และโผล่เฉพาะจอกว้างที่เปิดหลายฉบับ ⇒ คอลัมน์แรกจึงไม่มีหัวแบบเดียวกับคอลัมน์อื่น
           ⇒ ตอนนี้ **มีเสมอ ทุกจอ ทุกจำนวนคอลัมน์** ⇒ เรียนรู้ครั้งเดียวใช้ได้ทุกคอลัมน์
         ⭐⭐ **ปุ่มเปลี่ยนตอน กับฉบับ ⇒ ขยับคอลัมน์ของตัวเองคอลัมน์เดียว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 8)
           ⇒ ⚠️ ของเดิม (ใบ #102) ⇒ ปุ่มบนหัวของคอลัมน์ในตารางพาทั้งตารางไป ⇒ พี่เอมใช้จริงแล้วแยกไม่ออก ⇒ เปลี่ยนแล้ว
           ⇒ คอลัมน์แรก ⇒ พาคำภาษาเดิมไปด้วย ⇒ คอลัมน์อื่นในตารางอยู่บทเดิม ⇒ ออกไปไหลเอง
           ⇒ คอลัมน์อื่น ⇒ ออกจากตารางไปไหลเองคนเดียว ⇒ กติกาอยู่ที่ `รับผลจากแผง` ในสคริปต์
         ⛔ **หัว ⛔ ไม่มี ‹ › แล้ว ทุกขนาดจอ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30302 ข้อ 3 · 5)
           ⇒ ‹ › อยู่ที่แถบล่างที่เดียว ⇒ ทุกคอลัมน์ไปบทเดียวกับคอลัมน์ซ้ายสุด (ใบ #162) ⇒ ดู `กดลูกศรล่าง`
         ⛔ **จอแคบ หัว ⛔ ไม่หนึบ** ⇒ แถบหนึบของจอมือถือห้ามสูงขึ้น (ข้อ 6.3 · ใบ #76) ⇒ เจ้าของกฎคือ `main.css`
         ⭐ ช่องเลขข้อของแถวหัวต้องกว้างเท่าช่องเลขข้อของแถวเนื้อ ⇒ ไม่งั้นหัวเลื่อนไม่ตรงคอลัมน์
           ⇒ ใส่ตัวเลขจริงไว้แล้วซ่อน **ด้วย `visibility`** ⇒ กล่องยังกินที่เท่าเดิม -->
    <div
      v-if="ฉบับที่แสดง.length"
      class="pk-หัวคอลัมน์"
      :class="{
        'pk-ซ่อนเลข': !มุม.แสดงเลข,
        // ⭐ *ไหลต่อเนื่อง* กับ *แยกตามย่อหน้า* วางเลขข้อเป็นตัวยกในเนื้อ ⇒ **ไม่มีช่องเลขข้างซ้าย**
        //   ⇒ หัวคอลัมน์ต้องยุบช่องนั้นทิ้งด้วย ไม่งั้นชื่อฉบับเลื่อนไม่ตรงกับเนื้อข้างล่าง
        'pk-ไม่มีช่องเลข': มุม.จัดวาง !== 'แยกตามข้อ',
        'pk-ทีละฉบับ': ทีละฉบับอยู่,
      }"
    >
      <sup class="pk-เลขข้อ pk-กันที่" aria-hidden="true">88</sup>
      <div
        class="pk-ช่องทั้งหมด"
        :class="`pk-คอลัมน์-${กี่ช่องตาราง}`"
        :style="{
          // ⭐ หัวที่อยู่แถวนี้จริง ⇒ ฉบับในตาราง · คำภาษาเดิม (จอแคบ) · คอลัมน์คนละบทตอนบนล่าง · ฉบับซ้ำที่เป็นช่องในตาราง (ใบ #164)
          '--pk-กี่หัว':
            กี่ช่องตาราง + (หัวคำเดิมในแถว ? 1 : 0) + (จับคู่บนล่าง ? คอลัมน์เทียบที่แสดง.length : 0),
          // ⭐ ใบ #131 note_30489 ⇒ หัวแถวเดียวที่แคบสุดที่ยังไม่ตัดเลขบท ⇒ แถบหัวของบนล่างใช้เป็นขั้นต่ำของแต่ละหัว (`main.css`)
          '--pk-หัวขั้นต่ำ': กว้างหัวขั้นต่ำ ? `${Math.ceil(กว้างหัวขั้นต่ำ)}px` : undefined,
        }"
      >
        <!-- ⭐ ใบ #145 ก้อน ข. ⇒ จอแคบเดินตามลำดับจริงของตาราง (`ลำดับตาราง`) ⇒ หัวคำเดิมอยู่ตำแหน่งของมัน ⛔ ไม่ใช่ที่ 2 เสมอ -->
        <template v-for="ฉ in หัวคำเดิมในแถว && ตัวจัดแถวพร้อม ? ลำดับตาราง : ฉบับที่แสดง" :key="`หัว-${ฉ}`">
        <component
          :is="หัวคอลัมน์"
          v-if="ฉ !== คำเดิมในลำดับ"
          class="pk-ช่องหัว"
          :class="{ 'pk-ช่องที่อ่าน': ฉ === ฉบับที่กำลังดู }"
          :data-ฉบับ="ฉ"
          :ป้าย="ป้ายที่ของหน้า"
          :ชื่อย่อ="ของเล่ม?.ชื่อย่อของชั้น?.[ฉ]"
          :เลข="เลขบนแถบล่าง"
          :ภาษา="ภาษาของชั้น[ฉ]"
          :ลำดับ="ฉบับที่แสดง.indexOf(ฉ) + 1"
          :ฉบับ="ฉ"
          :ฉบับที่มี="ตัวเลือกหัว"
          :ภาษาของตัวเลือก="ภาษาของตัวเลือก"
          :ปิดได้="ปิดได้ทุกคอลัมน์"
          @เปลี่ยนตอน="เปิดแผงของช่อง(ฉ)"
          @ฉบับ="(x: string) => เปลี่ยนช่องตาราง(ฉ, x)"
          @ปิด="ปิดช่องฉบับ(ฉ)"
        />
        <!-- ⭐⭐ **จอแคบ ⇒ หัวของคอลัมน์คำภาษาเดิมอยู่แถวนี้ ถัดจากหัวคอลัมน์แรก** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30490)
               ⇒ ลำดับเดียวกับที่วางคอลัมน์ (คอลัมน์แรก · คำภาษาเดิม · ฉบับอื่น) ⇒ ซ้ายขวาหัวอยู่เหนือคอลัมน์ของมัน · บนล่างอยู่ในแถบหัว · ทีละฉบับเห็นเฉพาะที่อ่าน
               ⇒ ⚠️ ของเดิม (ใบ #125 ข้อ 11.2) ⇒ จอแคบหัวนี้อยู่ใต้หัวฉบับ ⛔ หนึบ ⇒ จอกว้างยังเป็นชิ้นแยกที่หนึบในช่องของตัวเอง (`pk-ชื่อคำเดิม` ข้างล่าง) -->
        <component
          :is="หัวคอลัมน์"
          v-else
          class="pk-ช่องหัว pk-ชื่อคำเดิม"
          :class="{ 'pk-ช่องที่อ่าน': ดูคำเดิมอยู่ }"
          data-ชื่อคำเดิม
          v-bind="พร็อปหัวคำเดิม"
          :เครื่องมือ="ปุ่มเครื่องมือ"
          @เปลี่ยนตอน="เปิดแผงของคำเดิม()"
          @ฉบับ="(x: string) => เปลี่ยนช่องตาราง(คำเดิมในลำดับ, x)"
          @ปิด="ปิดคำเดิม"
          @กล่องคำเดิม="(แบบ: กล่องคำเดิมที่มี) => สลับกล่องคำเดิม(แบบ)"
        >
          <!-- ⭐ ใบ #154 ⇒ กล่องของปุ่มเฟืองกับ i ⇒ ต่อจากปุ่มของมัน ⇒ เหตุผลอยู่หัวไฟล์ `แถวปุ่มคำเดิม.vue` -->
          <template v-for="แบบ in (['เครื่องมือ', 'คำอธิบาย'] as const)" :key="แบบ" #[แบบ]>
            <component
              :is="แถวปุ่มคำเดิม"
              v-if="ปุ่มเครื่องมือ && เจ้าของกล่องคำเดิม === -1 && กล่องคำเดิม === แบบ"
              :แบบ="แบบ"
              :ไอดี="ไอดีกล่องคำเดิม[แบบ]"
              :เต็มจอ="จอแคบ"
              v-bind="พร็อปแถวปุ่ม"
              :กรีก="คำเดิมเป็นกรีก"
              @กาล="สลับกาลคำเดิม"
              @เครื่องหมาย="ตั้งเครื่องหมายคำเดิม"
              @ตัวเดิม="ตั้งตัวเดิม"
              @เลขStrong="ตั้งเลขStrong"
              @จุดคั่น="ตั้งจุดคั่น"
              @ปิด="ปิดกล่องคำเดิม"
            />
          </template>
        </component>
        </template>
        <!-- ⭐⭐ **คอลัมน์ฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ หัวของมันเป็นช่องในแถวหัวของตาราง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/164)
               ⇒ ต่อท้ายหัวของตาราง ⇒ ตรงกับช่องของมันในตัวบทข้างล่าง (`ลำดับช่องทั้งหมด`) ⇒ เหตุผลอยู่ที่ `เงาในตาราง` ในสคริปต์
               ⇒ ป้ายกับเลขบทเป็นของหน้า ⇒ มันเลื่อนไปกับตาราง ⇒ บทที่ตาเห็นคือบทของหน้า
               ⇒ ปุ่มทำงานผ่านลำดับของมันในคอลัมน์ตอนอื่น ⇒ ทางเดียวกับหัวในกล่องของมันเดิมทุกปุ่ม (SC 3.2.4) -->
        <component
          :is="หัวคอลัมน์"
          v-for="ง in ช่องเงา"
          :key="`หัวเงา-${ง.เทียบ}`"
          class="pk-ช่องหัว pk-หัวเงา"
          :data-ฉบับ="ง.ฉ"
          :data-เทียบ="ง.เทียบ"
          :ป้าย="ป้ายที่ของหน้า"
          :ชื่อย่อ="ของเล่ม?.ชื่อย่อของชั้น?.[ง.ฉ]"
          :เลข="เลขบนแถบล่าง"
          :ภาษา="ภาษาของชั้น[ง.ฉ]"
          :ลำดับ="ฉบับที่แสดง.length + ง.เทียบ + 1"
          :ฉบับ="ง.ฉ"
          :ฉบับที่มี="ตัวเลือกหัว"
          :ภาษาของตัวเลือก="ภาษาของตัวเลือก"
          :ปิดได้="ปิดได้ทุกคอลัมน์"
          @เปลี่ยนตอน="เปิดแผงให้(ง.เทียบ)"
          @ฉบับ="(x: string) => เปลี่ยนฉบับของเทียบ(ง.เทียบ, x)"
          @ปิด="ถอดคอลัมน์เทียบ(ง.เทียบ)"
        />
        <!-- ⭐⭐ **บนล่าง ⇒ หัวของคอลัมน์คนละเล่มคนละบทอยู่แถวหัวที่หนึบแถวนี้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30367)
               ⇒ ตัวบทของมันคู่ทีละข้อในฝั่งนี้ ⇒ ⛔ ไม่มีกล่องของตัวเอง ⇒ หัวจึงมาอยู่กับหัวอื่น ⇒ ทุกคอลัมน์เห็นชื่อฉบับของตัวเองตลอด
               ⇒ ชิ้นส่วนเดียวกับหัวในกล่องของมัน ⇒ ปุ่ม ลำดับ และชื่อที่ได้ยินเหมือนเดิมทุกอย่าง (SC 3.2.4) -->
        <template v-if="จับคู่บนล่าง">
          <component
            :is="หัวคอลัมน์"
            v-for="(ต, i) in คอลัมน์เทียบที่แสดง"
            :key="`หัวคู่-${ต.กุญแจ}`"
            class="pk-ช่องหัว pk-หัวคู่"
            :data-เทียบ="i"
            :ป้าย="`${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท}`"
            :ชื่อย่อ="ต.ชื่อย่อ"
            :เลข="`${ต.บท}`"
            :ภาษา="ต.คำเดิม ? 'th' : ต.ภาษา"
            :ชื่อคอลัมน์="ต.คำเดิม ? ถ้อยคำคำเดิม.เปิด : undefined"
            :ชื่อภาษา="ต.คำเดิม?.ชั้น || undefined"
            :ลำดับ="ฉบับที่แสดง.length + i + 1"
            :ฉบับ="ต.ฉบับ"
            :ฉบับที่มี="ตัวเลือกหัว"
            :ภาษาของตัวเลือก="ภาษาของตัวเลือก"
            :ปิดได้="ปิดได้ทุกคอลัมน์"
            :เครื่องมือ="ปุ่มเครื่องมือของเทียบ(i, ต.คำเดิม)"
            @เปลี่ยนตอน="เปิดแผงให้(i)"
            @ฉบับ="(x: string) => เปลี่ยนฉบับของเทียบ(i, x)"
            @ปิด="ถอดคอลัมน์เทียบ(i)"
            @กล่องคำเดิม="(แบบ: กล่องคำเดิมที่มี) => สลับกล่องคำเดิม(แบบ, i)"
          >
            <!-- ⭐ คอลัมน์คนละที่ที่เป็นคำภาษาเดิม ⇒ เฟืองที่มีสวิตช์ตัวเดิม (พี่เอมขอ 17 พ.ย. 2569) ⇒ เหตุผลอยู่ที่ `ปุ่มเครื่องมือของเทียบ` ในสคริปต์ -->
            <template #เครื่องมือ>
              <component
                :is="แถวปุ่มคำเดิม"
                v-if="ต.คำเดิม && เจ้าของกล่องคำเดิม === i && กล่องคำเดิม === 'เครื่องมือ'"
                แบบ="เครื่องมือ"
                :ไอดี="ไอดีกล่องของเทียบ(i).เครื่องมือ"
                :เต็มจอ="จอแคบ"
                v-bind="พร็อปแถวปุ่ม"
                :กรีก="false"
                @ตัวเดิม="ตั้งตัวเดิม"
                @เลขStrong="ตั้งเลขStrong"
                @จุดคั่น="ตั้งจุดคั่น"
                @ปิด="ปิดกล่องคำเดิม"
              />
            </template>
          </component>
        </template>
      </div>
    </div>
    <!-- ⭐⭐ **ป้าย *ย่อหน้าตาม …* ⛔ อยู่บนหน้าอ่านแล้ว ทุกขนาดจอ** (พี่เอมสั่ง 3 พ.ย. 2569 ในใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 ⇒ เปลืองที่แนวตั้ง)
           ⇒ ย้ายไปบอกที่หน้าแหล่งข้อมูล ใต้ฉบับที่ไม่มีย่อหน้าของตัวเอง ⇒ `app/components/content/ParagraphSource.vue`
           ⇒ ⚠️ ของเดิม (ใบ #106 ข้อ 8 · ใบ #131 note_30365) ⇒ ป้ายในหัวจอกว้าง · แถวป้ายใต้หัวจอแคบ ⇒ ถอดทั้งคู่
           ⇒ การยืมย่อหน้ายังทำเหมือนเดิมทุกอย่าง (`จัดย่อหน้าของฉบับ`) ⇒ ถอดแค่ป้าย -->
    <!-- ⭐⭐ **ชื่อของคอลัมน์คำภาษาเดิม ⇒ อยู่แถวหัวที่หนึบ ⇒ เห็นตลอด** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 11.2 · 11.5)
           ⇒ บอกตอนเดียวกับคอลัมน์แรก แล้วตามด้วยชื่อตัวบท SBLGNT หรือ WLC ⇒ ของเดิมป้ายแหล่งขึ้นครั้งเดียวที่ต้นบท ⇒ เลื่อนลงแล้วไม่รู้ว่าเป็นภาษาอะไร (ข้อ 4.3)
           ⇒ ⛔ ไม่เขียน MACULA บนหัว (ข้อ 11.2.1) ⇒ สีและหน้าตาเดียวกับหัวทุกคอลัมน์ (ข้อ 11.10)
           ⇒ ⭐ **ทรงเดียวกับหัวของคอลัมน์อื่น** ⇒ บรรทัดบนเป็นป้าย · บรรทัดล่างเป็นปุ่ม ⇒ ปุ่ม × ที่เดียวกัน หน้าตาเดียวกัน ⇒ WCAG 2.2 SC 3.2.4
           ⇒ ⭐ **ไม่สูงกว่าหัวคอลัมน์อื่น** ⇒ ตัวคุมน้อยกว่าหัวฉบับแปล ⇒ แถบหนึบ ⛔ สูงขึ้น (ข้อ 11.3) ⇒ ชื่อตอนยาวห่อบรรทัด ⛔ ไม่ตัดด้วยจุดไข่ปลา
           ⇒ ปุ่มสัญลักษณ์กาล คำเน้น ความหมาย ⇒ แถวถัดลงมา (`แถวปุ่มคำเดิม.vue`) ⇒ ⛔ ไม่ยัดลงหัวที่หนึบ เพราะทำให้หัวสูงขึ้น
           ⇒ ⛔ ไม่เพิ่มปุ่มที่หัวคอลัมน์แรก (ข้อ 11.8) ⇒ ชิ้นนี้เป็นหัวของคอลัมน์คำภาษาเดิมเอง
           ⛔ `data-ปุ่ม` ของ × ⛔ ไม่ใช่ `ปิดคอลัมน์` ⇒ ตัวนั้นนับคอลัมน์อ่าน ⇒ คอลัมน์อ่านเหลือ 1 ยังปิดไม่ได้ (ใบ #102 ข้อ 6.1) -->
    <!-- ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30490 ⇒ ข้างในเป็นชิ้นส่วนหัวเดียวกับทุกคอลัมน์ ⇒ ช่องตัวบท ▾ · ชื่อย่อเล่มกับบท · ×
           ⇒ ⚠️ ของเดิม ⇒ ป้ายตอน · ชื่อตัวบทที่กดไม่ได้ · × ⇒ เหตุผลของช่องตัวบทกับปุ่มชื่อย่ออยู่ที่ `หัวคำเดิม` ในสคริปต์
           ⇒ จอแคบ ⇒ หัวนี้ไปอยู่แถวหัวฉบับ (`หัวคำเดิมในแถว`) ⇒ ⛔ ไม่วาดที่นี่ -->
    <div v-if="มุม.ภาษาเดิม && ตัวจัดแถวพร้อม && !หัวคำเดิมในแถว" class="pk-ชื่อคำเดิม" data-ชื่อคำเดิม>
      <component
        :is="หัวคอลัมน์"
        v-bind="พร็อปหัวคำเดิม"
        :เครื่องมือ="ปุ่มเครื่องมือ"
        @เปลี่ยนตอน="เปิดแผงของคำเดิม()"
        @ฉบับ="(x: string) => เปลี่ยนช่องตาราง(คำเดิมในลำดับ, x)"
        @ปิด="ปิดคำเดิม"
        @กล่องคำเดิม="(แบบ: กล่องคำเดิมที่มี) => สลับกล่องคำเดิม(แบบ)"
      >
        <template v-for="แบบ in (['เครื่องมือ', 'คำอธิบาย'] as const)" :key="แบบ" #[แบบ]>
          <component
            :is="แถวปุ่มคำเดิม"
            v-if="ปุ่มเครื่องมือ && เจ้าของกล่องคำเดิม === -1 && กล่องคำเดิม === แบบ"
            :แบบ="แบบ"
            :ไอดี="ไอดีกล่องคำเดิม[แบบ]"
            :เต็มจอ="จอแคบ"
            v-bind="พร็อปแถวปุ่ม"
            :กรีก="คำเดิมเป็นกรีก"
            @กาล="สลับกาลคำเดิม"
            @เครื่องหมาย="ตั้งเครื่องหมายคำเดิม"
            @ตัวเดิม="ตั้งตัวเดิม"
            @เลขStrong="ตั้งเลขStrong"
            @จุดคั่น="ตั้งจุดคั่น"
            @ปิด="ปิดกล่องคำเดิม"
          />
        </template>
      </component>
    </div>
    <!-- ⛔⛔ **แถวปุ่มใต้หัวคอลัมน์คำภาษาเดิม ⛔ อยู่ที่นี่แล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/151 เกณฑ์ข้อ 3)
           ⇒ ⚠️ ของเดิม (ใบ #119) ⇒ แถวในผังคอลัมน์ใต้หัว ⇒ หนึบเฉพาะตอนไม่สูงกว่าหัวฉบับแปล ⇒ ส่วนใหญ่เลื่อนหายไปกับต้นบท
           ⇒ ⭐ ตอนนี้ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/154) ⇒ ปุ่มรูปเฟืองกับตัว i บนหัวคอลัมน์ภาษาเดิม (ข้างบน) ทุกจอ
           ⇒ ⭐ ข้อที่ยังถืออยู่ ⇒ ชิ้นที่โหลดแยกสร้างผ่าน `ชิ้นโหลดแยก` (ใบ #142) ⇒ เหตุผลเต็มอยู่ที่ `app/utils/ชิ้นโหลดแยก.ts` -->

    <div
      class="pk-ตัวบท"
      :class="[
        `pk-จัดวาง-${มุม.จัดวาง}`,
        {
          'pk-ซ่อนเลข': !มุม.แสดงเลข,
          // ⭐ ซ่อนฉบับอื่น **เฉพาะตอนจอแคบที่อ่านทีละฉบับ** ⇒ ขนานกันแล้วต้องเห็นครบ (ใบ #97)
          'pk-ทีละฉบับ': ทีละฉบับอยู่,
        },
      ]"
      @click="เลือก.แตะในตัวบท"
      @keydown="เลือก.แป้นในตัวบท"
    >
      <template v-for="ก in บทที่แสดง" :key="ก.บท">
        <!-- ⭐ **หมุดเลขบท เล็ก ๆ ในเนื้อ ⛔ ไม่ใช่เส้นขวางตัดหน้า** (พี่เอมสั่ง 6 ก.ย. 2569)
             ⛔ ต้องเป็นหัวเรื่องจริง ⇒ คนที่ใช้โปรแกรมอ่านหน้าจอกระโดดข้ามบทด้วยหัวเรื่อง -->
        <h2 :id="`บท-${ก.บท}`" class="pk-หมุดบท" :data-หมุดบท="ก.บท" :style="ช่องกริด(ก.บท, 'หมุด')">
          {{ เล่มนี้.ชื่อไทย }} {{ ก.บท }}
        </h2>
        <!-- ⛔ **แผงเรื่องเล่าใต้หมุดบท ถอดออกแล้ว** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/105 รอบ 2 ข้อ 4)
             ⇒ ทางเข้าเรื่องเล่ามีทางเดียวคือแถบบางเหนือแถบล่าง ⇒ ดูที่ `pk-แถบเรื่องเล่า` ข้างล่าง
             ⇒ ตัวเฝ้าคือ `tools/ด่านเรื่องเล่าบนหน้า.mjs` ข้อ ⑨ ⇒ ปุ่มเรื่องเล่าโผล่ในตัวบทเมื่อไร แดงทันที -->
        <!-- ================= คำภาษาเดิมของบทนี้ (ใบงาน v3/phrakham#95) =================
             ⭐⭐ **เป็นก้อนของตัวเอง 1 ก้อนต่อ 1 บท** ⇒ หัวคอลัมน์ ปุ่ม และจุดหยุด Tab อยู่ที่ก้อนนี้
             ⭐⭐ **ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/112 ⇒ ข้างในก้อนจัดเป็นแถวเดียวกับฉบับแปล**
               ⇒ ⛔ ของเดิม (ใบ #95) ⛔ ไม่วางให้ตรงบรรทัด ⇒ *เคียงกัน ⛔ ไม่ได้แปลว่าจับคู่* ⇒ พี่เอมเปลี่ยนเอง 26 ต.ค. 2569
               ⇒ ข้อเดิมไปแถวไหน ⇒ ตามตาราง `ข้อแปล` ที่ตรวจแล้ว ⇒ กติกาอยู่ที่ `app/utils/แถวคำเดิม.ts`
             ⭐ **จอกว้างก้อนนี้อยู่คอลัมน์ขวาของตารางแถว · จอแคบไม่มีก้อนนี้** (คนตรวจ !102 ทัก ② · ใบ #124)
               ⇒ ⛔ **ที่นี่ ⛔ ไม่ตัดสินเรื่องนั้น** ⇒ เจ้าของคือ `app/assets/css/แถวคำเดิม.css`
               ⇒ ⭐ ก้อนขึ้นหลังกฎหน้าตาของแถวมาถึงแล้วเท่านั้น (`ตัวจัดแถวพร้อม`)
             ⭐ เลขข้อที่เห็นในก้อนนี้คือ **เลขของฝั่งภาษาเดิม** ⇒ ซ่อนพร้อมเลขอื่นเมื่อผู้อ่านปิดเลข
             ⛔ **คำแปลกำกับเป็นภาษาอังกฤษ** ⇒ ต้องติด `lang="en"` ⛔ ไม่งั้นเสียงไทยอ่านคำอังกฤษ
               ⇒ WCAG 2.2 SC 3.1.2 Language of Parts (ระดับ AA) -->
        <!-- ⭐ **ตอนดูช่วง ก้อนนี้มีเฉพาะข้อเดิมที่อยู่กับข้อแปลในช่วง** (ใบ #104) ⇒ ตัดที่ `คำของก้อน` ในสคริปต์
             ⭐⭐ **จอแคบ ⛔ ไม่วาดก้อนนี้แล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/124)
               ⇒ คำเดิมไปอยู่ใต้แต่ละแถว (`คำเดิมใต้แถว.vue`) ⇒ ไหลต่อเนื่องไปอยู่ท้ายบท ⇒ เหตุผลอยู่ที่ `ทางคำเดิมจอแคบ` ในสคริปต์ -->
        <section
          v-if="มุม.ภาษาเดิม && ตัวจัดแถวพร้อม && คำของก้อน.get(ก.บท) && !ทางคำเดิมจอแคบ && !ซ่อนคำเดิม"
          class="pk-ชั้นคำ"
          :class="`pk-ขนาดคำ-${มุม.ขนาดคำเดิม}`"
          :aria-label="`คำภาษาเดิม ${เล่มนี้.ชื่อไทย} ${ก.บท}`"
          :style="ช่องกริด(ก.บท, 'ชั้นคำ')"
        >
          <template v-for="ชั้น in คำของก้อน.get(ก.บท)!" :key="ชั้น.ชื่อ">
            <!-- ============ ป้ายที่มาของชั้นคำ (ใบงาน v3/phrakham#96 · ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/119) ============
                 ⭐⭐ **ปุ่มของคอลัมน์ ⛔ ไม่อยู่ที่นี่แล้ว** ⇒ ย้ายไปแถวเดียวกับหัวคอลัมน์ฉบับแปล (`แถวปุ่มคำเดิม.vue`)
                   ⇒ ⛔ ของเดิมปุ่ม 6 ปุ่มอยู่แถวเดียวกับหมุดบท ⇒ ห่อ 2 ถึง 3 บรรทัด ⇒ ดันข้อแรกของฉบับแปลลง (ใบ #119 ข้อ 5.4)
                   ⇒ เหตุผลเต็มอยู่หัวไฟล์นั้น ⛔ ไม่จดซ้ำที่นี่
                 ⭐ ป้ายที่มาติดทีละชั้น ⛔ ป้ายเดียวคลุมทั้งหน้าไม่ได้ ⇒ เจ้าของเหตุผลคือ `docs/บันทึก-แหล่งข้อมูล.md` หัวข้อ ②
                   ⇒ จอกว้างป้ายนี้สูงเท่าหมุดบทพอดี ⇒ แถวหมุดบท ⛔ ไม่ยืด ⇒ กฎอยู่ที่ `app/assets/css/แถวคำเดิม.css` -->
            <div class="pk-หัวชั้นคำ">
              <!-- ⭐ ใบ #125 ข้อ 11.2.1 ⇒ ภาษากับชื่อตัวบท ⇒ ⛔ ไม่ใช่ชื่อชุดข้อมูล MACULA ⇒ แบบเดียวกับป้ายจอแคบ (ข้อ 11.4) -->
              <p class="pk-ที่มาชั้นคำ">{{ ป้ายชั้นคำ(ชั้น.ชื่อ) }}</p>
            </div>
            <!-- ⭐⭐ **กล่องที่เลื่อนได้ ⇒ อยู่ตรงนี้ ⛔ ไม่ใช่ที่ตัวข้อ และ ⛔ ไม่ใช่ที่ทั้งก้อน**
                   ⇒ แบบ *ตามขนาดจริง* ⛔ ไม่หักคำกลางคำ ⇒ คำที่ยาวกว่าบรรทัดจึงล้นออกมาได้
                   ⇒ **ล้นแล้วต้องเลื่อนได้เฉพาะในคอลัมน์ ⛔ ห้ามลากทั้งหน้าเลื่อนตาม**
                     ⇒ WCAG 2.2 SC 1.4.10 Reflow (ระดับ AA)
                 🔴 **ทำไม `dir` ต้องอยู่ที่กล่องนี้ด้วย ⛔ ไม่ใช่แค่ที่ตัวข้อ**
                   ⇒ ฝั่งฮีบรูล้นไป **ทางซ้าย** ⇒ กล่องที่เป็น `ltr` **ไม่นับของที่ล้นทางซ้ายเป็นของที่เลื่อนถึง**
                   ⇒ วัดเองที่จอ 320 ตัวอักษร 200% ⇒ กล่อง `ltr` ได้ `scrollWidth` เท่า `clientWidth` เป๊ะ
                     **แปลว่าคำที่ล้นออกไปอ่านไม่ได้เลย** ⇒ ใส่ `dir` แล้วเลื่อนได้จริง 31 จุด
                 ⭐ **โฟกัสได้เฉพาะตอนที่มันเลื่อนได้** ⇒ คนใช้แป้นพิมพ์ต้องเลื่อนกล่องนี้ได้
                   ⇒ WCAG 2.2 SC 2.1.1 Keyboard (ระดับ A) ⇒ แบบ *พอดี* ⛔ ไม่เลื่อน จึง ⛔ ไม่กินจุดหยุด Tab -->
            <div
              class="pk-กล่องคำ"
              :class="{ 'pk-แสดงกาล': ชั้น.ภาษา === 'grc' && มุม.สัญลักษณ์กาล }"
              :lang="ชั้น.ภาษา"
              :dir="ชั้น.ทิศ"
              :tabindex="มุม.ขนาดคำเดิม === 'ตามขนาดจริง' ? 0 : undefined"
              :role="มุม.ขนาดคำเดิม === 'ตามขนาดจริง' ? 'group' : undefined"
              :aria-label="
                มุม.ขนาดคำเดิม === 'ตามขนาดจริง'
                  ? `${ชั้น.ชื่อ} ${เล่มนี้.ชื่อไทย} ${ก.บท} เลื่อนซ้ายขวาได้`
                  : undefined
              "
              @keydown="แป้นในกล่องคำ"
              :style="ช่องกริด(ก.บท, 'กล่องคำ')"
            >
              <!-- ⭐⭐ **แถวของคำเดิม = แถวเดียวกับฉบับแปล** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/112)
                     ⇒ กลุ่มหนึ่งถือข้อเดิมทุกข้อที่เริ่มในแถวนั้น ⇒ แถวที่ไม่มีคำเดิม ⛔ ไม่มีกลุ่ม
                     ⇒ `data-แถว` จับคู่กับแถวเนื้อของฉบับแปล ⇒ ตัวย่อแบบ *พอดี* กับด่านใช้ป้ายเดียวกัน
                   ⭐ จอแคบ ⇒ ก้อนนี้ไม่ถูกวาด ⇒ กลุ่มของแต่ละแถวไปอยู่ใต้แถวนั้น (`คำเดิมใต้แถว.vue` ⇒ ใบ #124) -->
              <div
                v-for="กล in กลุ่มคำของก้อน.get(ก.บท)?.get(ชั้น.ชื่อ) || []"
                :key="`${ชั้น.ชื่อ}-${กล.แถว}`"
                class="pk-แถวคำ"
                :data-แถว="ป้ายแถว(ก.บท, กล.แถว)"
                :style="ผังแถว.has(ก.บท) ? { gridRow: String(กล.แถว + 1) } : undefined"
              >
              <!-- ⭐⭐ **ทุกคำเป็นปุ่ม ⇒ กดแล้วการ์ดความหมายขึ้น** (ใบงาน v3/phrakham#103)
                     ⇒ `<button>` จริง ⛔ ไม่ใช่ `span` ที่ติด `@click` ⇒ แป้นพิมพ์ Enter กับ Space ใช้ได้เอง
                     ⇒ **จุดหยุด Tab มีจุดเดียวต่อกล่อง** ⇒ เหตุผลอยู่ที่ `คำที่รับTab` ในสคริปต์
                     ⛔ **ข้างในปุ่มต้องมีแค่คำเดิมกับคำแปลกำกับ** ⇒ ด่านของใบ #95/#96 เทียบตัวอักษรของปุ่มนี้
                       ⇒ ชื่อที่โปรแกรมอ่านหน้าจอได้ยิน = คำที่ตาเห็น ⇒ SC 2.5.3 Label in Name (ระดับ A) -->
              <!-- ⭐ **เลขกำกับคือเลขข้อของฝั่งภาษาเดิมเอง** ⇒ ⭐ เขียนแบบเดียวกับฉบับแปลด้วย `ป้ายเลขข้อ` ตัวเดียวกัน
                     ⇒ ข้อแรกของก้อน (ข้อแรกของชั้นนี้) เป็น *บท:ข้อ* เหมือนฉบับแปล ⇒ ข้ออื่นเลขข้อเปล่า
                     (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/117 ⇒ ⛔ ของเดิมใบ #95 เขียน *บท:ข้อ* เสมอ)
                     ⇒ ⭐ ข้อเดิมที่อยู่คนละบทกับแถว ⇒ ยังเขียนบทด้วย ⇒ เช่น ช่วงวิวรณ์ 13:1–4 ได้ `12:18` ⛔ ไม่ใช่ `18`
                       ที่ผู้อ่านจะนึกว่าเป็น 13:18 ซึ่งไม่มีอยู่จริง ⇒ *บทของแถว* คือ `ก.บท` ⇒ นิยามกับเหตุผลอยู่ที่ `app/utils/ป้ายเลขข้อ.ts`
                     ⇒ ตัวหนังสือที่ตาเห็น = ที่โปรแกรมอ่านหน้าจอได้ยิน ⇒ ⛔ ห้ามเติมบทแบบเฉพาะเสียง
                   ⭐ `data-ข้อเดิม` ⇒ *บท:ข้อ* เต็มเสมอ ⇒ ให้ด่านอ่านเลขโดยไม่ต้องแกะตัวหนังสือที่ผู้อ่านเห็น -->
              <p
                v-for="แถว in กล.ข้อ"
                :key="`${ชั้น.ชื่อ}-${แถว.บท}-${แถว.ข้อ}`"
                class="pk-ข้อคำ"
                :data-ข้อเดิม="`${แถว.บท}:${แถว.ข้อ}`"
                :lang="ชั้น.ภาษา"
                :dir="ชั้น.ทิศ"
              >
                <sup class="pk-เลขข้อ">{{ ป้ายเลขข้อ(แถว.บท, แถว.ข้อ, ก.บท, แถว === ชั้น.ข้อ[0]) }}</sup
                ><button
                  v-for="(ค, i) in แถว.คำ"
                  :key="i"
                  type="button"
                  class="pk-คำ"
                  :class="{
                    'pk-คำที่เปิด':
                      คำที่เปิด?.บท === แถว.บท &&
                      คำที่เปิด?.ชั้น === ชั้น.ชื่อ &&
                      คำที่เปิด?.ข้อ === แถว.ข้อ &&
                      คำที่เปิด?.ลำดับ === i,
                  }"
                  aria-haspopup="dialog"
                  :data-ลค="แถว.ตา?.[i]?.ลค"
                  :data-ป้าย="แถว.ตา?.[i]?.ป้าย"
                  :tabindex="คำที่รับTab(ก.บท, ชั้น) === กุญแจคำ(แถว.บท, ชั้น.ชื่อ, แถว.ข้อ, i) ? 0 : -1"
                  @focus="โฟกัสคำ($event, ก.บท, ชั้น.ชื่อ, แถว.บท, แถว.ข้อ, i)"
                  @click="กดคำ($event, แถว.บท, ชั้น.ชื่อ, แถว.ข้อ, i, ค, แถว.จุด?.[i])"
                  ><span class="pk-ตัวเดิม" :data-หน้า="แถว.ตา?.[i]?.หน้า" :data-หลัง="แถว.ตา?.[i]?.หลัง">{{ ค[0] }}</span
                  ><span class="pk-คำแปลคำ" lang="en" dir="ltr" :data-หน้า="แถว.ตา?.[i]?.หน้า" :data-หลัง="แถว.ตา?.[i]?.หลัง">{{ ค[1]
                    }}<!-- ⭐ ใบ #178 ⇒ เลข Strong ตัวเล็กท้ายคำแปล ⇒ มีเฉพาะตอนเปิดสวิตช์ และคำนั้นมีเลข ⇒ เหตุผลของที่วางอยู่ `main.css` หัวข้อ *เลข Strong* --><span
                      v-if="เลขบนคำ(รหัสเล่ม, แถว.บท, ชั้น.ชื่อ, แถว.ข้อ, i, ชั้น.ภาษา)"
                      class="pk-เลขStrong"
                      >{{ เลขบนคำ(รหัสเล่ม, แถว.บท, ชั้น.ชื่อ, แถว.ข้อ, i, ชั้น.ภาษา) }}</span
                    ></span
                  ><!-- ⭐ สัญลักษณ์กาล (ใบ #110) ⇒ เฉพาะคำที่มีช่องที่ 3 = คำกริยากรีก ⇒ เหตุผลอยู่หัวไฟล์ `กาลบนคำ.vue`
                         ⭐ ปิดที่หัวคอลัมน์ ⇒ ยังวาดแต่ล่องหน ⇒ คำไม่ขยับ (ใบ #133 ข้อ 15) --><component
                    :is="กาลบนคำ"
                    v-if="ค[2]"
                    :รหัส="ค[2]"
                    :ซ่อน="!มุม.สัญลักษณ์กาล"
                  /><!-- ⭐ เครื่องหมายของ Levinsohn (ใบ #146) ⇒ หน้าตามาจาก `data-ลค` ข้างบน ⇒ ชิ้นนี้ให้เสียงกับ CSS ⇒ เหตุผลอยู่หัวไฟล์ `เน้นบนคำ.vue` --><component
                    :is="เน้นบนคำ"
                    v-if="แถว.ตา?.[i]?.ลค"
                    :เสียง="แถว.ตา?.[i]?.เสียง" /></button
                >
              </p>
              </div>
            </div>
          </template>
        </section>
        <!-- ⛔ เปิดปุ่มไว้แต่บทนี้ ⛔ ไม่มีคำเดิม ⇒ **บอกตรง ๆ** ⛔ ไม่ใช่ช่องว่างที่ดูเหมือนเว็บพัง
             ⇒ เกิดจริง เช่น มาลาคีบท 4 ⇒ ฝั่งฮีบรูจบที่บท 3 -->
        <p
          v-else-if="มุม.ภาษาเดิม && ตัวจัดแถวพร้อม && คำของก้อน.get(ก.บท) === null && !ซ่อนคำเดิม"
          class="pk-ไม่มีคำเดิม"
          :style="ช่องกริด(ก.บท, 'หมุด')"
        >
          {{ ช่วงที่ฟัง ? 'ช่วงนี้' : 'บทนี้' }} ⛔ ไม่มีคำภาษาเดิมในข้อมูลที่เรามี ⇒ ฝั่งภาษาเดิมแบ่งบทไม่ตรงกับฉบับแปล
        </p>
        <!-- ⭐⭐ **ไหลต่อเนื่องบนจอแคบ ⇒ ป้ายใต้ชื่อบทบอกว่าคำเดิมอยู่ไหน และดูทีละข้อได้ยังไง** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/124 ข้อ 7)
               ⇒ ลิงก์พาลงไปที่ก้อนคำท้ายบท · ปุ่มเปลี่ยนเป็นแยกตามข้อ ⇒ ถ้อยคำอยู่ที่ `app/utils/คำเดิมจอแคบ.ts` ที่เดียว
             ⭐ ลิงก์เป็น `<a href>` จริง ⇒ โค้ดไม่ทำงานก็ยังพาไปได้ด้วย `#` ⇒ ⭐ ปุ่มเป็น `<button>` จริง ⇒ ชื่อที่ได้ยิน = คำที่ตาเห็น (SC 2.5.3) -->
        <p
          v-if="ทางคำเดิมจอแคบ === 'ท้ายบท' && ตัวจัดแถวพร้อม && คำของก้อน.get(ก.บท)"
          class="pk-ป้ายคำเดิมท้ายบท"
          data-ป้ายคำเดิมท้ายบท
        >
          <template v-if="ถ้อยคำคำเดิมท้ายบท.ประโยค">{{ ถ้อยคำคำเดิมท้ายบท.ประโยค }} </template
          ><a :href="`#คำเดิม-${ก.บท}`" class="pk-ลิงก์คำเดิมท้ายบท" @click.prevent="ไปที่คำเดิมท้ายบท(ก.บท)">{{
            ถ้อยคำคำเดิมท้ายบท.ลิงก์
          }}</a
          ><Button type="button" class="pk-ปุ่มขนาด pk-ปุ่มดูทีละข้อ" @click="ดูคำเดิมทีละข้อ(ก.บท)">
            {{ ถ้อยคำคำเดิมท้ายบท.ปุ่ม }}
          </Button>
        </p>
        <!-- ================= ไหลต่อเนื่อง — **ไหลอยู่ใน *ฉบับของตัวเอง*** =================
             ⭐⭐ **1 ฉบับ = 1 กล่อง เสมอ** (ใบงาน v3/phrakham#87 · ท่าเดียวกับ `gridRender` ของรุ่น 2)
               ⛔ ของเดิมสั่ง `display:inline` ให้ทั้งข้อและทั้งช่องฉบับ ⇒ ตัวบทของ **ทุกฉบับ**
                  ไหลรวมกันเป็นพืดเดียว ⇒ อ่านได้ว่า *"…พระวาทะเป็นพระเจ้าIn the beginning…"*
                  (พี่เอมเปิดของจริงเจอ 8 ก.ย. 2569)
               ⇒ ⭐ **จึงต้องสลับแกน** ⇒ วนฉบับข้างนอก วนข้างในเป็นข้อ ⇒ ข้อของฉบับเดียวกัน
                  ต่อกันเป็นเนื้อเดียว แต่ ⛔ ไม่มีทางข้ามไปปนกับฉบับอื่น เพราะคนละกล่อง
             ⭐ ใช้ `pk-ช่องทั้งหมด` กับ `pk-คอลัมน์-N` ตัวเดียวกับโหมดแยกตามข้อ
               ⇒ คอลัมน์กว้างเท่ากันและตรงกับหัวคอลัมน์หนึบ ⛔ ไม่มีผังคู่ขนานให้ค้างรุ่นเก่า -->
        <!-- ================= แยกตามย่อหน้า — ย่อหน้าที่ *คนแปล* แบ่งไว้เอง =================
             ⭐⭐ **ขึ้นย่อหน้าจริงด้วย `<p>` คนละกล่อง** (ใบงาน v3/phrakham#98)
               ⛔ **ของเดิมที่ถูกถอดทิ้ง 7 ก.ย. 2569 ทำได้แค่ถ่างช่องไฟใต้ข้อ** ⇒ ⛔ นั่นไม่ใช่ย่อหน้า
               ⇒ กล่อง `<p>` คนละกล่อง ทำให้ **โปรแกรมอ่านหน้าจอได้ยินว่าขึ้นย่อหน้าใหม่**
                 ⇒ ⛔ ไม่ใช่ช่องว่างที่เห็นด้วยตาอย่างเดียว
             ⭐ **1 ฉบับ = 1 กล่อง** เหมือนโหมดไหลต่อเนื่อง ⇒ เหตุผลอยู่ที่กิ่งข้างล่าง ⛔ ไม่จดซ้ำ
             ⛔ **หมุดเกาะ *ข้อ* ⛔ ไม่ใช่ย่อหน้า** ⇒ WCAG 2.2 SC 2.4.5
               ⇒ ข้อที่ถูกรอยย่อหน้าผ่ากลาง ⇒ หมุดกับเลขข้ออยู่ที่ **ท่อนแรก** เท่านั้น
             ⭐⭐ **ย่อหน้าเดียวกันของทุกคอลัมน์เริ่มระดับเดียวกัน** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/109 ข้อ 6)
               ⇒ ⛔ ของเดิมวาด 1 ฉบับเป็น 1 กล่องยาวทั้งบท ⇒ มาระโก 10 TCV คู่ LSV จอ 1280 ⇒ ย่อหน้าข้อ 13 ห่างกัน 108 จุด ⇒ ห่างขึ้นเรื่อย ๆ จนข้อ 46 ห่าง 814 จุด
               ⇒ ⭐ ตอนนี้วาดเป็น **แถว** ⇒ 1 แถวมีช่องของทุกคอลัมน์ ⇒ แถวถัดไปเริ่มเมื่อช่องที่ยาวที่สุดจบ
                 ⇒ ช่องที่สั้นกว่าเว้นที่ว่างเอง (ข้อ 6.1) ⇒ ⛔ ไม่ต้องคำนวณความสูงด้วยโค้ด ⇒ ผังตารางของเบราว์เซอร์ทำให้
               ⇒ **ตัดแถวเฉพาะจุดที่ทุกคอลัมน์ขึ้นย่อหน้าพร้อมกัน** ⇒ กติกาอยู่ที่ `จับคู่ย่อหน้า` ใน `app/utils/ย่อหน้า.ts`
                 ⇒ ⛔ ไม่เพิ่ม ไม่ลบ ไม่ย้ายจุดขึ้นย่อหน้าของฉบับไหน (ข้อ 6.2) ⇒ TCV กับ THKJV แบ่งคนละที่ก็ยังเป็นของคนแปลเอง
             ⭐ **1 ช่อง = ฉบับเดียว** ⇒ ตัวบทของคนละฉบับ ⛔ ไม่มีทางไหลมาปนกัน ⇒ เหตุผลเดิมของใบ #87 ยังอยู่ครบ -->
        <div
          v-if="มุม.จัดวาง === 'แยกตามย่อหน้า'"
          class="pk-ย่อหน้ากอง"
          :style="ช่องกริด(ก.บท, 'กอง')"
        >
          <template v-for="(กล, g) in กลุ่มย่อหน้าของบท.get(ก.บท) || []" :key="กล.กุญแจ">
          <!-- ⭐⭐ **แถวหัวข้อ** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134) ⇒ แถวย่อหน้าถัดลงมาเปิดด้วยหัวข้อในฉบับใดฉบับหนึ่ง
                 ⇒ ทุกคอลัมน์มีช่อง ⇒ ฉบับที่ไม่มีหัวข้อตรงนี้ได้ช่องว่าง ⇒ แถวย่อหน้าถัดลงมายังเริ่มระดับเดียวกัน
                 ⇒ กติกาเต็มอยู่หัวไฟล์ `app/utils/หัวข้อย่อย.ts` ⛔ ไม่จดซ้ำที่นี่ -->
          <div
            v-if="กล.หัวข้อ"
            class="pk-กลุ่มย่อหน้า pk-ช่องทั้งหมด pk-แถวหัวข้อ"
            :class="`pk-คอลัมน์-${กี่ช่องตาราง}`"
            :data-แถว="ป้ายแถว(ก.บท, g)"
            :style="ผังแถว.has(ก.บท) ? { gridRow: String(g + 1) } : undefined"
          >
            <!-- ⭐ ใบ #145 ข้อ 4 ⇒ ช่องว่างของคำเดิมที่ตำแหน่งของมัน ⇒ เหตุผลเดียวกับแถวหัวข้อของแบบแยกตามข้อ
                 ⭐ ใบ #164 ⇒ ฉบับซ้ำที่เป็นช่องในตารางได้หัวข้อของฉบับเดียวกัน (`ฐานของช่อง`) ⇒ ย่อหน้าถัดลงมาเริ่มระดับเดียวกัน -->
            <template v-for="i in ลำดับช่องทั้งหมด(กล.หัวข้อ.length)" :key="i">
            <div v-if="i < 0" class="pk-ช่องคำเดิม" aria-hidden="true" />
            <template v-else>
            <div
              v-for="ห in [กล.หัวข้อ[ฐานของช่อง(i)]]"
              :key="`หัวย่อ-${ก.บท}-${ฉบับที่แสดง[ฐานของช่อง(i)]}-${i}`"
              class="pk-ช่องหัวข้อ"
              :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && ฉบับที่แสดง[i] === ฉบับที่กำลังดู }"
              :data-ฉบับ="ฉบับที่แสดง[ฐานของช่อง(i)]"
              :data-ป้ายบนล่าง="บนล่างอยู่ && ห ? ป้ายบนล่างของตาราง(ฉบับที่แสดง[i]!, ก.บท) : undefined"
              :lang="ภาษาของชั้น[ฉบับที่แสดง[ฐานของช่อง(i)]!]"
            >
              <h3 v-if="ห" class="pk-หัวข้อย่อย">{{ ห.ตัวหนังสือ }}</h3><component :is="คู่ขนานใต้หัวข้อ" :หัว="ห" @ไปที่="(t: string) => เปิดข้ออื่น(t, ฉบับที่แสดง[ฐานของช่อง(i)]!)" />
            </div>
            </template>
            </template>
          </div>
          <div
            v-else
            class="pk-กลุ่มย่อหน้า pk-ช่องทั้งหมด"
            :class="`pk-คอลัมน์-${กี่ช่องตาราง}`"
            :data-แถว="ป้ายแถว(ก.บท, g)"
            :style="ผังแถว.has(ก.บท) ? { gridRow: String(g + 1) } : undefined"
          >
          <!-- ⛔ **ทุกแถวมีช่องครบทุกคอลัมน์ แม้ช่องนั้นว่าง** ⇒ ช่องคือตำแหน่งในผังตาราง
                 ⇒ ข้ามช่องว่างเมื่อไร ช่องของคอลัมน์ถัดไปเลื่อนมานั่งผิดคอลัมน์
               ⭐ ใบ #145 ข้อ 4 ⇒ คำเดิมของแถวย่อหน้านี้เป็นช่องหนึ่งที่ตำแหน่งของมัน (`ลำดับช่อง`) ⇒ ⛔ มีคำ ⇒ ช่องว่าง
               ⭐ ใบ #164 ⇒ ฉบับซ้ำที่เป็นช่องในตารางต่อท้าย (`ลำดับช่องทั้งหมด`) ⇒ ย่อหน้าของฉบับเดียวกัน (`ฐานของช่อง`) ⇒ กุญแจของคอลัมน์มันเอง (`ของข้อในช่อง`) -->
          <template
            v-for="i in ลำดับช่องทั้งหมด((ย่อหน้าของบท.get(ก.บท) || []).length)"
            :key="i < 0 ? 'คำเดิม' : `ย่อ-${ก.บท}-${ย่อหน้าของบท.get(ก.บท)![ฐานของช่อง(i)]!.ฉบับ}-${i}`"
          >
          <component
            :is="คำเดิมใต้แถว"
            v-if="i < 0 && คำเดิมของช่อง(ก.บท, g)"
            class="pk-ช่องคำเดิม"
            :บท="ก.บท"
            :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
            :ชั้นทั้งหมด="คำเดิมของช่อง(ก.บท, g)!"
            :ป้ายแถว="ป้ายแถว(ก.บท, g)"
            :ขนาด="มุม.ขนาดคำเดิม"
            :กาล="มุม.สัญลักษณ์กาล"
            :ช่วย="ช่วยคำเดิม"
          />
          <div v-else-if="i < 0" class="pk-ช่องคำเดิม" aria-hidden="true" />
          <template v-else>
          <div
            v-for="คอ in [ย่อหน้าของบท.get(ก.บท)![ฐานของช่อง(i)]!]"
            :key="`ย่อ-${ก.บท}-${คอ.ฉบับ}-${i}`"
            class="pk-ช่องฉบับ"
            :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && คอ.ฉบับ === ฉบับที่กำลังดู }"
            :data-ฉบับ="คอ.ฉบับ"
            :data-เงา="เงาของช่อง(i)?.เทียบ"
            :data-ป้ายบนล่าง="บนล่างอยู่ && กล.ช่อง[i]?.length ? ป้ายบนล่างของตาราง(คอ.ฉบับ, ก.บท) : undefined"
            :lang="ภาษาของชั้น[คอ.ฉบับ]"
          >
            <!-- ชื่อฉบับติดมากับเนื้อสำหรับโปรแกรมอ่านหน้าจอ ⇒ เหตุผลเดียวกับโหมดแยกตามข้อ
                 ⇒ ช่องว่าง ⛔ ไม่มีชื่อ ⇒ ⛔ ไม่ให้โปรแกรมอ่านหน้าจอได้ยินชื่อฉบับลอย ๆ -->
            <span v-if="กี่ช่องตาราง > 1 && กล.ช่อง[ฐานของช่อง(i)]?.length" class="pk-เฉพาะเสียง"
              >{{ แหล่งของชั้น[คอ.ฉบับ] }}: </span
            >
            <!-- ⭐⭐ **ฉบับที่ยังไม่มีย่อหน้า ⇒ บอกตรง ๆ** ⇒ เกณฑ์ผ่านของใบ #98 สั่งไว้เอง
                 ⇒ ⛔ **ประโยคเหตุผลมาจากซองที่เครื่องนับเอง** ⛔ ไม่ได้พิมพ์ไว้ที่นี่
                   **ทำไม** ⇒ เหตุของ LSV กับ WEB **คนละเรื่องกัน** ⇒ พิมพ์เองเมื่อไรจะรวบเป็นเรื่องเดียว
                 ⇒ ตัวบทยังขึ้นครบข้างล่าง ⇒ ผู้อ่าน ⛔ ไม่เสียอะไร นอกจาก ⛔ ไม่มีรอยย่อหน้า
                 ⭐ **ใบ #106 ⇒ ฉบับพวกนี้ยืมย่อหน้าจากฉบับอื่นได้แล้ว** ⇒ ป้ายนี้เหลือเฉพาะตอนที่ ⛔ ไม่มีฉบับไหนให้ยืม
                   ⇒ ตอนยืม ⇒ บอกที่หน้าแหล่งข้อมูลใต้ฉบับนั้น (ใบ #131 ⇒ ถอดป้ายออกจากหัวคอลัมน์แล้ว) ⇒ เหตุผลอยู่ที่ `จัดย่อหน้าของฉบับ` -->
            <p
              v-if="กล === (กลุ่มย่อหน้าของบท.get(ก.บท) || []).find((x) => !x.หัวข้อ) && คอ.ยังไม่มี"
              class="pk-ยังไม่มีย่อหน้า"
              role="note"
            >
              ฉบับ {{ แหล่งของชั้น[คอ.ฉบับ] }} ⛔ ยังไม่มีย่อหน้าให้ใช้ ⇒ {{ คอ.ยังไม่มี }}
            </p>
            <template v-for="ย in กล.ช่อง[ฐานของช่อง(i)] || []" :key="ย.กุญแจ">
            <!-- ⭐ หัวข้อที่อยู่กลางแถวย่อหน้า ⇒ อยู่ในคอลัมน์ของฉบับนั้น เหนือย่อหน้าที่มันเปิด (กติกา ③ ใน `app/utils/หัวข้อย่อย.ts`) -->
            <h3 v-if="หัวในช่องย่อหน้า(ก.บท, ฐานของช่อง(i), ย.กุญแจ)" class="pk-หัวข้อย่อย">
              {{ หัวในช่องย่อหน้า(ก.บท, ฐานของช่อง(i), ย.กุญแจ)!.ตัวหนังสือ }}
            </h3>
            <component
              :is="คู่ขนานใต้หัวข้อ"
              :หัว="หัวในช่องย่อหน้า(ก.บท, ฐานของช่อง(i), ย.กุญแจ)"
              @ไปที่="(t: string) => เปิดข้ออื่น(t, ฉบับที่แสดง[ฐานของช่อง(i)]!)"
            />
            <p
              class="pk-ย่อหน้า"
              :class="[ย.ป้าย ? `pk-ป้าย-${ย.ป้าย}` : undefined, { 'pk-เยื้อง': เยื้องบรรทัดแรก(ย.ป้าย) }]"
            ><!-- ⭐ เยื้องหรือไม่ ⇒ ตามป้ายของคนแปลอย่างเดียว ⛔ ไม่ดูว่าอยู่ใต้หัวข้อหรือเป็นก้อนแรก ⇒ เหตุผลอยู่ที่ `เยื้องบรรทัดแรก` -->
              <template v-for="(ท, k) in ย.ท่อน" :key="ท.กุญแจ"
                ><span
                  :id="i === 0 && ท.ท่อนแรก ? `ข้อ-${ท.บท}-${ท.เลข}` : undefined"
                  class="pk-ข้อไหล"
                  :data-ข้อ="`${ท.บท}:${ท.เลข}`"
                  v-bind="ของข้อในช่อง(i, `${ท.บท}:${ท.เลข}`, คอ.ฉบับ, ถือTabได้(คอ.ฉบับ) && ท.ท่อนแรก)"
                  :class="{
                    'pk-ไฟส่อง':
                      ไฟส่องติด && ท.บท === บทของข้อที่พาไป && Number(ท.เลข) === ข้อที่พาไป,
                    'pk-กำลังอ่าน': กุญแจที่เล่น === `${ท.บท}:${ท.เลข}`,
                  }"
                  ><!-- ⭐ เลขข้อขึ้นเฉพาะ **ท่อนแรก** ⇒ ท่อนที่ต่อมาเป็นข้อเดิมที่ขึ้นย่อหน้าใหม่
                         ⇒ ใส่เลขซ้ำเมื่อไร ผู้อ่านจะนึกว่าเป็นอีกข้อหนึ่ง --><sup
                    v-if="ท.ป้าย"
                    class="pk-เลขข้อ"
                    >{{ ท.ป้าย }}</sup
                  ><!-- ⭐ คำที่พระเยซูพูดใส่สีเน้น ⇒ เหตุผลอยู่ที่โหมดไหลต่อเนื่อง ⛔ ไม่จดซ้ำ --><template
                    v-for="(ชิ้น, j) in ท.ชิ้น"
                    :key="j"
                    ><!-- ⭐ เครื่องหมายเชิงอรรถ ⇒ ⛔ ไม่ใช่ปุ่ม ⇒ ข้อทั้งข้อเป็นปุ่มอยู่แล้ว (role=button) ⇒ ปุ่มซ้อนปุ่มผิด WCAG (axe nested-interactive)
                         ⇒ กดด้วยนิ้วหรือเมาส์ได้ · โปรแกรมอ่านหน้าจอข้าม ⇒ แป้นพิมพ์กับโปรแกรมอ่านหน้าจอไปทางปุ่ม *เชิงอรรถ* ในแถบข้อที่เลือก --><span
                    v-if="ชิ้น.เชิงอรรถ"
                    class="pk-เครื่องหมายเชิงอรรถ"
                    aria-hidden="true"
                    :data-เลขเชิงอรรถ="เลขเชิงอรรถ(ชิ้น.เชิงอรรถ)"
                    :data-เปิด="เชิงอรรถที่เปิด?.รายการ.includes(ชิ้น.เชิงอรรถ) ? '' : undefined"
                    data-เชิงอรรถ
                    :data-อักษร="ชิ้น.เชิงอรรถ.ป้าย"
                    @click.stop="สลับเชิงอรรถ(ชิ้น.เชิงอรรถ, $event)"
                  ></span
                  ><span v-else-if="ชิ้น.พระเยซู" class="pk-คำพระเยซู">{{ ชิ้น.ตัวหนังสือ }}</span
                    ><template v-else>{{ ชิ้น.ตัวหนังสือ }}</template></template
                  ></span
                ><!-- ⭐ ช่องไฟคั่นข้อ ⇒ ใส่ **ระหว่าง** ท่อนเท่านั้น ⛔ ไม่ใส่ท้ายย่อหน้า
                       ⇒ ท่อนสุดท้ายของย่อหน้าคือรอยผ่า ซึ่งมีช่องว่างของเจ้าของติดมาอยู่แล้ว
                  --><template v-if="k < ย.ท่อน.length - 1">{{ ' ' }}</template></template
              >
            </p>
            </template>
          </div>
          </template>
          </template>
          </div>
          <!-- ⭐ จอแคบ ⇒ คำเดิมของแถวย่อหน้านี้ต่อท้ายแถว ⇒ แถวเดียวกับจอกว้าง (ใบ #109 · #112 · #124 ข้อ 6) -->
          <component
            :is="คำเดิมใต้แถว"
            v-if="ทางคำเดิมจอแคบ === 'ใต้แถว' && ตัวจัดแถวพร้อม && คำใต้แถว.get(ก.บท)?.get(g)"
            :บท="ก.บท"
            :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
            :ชั้นทั้งหมด="คำใต้แถว.get(ก.บท)!.get(g)!"
            :ป้ายแถว="ป้ายแถว(ก.บท, g)"
            :ขนาด="มุม.ขนาดคำเดิม"
            :กาล="มุม.สัญลักษณ์กาล"
            :ช่วย="ช่วยคำเดิม"
          />
          </template>
        </div>

        <div
          v-else-if="มุม.จัดวาง === 'ไหลต่อเนื่อง'"
          class="pk-ไหล pk-ช่องทั้งหมด"
          :class="`pk-คอลัมน์-${กี่ช่องตาราง}`"
          :data-แถว="ป้ายแถว(ก.บท, 0)"
          :style="ช่องกริด(ก.บท, 'เนื้อ')"
        >
          <!-- ⭐ ใบ #145 ข้อ 4 ⇒ คำเดิมของทั้งบทเป็นช่องหนึ่งที่ตำแหน่งของมัน (`ลำดับช่อง`) ⇒ กล่องทั้งบทแบบท้ายบทของจอแคบ
               ⭐ ใบ #164 ⇒ ฉบับซ้ำที่เป็นช่องในตารางต่อท้าย ⇒ ตัวบทของช่องฐาน (`ฐานของช่อง`) ⇒ กุญแจของคอลัมน์มันเอง (`ของข้อในช่อง`) -->
          <template
            v-for="i in ลำดับช่องทั้งหมด(ฉบับที่แสดง.length)"
            :key="i < 0 ? `ไหล-${ก.บท}-คำเดิม` : `ไหล-${ก.บท}-${ฉบับที่แสดง[ฐานของช่อง(i)]}-${i}`"
          >
          <component
            :is="คำเดิมใต้แถว"
            v-if="i < 0 && คำเดิมของช่อง(ก.บท, 0)"
            class="pk-ช่องคำเดิม"
            :บท="ก.บท"
            :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
            :ชั้นทั้งหมด="คำเดิมของช่อง(ก.บท, 0)!"
            :ป้ายแถว="ป้ายแถว(ก.บท, 0)"
            :ขนาด="มุม.ขนาดคำเดิม"
            :กาล="มุม.สัญลักษณ์กาล"
            ทั้งบท
            :ช่วย="ช่วยคำเดิม"
          />
          <div v-else-if="i < 0" class="pk-ช่องคำเดิม" aria-hidden="true" />
          <template v-else>
          <template v-for="ฉ in [ฉบับที่แสดง[ฐานของช่อง(i)]!]" :key="ฉ">
          <!-- ⭐⭐ **คอลัมน์ที่มีหัวข้อในบทนี้ ⇒ ผ่าเป็นตอน ⇒ หัวข้อ `h3` คั่นระหว่างตอน** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134)
                 ⇒ ไหลต่อเนื่อง ⛔ ไม่มีแถวรายข้อ ⇒ หัวข้อไหลไปกับคอลัมน์ของตัวเอง (กติกา ③ ใน `app/utils/หัวข้อย่อย.ts`)
                 ⇒ ⛔ `h3` อยู่ใน `<p>` ไม่ได้ ⇒ กล่องของคอลัมน์จึงเป็น `div` ที่ถือ `<p>` ทีละตอน
                 ⇒ คอลัมน์ที่ไม่มีหัวข้อ หรือผู้อ่านปิดสวิตช์ ⇒ กล่อง `<p>` เดียวแบบเดิมทุกไบต์ ⇒ เนื้อความต่อกันเป็นพืดเดียว (ข้อ 11) -->
          <div
            v-if="ตอนไหลของบท.get(ก.บท)?.[ฐานของช่อง(i)]"
            class="pk-ช่องฉบับ pk-ไหลมีหัวข้อ"
            :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && ฉ === ฉบับที่กำลังดู }"
            :data-ฉบับ="ฉ"
            :data-เงา="เงาของช่อง(i)?.เทียบ"
            :data-ป้ายบนล่าง="บนล่างอยู่ ? ป้ายบนล่างของตาราง(ฉ, ก.บท) : undefined"
            :lang="ภาษาของชั้น[ฉ]"
          >
            <template v-for="(ย, k) in ตอนไหลของบท.get(ก.บท)![ฐานของช่อง(i)]!.ย่อหน้า" :key="ย.กุญแจ">
              <h3 v-if="ตอนไหลของบท.get(ก.บท)![ฐานของช่อง(i)]!.หัว[k]" class="pk-หัวข้อย่อย">
                {{ ตอนไหลของบท.get(ก.บท)![ฐานของช่อง(i)]!.หัว[k]!.ตัวหนังสือ }}
              </h3>
              <component
                :is="คู่ขนานใต้หัวข้อ"
                :หัว="ตอนไหลของบท.get(ก.บท)![ฐานของช่อง(i)]!.หัว[k]"
                @ไปที่="(t: string) => เปิดข้ออื่น(t, ฉ)"
              />
              <p class="pk-ตอนไหล">
                <span v-if="k === 0 && กี่ช่องตาราง > 1" class="pk-เฉพาะเสียง"
                  >{{ แหล่งของชั้น[ฉ] }}: </span
                ><template v-for="ท in ย.ท่อน" :key="ท.กุญแจ"
                  ><span
                    :id="i === 0 && ท.ท่อนแรก ? `ข้อ-${ท.บท}-${ท.เลข}` : undefined"
                    class="pk-ข้อไหล"
                    :data-ข้อ="`${ท.บท}:${ท.เลข}`"
                    v-bind="ของข้อในช่อง(i, `${ท.บท}:${ท.เลข}`, ฉ, ถือTabได้(ฉ) && ท.ท่อนแรก)"
                    :class="{
                      'pk-ไฟส่อง':
                        ไฟส่องติด && ท.บท === บทของข้อที่พาไป && Number(ท.เลข) === ข้อที่พาไป,
                      'pk-กำลังอ่าน': กุญแจที่เล่น === `${ท.บท}:${ท.เลข}`,
                    }"
                    ><sup v-if="ท.ป้าย" class="pk-เลขข้อ">{{ ท.ป้าย }}</sup
                    ><template v-for="(ชิ้น, j) in ท.ชิ้น" :key="j"
                      ><!-- ⭐ เครื่องหมายเชิงอรรถ ⇒ ⛔ ไม่ใช่ปุ่ม ⇒ ข้อทั้งข้อเป็นปุ่มอยู่แล้ว (role=button) ⇒ ปุ่มซ้อนปุ่มผิด WCAG (axe nested-interactive)
                         ⇒ กดด้วยนิ้วหรือเมาส์ได้ · โปรแกรมอ่านหน้าจอข้าม ⇒ แป้นพิมพ์กับโปรแกรมอ่านหน้าจอไปทางปุ่ม *เชิงอรรถ* ในแถบข้อที่เลือก --><span
                    v-if="ชิ้น.เชิงอรรถ"
                    class="pk-เครื่องหมายเชิงอรรถ"
                    aria-hidden="true"
                    :data-เลขเชิงอรรถ="เลขเชิงอรรถ(ชิ้น.เชิงอรรถ)"
                    :data-เปิด="เชิงอรรถที่เปิด?.รายการ.includes(ชิ้น.เชิงอรรถ) ? '' : undefined"
                    data-เชิงอรรถ
                    :data-อักษร="ชิ้น.เชิงอรรถ.ป้าย"
                    @click.stop="สลับเชิงอรรถ(ชิ้น.เชิงอรรถ, $event)"
                  ></span
                  ><span v-else-if="ชิ้น.พระเยซู" class="pk-คำพระเยซู">{{ ชิ้น.ตัวหนังสือ }}</span
                      ><template v-else>{{ ชิ้น.ตัวหนังสือ }}</template></template
                    ></span
                  >{{ ' ' }}</template
                >
              </p>
            </template>
          </div>
          <p
            v-else
            class="pk-ช่องฉบับ"
            :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && ฉ === ฉบับที่กำลังดู }"
            :data-ฉบับ="ฉ"
            :data-เงา="เงาของช่อง(i)?.เทียบ"
            :data-ป้ายบนล่าง="บนล่างอยู่ ? ป้ายบนล่างของตาราง(ฉ, ก.บท) : undefined"
            :lang="ภาษาของชั้น[ฉ]"
          >
            <!-- ชื่อฉบับติดมากับเนื้อสำหรับโปรแกรมอ่านหน้าจอ ⇒ เหตุผลเดียวกับโหมดแยกตามข้อ -->
            <span v-if="กี่ช่องตาราง > 1" class="pk-เฉพาะเสียง"
              >{{ แหล่งของชั้น[ฉ] }}: </span
            ><template v-for="x in ก.แถว" :key="x.กุญแจ"
              ><span
                v-if="x.ช่อง[ฐานของช่อง(i)]?.เนื้อ"
                :id="i === 0 ? `ข้อ-${x.บท}-${x.เลข}` : undefined"
                class="pk-ข้อไหล"
                :data-ข้อ="`${x.บท}:${x.เลข}`"
                v-bind="ของข้อในช่อง(i, `${x.บท}:${x.เลข}`, ฉ, ถือTabได้(ฉ))"
                :class="{
                  'pk-ไฟส่อง':
                    ไฟส่องติด && x.บท === บทของข้อที่พาไป && Number(x.เลข) === ข้อที่พาไป,
                  'pk-กำลังอ่าน': กุญแจที่เล่น === `${x.บท}:${x.เลข}`,
                }"
                ><sup class="pk-เลขข้อ">{{ x.ป้าย }}</sup
                ><!-- ⭐ คำที่พระเยซูพูดใส่สีเน้น ⇒ เจ้าของช่วงคือ `tools/สร้างคำพระเยซู.py`
                       ⛔ ฉบับที่เจ้าของไม่ได้ทำเครื่องหมายไว้ ⇒ ได้ชิ้นเดียวที่ `พระเยซู` เป็นเท็จ
                       ⇒ **ตัวหนังสือเท่าเดิมทุกตัวอักษร** ⇒ ต่างแค่มีหรือไม่มีกล่องครอบ --><template
                  v-for="(ชิ้น, j) in x.ช่อง[ฐานของช่อง(i)]?.ชิ้น || []"
                  :key="j"
                  ><!-- ⭐ เครื่องหมายเชิงอรรถ ⇒ ⛔ ไม่ใช่ปุ่ม ⇒ ข้อทั้งข้อเป็นปุ่มอยู่แล้ว (role=button) ⇒ ปุ่มซ้อนปุ่มผิด WCAG (axe nested-interactive)
                         ⇒ กดด้วยนิ้วหรือเมาส์ได้ · โปรแกรมอ่านหน้าจอข้าม ⇒ แป้นพิมพ์กับโปรแกรมอ่านหน้าจอไปทางปุ่ม *เชิงอรรถ* ในแถบข้อที่เลือก --><span
                    v-if="ชิ้น.เชิงอรรถ"
                    class="pk-เครื่องหมายเชิงอรรถ"
                    aria-hidden="true"
                    :data-เลขเชิงอรรถ="เลขเชิงอรรถ(ชิ้น.เชิงอรรถ)"
                    :data-เปิด="เชิงอรรถที่เปิด?.รายการ.includes(ชิ้น.เชิงอรรถ) ? '' : undefined"
                    data-เชิงอรรถ
                    :data-อักษร="ชิ้น.เชิงอรรถ.ป้าย"
                    @click.stop="สลับเชิงอรรถ(ชิ้น.เชิงอรรถ, $event)"
                  ></span
                  ><span v-else-if="ชิ้น.พระเยซู" class="pk-คำพระเยซู">{{ ชิ้น.ตัวหนังสือ }}</span
                  ><template v-else>{{ ชิ้น.ตัวหนังสือ }}</template></template
                ></span
              >{{ ' ' }}</template
            >
          </p>
          </template>
          </template>
          </template>
        </div>

        <template v-else>
          <!-- ================= แยกตามข้อ — 1 ข้อ 1 แถว เทียบบรรทัดกันได้ =================
               ⭐ **ไฟส่อง** ⇒ ข้อที่ลิงก์หรือปุ่มพามา สว่างขึ้นให้ตาหาเจอ **แล้วจางไปเอง**
               ⛔ ไม่ค้างถาวร — ค้างเมื่อไรมันบอกกลาย ๆ ว่าข้อนี้พิเศษกว่าที่เหลือ
                  ซึ่งย้อนแย้งกับ *ไม่มีกำแพง* (เหตุผลอยู่ที่ `docs/design/แนวคิดออกแบบ.md`) -->
          <template v-for="(x, r) in ก.แถว" :key="x.กุญแจ">
          <div
            :id="`ข้อ-${x.บท}-${x.เลข}`"
            class="pk-ข้อ"
            :data-ข้อ="`${x.บท}:${x.เลข}`"
            :data-แถว="ป้ายแถว(ก.บท, r)"
            :style="ช่องกริด(ก.บท, 'เนื้อ', r)"
            :class="{
              'pk-ไฟส่อง':
                ไฟส่องติด && x.บท === บทของข้อที่พาไป && Number(x.เลข) === ข้อที่พาไป,
              'pk-กำลังอ่าน': กุญแจที่เล่น === `${x.บท}:${x.เลข}`,
              'pk-มีหัวข้อ': หัวข้อของแถว.get(ก.บท)?.has(x.เลข),
            }"
          >
            <!-- ⭐⭐ **แถวหัวข้อ ⇒ อยู่ในกล่องของข้อ เหนือตัวบท** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/134)
                   ⇒ ฉบับใดฉบับหนึ่งเริ่มหัวข้อที่ข้อนี้ ⇒ ทุกคอลัมน์มีช่องในแถวนี้ ⇒ ฉบับที่ไม่มีหัวข้อได้ช่องว่าง
                   ⇒ ตัวบทของข้อนี้จึงยังเริ่มระดับเดียวกันทุกคอลัมน์ ⇒ กติกาเต็มอยู่หัวไฟล์ `app/utils/หัวข้อย่อย.ts`
                 ⭐ **ทำไมอยู่ในกล่องข้อ ⛔ ไม่ใช่แถวของตัวเอง** ⇒ ตารางแถวของคอลัมน์คำเดิม (`ผังแถว`) นับ 1 ข้อ 1 แถว
                   ⇒ อยู่ในกล่องข้อ ⇒ แถวของคำเดิมยังตรงกับข้อเดิมโดย ⛔ ไม่ต้องแก้ผัง
                 ⭐ อยู่ **ก่อน** เลขข้อในโครงหน้า ⇒ โปรแกรมอ่านหน้าจอได้ยินหัวข้อก่อนตัวบท ⇒ ลำดับเดียวกับที่ตาเห็น (SC 1.3.2) -->
            <div
              v-if="หัวข้อของแถว.get(ก.บท)?.get(x.เลข)"
              class="pk-ช่องทั้งหมด pk-แถวหัวข้อ"
              :class="`pk-คอลัมน์-${กี่ช่องตาราง}`"
            >
              <!-- ⭐ ใบ #145 ข้อ 4 ⇒ คำเดิมเป็นช่องในตาราง ⇒ แถวหัวข้อมีช่องว่างของมันที่ตำแหน่งเดียวกัน ⇒ หัวข้อ ⛔ เลื่อนไปนั่งเหนือคำเดิม
                   ⭐ ใบ #164 ⇒ ฉบับซ้ำที่เป็นช่องในตารางได้หัวข้อของฉบับเดียวกัน ⇒ ตัวบทของข้อนี้ยังเริ่มระดับเดียวกันทุกคอลัมน์ -->
              <template v-for="i in ลำดับช่องทั้งหมด(ฉบับที่แสดง.length)" :key="i">
              <div v-if="i < 0" class="pk-ช่องคำเดิม" aria-hidden="true" />
              <template v-else>
              <div
                v-for="ห in [หัวข้อของแถว.get(ก.บท)!.get(x.เลข)![ฐานของช่อง(i)]]"
                :key="`หัว-${x.กุญแจ}-${ฉบับที่แสดง[ฐานของช่อง(i)]}-${i}`"
                class="pk-ช่องหัวข้อ"
                :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && ฉบับที่แสดง[i] === ฉบับที่กำลังดู }"
                :data-ฉบับ="ฉบับที่แสดง[ฐานของช่อง(i)]"
                :data-ป้ายบนล่าง="บนล่างอยู่ && ห ? ป้ายบนล่างของตาราง(ฉบับที่แสดง[i]!, x.บท) : undefined"
                :lang="ภาษาของชั้น[ฉบับที่แสดง[ฐานของช่อง(i)]!]"
              >
                <h3 v-if="ห" class="pk-หัวข้อย่อย">{{ ห.ตัวหนังสือ }}</h3><component :is="คู่ขนานใต้หัวข้อ" :หัว="ห" @ไปที่="(t: string) => เปิดข้ออื่น(t, ฉบับที่แสดง[ฐานของช่อง(i)]!)" />
              </div>
              </template>
              </template>
            </div>
            <!-- ⭐⭐ ซ่อนเลขคือ **ซ่อนจากตา ⛔ ไม่ใช่เอาออกจากหน้า**
                 ⇒ WCAG SC 1.3.1 Info and Relationships (ระดับ A) -->
            <sup class="pk-เลขข้อ">{{ x.ป้าย }}</sup>
            <div class="pk-ช่องทั้งหมด" :class="`pk-คอลัมน์-${กี่ช่องตาราง}`">
              <!-- ⭐⭐ **ชื่อฉบับติดอยู่ทุกช่อง แต่ ⛔ ซ่อนจากตา** (ใบงาน v3/phrakham#76)
                   ⇒ ตาเห็นชื่อฉบับจาก **หัวคอลัมน์หนึบ** (จอกว้าง) หรือ **ปุ่ม `ฉบับ`** (จอแคบ)
                   ⇒ ⛔ แต่โปรแกรมอ่านหน้าจอ ⛔ ไม่เห็นคอลัมน์ ⇒ มันต้องได้ยินชื่อฉบับติดมากับเนื้อ
                     ⇒ WCAG SC 1.3.1 Info and Relationships (ระดับ A)
                   ⛔ **ไม่ทำเป็นหัวเรื่อง `<h3>`** ⇒ 30 ข้อ × 4 ฉบับ = 120 หัวเรื่อง
                     ⇒ คนที่กระโดดอ่านด้วยหัวเรื่องจะพัง ⇒ **ทั้ง G และ N ค้านข้อนี้ตรงกัน 7 ก.ย. 2569**
                   ⭐ **ชื่อเต็ม ⛔ ไม่ใช่ชื่อย่อ** ⇒ โปรแกรมอ่านหน้าจอสะกด `TCV` ทีละตัวอักษร
                 ⭐ ใบ #145 ข้อ 4 ⇒ จอกว้างที่วางทุกคอลัมน์ข้างกันไม่พอ ⇒ คำเดิมของข้อนี้เป็นช่องหนึ่งที่ตำแหน่งของมัน (`ลำดับช่อง`)
                   ⇒ ข้อที่ไม่มีคำเดิม ⇒ ช่องว่าง ⇒ ช่องถัดไป ⛔ เลื่อนมานั่งผิดคอลัมน์
                 ⭐ ใบ #164 ⇒ ฉบับซ้ำที่เป็นช่องในตารางต่อท้าย ⇒ ตัวบทของช่องฐาน (`ฐานของช่อง`) ⇒ กุญแจของคอลัมน์มันเอง (`ของข้อในช่อง`) -->
              <template v-for="i in ลำดับช่องทั้งหมด(x.ช่อง.length)" :key="i < 0 ? 'คำเดิม' : `${x.ช่อง[ฐานของช่อง(i)]!.ฉบับ}-${i}`">
              <component
                :is="คำเดิมใต้แถว"
                v-if="i < 0 && คำเดิมของช่อง(ก.บท, r)"
                class="pk-ช่องคำเดิม"
                :บท="ก.บท"
                :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
                :ชั้นทั้งหมด="คำเดิมของช่อง(ก.บท, r)!"
                :ป้ายแถว="ป้ายแถว(ก.บท, r)"
                :ขนาด="มุม.ขนาดคำเดิม"
                :กาล="มุม.สัญลักษณ์กาล"
                :ช่วย="ช่วยคำเดิม"
              />
              <div v-else-if="i < 0" class="pk-ช่องคำเดิม" aria-hidden="true" />
              <template v-else>
              <p
                v-for="ช in [x.ช่อง[ฐานของช่อง(i)]!]"
                :key="ช.ฉบับ"
                class="pk-ช่องฉบับ"
                :class="{ 'pk-ช่องที่อ่าน': !เงาของช่อง(i) && ช.ฉบับ === ฉบับที่กำลังดู }"
                :data-ฉบับ="ช.ฉบับ"
                :data-เงา="เงาของช่อง(i)?.เทียบ"
                :data-ป้ายบนล่าง="บนล่างอยู่ ? ป้ายบนล่างของตาราง(ช.ฉบับ, x.บท) : undefined"
                :lang="ภาษาของชั้น[ช.ฉบับ]"
                v-bind="ช.เนื้อ ? ของข้อในช่อง(i, `${x.บท}:${x.เลข}`, ช.ฉบับ, ถือTabได้(ช.ฉบับ)) : {}"
              >
                <span v-if="กี่ช่องตาราง > 1" class="pk-เฉพาะเสียง"
                  >{{ แหล่งของชั้น[ช.ฉบับ] }}: </span
                ><!-- ⭐ เหตุผลของการตัดชิ้น อยู่ที่โหมดไหลต่อเนื่องข้างบน ⛔ ไม่จดซ้ำ --><template
                  v-for="(ชิ้น, j) in ช.ชิ้น"
                  :key="j"
                  ><!-- ⭐ เครื่องหมายเชิงอรรถ ⇒ ⛔ ไม่ใช่ปุ่ม ⇒ ข้อทั้งข้อเป็นปุ่มอยู่แล้ว (role=button) ⇒ ปุ่มซ้อนปุ่มผิด WCAG (axe nested-interactive)
                         ⇒ กดด้วยนิ้วหรือเมาส์ได้ · โปรแกรมอ่านหน้าจอข้าม ⇒ แป้นพิมพ์กับโปรแกรมอ่านหน้าจอไปทางปุ่ม *เชิงอรรถ* ในแถบข้อที่เลือก --><span
                    v-if="ชิ้น.เชิงอรรถ"
                    class="pk-เครื่องหมายเชิงอรรถ"
                    aria-hidden="true"
                    :data-เลขเชิงอรรถ="เลขเชิงอรรถ(ชิ้น.เชิงอรรถ)"
                    :data-เปิด="เชิงอรรถที่เปิด?.รายการ.includes(ชิ้น.เชิงอรรถ) ? '' : undefined"
                    data-เชิงอรรถ
                    :data-อักษร="ชิ้น.เชิงอรรถ.ป้าย"
                    @click.stop="สลับเชิงอรรถ(ชิ้น.เชิงอรรถ, $event)"
                  ></span
                  ><span v-else-if="ชิ้น.พระเยซู" class="pk-คำพระเยซู">{{ ชิ้น.ตัวหนังสือ }}</span
                  ><template v-else>{{ ชิ้น.ตัวหนังสือ }}</template></template
                >
              </p>
              </template>
              </template>
            </div>
          </div>
          <!-- ⭐⭐ **จอแคบ ⇒ คำเดิมของข้อนี้ต่อท้ายข้อนี้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/124 ข้อ 5)
                 ⇒ เริ่มหลังตัวบทของทุกฉบับในแถวจบ (ขนานกันก็อยู่ในแถวเดียวกัน) ⇒ จบก่อนข้อถัดไปเริ่ม
                 ⇒ ข้อที่ไม่มีคำเดิม ⇒ ⛔ ไม่มีกล่อง · ข้อเดิมหลายข้อลงแถวเดียว ⇒ อยู่กล่องเดียวกัน (ข้อ 5.2) -->
          <component
            :is="คำเดิมใต้แถว"
            v-if="ทางคำเดิมจอแคบ === 'ใต้แถว' && ตัวจัดแถวพร้อม && คำใต้แถว.get(ก.บท)?.get(r)"
            :บท="ก.บท"
            :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
            :ชั้นทั้งหมด="คำใต้แถว.get(ก.บท)!.get(r)!"
            :ป้ายแถว="ป้ายแถว(ก.บท, r)"
            :ขนาด="มุม.ขนาดคำเดิม"
            :กาล="มุม.สัญลักษณ์กาล"
            :ช่วย="ช่วยคำเดิม"
          />
          <!-- ⭐⭐ **บนล่าง ⇒ ข้อของคอลัมน์คนละเล่มคนละบทคู่ต่อท้ายข้อนี้** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30310 ข้อ 3)
                 ⇒ มัทธิว 17:1 ⇒ มาระโก 9:1 ⇒ 17:2 ⇒ 9:2 ⇒ คู่ตามลำดับข้อในบท ⛔ ไม่ใช่เลขข้อ ⇒ ⛔ ไม่อ้างว่าข้อไหนตรงกับข้อไหน (us07)
                 ⇒ คู่กับบทที่คอลัมน์แรกถูกพามาเท่านั้น (`บทจับคู่`) ⇒ บทอื่นที่เลื่อนต่อมาเดินคนเดียว
                 ⇒ ป้ายเล็กบอกเล่ม บท และฉบับทุกข้อ (ข้อ 3.3) ⇒ ลำดับที่ฟังตรงกับลำดับที่เห็น (SC 1.3.2) -->
          <template v-if="จับคู่บนล่าง && ก.บท === บทจับคู่">
            <!-- ⛔ คอลัมน์คนละบทยังโหลดไม่เสร็จ หรือไม่มีในฉบับนั้น ⇒ **บอกตรง ๆ ใต้ข้อแรก** ⛔ ไม่เงียบ ⇒ ประโยคเดียวกับกล่องของมัน -->
            <template v-if="r === 0">
              <p
                v-for="ต in คอลัมน์เทียบที่แสดง.filter((x) => x.ยังไม่มี)"
                :key="`ยังไม่มี-${ต.กุญแจ}`"
                class="pk-ยังไม่มีตอนเทียบ pk-ข้อคู่"
                role="note"
                :data-ป้ายบนล่าง="ป้ายบนล่างของเทียบ(ต)"
              >
                {{ ต.ยังไม่มี }}
              </p>
              <!-- ⭐ ใบ #143 ⇒ ข้อของคอลัมน์นี้ที่อยู่ก่อนข้อที่เลือก แต่บทคู่ไม่มีแถวให้คู่แล้ว ⇒ ต่อท้ายแถวแรก (`เลื่อนคู่`) -->
              <component
                :is="เนื้อตอนเทียบ"
                @ไปที่="(x: { ที่อยู่: string; ต: object }) => เปิดข้ออื่น(x.ที่อยู่, (x.ต as ก้อนเทียบ).ฉบับ)"
                @คำ="(x: { e: Event; ต: object; บท: number; ข้อ: string; i: number; คำ: คำเดิม }) => กดคำเทียบ(x.e, x.ต as ก้อนเทียบ, x.บท, x.ข้อ, x.i, x.คำ)"
                v-for="ค in แถวก่อนของเทียบ()"
                :key="`ก่อน-${ค.ต.กุญแจ}-${ค.r}`"
                :ต="ค.ต"
                :จัดวาง="มุม.จัดวาง"
                :เล่มของหน้า="รหัสเล่ม"
                :เลือก="ตัวเลือกของเทียบ(ค.ต, false)"
                :กุญแจที่เล่น="กุญแจที่เล่น"
                :แถวที่="ค.r"
                :ป้าย="ป้ายบนล่างของเทียบ(ค.ต)"
              />
            </template>
            <component
              :is="เนื้อตอนเทียบ"
                @ไปที่="(x: { ที่อยู่: string; ต: object }) => เปิดข้ออื่น(x.ที่อยู่, (x.ต as ก้อนเทียบ).ฉบับ)"
              @คำ="(x: { e: Event; ต: object; บท: number; ข้อ: string; i: number; คำ: คำเดิม }) => กดคำเทียบ(x.e, x.ต as ก้อนเทียบ, x.บท, x.ข้อ, x.i, x.คำ)"
              v-for="(ต, ti) in คอลัมน์เทียบที่แสดง"
              :key="`คู่-${ต.กุญแจ}-${r}`"
              :ต="ต"
              :จัดวาง="มุม.จัดวาง"
              :เล่มของหน้า="รหัสเล่ม"
              :เลือก="ตัวเลือกของเทียบ(ต, false)"
              :กุญแจที่เล่น="กุญแจที่เล่น"
              :แถวที่="r + (เลื่อนคู่[ti] ?? 0)"
              :ป้าย="ป้ายบนล่างของเทียบ(ต)"
            />
            <!-- ⭐ บทของคอลัมน์แรกหมดก่อน ⇒ ข้อที่เหลือของคอลัมน์คนละบทเดินต่อคนเดียวจนจบ (ข้อ 3.2) -->
            <template v-if="r === ก.แถว.length - 1">
              <component
                :is="เนื้อตอนเทียบ"
                @ไปที่="(x: { ที่อยู่: string; ต: object }) => เปิดข้ออื่น(x.ที่อยู่, (x.ต as ก้อนเทียบ).ฉบับ)"
                @คำ="(x: { e: Event; ต: object; บท: number; ข้อ: string; i: number; คำ: คำเดิม }) => กดคำเทียบ(x.e, x.ต as ก้อนเทียบ, x.บท, x.ข้อ, x.i, x.คำ)"
                v-for="ค in แถวเกินของเทียบ(ก.แถว.length)"
                :key="`เกิน-${ค.ต.กุญแจ}-${ค.r}`"
                :ต="ค.ต"
                :จัดวาง="มุม.จัดวาง"
                :เล่มของหน้า="รหัสเล่ม"
                :เลือก="ตัวเลือกของเทียบ(ค.ต, false)"
                :กุญแจที่เล่น="กุญแจที่เล่น"
                :แถวที่="ค.r"
                :ป้าย="ป้ายบนล่างของเทียบ(ค.ต)"
              />
            </template>
          </template>
          </template>
        </template>
        <!-- ⭐⭐ **ไหลต่อเนื่องบนจอแคบ ⇒ ก้อนคำทั้งบทอยู่ท้ายบท ⛔ ไม่ใช่ต้นบท** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/124 ข้อ 7 · 8)
               ⇒ ทั้งบทเป็นแถวเดียว (ใบ #112 ข้อ 10) ⇒ แทรกทีละข้อไม่ได้ ⇒ อยู่ท้ายบท = คำเดิมของข้อ n ถูกอ่านหลังตัวบทข้อ n เสมอ
               ⇒ ป้ายใต้ชื่อบทพามาที่นี่ (`#คำเดิม-<บท>`) ⇒ เป็น `section` ที่มีชื่อเหมือนก้อนของจอกว้าง -->
        <component
          :is="คำเดิมใต้แถว"
          v-if="มุม.จัดวาง === 'ไหลต่อเนื่อง' && ทางคำเดิมจอแคบ === 'ท้ายบท' && ตัวจัดแถวพร้อม && คำใต้แถว.get(ก.บท)?.get(0)"
          :บท="ก.บท"
          :ชื่อเล่ม="เล่มนี้.ชื่อไทย"
          :ชั้นทั้งหมด="คำใต้แถว.get(ก.บท)!.get(0)!"
          :ป้ายแถว="ป้ายแถว(ก.บท, 0)"
          :ขนาด="มุม.ขนาดคำเดิม"
          :กาล="มุม.สัญลักษณ์กาล"
          :ช่วย="ช่วยคำเดิม"
          ทั้งบท
        />
        <!-- ⭐⭐ **บนล่าง แบบไหลต่อเนื่องหรือแยกตามย่อหน้า ⇒ คอลัมน์คนละเล่มคนละบทต่อท้ายบทคู่ทั้งบท** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131#note_30367)
               ⇒ สองแบบนี้ไม่มีแถวรายข้อให้คู่ ⇒ ตารางของมันเองก็ซ้อนทั้งบทต่อฉบับอยู่แล้ว ⇒ คอลัมน์คนละบทซ้อนต่อแบบเดียวกัน
               ⇒ มัทธิว 17 ทั้งบท ⇒ มาระโก 9 ทั้งบท ⇒ มัทธิว 18 ⇒ ป้ายเล็กบอกเล่ม บท และฉบับ ⇒ เหตุผลของการเลือกอยู่ในคำขอรวมของชิ้นนี้ -->
        <template v-if="จับคู่บนล่าง && มุม.จัดวาง !== 'แยกตามข้อ' && ก.บท === บทจับคู่">
          <section
            v-for="ต in คอลัมน์เทียบที่แสดง"
            :key="`บทคู่-${ต.กุญแจ}`"
            class="pk-บทคู่"
            :class="{ 'pk-ซ่อนเลข': !มุม.แสดงเลข }"
            :aria-label="`ตอนที่เอามาเทียบ ${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท} ฉบับ ${ต.ชื่อฉบับ}`"
          >
            <p v-if="ต.ยังไม่มี" class="pk-ยังไม่มีตอนเทียบ" role="note">{{ ต.ยังไม่มี }}</p>
            <component
              :is="เนื้อตอนเทียบ"
                @ไปที่="(x: { ที่อยู่: string; ต: object }) => เปิดข้ออื่น(x.ที่อยู่, (x.ต as ก้อนเทียบ).ฉบับ)"
              @คำ="(x: { e: Event; ต: object; บท: number; ข้อ: string; i: number; คำ: คำเดิม }) => กดคำเทียบ(x.e, x.ต as ก้อนเทียบ, x.บท, x.ข้อ, x.i, x.คำ)"
              :ต="ต"
              :จัดวาง="มุม.จัดวาง"
              :เล่มของหน้า="รหัสเล่ม"
              :เลือก="ตัวเลือกของเทียบ(ต, false)"
              :กุญแจที่เล่น="กุญแจที่เล่น"
              :ป้าย="ป้ายบนล่างของเทียบ(ต)"
            />
          </section>
        </template>
      </template>
    </div>

    <!-- ⭐ ปลายม้วน — เลื่อนมาใกล้ตรงนี้เมื่อไร บทถัดไปถูกต่อเข้ามาเอง -->
    <div ref="ปลายม้วน" class="pk-ปลายม้วน">
      <!-- ⭐⭐ **กำลังดูช่วง ⇒ ลิงก์ *อ่านทั้งบท* ใต้ช่วงเสมอ** (ใบงาน #102 ข้อ 19.2 · พี่เอมเคาะ 24 ต.ค. 2569)
             ⇒ ท่าเดียวกับ *Read full chapter* ของ Bible Gateway และ *Read Mark 10* ของ YouVersion
             ⇒ **เป็นทั้งทางออก และตัวบอกว่ากำลังดูแค่บางช่วง** ⇒ จึงบอกชื่อเล่มกับบทด้วยตัวหนังสือที่ตาเห็น
           ⭐ **เป็นลิงก์จริง `<a href>`** ⇒ โค้ดของเว็บโหลดไม่สำเร็จก็ยังกดไปได้ · คลิกขวาคัดลอกได้
             ⇒ ที่อยู่ปลายทาง ⛔ ไม่มี `r` ⇒ ได้ทั้งเล่มแบบเลือกแค่ข้อเริ่ม ยืนที่ข้อต้นช่วง -->
      <p v-if="ช่วงที่ฟัง" class="pk-อ่านทั้งบท">
        <a
          :href="ที่อยู่อ่านทั้งบท"
          data-ลิงก์="อ่านทั้งบท"
          @click.prevent="อ่านทั้งบท()"
          >อ่านทั้งบท · {{ เล่มนี้.ชื่อไทย }} {{ บทของช่วง }}</a
        >
      </p>
      <p v-else-if="กำลังต่อ" class="pk-กำลังต่อ" role="status">กำลังต่อบทถัดไป…</p>
      <p v-else-if="!บทถัด" class="pk-จบเล่ม">
        จบ{{ เล่มนี้.ชื่อไทย }}แล้ว · เลือกเล่มต่อไปได้จากปุ่ม “เปลี่ยนตอน”
      </p>
    </div>
    </div>

      <!-- ================= ตอนที่เอามาเทียบ — คนละเล่มหรือคนละบทก็ได้ =================
           ⭐⭐ **กล่องไหลของตัวเอง ⛔ ไม่เข้าผังเทียบบรรทัดของคอลัมน์แรก**
             ⇒ **เกณฑ์ผ่านของ us07 ห้ามจับคู่เลขข้ามคอลัมน์** ⇒ *วางเคียงกันได้โดย ⛔ ไม่อ้างว่า
               ข้อไหนคู่กับข้อไหน* ⇒ ยัดเข้าผังเทียบบรรทัดเมื่อไร **ผังนั้นเองคือคำอ้างนั้น**
             ⇒ ท่าเดียวกับกล่องชั้นคำภาษาเดิมของใบ v3/phrakham#95 ⛔ ไม่ได้คิดท่าใหม่
           ⭐ **เป็น `<section>` ที่มีชื่อของตัวเอง** ⇒ โปรแกรมอ่านหน้าจอรู้ว่าคอลัมน์ไหนคือที่ไหน
             ⇒ **WCAG 2.2 SC 1.3.1 Info and Relationships (ระดับ A)**
           ⛔ **`lang` ของตัวบทเป็นของฉบับนั้น** ⇒ SC 3.1.2 Language of Parts (ระดับ AA)
             ⇒ ⛔ แต่หัวคอลัมน์เป็นภาษาไทยเสมอ เพราะชื่อเล่มของเราเป็นภาษาไทย (ดูหัวคอลัมน์ข้างล่าง) -->
      <!-- ⭐ ใบ #131 note_30367 ⇒ บนล่างจอแคบ ⇒ ⛔ ไม่มีกล่องนี้ ⇒ หัวอยู่แถวหัวที่หนึบ ⇒ ตัวบทคู่ทีละข้อในฝั่งหลัก
             ⇒ ทีละฉบับ ⇒ เห็นเฉพาะกล่องที่เลือกอ่าน (`pk-ตอนที่อ่าน`) ⇒ กฎอยู่ที่ `main.css` หัวข้อ *การวางคอลัมน์บนจอแคบ* -->
      <!-- ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/164 ⇒ คอลัมน์ฉบับซ้ำที่อยู่ที่เดียวกับหน้า ⇒ เป็นช่องในตาราง (`เงาในตาราง`) ⇒ ⛔ มีกล่องนี้ -->
      <template v-for="(ต, i) in จับคู่บนล่าง ? [] : คอลัมน์เทียบที่แสดง" :key="ต.กุญแจ">
      <section
        v-if="!เงาในตาราง.includes(i)"
        class="pk-ตอนเทียบ"
        :data-เทียบ="i"
        :class="{ 'pk-ซ่อนเลข': !มุม.แสดงเลข, 'pk-ตอนที่อ่าน': i === ดูเทียบที่, 'pk-ต้นแถว': ตอนเทียบต้นแถว[i] }"
        :aria-label="`ตอนที่เอามาเทียบ ${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท} ฉบับ ${ต.ชื่อฉบับ}`"
      >
        <!-- ============ หัวคอลัมน์ของตอนที่เอามาเทียบ ============
             ⭐⭐ **ชิ้นส่วนเดียวกับหัวของคอลัมน์ฉบับ** (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/102 ข้อ 6)
               ⇒ ลำดับ ขนาด และชื่อที่โปรแกรมอ่านหน้าจอได้ยิน มาจากที่เดียว ⇒ `app/components/หัวคอลัมน์.vue`
             🔴 **หัวของทุกคอลัมน์บอกเล่มและบทของตัวเอง** ⇒ ข้อ 0.1 ของหัวข้อ *หัวคอลัมน์ฉบับ*
               ใน `docs/เคาะ/หน้าจอกับการอ่าน.md` ⇒ ⭐ ใบ #102 ขยายไปถึงคอลัมน์ที่อยู่ที่เดียวกับหน้าด้วยแล้ว
             ⭐ **ชื่อเล่มเป็นภาษาไทยทุกคอลัมน์ แม้คอลัมน์นั้นเป็นฉบับภาษาอังกฤษ** ⇒ เหตุผลอยู่ในเอกสารเดียวกัน
               ⇒ กล่องหัวจึงเป็นภาษาไทย ส่วนกล่องตัวบทติด `lang` ของฉบับตัวเอง -->
        <component
          :is="หัวคอลัมน์"
          :ป้าย="`${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท}`"
          :ชื่อย่อ="ต.ชื่อย่อ"
          :เลข="`${ต.บท}`"
          :ภาษา="ต.คำเดิม ? 'th' : ต.ภาษา"
          :ชื่อคอลัมน์="ต.คำเดิม ? ถ้อยคำคำเดิม.เปิด : undefined"
          :ชื่อภาษา="ต.คำเดิม?.ชั้น || undefined"
          :ลำดับ="ฉบับที่แสดง.length + i + 1"
          :ฉบับ="ต.ฉบับ"
          :ฉบับที่มี="ตัวเลือกหัว"
          :ภาษาของตัวเลือก="ภาษาของตัวเลือก"
          :ปิดได้="ปิดได้ทุกคอลัมน์"
          :เครื่องมือ="ปุ่มเครื่องมือของเทียบ(i, ต.คำเดิม)"
          @เปลี่ยนตอน="เปิดแผงให้(i)"
          @ฉบับ="(x: string) => เปลี่ยนฉบับของเทียบ(i, x)"
          @ปิด="ถอดคอลัมน์เทียบ(i)"
          @กล่องคำเดิม="(แบบ: กล่องคำเดิมที่มี) => สลับกล่องคำเดิม(แบบ, i)"
        >
          <!-- ⭐ คอลัมน์คนละที่ที่เป็นคำภาษาเดิม ⇒ เฟืองที่มีสวิตช์ตัวเดิม (พี่เอมขอ 17 พ.ย. 2569) ⇒ เหตุผลอยู่ที่ `ปุ่มเครื่องมือของเทียบ` ในสคริปต์ -->
          <template #เครื่องมือ>
            <component
              :is="แถวปุ่มคำเดิม"
              v-if="ต.คำเดิม && เจ้าของกล่องคำเดิม === i && กล่องคำเดิม === 'เครื่องมือ'"
              แบบ="เครื่องมือ"
              :ไอดี="ไอดีกล่องของเทียบ(i).เครื่องมือ"
              :เต็มจอ="จอแคบ"
              v-bind="พร็อปแถวปุ่ม"
              :กรีก="false"
              @ตัวเดิม="ตั้งตัวเดิม"
              @เลขStrong="ตั้งเลขStrong"
              @จุดคั่น="ตั้งจุดคั่น"
              @ปิด="ปิดกล่องคำเดิม"
            />
          </template>
        </component>

        <!-- ⭐⭐ **กล่องนี้เลื่อนอ่านของตัวเองบนจอกว้าง** ⇒ ⛔ ไม่ผูกกับการเลื่อนของคอลัมน์แรก
               ⇒ **เหตุผลที่วัดได้อยู่ที่ `docs/ข้อมูล/ความสูงตอนที่เอามาเทียบ.md`** ⛔ ไม่จดซ้ำที่นี่
               ⇒ ใจความ ⇒ คอลัมน์แรกต่อบทไปเรื่อย ๆ ไม่มีที่สิ้นสุด แต่ตอนที่เทียบมีบทเดียว
                 ⇒ **ผูกกันเมื่อไร ฝั่งเทียบหมดก่อนแล้วเหลือที่ว่างยาว** ⇒ ⛔ ไม่ใช่การอ่านเทียบ
             ⭐ **โฟกัสได้เพราะมันเลื่อนได้** ⇒ คนใช้แป้นพิมพ์ต้องเลื่อนกล่องนี้ได้
               ⇒ **WCAG 2.2 SC 2.1.1 Keyboard (ระดับ A)** ⇒ ท่าเดียวกับกล่องคำภาษาเดิมของใบ #96
             ⭐ **จอแคบที่วางซ้ายขวาหรือทีละฉบับ ⇒ เลื่อนของตัวเองด้วยแล้ว** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/143)
               ⇒ ⚠️ ของเดิม ⇒ จอแคบไม่มีกล่องเลื่อนซ้อน ⇒ คอลัมน์นี้อยู่เหนือจอตอนคอลัมน์แรกอยู่ลึก ⇒ เหตุผลเต็มอยู่ที่ `main.css`
               ⇒ บนล่าง ⇒ ⛔ ไม่มีกล่องนี้ ⇒ ข้อคู่ทีละข้อ (`เลื่อนคู่`) -->
        <!-- ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/159 ⇒ แตะข้อในกล่องนี้เลือกได้ ⇒ ตัวดักตัวเดียวกับตัวบท ⇒ กติกาอยู่ที่ `app/composables/เลือกข้อ.ts` -->
        <div
          class="pk-เนื้อตอนเทียบ"
          tabindex="0"
          role="group"
          :aria-label="`ตัวบท ${ต.ชื่อเล่ม || ต.เล่ม} ${ต.บท} ฉบับ ${ต.ชื่อฉบับ} เลื่อนอ่านได้`"
          @click="เลือก.แตะในตัวบท"
          @keydown="เลือก.แป้นในตัวบท"
        >
          <p v-if="ต.ยังไม่มี" class="pk-ยังไม่มีตอนเทียบ" role="note">{{ ต.ยังไม่มี }}</p>

          <!-- ⭐ ตัวบททั้งบทตามแบบการจัดวาง ⇒ ชิ้นส่วนเดียวกับตอนคู่ทีละข้อ (`เนื้อตอนเทียบ.vue`) ⇒ เหตุผลของแต่ละแบบอยู่ในชิ้นนั้น -->
          <component
            :is="เนื้อตอนเทียบ"
                @ไปที่="(x: { ที่อยู่: string; ต: object }) => เปิดข้ออื่น(x.ที่อยู่, (x.ต as ก้อนเทียบ).ฉบับ)"
            @คำ="(x: { e: Event; ต: object; บท: number; ข้อ: string; i: number; คำ: คำเดิม }) => กดคำเทียบ(x.e, x.ต as ก้อนเทียบ, x.บท, x.ข้อ, x.i, x.คำ)"
            :ต="ต"
            :จัดวาง="มุม.จัดวาง"
            :เล่มของหน้า="รหัสเล่ม"
            :เลือก="ตัวเลือกของเทียบ(ต, true)"
            :กุญแจที่เล่น="กุญแจที่เล่น"
          />
        </div>
      </section>
      </template>
    </div>

    </div>

    <!-- ================= ④ แถบล่าง — บาง หนึบอยู่กับขอบล่าง =================
         ⭐ ตรงกลางบอกว่า **ตอนนี้อ่านอยู่ตรงไหน** ⇒ เปลี่ยนเองตามการเลื่อน
         ⭐ ลูกศร **มีได้ แต่เล็กและเงียบ** เพราะทางหลักคือเลื่อนอ่าน (พี่เอมเคาะ 6 ก.ย. 2569)
         ⛔ เล็กในที่นี้คือ **ดูเบา** ⛔ ไม่ใช่กล่องกดเล็ก ⇒ กล่องกดยังไม่ต่ำกว่า 44 จุด -->
    <!-- ⭐⭐ **แถบล่างมี 2 ส่วน** ⇒ ทางเดินบท (`<nav>`) กับ **ปุ่มเล่นเสียง** (ใบงาน #101)
         ⭐ **ทำไมปุ่มเล่นอยู่ที่นี่ ⛔ ไม่ใช่แถบบน** ⇒ ใบ #101 ข้อ 7.1 ห้ามแถบบนของจอมือถือสูงขึ้น
           ⇒ จอ 320 แถบบนเต็มแถวอยู่แล้ว ⇒ ส่วนแถบล่างหนึบอยู่ที่ขอบจอเสมอ ⇒ **เห็นโดยไม่ต้องเลื่อน** (ข้อ 7)
           ⇒ และเป็นที่เดียวกับที่แอปพระคัมภีร์ทั่วไปวางตัวเล่น ⇒ Laws of UX — Jakob's law
         ⛔ **ปุ่มเล่นอยู่นอก `<nav>`** ⇒ มันคุมเสียง ⛔ ไม่ได้พาไปไหน ⇒ WCAG 2.2 SC 1.3.1 (ระดับ A) -->
    <div class="pk-แถบล่าง" :class="{ 'pk-เรื่องสองแถว': เรื่องในแถบ && เรื่องสองแถว }">
    <!-- ================= แถวบางเสียงเรื่องเล่า (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/105 รอบ 2 ข้อ 3) =================
         ⭐ **โผล่เฉพาะตอนเสียงเรื่องเล่ายังไม่จบ** ⇒ ปิดแผ่นแล้วยังหยุดได้จากตรงนี้
         ⚠️ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131 ⇒ ปุ่ม *เรื่องเล่า* ย้ายลงแถวเดียวกับปุ่ม *ฟัง* แล้ว ⇒ แถวนี้เหลือปุ่มเสียงปุ่มเดียว
           ⇒ ชื่อเต็มขึ้นต้นด้วยคำที่ตาเห็น แล้วบอกว่าเป็นเสียงของเรื่องไหน ⇒ WCAG 2.2 SC 2.5.3 Label in Name (ระดับ A)
           ⇒ อยู่แถวของมันเอง ⇒ ⛔ ปนกับปุ่ม *ฟัง* พระคำในแถวล่างไม่ได้
         ⛔ **กล่องกดไม่เล็กกว่า 44 จุดทั้งกว้างและสูง** ⇒ SC 2.5.8 -->
    <div v-if="เรื่องในแถบ && เสียงเรื่องค้าง" class="pk-แถบเรื่องเล่า" :data-เรื่องเล่า="เรื่องในแถบ.รหัส">
      <Button
        type="button"
        variant="เข้ม"
        class="pk-ปุ่มเสียงเรื่อง"
        data-ปุ่ม="เสียงเรื่องเล่าล่าง"
        :data-สถานะ="สภาพเสียงเรื่อง.สถานะ"
        :aria-label="`${คำบนปุ่มเสียงเรื่อง} เสียงเรื่องเล่า ${เล่มนี้.ชื่อไทย} ${แสดงช่วงฟัง(เรื่องในแถบ)}`"
        @click="กดเสียงเรื่องในแถบ"
      >
        <span aria-hidden="true">{{ สภาพเสียงเรื่อง.สถานะ === 'กำลังเล่น' ? '❚❚' : '▶' }}</span>
        {{ คำบนปุ่มเสียงเรื่อง }}
      </Button>
    </div>
    <!-- ⭐ **ของที่ลอยเหนือแถบล่าง** ⇒ โผล่เฉพาะตอนมีเรื่องต้องบอก ⇒ ⛔ ไม่กินที่อ่านตอนปกติ
         ① ปุ่ม *กลับไปที่กำลังอ่าน* ⇒ ผู้อ่านเลื่อนจอเองระหว่างเล่น (ข้อ 10)
         ② ประโยคว่าหยุดเพราะอะไร ⇒ คิวจบเอง หรือบทนี้ยังไม่มีเสียง (ข้อ 8 · 13)
         ⭐ `role="status"` ⇒ โปรแกรมอ่านหน้าจอได้ยินเองโดยไม่ต้องย้ายโฟกัส ⇒ SC 4.1.3 (ระดับ AA) -->
    <div class="pk-ลอยเหนือแถบ" role="status">
      <Button
        v-if="เสียง.ทำงานอยู่.value && !เสียง.ตามอ่าน.value"
        type="button"
        variant="เข้ม"
        class="pk-ปุ่มกลับไปที่อ่าน"
        data-ปุ่ม="กลับไปที่กำลังอ่าน"
        @click="เสียง.กลับไปที่กำลังอ่าน()"
      >
        กลับไปที่กำลังอ่าน<template v-if="เสียง.ข้อที่เล่นอยู่.value">
          · {{ เสียง.ข้อที่เล่นอยู่.value.บท }}:{{ เสียง.ข้อที่เล่นอยู่.value.ข้อ }}</template
        >
      </Button>
      <p v-else-if="เสียง.ข้อความจบ.value" class="pk-ข้อความเสียง" data-ข้อความ="จบ">
        {{ เสียง.ข้อความจบ.value }}
      </p>
      <!-- ③ ข้อที่เลือกไว้ (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/139 ข้อ 7)
             ⇒ ผู้อ่านรู้ก่อนกดแชร์ว่าจะส่งกี่ข้อ ⇒ ไม่มีแถบนี้ = แชร์ทั้งหน้า ⇒ จำนวนเดียวกับตัวเลขบนปุ่มแชร์
             ⇒ ยกเลิกการเลือกทุกข้อได้ในการกดครั้งเดียว ⇒ อยู่ใกล้นิ้วโป้ง ⇒ ⛔ ไม่ต้องเอื้อมขึ้นแถบบน
             ⭐ อยู่ในกล่อง `role="status"` ⇒ แตะเลือกแล้วโปรแกรมอ่านหน้าจอได้ยินจำนวนใหม่เอง (SC 4.1.3) -->
      <div v-if="ชิ้นที่เลือก.length" class="pk-แถบข้อที่เลือก" data-แถบ="ข้อที่เลือก">
        <span>{{ ถ้อยคำแชร์.เลือกแล้ว(ข้อที่จะแชร์.length) }}</span>
        <!-- ⭐ ทางของแป้นพิมพ์และโปรแกรมอ่านหน้าจอไปถึงเชิงอรรถ ⇒ โผล่เฉพาะตอนข้อที่เลือกมีเชิงอรรถ ⇒ เหตุผลอยู่หัว `แผ่นเชิงอรรถ.vue` -->
        <Button
          v-if="เชิงอรรถของข้อที่เลือก.length"
          type="button"
          class="pk-ปุ่มเชิงอรรถข้อ"
          data-ปุ่ม="เชิงอรรถข้อที่เลือก"
          aria-haspopup="dialog"
          :aria-expanded="!!เชิงอรรถที่เปิด?.จากแถบ"
          @click="เปิดเชิงอรรถของข้อที่เลือก"
        >
          {{ ถ้อยคำเชิงอรรถ.ปุ่ม }}
        </Button>
        <Button type="button" class="pk-ปุ่มเลิกเลือก" data-ปุ่ม="เลิกเลือก" @click="เลือก.เลิกทั้งหมด()">
          {{ ถ้อยคำแชร์.เลิกเลือก }}
        </Button>
      </div>
    </div>
    <nav class="pk-นำทางล่าง" :aria-label="คำแถบล่าง.กลุ่ม" :data-ทุกคอลัมน์="ปิดคอลัมน์ได้ ? 'ใช่' : undefined">
      <!-- ⭐⭐ **ลูกศรเป็นลิงก์จริง แต่กดแล้ว ⛔ ไม่โหลดหน้าใหม่** (ใบงาน v3/phrakham#73)
           ⇒ บทอื่นอยู่ในหน้าเดียวกันแล้ว ⇒ กดแล้วเลื่อนไปตรงนั้นเลย ⇒ เร็วกว่าและไม่กระพริบ
           ⛔ **ยังต้องเป็น `<a href>` อยู่** ⇒ คลิกขวาคัดลอกลิงก์ได้ · เปิดแท็บใหม่ได้ ·
              และโค้ดของเว็บโหลดไม่สำเร็จก็ยังกดไปได้
         ⭐ **ที่อยู่บนลูกศร ⛔ ไม่พกช่วง (`r`)** (ใบงาน #102 ข้อ 19) ⇒ กดแล้วออกจากช่วงไปบทเต็มที่อยู่ติดกัน
         ⭐⭐ **ลูกศรแถบล่างพาทุกคอลัมน์ไป** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 9.1 ⇒ แทนใบ #102 ข้อ 21)
           ⇒ ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/162 ⇒ คอลัมน์ซ้ายสุดไปบทก่อนหรือบทถัดไป ⇒ คอลัมน์อื่นทุกคอลัมน์ไปเล่มและบทเดียวกับมัน ⇒ ฉบับเดิม
             ⇒ ⚠️ ของเดิม (ใบ #125) ⇒ แต่ละคอลัมน์ไปบทก่อนหรือบทถัดไปในเล่มของตัวเอง
           ⇒ ลูกศรมีเมื่อคอลัมน์ซ้ายสุดมีบทให้ไป ⇒ ⛔ ไม่มีลูกศรที่กดแล้วเงียบ
           ⇒ `href` กับการกดใช้ผลตัวเดียวกัน (`ผลของลูกศรล่าง`) ⇒ คัดลอกลิงก์แล้วได้หน้าเดียวกับที่กด -->
      <Button
        as="a"
        v-if="ลูกศรล่าง.ก่อน.ขยับ"
        class="pk-ลูกศรบท"
        data-ปุ่ม="บทก่อนล่าง"
        :href="ที่อยู่ของลูกศรล่าง(ลูกศรล่าง.ก่อน)"
        @click.prevent="กดลูกศรล่าง(-1)"
      >
        <span aria-hidden="true">‹</span><span class="pk-เฉพาะเสียง">{{ คำแถบล่าง.ก่อน }}</span>
      </Button>
      <span v-else class="pk-ลูกศรว่าง" aria-hidden="true"></span>

      <!-- ⭐⭐ **ปุ่มกลาง ⇒ จอแคบบอกที่อยู่ · จอกว้างเขียน *เปลี่ยนตอน*** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/113)
             ⇒ **จอแคบ (ต่ำกว่า 768 จุด)** ⇒ เขียนชื่อเล่มกับบทที่อ่านอยู่ เช่น *มาระโก 11* ⇒ ดูช่วงอยู่ ⇒ เขียนช่วง
               ⇒ เพราะจอแคบหัวคอลัมน์ ⛔ ไม่หนึบ (ใบ #102 ข้อ 6.3) ⇒ เลื่อนลงกลางบทแล้วทั้งจอไม่มีที่ไหนบอกบท
                 (พี่เอมส่งภาพมือถือ 26 ต.ค. 2569 *"ไม่เห็นบทเลย"*) ⇒ Nielsen ข้อ 1 Visibility of system status
               ⇒ ⭐ **ป้ายเป็นปุ่มเดิม ⇒ ⛔ ไม่เพิ่มแถว ⛔ ไม่เพิ่มปุ่ม** ⇒ แถบหนึบของจอมือถือห้ามสูงขึ้น (ใบ #76)
                 ⇒ ท่าเดียวกับปุ่มชื่อบทของ YouVersion ที่กดแล้วเปิดตัวเลือกบท
             ⇒ **จอกว้าง** ⇒ เขียน *เปลี่ยนตอน* เหมือนเดิม (ใบ #104 ข้อ 7) ⇒ หัวคอลัมน์หนึบบอกบทอยู่แล้ว ⇒ ⛔ ไม่บอกซ้ำ
             ⇒ ⭐ **ค่าตัวเดียวกับป้ายหัวคอลัมน์** (`ป้ายที่ของหน้า`) ⇒ ⛔ ไม่มีสองสำเนาให้แยกกันเดิน
             ⭐ **ชื่อที่โปรแกรมอ่านหน้าจอได้ยิน ขึ้นต้นด้วยคำที่ตาเห็น** ⇒ *มาระโก 11 เปลี่ยนตอน* ⇒ SC 2.5.3 Label in Name (ระดับ A)
               ⇒ เลือกด้วย CSS ล้วน (`.pk-ป้ายตอน` / `.pk-คำเปลี่ยนตอน`) ⇒ ของที่ `display: none` ⛔ ไม่เข้าชื่อ ⇒ ⛔ ไม่มีโค้ดวัดจอ
             ⭐ **ชื่อยาวไม่พอที่ ⇒ ชื่อเล่มหดพร้อมจุดไข่ปลา ⇒ เลขบทและข้อ ⛔ ไม่ถูกตัด** ⇒ ตาเห็นว่าถูกย่อ ⛔ ไม่ใช่ตัดเงียบ
               ⇒ บรรทัดเดียวเสมอ ⇒ ⛔ ไม่ดันปุ่ม *ฟัง* ⇒ กฎอยู่ที่ `main.css` ⇒ ตัวเฝ้าคือ `tools/ด่านแถบล่าง.mjs` ข้อ ④ ถึง ⑦
             ⭐⭐ **มากกว่า 1 คอลัมน์ ⇒ ปุ่มนี้พาทุกคอลัมน์ไปตอนที่เลือก** (ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/125 ข้อ 9.2 · 9.3)
               ⇒ คำท้ายปุ่มเป็น *เปลี่ยนตอนทุกคอลัมน์* ⇒ จอกว้างตาเห็น · จอแคบหูได้ยินต่อท้ายชื่อบท ⇒ ถ้อยคำอยู่ที่ `app/utils/ถ้อยคำแถบล่าง.ts`
             ⛔ **`data-ปุ่ม` ห้ามเปลี่ยน** ⇒ ด่านหาปุ่มนี้ด้วยค่านี้ -->
      <Button
        type="button"
        class="pk-ปุ่มตอนนี้"
        data-ปุ่ม="เปลี่ยนตอนล่าง"
        aria-haspopup="dialog"
        :aria-expanded="เปิดหน้าต่างเล่ม"
        @click="เปิดแผงให้('ทั้งหมด')"
      >
        <span class="pk-ป้ายตอน" data-ป้าย="แถบล่าง"
          ><span class="pk-ป้ายเล่ม">{{ เล่มนี้.ชื่อไทย }}</span> <span class="pk-ป้ายเลข">{{ เลขบนแถบล่าง }}</span></span
        ><span class="pk-คำเปลี่ยนตอน"> {{ คำแถบล่าง.ปุ่มกลาง }}</span>
      </Button>

      <Button
        as="a"
        v-if="ลูกศรล่าง.ถัด.ขยับ"
        class="pk-ลูกศรบท"
        data-ปุ่ม="บทถัดล่าง"
        :href="ที่อยู่ของลูกศรล่าง(ลูกศรล่าง.ถัด)"
        @click.prevent="กดลูกศรล่าง(1)"
      >
        <span aria-hidden="true">›</span><span class="pk-เฉพาะเสียง">{{ คำแถบล่าง.ถัด }}</span>
      </Button>
      <span v-else class="pk-ลูกศรว่าง" aria-hidden="true"></span>
    </nav>
    <!-- ================= ปุ่มเรื่องเล่า (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/105 รอบ 2 · ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/131) =================
         ⭐ **โผล่เฉพาะตอนข้อบนจอทับช่วงของเรื่องเล่า** ⇒ กติกาอยู่ที่ `เรื่องในแถบ` ในสคริปต์
         ⭐ **อยู่ก่อนปุ่ม ▶ ฟัง** ⇒ แบบป้าย (เต็ม · สั้น · สองแถว · สองแถวสั้น) เลือกที่ `จัดปุ่มเรื่องเล่า` ⇒ กฎหน้าตาอยู่ที่ `main.css`
         ⭐ **ปุ่มเปิดแผ่น ⇒ `aria-haspopup="dialog"`** ⇒ บอกล่วงหน้าว่ากดแล้วเปิดหน้าต่าง ⇒ `aria-expanded` บอกว่าเปิดอยู่ไหม
         ⭐ แบบสั้นซ่อนชื่อย่อกับช่วงด้วย `display: none` ⇒ ⛔ เข้าชื่อที่ได้ยิน ⇒ ชื่อเต็มกับช่วงต่อท้ายเป็นเสียงทุกแบบ
         ⛔ `data-ปุ่ม` ห้ามเปลี่ยน ⇒ ด่านหาปุ่มนี้ด้วยค่านี้ -->
    <Button
      v-if="เรื่องในแถบ"
      ref="ปุ่มเรื่องเล่าชิ้น"
      type="button"
      class="pk-ปุ่มเรื่องเล่า"
      :class="{ 'pk-ป้ายสั้น': ป้ายเรื่องสั้น }"
      data-ปุ่ม="เรื่องเล่า"
      :data-เรื่องเล่า="เรื่องในแถบ.รหัส"
      :data-แบบ="แบบปุ่มเรื่อง"
      aria-haspopup="dialog"
      :aria-expanded="!!เรื่องที่เปิด"
      @click="เปิดเรื่องเล่า"
    >
      <span
        >เรื่องเล่า<span class="pk-ช่วงเรื่อง">{{ ` ${ชื่อย่อเรื่อง} ${แสดงช่วงฟัง(เรื่องในแถบ)}` }}</span
        ><span class="pk-เฉพาะเสียง">{{ ` ${เล่มนี้.ชื่อไทย} ${แสดงช่วงฟัง(เรื่องในแถบ)}` }}</span></span
      >
    </Button>
    <!-- ⭐⭐ **ปุ่มเดียว** ⇒ ฟัง · หยุดพัก · ฟังต่อ ⇒ **อยู่ที่เดิมทุกสถานะ** (ข้อ 11)
         ⭐ ใหญ่อย่างน้อย 44 จุด ⇒ SC 2.5.8 Target Size (ระดับ AA) ⇒ เกณฑ์ของทั้งเว็บ
         ⛔ **บทที่ไม่มีเสียง ⛔ ไม่มีปุ่ม** ⇒ ปุ่มที่กดแล้วเงียบคือของที่ใบสั่งห้ามตรง ๆ (ข้อ 13)
           ⇒ บอกด้วยตัวหนังสือว่า *ยังไม่มีเสียง* แทน ⇒ อยู่ที่เดียวกับปุ่ม ⇒ ผู้อ่านไม่ต้องเดาว่าปุ่มหายไปไหน -->
    <Button
      v-if="เสียง.มีเสียงให้เล่น.value"
      type="button"
      variant="เข้ม"
      class="pk-ปุ่มฟัง"
      data-ปุ่ม="ฟัง"
      :data-สถานะ="เสียง.สภาพ.value.สถานะ"
      :aria-label="เสียง.ชื่อเต็มของปุ่ม.value"
      @click="กดฟังพระคำ()"
    >
      <span aria-hidden="true">{{ เสียง.สภาพ.value.สถานะ === 'กำลังเล่น' ? '❚❚' : '▶' }}</span>
      {{ เสียง.คำบนปุ่ม.value }}
      <!-- ⭐ ใบ #132 ข้อ 11 ⇒ **ชื่อฉบับที่จะได้ยินอยู่บนปุ่ม** ⇒ บรรทัดเล็กใต้คำ ⇒ ปุ่ม ⛔ ไม่กว้างขึ้น ⇒ แถบล่างจอ 320 ยังพอ -->
      <span class="pk-ฉบับที่ฟัง" data-ฉบับ="ฟัง">{{ ฉบับที่ฟัง }}</span>
    </Button>
    <!-- ⭐ ใบ #132 ข้อ 11.3 ⇒ **บอกว่าฉบับไหนยังไม่มีเสียง** ⇒ ⛔ ไม่ใช่ *ยังไม่มีเสียง* ลอย ๆ ⇒ ผู้อ่านรู้ว่าเปลี่ยนคอลัมน์แรกเป็นฉบับอื่นได้ -->
    <!-- ⭐ ใบ https://aimgit.aimagin.com/v3/phrakham/-/issues/145 ข้อ 6 ⇒ ไม่มีคอลัมน์ไหนมีเสียงอ่านเลย (เหลือแต่คำภาษาเดิม) ⇒ ⛔ ไม่มีทั้งปุ่มและประโยค
           ⇒ คำเดิมไม่ใช่ฉบับที่ยังไม่มีเสียง ⇒ มันไม่มีเสียงอ่านโดยธรรมชาติ ⇒ ประโยค *… ยังไม่มีเสียง* จึงไม่จริง ⇒ เปิดฉบับแปลที่มีเสียงแล้วปุ่มกลับมาเอง -->
    <p v-else-if="ฉบับที่ฟัง" class="pk-ยังไม่มีเสียง" data-ปุ่ม="ไม่มีเสียง">
      <span class="pk-ฉบับที่ฟัง">{{ ฉบับที่ฟัง }}</span> ยังไม่มีเสียง
    </p>
    </div>

    <!-- ⭐ **ที่มาของเสียง** ⇒ สัญญาอนุญาต CC BY-SA 4.0 ของ TCV บังคับให้บอกว่าเสียงนี้ดัดแปลงมาจากไหน
         ⇒ ⛔ **ประโยคยกมาจากรายการเสียงทั้งดุ้น** ⛔ ห้ามพิมพ์ใหม่ทับ
         ⇒ ⭐ โผล่หลังกดเล่นครั้งแรกเท่านั้น ⇒ รายการเต็มถูกขอตอนนั้น ⇒ คนไม่กดเล่น ⛔ ไม่จ่ายไบต์นี้ -->
    <details v-if="เสียง.ประกาศที่มา.value" class="pk-ที่มาเสียง">
      <summary>เสียงอ่านนี้มาจากไหน</summary>
      <p class="pk-ประกาศที่มา">{{ เสียง.ประกาศที่มา.value }}</p>
    </details>

    <!-- ⭐⭐ **พวงลิงก์ท้ายหน้า — เหลืออยู่ที่หน้านี้หน้าเดียวแล้ว** (พี่เอมทัก 12 ต.ค. 2569)
         ⇒ **มันมาแทนหัวเมนูที่จอแคบซ่อนไว้** ⇒ CSS ซ่อนมันเองบนจอกว้าง ที่ซึ่งหัวเมนูเห็นครบ
         ⇒ หน้าอื่นถอดชุดนี้ออกหมดแล้ว เพราะที่นั่นมันซ้ำกับหัวเมนูเฉย ๆ
         ⇒ เหตุผลเต็มกับมาตรฐานที่อ้าง อยู่ที่ `app/components/พวงลิงก์.vue` ⛔ ไม่จดซ้ำที่นี่ -->
    <component :is="พวงลิงก์" @เปิดแผง="เปิดแผงให้(null)" />

    <!-- ================= แผ่นเรื่องเล่า (ใบงาน https://aimgit.aimagin.com/v3/phrakham/-/issues/105 รอบ 2 ข้อ 2) =================
         ⭐ **มีบนหน้าเฉพาะตอนกดปุ่มเรื่องเล่าแล้ว** ⇒ ก่อนนั้น ⛔ ไม่มีแม้แต่โค้ดของแผ่น (`defineAsyncComponent`) ⇒ เกณฑ์ข้อ 10
         ⭐ แผ่นเป็นเจ้าของการเปิดปิดแบบ modal ⇒ หน้านี้แค่รู้ว่าปิดแล้ว ⇒ คืนโฟกัสให้ปุ่ม *เรื่องเล่า* -->
    <component
      :is="แผงเรื่องเล่า"
      v-if="เรื่องที่เปิด"
      :key="เรื่องที่เปิด.รหัส"
      :ที่อยู่เรื่อง="ที่อยู่หลังบ้าน(`api/story/${เรื่องที่เปิด.รหัส}.json`)"
      :ชื่อช่วง="`${เล่มนี้.ชื่อไทย} ${แสดงช่วงฟัง(เรื่องที่เปิด)}`"
      :สถานะเสียง="เรื่องในตัวเล่น?.รหัส === เรื่องที่เปิด.รหัส ? สภาพเสียงเรื่อง.สถานะ : 'ยังไม่เริ่ม'"
      @ฟัง="กดฟังเรื่องเล่า"
      @ปิด="ปิดเรื่องเล่า"
    />

    <!-- ================= การ์ดความหมายคำ (ใบงาน v3/phrakham#103) =================
         ⭐ **มีบนหน้าเฉพาะตอนกดคำแล้ว** ⇒ ก่อนนั้น ⛔ ไม่มีแม้แต่โค้ดของการ์ด (`defineAsyncComponent`)
         ⭐ ค่าแหล่งที่เลือกเป็นของ `มุม` ⇒ จำข้ามหน้าและข้ามรอบด้วยที่เก็บเดียวกับมุมมองอื่น (เกณฑ์ข้อ 8) -->
    <component
      :is="การ์ดคำ"
      v-if="คำที่เปิด"
      :เล่ม="คำที่เปิด.เล่ม || รหัสเล่ม"
      :ชื่อเล่ม="คำที่เปิด.ชื่อเล่ม || เล่มนี้.ชื่อไทย"
      :บท="คำที่เปิด.บท"
      :ชั้น="คำที่เปิด.ชั้น"
      :ข้อ="คำที่เปิด.ข้อ"
      :ลำดับ="คำที่เปิด.ลำดับ"
      :ตัว="คำที่เปิด.ตัว"
      :คำแปล="คำที่เปิด.คำแปล"
      :ภาษา="คำที่เปิด.ภาษา"
      :จุด="คำที่เปิด.จุด"
      :ฉบับ="คำที่เปิด.ฉบับ ? [คำที่เปิด.ฉบับ] : ฉบับในที่อยู่"
      :ที่ในลิงก์="ที่ในลิงก์คำ"
      :แหล่ง="มุม.แหล่งความหมาย"
      @ปิด="ปิดการ์ด"
      @เปลี่ยนแหล่ง="(x: string[]) => (มุม.แหล่งความหมาย = x)"
    />
    <!-- ⭐ แผ่นเชิงอรรถของผู้แปล ⇒ เหตุผลอยู่หัว `app/components/แผ่นเชิงอรรถ.vue` -->
    <component
      :is="แผ่นเชิงอรรถ"
      v-if="เชิงอรรถที่เปิด"
      :รายการ="เชิงอรรถที่เปิด.รายการ"
      :ภาษาของ="ภาษาของชั้น"
      :จับโฟกัส="เชิงอรรถที่เปิด.จากแถบ"
      @ปิด="ปิดเชิงอรรถ"
      @ไปที่="ไปที่จากเชิงอรรถ"
    />
  </article>
</template>
